begin;
-- receta-dulce-de-leche
do $pub$
declare
  g constant uuid := '218f9269-b912-4ffe-b5d0-8cb1a74b53ed';
  es_id constant uuid := '993ae1bd-a335-4d87-8ffc-448f3b1eea0b';
  j constant jsonb := $j$[{"id":"993ae1bd-a335-4d87-8ffc-448f3b1eea0b","recipe_group_id":"218f9269-b912-4ffe-b5d0-8cb1a74b53ed","slug":"receta-dulce-de-leche","public_path":"/receta-dulce-de-leche","source_url":"https://manualdecocina.com/receta-dulce-de-leche/","language":"es","title":"Dulce de leche casero","excerpt":"Dulce de leche casero en olla abierta, con leche entera, azúcar y vainilla. Aprende a reducirlo sin que se pegue y a comprobar su punto.","summary":"La leche y el azúcar se reducen lentamente en una olla amplia hasta formar una crema color caramelo. Esta versión se cocina a olla abierta; no se calienta ninguna lata cerrada.\n\nRinde aproximadamente 500 g, unas 20 porciones de 25 g. Los 190 minutos totales incluyen 60 minutos de enfriado; el punto final depende del diámetro de la olla y de la intensidad del fuego.","category":"Postres","category_slug":"postres","difficulty":"Media","course":"Postre","cuisine":"Latinoamericana","prep_time_minutes":10,"cook_time_minutes":120,"total_time_minutes":190,"servings":20,"ingredients":[{"name":"leche entera","amount":"1000","unit":"ml","group":"Base"},{"name":"azúcar","amount":"250","unit":"g","group":"Base"},{"name":"extracto de vainilla","amount":"5","unit":"ml","group":"Aromatizante"}],"steps":[{"title":"Prepara la olla","content":"Mide 1 litro de leche entera y 250 g de azúcar. Usa una olla de fondo grueso de al menos 3 litros y una espátula de silicona resistente al calor. Reserva un plato pequeño en la nevera para comprobar el punto.","image_url":"/recetas/receta-dulce-de-leche/paso-01.webp","image_alt":"Dulce de leche casero: Prepara la olla"},{"title":"Disuelve el azúcar","content":"Vierte la leche y los 250 g de azúcar en la olla. Calienta a fuego medio unos 8 minutos, removiendo hasta que no se noten cristales. No llenes la olla más de la mitad.","image_url":"/recetas/receta-dulce-de-leche/paso-02.webp","image_alt":"Dulce de leche casero: Disuelve el azúcar"},{"title":"Mantén un hervor suave","content":"Cuando la leche empiece a subir, baja enseguida el fuego. Mantén burbujas pequeñas y la olla destapada; remueve el fondo cada 3–5 minutos durante la primera hora. Si sube espuma, retira unos segundos del fuego.","image_url":"/recetas/receta-dulce-de-leche/paso-03.webp","image_alt":"Dulce de leche casero: Mantén un hervor suave"},{"title":"Reduce la mezcla","content":"Continúa a fuego bajo de 40 a 60 minutos más. Raspa fondo y esquinas con la espátula cada 1–2 minutos cuando tome color beige y espese; evita un hervor fuerte que queme el fondo.","image_url":"/recetas/receta-dulce-de-leche/paso-04.webp","image_alt":"Dulce de leche casero: Reduce la mezcla"},{"title":"Comprueba el punto","content":"Pon una cucharadita en el plato frío y espera 1 minuto. Debe moverse lentamente al inclinarlo, todavía algo más fluida que el dulce terminado. Si corre como leche, cocina otros 5 minutos y repite.","image_url":"/recetas/receta-dulce-de-leche/paso-05.webp","image_alt":"Dulce de leche casero: Comprueba el punto"},{"title":"Añade la vainilla","content":"Retira la olla del fuego y mezcla 5 ml de extracto de vainilla durante 1 minuto. Si aparecen pequeños grumos, bate a mano hasta alisarlos sin salpicar.","image_url":"/recetas/receta-dulce-de-leche/paso-06.webp","image_alt":"Dulce de leche casero: Añade la vainilla"},{"title":"Enfría sin tapar herméticamente","content":"Pasa el dulce a un recipiente limpio resistente al calor y deja que pierda calor 30 minutos. Remueve ocasionalmente; refrigera y deja enfriar otros 30 minutos antes de valorar la textura. No lo dejes más de 2 horas fuera de la nevera.","image_url":"/recetas/receta-dulce-de-leche/paso-07.webp","image_alt":"Dulce de leche casero: Enfría sin tapar herméticamente"},{"title":"Guarda y sirve","content":"Una vez frío, tapa y conserva refrigerado hasta 7 días. Sirve porciones de unos 25 g con una cuchara limpia; la receta no es una conserva estable a temperatura ambiente.","image_url":"/recetas/receta-dulce-de-leche/paso-08.webp","image_alt":"Dulce de leche casero: Guarda y sirve"}],"notes":"Para un dulce más fluido, retíralo antes; para relleno, reduce unos minutos adicionales, recordando que espesa al enfriar. Si el fondo se quema, cambia de recipiente sin raspar la parte quemada. La leche sin lactosa puede dorarse de otra manera y requiere vigilar el punto. No se necesita bicarbonato en esta versión.","nutrition":{"calories":81.0,"protein_g":1.6,"carbs_g":15.0,"fat_g":1.7,"saturated_fat_g":1.0,"fiber_g":0.0,"sugar_g":15.1,"sodium_mg":22.0,"serving_size":"1 de 20 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 20 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma.  Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"leche entera","edible_grams":1030,"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"fat_g":3.25,"sugar_g":5.05,"carbs_g":4.8,"calories":61.0,"saturated_fat_g":1.865,"fiber_g":0.0,"sodium_mg":43.0,"protein_g":3.15},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients"},{"ingredient":"azúcar","edible_grams":250,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"protein_g":0.0,"sodium_mg":1.0,"fat_g":0.0,"calories":387.0,"saturated_fat_g":0.0,"sugar_g":99.8,"carbs_g":99.98,"fiber_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"extracto de vainilla","edible_grams":5,"fdc_id":173471,"fdc_description":"Vanilla extract","per_100g":{"fat_g":0.06,"carbs_g":12.65,"calories":288.0,"protein_g":0.06,"fiber_g":0.0,"sodium_mg":9.0,"saturated_fat_g":0.01,"sugar_g":12.65},"source_url":"https://fdc.nal.usda.gov/food-details/173471/nutrients"}]},"keywords":["dulce de leche casero","dulce de leche en olla","leche y azúcar"],"image_url":"/recetas/receta-dulce-de-leche/portada.webp","gallery":[{"url":"/recetas/receta-dulce-de-leche/portada.webp","alt":"Dulce de leche casero: plato terminado"}],"seo":{"title":"Dulce de leche casero | Manual de Cocina","description":"Dulce de leche casero en olla abierta, con leche entera, azúcar y vainilla. Aprende a reducirlo sin que se pegue y a comprobar su punto.","image_alt":"Dulce de leche casero: plato terminado","image_variants":["/recetas/receta-dulce-de-leche/portada-1x1.webp","/recetas/receta-dulce-de-leche/portada-4x3.webp","/recetas/receta-dulce-de-leche/portada-16x9.webp"],"faq":[{"q":"¿Por qué queda líquido al retirar del fuego?","a":"Espesa al enfriarse. Usa la prueba del plato frío antes de seguir reduciendo para no dejarlo demasiado duro."},{"q":"¿Puedo reducir el azúcar?","a":"Esta proporción se diseñó con 250 g. Reducirla cambia textura, rendimiento y conservación; no lo trates como una conserva."},{"q":"¿Cuánto dura en la nevera?","a":"Hasta 7 días en un recipiente limpio y tapado. Usa utensilios limpios y desecha si cambia de olor o presenta moho."}]},"published":false,"editorial_status":"ready","content_html":"<p>La leche y el azúcar se reducen lentamente en una olla amplia hasta formar una crema color caramelo. Esta versión se cocina a olla abierta; no se calienta ninguna lata cerrada.</p><p>Rinde aproximadamente 500 g, unas 20 porciones de 25 g. Los 190 minutos totales incluyen 60 minutos de enfriado; el punto final depende del diámetro de la olla y de la intensidad del fuego.</p>"},{"id":"375d4b51-e9ce-5627-985c-fa18a57ee38c","recipe_group_id":"218f9269-b912-4ffe-b5d0-8cb1a74b53ed","slug":"dulce-de-leche-selber-machen","public_path":"/de/dulce-de-leche-selber-machen","source_url":null,"language":"de","title":"Dulce de Leche selbst gemacht","excerpt":"Dulce de leche aus Vollmilch, Zucker und Vanille im offenen Topf: langsam einkochen und mit der Tellerprobe die Konsistenz prüfen.","summary":"Milch und Zucker werden im breiten, offenen Topf zu einer karamellfarbenen Creme eingekocht. Eine geschlossene Dose wird dabei niemals erhitzt.\n\nErgibt etwa 500 g, also 20 Portionen à 25 g. Die Gesamtzeit von 190 Minuten enthält 60 Minuten Abkühlen; Topfbreite und Hitze beeinflussen den Endpunkt.","category":"Desserts","category_slug":"postres","difficulty":"Mittel","course":"Dessert","cuisine":"Lateinamerikanisch","prep_time_minutes":10,"cook_time_minutes":120,"total_time_minutes":190,"servings":20,"ingredients":[{"name":"Vollmilch","amount":"1000","unit":"ml","group":"Grundmasse"},{"name":"Zucker","amount":"250","unit":"g","group":"Grundmasse"},{"name":"Vanilleextrakt","amount":"5","unit":"ml","group":"Aroma"}],"steps":[{"title":"Topf vorbereiten","content":"1 Liter Vollmilch und 250 g Zucker abmessen. Einen Topf mit dickem Boden und mindestens 3 Litern Fassungsvermögen sowie einen hitzefesten Silikonspatel bereitlegen. Einen kleinen Teller für die Konsistenzprobe kalt stellen.","image_url":"/recetas/receta-dulce-de-leche/paso-01.webp","image_alt":"Dulce de Leche selbst gemacht: Topf vorbereiten"},{"title":"Zucker auflösen","content":"Milch und 250 g Zucker im Topf bei mittlerer Hitze etwa 8 Minuten unter Rühren erwärmen, bis keine Kristalle mehr fühlbar sind. Den Topf höchstens halb füllen.","image_url":"/recetas/receta-dulce-de-leche/paso-02.webp","image_alt":"Dulce de Leche selbst gemacht: Zucker auflösen"},{"title":"Sanft köcheln lassen","content":"Sobald die Milch aufsteigt, die Hitze sofort reduzieren. Offen bei kleinen Blasen köcheln; in der ersten Stunde alle 3–5 Minuten über den Boden rühren. Bei aufsteigendem Schaum den Topf kurz vom Herd nehmen.","image_url":"/recetas/receta-dulce-de-leche/paso-03.webp","image_alt":"Dulce de Leche selbst gemacht: Sanft köcheln lassen"},{"title":"Mischung reduzieren","content":"Weitere 40–60 Minuten bei kleiner Hitze einkochen. Sobald die Masse beige und dicklicher wird, Boden und Ecken alle 1–2 Minuten mit dem Spatel abstreifen. Starkes Kochen vermeiden.","image_url":"/recetas/receta-dulce-de-leche/paso-04.webp","image_alt":"Dulce de Leche selbst gemacht: Mischung reduzieren"},{"title":"Konsistenz prüfen","content":"Einen Teelöffel auf den kalten Teller geben und 1 Minute warten. Beim Neigen soll die Masse langsam fließen und noch etwas dünner als das fertige Produkt sein. Fließt sie wie Milch, 5 Minuten weiterkochen und erneut prüfen.","image_url":"/recetas/receta-dulce-de-leche/paso-05.webp","image_alt":"Dulce de Leche selbst gemacht: Konsistenz prüfen"},{"title":"Vanille einrühren","content":"Vom Herd nehmen und 5 ml Vanilleextrakt 1 Minute einrühren. Kleine Klümpchen vorsichtig mit dem Schneebesen glätten, ohne zu spritzen.","image_url":"/recetas/receta-dulce-de-leche/paso-06.webp","image_alt":"Dulce de Leche selbst gemacht: Vanille einrühren"},{"title":"Offen abkühlen lassen","content":"In ein sauberes, hitzefestes Gefäß füllen und 30 Minuten abkühlen lassen; gelegentlich umrühren. Im Kühlschrank weitere 30 Minuten abkühlen, erst dann die Konsistenz beurteilen. Nicht länger als 2 Stunden ungekühlt lassen.","image_url":"/recetas/receta-dulce-de-leche/paso-07.webp","image_alt":"Dulce de Leche selbst gemacht: Offen abkühlen lassen"},{"title":"Aufbewahren und servieren","content":"Kalt verschließen und bis zu 7 Tage im Kühlschrank lagern. Mit sauberem Löffel etwa 25 g pro Portion entnehmen. Dies ist keine bei Raumtemperatur haltbare Konserve.","image_url":"/recetas/receta-dulce-de-leche/paso-08.webp","image_alt":"Dulce de Leche selbst gemacht: Aufbewahren und servieren"}],"notes":"Für eine flüssigere Creme früher vom Herd nehmen; für eine Füllung etwas länger einkochen, da sie beim Abkühlen nachdickt. Bei angebranntem Boden umfüllen, ohne Verbranntes abzukratzen. Laktosefreie Milch bräunt anders: die Konsistenz genau beobachten. Natron ist hier nicht nötig.","nutrition":{"calories":81.0,"protein_g":1.6,"carbs_g":15.0,"fat_g":1.7,"saturated_fat_g":1.0,"fiber_g":0.0,"sugar_g":15.1,"sodium_mg":22.0,"serving_size":"1 von 20 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 20 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers."},"keywords":["Dulce de leche selber machen","Milchkaramell","Dulce de leche im Topf"],"image_url":"/recetas/receta-dulce-de-leche/portada.webp","gallery":[{"url":"/recetas/receta-dulce-de-leche/portada.webp","alt":"Dulce de Leche selbst gemacht: fertiges Gericht"}],"seo":{"title":"Dulce de Leche selbst gemacht | Manual de Cocina","description":"Dulce de leche aus Vollmilch, Zucker und Vanille im offenen Topf: langsam einkochen und mit der Tellerprobe die Konsistenz prüfen.","image_alt":"Dulce de Leche selbst gemacht: fertiges Gericht","image_variants":["/recetas/receta-dulce-de-leche/portada-1x1.webp","/recetas/receta-dulce-de-leche/portada-4x3.webp","/recetas/receta-dulce-de-leche/portada-16x9.webp"],"faq":[{"q":"Warum ist die Creme beim Abnehmen noch flüssig?","a":"Sie dickt beim Abkühlen nach. Mit der kalten Tellerprobe prüfen, bevor sie zu stark eingekocht wird."},{"q":"Kann ich weniger Zucker verwenden?","a":"Diese Version ist auf 250 g ausgelegt. Weniger Zucker verändert Konsistenz, Ausbeute und Lagerung; nicht als haltbare Konserve behandeln."},{"q":"Wie lange hält sie im Kühlschrank?","a":"Bis zu 7 Tage im sauberen, verschlossenen Gefäß. Saubere Löffel verwenden; bei verändertem Geruch oder Schimmel entsorgen."}]},"published":false,"editorial_status":"ready","content_html":"<p>Milch und Zucker werden im breiten, offenen Topf zu einer karamellfarbenen Creme eingekocht. Eine geschlossene Dose wird dabei niemals erhitzt.</p><p>Ergibt etwa 500 g, also 20 Portionen à 25 g. Die Gesamtzeit von 190 Minuten enthält 60 Minuten Abkühlen; Topfbreite und Hitze beeinflussen den Endpunkt.</p>"},{"id":"059d9612-49b6-5f56-b769-30f4249fee76","recipe_group_id":"218f9269-b912-4ffe-b5d0-8cb1a74b53ed","slug":"homemade-dulce-de-leche","public_path":"/en/homemade-dulce-de-leche","source_url":null,"language":"en","title":"Homemade dulce de leche","excerpt":"Make dulce de leche in an open saucepan with whole milk, sugar and vanilla. Learn to reduce it gently and check its thickness on a cold plate.","summary":"Milk and sugar slowly reduce in a wide, open saucepan into a caramel-coloured spread. This method never heats a sealed can.\n\nMakes about 500 g, or 20 servings of 25 g. The 190-minute total includes 60 minutes of cooling; pan width and heat affect when it is ready.","category":"Desserts","category_slug":"postres","difficulty":"Medium","course":"Dessert","cuisine":"Latin American","prep_time_minutes":10,"cook_time_minutes":120,"total_time_minutes":190,"servings":20,"ingredients":[{"name":"whole milk","amount":"1000","unit":"ml","group":"Base"},{"name":"sugar","amount":"250","unit":"g","group":"Base"},{"name":"vanilla extract","amount":"5","unit":"ml","group":"Flavouring"}],"steps":[{"title":"Prepare the saucepan","content":"Measure 1 litre of whole milk and 250 g sugar. Choose a heavy-based saucepan holding at least 3 litres and a heatproof silicone spatula. Chill a small plate for testing the consistency.","image_url":"/recetas/receta-dulce-de-leche/paso-01.webp","image_alt":"Homemade dulce de leche: Prepare the saucepan"},{"title":"Dissolve the sugar","content":"Add the milk and 250 g sugar to the pan. Heat over medium heat for about 8 minutes, stirring until the sugar crystals dissolve. Fill the pan no more than halfway.","image_url":"/recetas/receta-dulce-de-leche/paso-02.webp","image_alt":"Homemade dulce de leche: Dissolve the sugar"},{"title":"Maintain a gentle simmer","content":"When the milk starts rising, immediately lower the heat. Keep the pan uncovered with small bubbles; scrape the base every 3–5 minutes during the first hour. If foam rises, briefly take the pan off the heat.","image_url":"/recetas/receta-dulce-de-leche/paso-03.webp","image_alt":"Homemade dulce de leche: Maintain a gentle simmer"},{"title":"Reduce the mixture","content":"Continue over low heat for another 40–60 minutes. As the mixture turns beige and thickens, scrape the base and corners every 1–2 minutes. Avoid vigorous boiling that could scorch the bottom.","image_url":"/recetas/receta-dulce-de-leche/paso-04.webp","image_alt":"Homemade dulce de leche: Reduce the mixture"},{"title":"Check the consistency","content":"Place a teaspoonful on the cold plate and wait 1 minute. It should move slowly when tilted and remain a little thinner than the finished spread. If it runs like milk, cook for another 5 minutes and repeat.","image_url":"/recetas/receta-dulce-de-leche/paso-05.webp","image_alt":"Homemade dulce de leche: Check the consistency"},{"title":"Add the vanilla","content":"Remove from the heat and stir in 5 ml vanilla extract for 1 minute. If small lumps form, whisk gently by hand until smooth without splashing.","image_url":"/recetas/receta-dulce-de-leche/paso-06.webp","image_alt":"Homemade dulce de leche: Add the vanilla"},{"title":"Cool without sealing","content":"Transfer to a clean, heatproof container and cool for 30 minutes, stirring occasionally. Refrigerate for another 30 minutes before judging the texture. Do not leave it out of the fridge for more than 2 hours.","image_url":"/recetas/receta-dulce-de-leche/paso-07.webp","image_alt":"Homemade dulce de leche: Cool without sealing"},{"title":"Store and serve","content":"Once cold, cover and refrigerate for up to 7 days. Serve roughly 25 g portions with a clean spoon. This is not a preserve that can be stored at room temperature.","image_url":"/recetas/receta-dulce-de-leche/paso-08.webp","image_alt":"Homemade dulce de leche: Store and serve"}],"notes":"For a thinner spread, stop cooking earlier; for a filling, reduce a little longer, remembering it thickens as it cools. If the base scorches, transfer without scraping burnt material. Lactose-free milk can brown differently, so watch the consistency. This version needs no baking soda.","nutrition":{"calories":81.0,"protein_g":1.6,"carbs_g":15.0,"fat_g":1.7,"saturated_fat_g":1.0,"fiber_g":0.0,"sugar_g":15.1,"sodium_mg":22.0,"serving_size":"1 of 20 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 20 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation."},"keywords":["homemade dulce de leche","dulce de leche saucepan","milk caramel spread"],"image_url":"/recetas/receta-dulce-de-leche/portada.webp","gallery":[{"url":"/recetas/receta-dulce-de-leche/portada.webp","alt":"Homemade dulce de leche: finished dish"}],"seo":{"title":"Homemade dulce de leche | Manual de Cocina","description":"Make dulce de leche in an open saucepan with whole milk, sugar and vanilla. Learn to reduce it gently and check its thickness on a cold plate.","image_alt":"Homemade dulce de leche: finished dish","image_variants":["/recetas/receta-dulce-de-leche/portada-1x1.webp","/recetas/receta-dulce-de-leche/portada-4x3.webp","/recetas/receta-dulce-de-leche/portada-16x9.webp"],"faq":[{"q":"Why is it runny when taken off the heat?","a":"It thickens as it cools. Use the cold-plate test before reducing it further so it does not become too firm."},{"q":"Can I reduce the sugar?","a":"This ratio was designed with 250 g. Reducing it changes texture, yield and storage; do not treat it as a shelf-stable preserve."},{"q":"How long does it keep in the fridge?","a":"Up to 7 days in a clean, covered container. Use clean utensils and discard it if its smell changes or mould appears."}]},"published":false,"editorial_status":"ready","content_html":"<p>Milk and sugar slowly reduce in a wide, open saucepan into a caramel-coloured spread. This method never heats a sealed can.</p><p>Makes about 500 g, or 20 servings of 25 g. The 190-minute total includes 60 minutes of cooling; pan width and heat affect when it is ready.</p>"},{"id":"96282523-dd3f-56ea-a081-11463ef9454a","recipe_group_id":"218f9269-b912-4ffe-b5d0-8cb1a74b53ed","slug":"confiture-de-lait-maison","public_path":"/fr/confiture-de-lait-maison","source_url":null,"language":"fr","title":"Dulce de leche maison","excerpt":"Confiture de lait maison au lait entier, sucre et vanille, cuite à découvert. Réduisez doucement et vérifiez la texture sur une assiette froide.","summary":"Le lait et le sucre réduisent lentement dans une casserole large et ouverte jusqu’à former une crème couleur caramel. Aucune boîte fermée n’est chauffée.\n\nEnviron 500 g, soit 20 portions de 25 g. Les 190 minutes comprennent 60 minutes de refroidissement; le diamètre de la casserole et le feu influencent le point final.","category":"Desserts","category_slug":"postres","difficulty":"Moyenne","course":"Dessert","cuisine":"Latino-américaine","prep_time_minutes":10,"cook_time_minutes":120,"total_time_minutes":190,"servings":20,"ingredients":[{"name":"lait entier","amount":"1000","unit":"ml","group":"Base"},{"name":"sucre","amount":"250","unit":"g","group":"Base"},{"name":"extrait de vanille","amount":"5","unit":"ml","group":"Arôme"}],"steps":[{"title":"Préparer la casserole","content":"Mesurez 1 litre de lait entier et 250 g de sucre. Préparez une casserole à fond épais d’au moins 3 litres et une spatule en silicone résistante à la chaleur. Placez une petite assiette au réfrigérateur.","image_url":"/recetas/receta-dulce-de-leche/paso-01.webp","image_alt":"Dulce de leche maison: Préparer la casserole"},{"title":"Dissoudre le sucre","content":"Versez le lait et les 250 g de sucre dans la casserole. Chauffez à feu moyen environ 8 minutes en remuant jusqu’à dissolution des cristaux. Ne remplissez pas au-delà de la moitié.","image_url":"/recetas/receta-dulce-de-leche/paso-02.webp","image_alt":"Dulce de leche maison: Dissoudre le sucre"},{"title":"Maintenir un léger frémissement","content":"Dès que le lait monte, baissez immédiatement le feu. Gardez de petites bulles et la casserole découverte; remuez le fond toutes les 3–5 minutes pendant la première heure. Si la mousse monte, retirez brièvement du feu.","image_url":"/recetas/receta-dulce-de-leche/paso-03.webp","image_alt":"Dulce de leche maison: Maintenir un léger frémissement"},{"title":"Faire réduire","content":"Poursuivez à feu doux 40–60 minutes. Dès que la préparation devient beige et épaisse, raclez le fond et les angles toutes les 1–2 minutes. Évitez une forte ébullition qui brûlerait le fond.","image_url":"/recetas/receta-dulce-de-leche/paso-04.webp","image_alt":"Dulce de leche maison: Faire réduire"},{"title":"Vérifier la consistance","content":"Déposez une cuillère à café sur l’assiette froide et attendez 1 minute. Elle doit couler lentement à l’inclinaison et rester un peu plus fluide que le résultat final. Si elle coule comme du lait, cuisez encore 5 minutes puis vérifiez.","image_url":"/recetas/receta-dulce-de-leche/paso-05.webp","image_alt":"Dulce de leche maison: Vérifier la consistance"},{"title":"Ajouter la vanille","content":"Hors du feu, incorporez 5 ml d’extrait de vanille pendant 1 minute. Lissez les petits grumeaux au fouet à main sans éclabousser.","image_url":"/recetas/receta-dulce-de-leche/paso-06.webp","image_alt":"Dulce de leche maison: Ajouter la vanille"},{"title":"Laisser refroidir sans fermer","content":"Transvasez dans un récipient propre résistant à la chaleur et laissez tiédir 30 minutes en remuant parfois. Réfrigérez encore 30 minutes avant d’évaluer la texture. Ne laissez pas plus de 2 heures hors du réfrigérateur.","image_url":"/recetas/receta-dulce-de-leche/paso-07.webp","image_alt":"Dulce de leche maison: Laisser refroidir sans fermer"},{"title":"Conserver et servir","content":"Une fois froide, couvrez et gardez jusqu’à 7 jours au réfrigérateur. Servez environ 25 g avec une cuillère propre. Ce produit n’est pas une conserve stable à température ambiante.","image_url":"/recetas/receta-dulce-de-leche/paso-08.webp","image_alt":"Dulce de leche maison: Conserver et servir"}],"notes":"Arrêtez plus tôt pour une texture fluide; pour une garniture, réduisez quelques minutes de plus, en tenant compte de l’épaississement à froid. Si le fond brûle, transvasez sans racler la partie brûlée. Le lait sans lactose peut dorer différemment: surveillez la texture. Pas de bicarbonate nécessaire.","nutrition":{"calories":81.0,"protein_g":1.6,"carbs_g":15.0,"fat_g":1.7,"saturated_fat_g":1.0,"fiber_g":0.0,"sugar_g":15.1,"sodium_mg":22.0,"serving_size":"1 des 20 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 20 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire."},"keywords":["confiture de lait maison","dulce de leche","caramel de lait"],"image_url":"/recetas/receta-dulce-de-leche/portada.webp","gallery":[{"url":"/recetas/receta-dulce-de-leche/portada.webp","alt":"Dulce de leche maison: plat terminé"}],"seo":{"title":"Dulce de leche maison | Manual de Cocina","description":"Confiture de lait maison au lait entier, sucre et vanille, cuite à découvert. Réduisez doucement et vérifiez la texture sur une assiette froide.","image_alt":"Dulce de leche maison: plat terminé","image_variants":["/recetas/receta-dulce-de-leche/portada-1x1.webp","/recetas/receta-dulce-de-leche/portada-4x3.webp","/recetas/receta-dulce-de-leche/portada-16x9.webp"],"faq":[{"q":"Pourquoi reste-t-elle liquide hors du feu?","a":"Elle épaissit en refroidissant. Faites le test de l’assiette froide avant de réduire davantage."},{"q":"Peut-on diminuer le sucre?","a":"Cette formule utilise 250 g. Une réduction modifie texture, rendement et conservation; ce n’est pas une conserve longue durée."},{"q":"Combien de temps se garde-t-elle?","a":"Jusqu’à 7 jours dans un récipient propre fermé au réfrigérateur. Utilisez des ustensiles propres; jetez en cas d’odeur différente ou de moisissure."}]},"published":false,"editorial_status":"ready","content_html":"<p>Le lait et le sucre réduisent lentement dans une casserole large et ouverte jusqu’à former une crème couleur caramel. Aucune boîte fermée n’est chauffée.</p><p>Environ 500 g, soit 20 portions de 25 g. Les 190 minutes comprennent 60 minutes de refroidissement; le diamètre de la casserole et le feu influencent le point final.</p>"},{"id":"eb4ff12d-80bc-5655-b87d-0659d3a900fc","recipe_group_id":"218f9269-b912-4ffe-b5d0-8cb1a74b53ed","slug":"dulce-de-leche-fatto-in-casa","public_path":"/it/dulce-de-leche-fatto-in-casa","source_url":null,"language":"it","title":"Dulce de leche fatto in casa","excerpt":"Dulce de leche in pentola aperta con latte intero, zucchero e vaniglia. Scopri come ridurlo senza bruciarlo e controllarne la consistenza.","summary":"Latte e zucchero si riducono lentamente in una pentola larga e aperta fino a diventare una crema color caramello. Non si riscalda mai una lattina chiusa.\n\nResa di circa 500 g, cioè 20 porzioni da 25 g. I 190 minuti totali comprendono 60 minuti di raffreddamento; diametro della pentola e intensità del fuoco influenzano il punto finale.","category":"Dolci","category_slug":"postres","difficulty":"Media","course":"Dolce","cuisine":"Latinoamericana","prep_time_minutes":10,"cook_time_minutes":120,"total_time_minutes":190,"servings":20,"ingredients":[{"name":"latte intero","amount":"1000","unit":"ml","group":"Base"},{"name":"zucchero","amount":"250","unit":"g","group":"Base"},{"name":"estratto di vaniglia","amount":"5","unit":"ml","group":"Aroma"}],"steps":[{"title":"Preparare la pentola","content":"Misura 1 litro di latte intero e 250 g di zucchero. Prepara una pentola a fondo spesso da almeno 3 litri e una spatola in silicone resistente al calore. Raffredda un piattino in frigorifero per la prova.","image_url":"/recetas/receta-dulce-de-leche/paso-01.webp","image_alt":"Dulce de leche fatto in casa: Preparare la pentola"},{"title":"Sciogliere lo zucchero","content":"Versa latte e 250 g di zucchero nella pentola. Scalda a fuoco medio per circa 8 minuti, mescolando finché i cristalli spariscono. Non riempire oltre metà.","image_url":"/recetas/receta-dulce-de-leche/paso-02.webp","image_alt":"Dulce de leche fatto in casa: Sciogliere lo zucchero"},{"title":"Mantenere un leggero bollore","content":"Quando il latte sale, abbassa subito il fuoco. Mantieni piccole bolle a pentola scoperta; mescola il fondo ogni 3–5 minuti durante la prima ora. Se la schiuma sale, togli brevemente dal fuoco.","image_url":"/recetas/receta-dulce-de-leche/paso-03.webp","image_alt":"Dulce de leche fatto in casa: Mantenere un leggero bollore"},{"title":"Far ridurre","content":"Continua a fuoco basso per altri 40–60 minuti. Quando la massa diventa beige e densa, raschia fondo e angoli ogni 1–2 minuti. Evita un bollore forte che bruci il fondo.","image_url":"/recetas/receta-dulce-de-leche/paso-04.webp","image_alt":"Dulce de leche fatto in casa: Far ridurre"},{"title":"Controllare la consistenza","content":"Metti un cucchiaino sul piattino freddo e aspetta 1 minuto. Inclinandolo deve scorrere lentamente, ancora un po’ più fluido del prodotto finale. Se scorre come latte, cuoci altri 5 minuti e ripeti.","image_url":"/recetas/receta-dulce-de-leche/paso-05.webp","image_alt":"Dulce de leche fatto in casa: Controllare la consistenza"},{"title":"Aggiungere la vaniglia","content":"Togli dal fuoco e incorpora 5 ml di estratto di vaniglia per 1 minuto. Sciogli eventuali piccoli grumi con una frusta a mano, senza schizzi.","image_url":"/recetas/receta-dulce-de-leche/paso-06.webp","image_alt":"Dulce de leche fatto in casa: Aggiungere la vaniglia"},{"title":"Lasciare raffreddare senza chiudere","content":"Trasferisci in un recipiente pulito resistente al calore e lascia intiepidire 30 minuti, mescolando ogni tanto. Raffredda in frigorifero altri 30 minuti prima di giudicare la consistenza. Non lasciarlo fuori oltre 2 ore.","image_url":"/recetas/receta-dulce-de-leche/paso-07.webp","image_alt":"Dulce de leche fatto in casa: Lasciare raffreddare senza chiudere"},{"title":"Conservare e servire","content":"Da freddo, copri e conserva in frigorifero fino a 7 giorni. Servi circa 25 g con un cucchiaio pulito. Non è una conserva stabile a temperatura ambiente.","image_url":"/recetas/receta-dulce-de-leche/paso-08.webp","image_alt":"Dulce de leche fatto in casa: Conservare e servire"}],"notes":"Per una crema più fluida interrompi prima; per un ripieno riduci qualche minuto in più, ricordando che addensa da fredda. Se il fondo brucia, travasa senza raschiare la parte bruciata. Il latte senza lattosio può colorire diversamente: controlla il punto. Qui non serve bicarbonato.","nutrition":{"calories":81.0,"protein_g":1.6,"carbs_g":15.0,"fat_g":1.7,"saturated_fat_g":1.0,"fiber_g":0.0,"sugar_g":15.1,"sodium_mg":22.0,"serving_size":"1 delle 20 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 20 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario."},"keywords":["dulce de leche fatto in casa","crema di latte caramellata","dulce de leche in pentola"],"image_url":"/recetas/receta-dulce-de-leche/portada.webp","gallery":[{"url":"/recetas/receta-dulce-de-leche/portada.webp","alt":"Dulce de leche fatto in casa: piatto pronto"}],"seo":{"title":"Dulce de leche fatto in casa | Manual de Cocina","description":"Dulce de leche in pentola aperta con latte intero, zucchero e vaniglia. Scopri come ridurlo senza bruciarlo e controllarne la consistenza.","image_alt":"Dulce de leche fatto in casa: piatto pronto","image_variants":["/recetas/receta-dulce-de-leche/portada-1x1.webp","/recetas/receta-dulce-de-leche/portada-4x3.webp","/recetas/receta-dulce-de-leche/portada-16x9.webp"],"faq":[{"q":"Perché è liquido quando spengo il fuoco?","a":"Addensa raffreddandosi. Usa la prova del piattino freddo prima di ridurre ancora."},{"q":"Posso diminuire lo zucchero?","a":"La proporzione prevista è 250 g. Ridurlo cambia consistenza, resa e conservazione; non considerarlo una conserva."},{"q":"Quanto dura in frigorifero?","a":"Fino a 7 giorni in un recipiente pulito e chiuso. Usa utensili puliti e scarta se l’odore cambia o compare muffa."}]},"published":false,"editorial_status":"ready","content_html":"<p>Latte e zucchero si riducono lentamente in una pentola larga e aperta fino a diventare una crema color caramello. Non si riscalda mai una lattina chiusa.</p><p>Resa di circa 500 g, cioè 20 porzioni da 25 g. I 190 minuti totali comprendono 60 minuti di raffreddamento; diametro della pentola e intensità del fuoco influenzano il punto finale.</p>"},{"id":"c3eefe56-146e-541e-a85c-2e8e5c86fb87","recipe_group_id":"218f9269-b912-4ffe-b5d0-8cb1a74b53ed","slug":"自家製ドゥルセデレチェ","public_path":"/ja/自家製ドゥルセデレチェ","source_url":null,"language":"ja","title":"自家製ドゥルセ・デ・レチェ","excerpt":"牛乳、砂糖、バニラで作るドゥルセ・デ・レチェ。ふたをしない鍋で煮詰め、冷たい皿でとろみを確認します。","summary":"牛乳と砂糖を広い鍋でゆっくり煮詰め、キャラメル色のクリームにします。密閉した缶を加熱する方法ではありません。\n\n約500 g、25 gずつ20人分が目安です。総時間190分には冷却60分を含みます。鍋の幅と火加減で煮詰まる時間は変わります。","category":"デザート","category_slug":"postres","difficulty":"普通","course":"デザート","cuisine":"中南米料理","prep_time_minutes":10,"cook_time_minutes":120,"total_time_minutes":190,"servings":20,"ingredients":[{"name":"成分無調整牛乳","amount":"1000","unit":"ml","group":"基本材料"},{"name":"砂糖","amount":"250","unit":"g","group":"基本材料"},{"name":"バニラエクストラクト","amount":"5","unit":"ml","group":"香り付け"}],"steps":[{"title":"鍋を用意する","content":"牛乳1リットルと砂糖250 gを量ります。容量3リットル以上の厚底鍋と耐熱シリコンへらを用意します。とろみの確認用に小皿を冷蔵庫で冷やします。","image_url":"/recetas/receta-dulce-de-leche/paso-01.webp","image_alt":"自家製ドゥルセ・デ・レチェ: 鍋を用意する"},{"title":"砂糖を溶かす","content":"鍋に牛乳と砂糖250 gを入れ、中火で約8分、砂糖の粒がなくなるまで混ぜて温めます。鍋には半分を超えて入れないでください。","image_url":"/recetas/receta-dulce-de-leche/paso-02.webp","image_alt":"自家製ドゥルセ・デ・レチェ: 砂糖を溶かす"},{"title":"弱く煮立てる","content":"牛乳がふき上がり始めたら、すぐ弱火にします。ふたをせず、小さな泡を保ちます。最初の1時間は3–5分おきに鍋底を混ぜ、泡が上がったら数秒火から離します。","image_url":"/recetas/receta-dulce-de-leche/paso-03.webp","image_alt":"自家製ドゥルセ・デ・レチェ: 弱く煮立てる"},{"title":"煮詰める","content":"さらに弱火で40–60分煮詰めます。ベージュ色になってとろみが付いたら、1–2分おきにへらで底と隅をなぞります。強く沸かして焦がさないようにします。","image_url":"/recetas/receta-dulce-de-leche/paso-04.webp","image_alt":"自家製ドゥルセ・デ・レチェ: 煮詰める"},{"title":"とろみを確認する","content":"冷たい皿に小さじ1杯を置き、1分待ちます。皿を傾けるとゆっくり動き、完成時より少しゆるい状態が目安です。牛乳のように流れるなら、5分煮て再確認します。","image_url":"/recetas/receta-dulce-de-leche/paso-05.webp","image_alt":"自家製ドゥルセ・デ・レチェ: とろみを確認する"},{"title":"バニラを加える","content":"火を止め、バニラエクストラクト5 mlを加えて1分混ぜます。小さな塊があれば、飛び散らないよう手動の泡立て器でなめらかにします。","image_url":"/recetas/receta-dulce-de-leche/paso-06.webp","image_alt":"自家製ドゥルセ・デ・レチェ: バニラを加える"},{"title":"密閉せずに冷ます","content":"清潔な耐熱容器に移して30分冷まし、時々混ぜます。その後冷蔵庫でさらに30分冷やしてから固さを判断します。冷蔵庫の外に2時間以上置かないでください。","image_url":"/recetas/receta-dulce-de-leche/paso-07.webp","image_alt":"自家製ドゥルセ・デ・レチェ: 密閉せずに冷ます"},{"title":"保存して盛り付ける","content":"冷めたらふたをし、冷蔵で最長7日保存します。清潔なスプーンで約25 gずつ取り分けます。常温保存できる瓶詰めではありません。","image_url":"/recetas/receta-dulce-de-leche/paso-08.webp","image_alt":"自家製ドゥルセ・デ・レチェ: 保存して盛り付ける"}],"notes":"ゆるめに仕上げたい場合は早めに火を止めます。フィリング用なら数分長く煮ますが、冷えると固くなることを考慮してください。底が焦げたら焦げをこそげず別の容器へ移します。乳糖除去牛乳は色付き方が変わるため、とろみを見て判断します。重曹は不要です。","nutrition":{"calories":81.0,"protein_g":1.6,"carbs_g":15.0,"fat_g":1.7,"saturated_fat_g":1.0,"fiber_g":0.0,"sugar_g":15.1,"sodium_mg":22.0,"serving_size":"全20人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を20人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。"},"keywords":["ドゥルセデレチェ","ミルクキャラメル","自家製ミルクジャム"],"image_url":"/recetas/receta-dulce-de-leche/portada.webp","gallery":[{"url":"/recetas/receta-dulce-de-leche/portada.webp","alt":"自家製ドゥルセ・デ・レチェ: 完成した料理"}],"seo":{"title":"自家製ドゥルセ・デ・レチェ | Manual de Cocina","description":"牛乳、砂糖、バニラで作るドゥルセ・デ・レチェ。ふたをしない鍋で煮詰め、冷たい皿でとろみを確認します。","image_alt":"自家製ドゥルセ・デ・レチェ: 完成した料理","image_variants":["/recetas/receta-dulce-de-leche/portada-1x1.webp","/recetas/receta-dulce-de-leche/portada-4x3.webp","/recetas/receta-dulce-de-leche/portada-16x9.webp"],"faq":[{"q":"火を止めたときにゆるいのはなぜですか？","a":"冷えると固くなります。煮詰めすぎないよう、冷たい皿で確認してください。"},{"q":"砂糖を減らせますか？","a":"この配合は250 gで設計しています。減らすと固さ、出来上がり量、保存性が変わります。常温保存用の加工品として扱わないでください。"},{"q":"冷蔵でどのくらい保存できますか？","a":"清潔なふた付き容器で最長7日です。清潔な器具を使い、においの変化やカビがあれば捨ててください。"}]},"published":false,"editorial_status":"ready","content_html":"<p>牛乳と砂糖を広い鍋でゆっくり煮詰め、キャラメル色のクリームにします。密閉した缶を加熱する方法ではありません。</p><p>約500 g、25 gずつ20人分が目安です。総時間190分には冷却60分を含みます。鍋の幅と火加減で煮詰まる時間は変わります。</p>"},{"id":"cbd0cbe9-5952-5256-baae-83966d7e87dd","recipe_group_id":"218f9269-b912-4ffe-b5d0-8cb1a74b53ed","slug":"doce-de-leite-caseiro","public_path":"/pt/doce-de-leite-caseiro","source_url":null,"language":"pt","title":"Doce de leite caseiro","excerpt":"Doce de leite caseiro em panela aberta, com leite integral, açúcar e baunilha. Aprenda a reduzir sem queimar e a testar o ponto no prato frio.","summary":"Leite e açúcar cozinham lentamente em panela larga e aberta até formar um creme cor de caramelo. Nenhuma lata fechada é aquecida.\n\nRende cerca de 500 g, ou 20 porções de 25 g. Os 190 minutos incluem 60 minutos de resfriamento; a largura da panela e o fogo alteram o ponto final.","category":"Sobremesas","category_slug":"postres","difficulty":"Média","course":"Sobremesa","cuisine":"Latino-americana","prep_time_minutes":10,"cook_time_minutes":120,"total_time_minutes":190,"servings":20,"ingredients":[{"name":"leite integral","amount":"1000","unit":"ml","group":"Base"},{"name":"açúcar","amount":"250","unit":"g","group":"Base"},{"name":"extrato de baunilha","amount":"5","unit":"ml","group":"Aroma"}],"steps":[{"title":"Prepare a panela","content":"Meça 1 litro de leite integral e 250 g de açúcar. Use panela de fundo grosso com pelo menos 3 litros e espátula de silicone resistente ao calor. Deixe um prato pequeno na geladeira para testar o ponto.","image_url":"/recetas/receta-dulce-de-leche/paso-01.webp","image_alt":"Doce de leite caseiro: Prepare a panela"},{"title":"Dissolva o açúcar","content":"Coloque leite e 250 g de açúcar na panela. Aqueça em fogo médio por cerca de 8 minutos, mexendo até dissolver os cristais. Não encha mais que a metade da panela.","image_url":"/recetas/receta-dulce-de-leche/paso-02.webp","image_alt":"Doce de leite caseiro: Dissolva o açúcar"},{"title":"Mantenha uma fervura suave","content":"Quando o leite começar a subir, abaixe imediatamente o fogo. Mantenha pequenas bolhas e a panela aberta; mexa o fundo a cada 3–5 minutos durante a primeira hora. Se a espuma subir, tire do fogo por alguns segundos.","image_url":"/recetas/receta-dulce-de-leche/paso-03.webp","image_alt":"Doce de leite caseiro: Mantenha uma fervura suave"},{"title":"Reduza a mistura","content":"Continue em fogo baixo por mais 40–60 minutos. Quando ficar bege e engrossar, raspe fundo e cantos com a espátula a cada 1–2 minutos. Evite fervura forte que queime o fundo.","image_url":"/recetas/receta-dulce-de-leche/paso-04.webp","image_alt":"Doce de leite caseiro: Reduza a mistura"},{"title":"Confira o ponto","content":"Ponha uma colher de chá no prato frio e espere 1 minuto. Ao inclinar, o doce deve correr devagar, ainda um pouco mais fluido que o resultado final. Se correr como leite, cozinhe mais 5 minutos e repita.","image_url":"/recetas/receta-dulce-de-leche/paso-05.webp","image_alt":"Doce de leite caseiro: Confira o ponto"},{"title":"Acrescente a baunilha","content":"Retire do fogo e misture 5 ml de extrato de baunilha por 1 minuto. Se houver pequenos grumos, alise com batedor manual sem espirrar.","image_url":"/recetas/receta-dulce-de-leche/paso-06.webp","image_alt":"Doce de leite caseiro: Acrescente a baunilha"},{"title":"Deixe esfriar sem vedar","content":"Transfira para recipiente limpo resistente ao calor e deixe amornar 30 minutos, mexendo às vezes. Leve à geladeira por mais 30 minutos antes de avaliar a textura. Não deixe fora da geladeira por mais de 2 horas.","image_url":"/recetas/receta-dulce-de-leche/paso-07.webp","image_alt":"Doce de leite caseiro: Deixe esfriar sem vedar"},{"title":"Guarde e sirva","content":"Depois de frio, tampe e conserve refrigerado por até 7 dias. Sirva cerca de 25 g com colher limpa. Esta receita não é uma conserva estável em temperatura ambiente.","image_url":"/recetas/receta-dulce-de-leche/paso-08.webp","image_alt":"Doce de leite caseiro: Guarde e sirva"}],"notes":"Para ficar mais fluido, retire antes; para recheio, reduza alguns minutos a mais, lembrando que engrossa ao esfriar. Se queimar no fundo, transfira sem raspar a parte queimada. Leite sem lactose pode dourar de outro modo: acompanhe o ponto. Não precisa de bicarbonato.","nutrition":{"calories":81.0,"protein_g":1.6,"carbs_g":15.0,"fat_g":1.7,"saturated_fat_g":1.0,"fiber_g":0.0,"sugar_g":15.1,"sodium_mg":22.0,"serving_size":"1 de 20 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 20 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário."},"keywords":["doce de leite caseiro","doce de leite na panela","leite e açúcar"],"image_url":"/recetas/receta-dulce-de-leche/portada.webp","gallery":[{"url":"/recetas/receta-dulce-de-leche/portada.webp","alt":"Doce de leite caseiro: prato pronto"}],"seo":{"title":"Doce de leite caseiro | Manual de Cocina","description":"Doce de leite caseiro em panela aberta, com leite integral, açúcar e baunilha. Aprenda a reduzir sem queimar e a testar o ponto no prato frio.","image_alt":"Doce de leite caseiro: prato pronto","image_variants":["/recetas/receta-dulce-de-leche/portada-1x1.webp","/recetas/receta-dulce-de-leche/portada-4x3.webp","/recetas/receta-dulce-de-leche/portada-16x9.webp"],"faq":[{"q":"Por que fica líquido ao sair do fogo?","a":"Ele engrossa ao esfriar. Faça o teste do prato frio antes de reduzir mais para não endurecer demais."},{"q":"Posso diminuir o açúcar?","a":"A proporção foi pensada com 250 g. Reduzir altera textura, rendimento e conservação; não trate como conserva de longa duração."},{"q":"Quanto tempo dura na geladeira?","a":"Até 7 dias em recipiente limpo e tampado. Use utensílios limpos e descarte se o cheiro mudar ou aparecer mofo."}]},"published":false,"editorial_status":"ready","content_html":"<p>Leite e açúcar cozinham lentamente em panela larga e aberta até formar um creme cor de caramelo. Nenhuma lata fechada é aquecida.</p><p>Rende cerca de 500 g, ou 20 porções de 25 g. Os 190 minutos incluem 60 minutos de resfriamento; a largura da panela e o fogo alteram o ponto final.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-dulce-de-leche') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

-- cheesecake-de-oreo-sin-horno
do $pub$
declare
  g constant uuid := 'a3e8d4de-d972-49a4-89e0-84800ae95b28';
  es_id constant uuid := 'f38efede-f854-45cc-8d6c-3ad972945b44';
  j constant jsonb := $j$[{"id":"f38efede-f854-45cc-8d6c-3ad972945b44","recipe_group_id":"a3e8d4de-d972-49a4-89e0-84800ae95b28","slug":"cheesecake-de-oreo-sin-horno","public_path":"/cheesecake-de-oreo-sin-horno","source_url":"https://manualdecocina.com/cheesecake-de-oreo-sin-horno/","language":"es","title":"Cheesecake de Oreo sin horno","excerpt":"Cheesecake de Oreo sin horno con base crujiente y relleno de queso crema. Molde de 20 cm, 12 porciones y reposo de 6 horas en la nevera.","summary":"La base combina galletas de chocolate con mantequilla y el relleno lleva queso crema, nata y gelatina sin sabor. Se refrigera sin hornear y se termina con galletas reservadas.\n\nUsa un molde desmontable de 20 cm y productos lácteos pasteurizados. Los 395 minutos incluyen 35 de preparación y al menos 360 de refrigeración.","category":"Postres","category_slug":"postres","difficulty":"Media","course":"Postre","cuisine":"Internacional","prep_time_minutes":35,"cook_time_minutes":0,"total_time_minutes":395,"servings":12,"ingredients":[{"name":"galletas Oreo o similares","amount":"300","unit":"g","group":"Base y relleno"},{"name":"mantequilla sin sal","amount":"70","unit":"g","group":"Base"},{"name":"queso crema","amount":"500","unit":"g","group":"Relleno"},{"name":"nata para montar, mínimo 35 % de grasa","amount":"250","unit":"ml","group":"Relleno"},{"name":"azúcar","amount":"80","unit":"g","group":"Relleno"},{"name":"gelatina sin sabor","amount":"8","unit":"g","group":"Relleno"},{"name":"agua fría","amount":"40","unit":"ml","group":"Relleno"}],"steps":[{"title":"Prepara el molde y las galletas","content":"Forra la base de un molde desmontable de 20 cm con papel de horno. Separa 200 g de galletas para la base, 80 g para el relleno y 20 g para decorar. Tritura los 200 g con su crema hasta obtener migas finas.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-01.webp","image_alt":"Cheesecake de Oreo sin horno: Prepara el molde y las galletas"},{"title":"Forma la base","content":"Derrite 70 g de mantequilla y mézclala con las migas. Reparte en el molde y presiona con un vaso hasta formar una base uniforme. Refrigera mientras preparas el relleno.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-02.webp","image_alt":"Cheesecake de Oreo sin horno: Forma la base"},{"title":"Hidrata la gelatina","content":"Espolvorea 8 g de gelatina sobre 40 ml de agua fría y deja reposar 10 minutos. No vuelques el agua sobre un bloque de gelatina, porque puede formar grumos.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-03.webp","image_alt":"Cheesecake de Oreo sin horno: Hidrata la gelatina"},{"title":"Alisa el queso","content":"Bate 500 g de queso crema pasteurizado con 80 g de azúcar durante 2 minutos. Usa queso que haya perdido el frío unos 15 minutos, no caliente, y detente cuando la mezcla esté lisa.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-04.webp","image_alt":"Cheesecake de Oreo sin horno: Alisa el queso"},{"title":"Monta la nata","content":"Bate 250 ml de nata fría hasta obtener picos suaves. Mantén las varillas y el bol fríos y detente antes de que se vuelva granulosa; suele tardar 2–4 minutos.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-05.webp","image_alt":"Cheesecake de Oreo sin horno: Monta la nata"},{"title":"Incorpora la gelatina y las galletas","content":"Calienta la gelatina hidratada en pulsos cortos de 5 segundos hasta que se disuelva, sin hervir. Mézclala primero con 2 cucharadas del queso y devuelve esa mezcla al bol. Añade la nata con movimientos envolventes y después los 80 g de galletas troceadas.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-06.webp","image_alt":"Cheesecake de Oreo sin horno: Incorpora la gelatina y las galletas"},{"title":"Rellena y refrigera","content":"Vierte el relleno sobre la base fría y alisa la superficie. Cubre y refrigera a 4 °C o menos durante al menos 6 horas; no lo cuajes en el congelador como sustituto de este reposo.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-07.webp","image_alt":"Cheesecake de Oreo sin horno: Rellena y refrigera"},{"title":"Desmolda y corta","content":"Pasa una espátula fina por el borde, abre el aro y decora con los 20 g de galletas reservados. Corta 12 porciones con un cuchillo limpio que seque entre cortes; conserva el resto en la nevera.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-08.webp","image_alt":"Cheesecake de Oreo sin horno: Desmolda y corta"}],"notes":"Conserva tapado y refrigerado hasta 3 días. No dejes el cheesecake más de 2 horas a temperatura ambiente. La nata ligera no monta igual; yogur y queso batido no sustituyen al queso crema en estas cantidades. Si necesitas una alternativa vegetariana a la gelatina, adapta el método a las instrucciones del gelificante; no hagas una sustitución directa por igual peso.","nutrition":{"calories":403.0,"protein_g":5.1,"carbs_g":27.3,"fat_g":31.4,"saturated_fat_g":17.6,"fiber_g":0.7,"sugar_g":19.0,"sodium_mg":235.0,"serving_size":"1 de 12 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 12 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma. Las galletas comerciales se aproximan con la ficha SR Legacy de galletas sándwich de chocolate; la marca concreta puede variar. Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"galletas Oreo o similares","edible_grams":300,"fdc_id":172718,"fdc_description":"Cookies, chocolate sandwich, with creme filling, regular","per_100g":{"sugar_g":40.67,"carbs_g":71.0,"fiber_g":2.9,"sodium_mg":388.0,"protein_g":5.21,"calories":464.0,"fat_g":19.14,"saturated_fat_g":5.649},"source_url":"https://fdc.nal.usda.gov/food-details/172718/nutrients"},{"ingredient":"mantequilla sin sal","edible_grams":70,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717.0,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0.0,"sodium_mg":11.0},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"queso crema","edible_grams":500,"fdc_id":173418,"fdc_description":"Cheese, cream","per_100g":{"protein_g":6.15,"saturated_fat_g":20.213,"fat_g":34.44,"carbs_g":5.52,"calories":350.0,"sugar_g":3.76,"sodium_mg":314.0,"fiber_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/173418/nutrients"},{"ingredient":"nata para montar, mínimo 35 % de grasa","edible_grams":250,"fdc_id":170859,"fdc_description":"Cream, fluid, heavy whipping","per_100g":{"fat_g":36.08,"calories":340.0,"sugar_g":2.92,"sodium_mg":27.0,"protein_g":2.84,"saturated_fat_g":23.032,"fiber_g":0.0,"carbs_g":2.84},"source_url":"https://fdc.nal.usda.gov/food-details/170859/nutrients"},{"ingredient":"azúcar","edible_grams":80,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"protein_g":0.0,"sodium_mg":1.0,"fat_g":0.0,"calories":387.0,"saturated_fat_g":0.0,"sugar_g":99.8,"carbs_g":99.98,"fiber_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"gelatina sin sabor","edible_grams":8,"fdc_id":169599,"fdc_description":"Gelatins, dry powder, unsweetened","per_100g":{"protein_g":85.6,"fiber_g":0.0,"sodium_mg":196.0,"saturated_fat_g":0.07,"fat_g":0.1,"carbs_g":0.0,"calories":335.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169599/nutrients"}]},"keywords":["cheesecake Oreo sin horno","tarta de galletas chocolate","cheesecake molde 20 cm"],"image_url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","gallery":[{"url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","alt":"Cheesecake de Oreo sin horno: plato terminado"}],"seo":{"title":"Cheesecake de Oreo sin horno | Manual de Cocina","description":"Cheesecake de Oreo sin horno con base crujiente y relleno de queso crema. Molde de 20 cm, 12 porciones y reposo de 6 horas en la nevera.","image_alt":"Cheesecake de Oreo sin horno: plato terminado","image_variants":["/recetas/cheesecake-de-oreo-sin-horno/portada-1x1.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-4x3.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-16x9.webp"],"faq":[{"q":"¿Puedo hacerlo sin gelatina?","a":"Esta fórmula usa gelatina para un corte estable. Omitirla requiere reformular el relleno, por lo que no se garantiza el mismo resultado."},{"q":"¿Se usan las galletas con su crema?","a":"Sí, se trituran enteras para la base y se trocean enteras para el relleno."},{"q":"¿Cuánto debe refrigerarse?","a":"Al menos 6 horas a 4 °C o menos; comprueba que el centro esté firme antes de desmoldar."}]},"published":false,"editorial_status":"ready","content_html":"<p>La base combina galletas de chocolate con mantequilla y el relleno lleva queso crema, nata y gelatina sin sabor. Se refrigera sin hornear y se termina con galletas reservadas.</p><p>Usa un molde desmontable de 20 cm y productos lácteos pasteurizados. Los 395 minutos incluyen 35 de preparación y al menos 360 de refrigeración.</p>"},{"id":"9ae6121d-c8db-5a26-bc76-3a7d9add8bc8","recipe_group_id":"a3e8d4de-d972-49a4-89e0-84800ae95b28","slug":"oreo-cheesecake-ohne-backen","public_path":"/de/oreo-cheesecake-ohne-backen","source_url":null,"language":"de","title":"Oreo-Cheesecake ohne Backen","excerpt":"Oreo-Cheesecake ohne Backen mit knusprigem Keksboden und Frischkäsefüllung. Für eine 20-cm-Form, 12 Stücke und mindestens 6 Stunden Kühlzeit.","summary":"Schokoladenkekse und Butter bilden den Boden; Frischkäse, Sahne und Gelatine die Füllung. Der Kuchen wird gekühlt und mit reservierten Keksen dekoriert.\n\nEine 20-cm-Springform und pasteurisierte Milchprodukte verwenden. Die 395 Minuten umfassen 35 Minuten Vorbereitung und mindestens 360 Minuten Kühlung.","category":"Desserts","category_slug":"postres","difficulty":"Mittel","course":"Dessert","cuisine":"International","prep_time_minutes":35,"cook_time_minutes":0,"total_time_minutes":395,"servings":12,"ingredients":[{"name":"Oreo-Kekse oder ähnliche Kekse","amount":"300","unit":"g","group":"Boden und Füllung"},{"name":"ungesalzene Butter","amount":"70","unit":"g","group":"Boden"},{"name":"Frischkäse","amount":"500","unit":"g","group":"Füllung"},{"name":"Schlagsahne mit mindestens 35 % Fett","amount":"250","unit":"ml","group":"Füllung"},{"name":"Zucker","amount":"80","unit":"g","group":"Füllung"},{"name":"geschmacksneutrale Gelatine","amount":"8","unit":"g","group":"Füllung"},{"name":"kaltes Wasser","amount":"40","unit":"ml","group":"Füllung"}],"steps":[{"title":"Form und Kekse vorbereiten","content":"Eine 20-cm-Springform am Boden mit Backpapier auslegen. 200 g Kekse für den Boden, 80 g für die Füllung und 20 g zum Dekorieren abteilen. Die 200 g samt Creme fein zerbröseln.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-01.webp","image_alt":"Oreo-Cheesecake ohne Backen: Form und Kekse vorbereiten"},{"title":"Boden formen","content":"70 g Butter schmelzen und unter die Krümel mischen. Im Formboden verteilen und mit einem Glas gleichmäßig festdrücken. Während der Füllungszubereitung kalt stellen.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-02.webp","image_alt":"Oreo-Cheesecake ohne Backen: Boden formen"},{"title":"Gelatine quellen lassen","content":"8 g Gelatine auf 40 ml kaltes Wasser streuen und 10 Minuten quellen lassen. Wasser nicht auf einen Gelatineklumpen gießen, damit keine Klümpchen entstehen.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-03.webp","image_alt":"Oreo-Cheesecake ohne Backen: Gelatine quellen lassen"},{"title":"Frischkäse glatt rühren","content":"500 g pasteurisierten Frischkäse mit 80 g Zucker 2 Minuten glatt rühren. Den Käse vorher etwa 15 Minuten temperieren, ohne ihn zu erwärmen; aufhören, sobald die Masse glatt ist.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-04.webp","image_alt":"Oreo-Cheesecake ohne Backen: Frischkäse glatt rühren"},{"title":"Sahne aufschlagen","content":"250 ml kalte Sahne 2–4 Minuten bis zu weichen Spitzen schlagen. Schüssel und Quirle kalt halten und vor einer körnigen Konsistenz stoppen.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-05.webp","image_alt":"Oreo-Cheesecake ohne Backen: Sahne aufschlagen"},{"title":"Gelatine und Kekse unterheben","content":"Gelatine in 5-Sekunden-Intervallen ohne Kochen auflösen. Erst mit 2 Esslöffeln Frischkäsemasse vermischen, dann zurückgeben. Sahne vorsichtig unterheben, danach 80 g grob zerkleinerte Kekse.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-06.webp","image_alt":"Oreo-Cheesecake ohne Backen: Gelatine und Kekse unterheben"},{"title":"Füllen und kühlen","content":"Füllung auf den kalten Boden geben und glatt streichen. Abgedeckt mindestens 6 Stunden bei höchstens 4 °C kühlen; das Gefrierfach ersetzt diese Ruhezeit nicht.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-07.webp","image_alt":"Oreo-Cheesecake ohne Backen: Füllen und kühlen"},{"title":"Ausformen und schneiden","content":"Mit einem dünnen Spatel den Rand lösen, Ring öffnen und mit 20 g Keksen dekorieren. Mit sauberem, zwischen den Schnitten abgetrocknetem Messer 12 Stücke schneiden. Reste kühl lagern.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-08.webp","image_alt":"Oreo-Cheesecake ohne Backen: Ausformen und schneiden"}],"notes":"Abgedeckt bis zu 3 Tage kühlen; nicht länger als 2 Stunden bei Raumtemperatur lassen. Leichte Sahne lässt sich nicht gleich schlagen, und Joghurt ersetzt in dieser Menge keinen Frischkäse. Ein vegetarisches Geliermittel nach dessen Anleitung verwenden, nicht gewichtsgleich austauschen.","nutrition":{"calories":403.0,"protein_g":5.1,"carbs_g":27.3,"fat_g":31.4,"saturated_fat_g":17.6,"fiber_g":0.7,"sugar_g":19.0,"sodium_mg":235.0,"serving_size":"1 von 12 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 12 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers. Die Kekse werden durch allgemeine SR-Legacy-Daten für Schokoladen-Sandwichkekse angenähert; die konkrete Marke kann abweichen."},"keywords":["Oreo-Cheesecake ohne Backen","Oreo-Torte","Frischkäsekuchen ohne Ofen"],"image_url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","gallery":[{"url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","alt":"Oreo-Cheesecake ohne Backen: fertiges Gericht"}],"seo":{"title":"Oreo-Cheesecake ohne Backen | Manual de Cocina","description":"Oreo-Cheesecake ohne Backen mit knusprigem Keksboden und Frischkäsefüllung. Für eine 20-cm-Form, 12 Stücke und mindestens 6 Stunden Kühlzeit.","image_alt":"Oreo-Cheesecake ohne Backen: fertiges Gericht","image_variants":["/recetas/cheesecake-de-oreo-sin-horno/portada-1x1.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-4x3.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-16x9.webp"],"faq":[{"q":"Geht es ohne Gelatine?","a":"Diese Füllung braucht Gelatine für einen stabilen Schnitt. Weglassen erfordert eine neue Rezeptur."},{"q":"Werden die Kekse samt Creme verwendet?","a":"Ja, für den Boden vollständig zerbröseln und für die Füllung vollständig zerkleinern."},{"q":"Wie lange kühlen?","a":"Mindestens 6 Stunden bei höchstens 4 °C; vor dem Ausformen prüfen, ob die Mitte fest ist."}]},"published":false,"editorial_status":"ready","content_html":"<p>Schokoladenkekse und Butter bilden den Boden; Frischkäse, Sahne und Gelatine die Füllung. Der Kuchen wird gekühlt und mit reservierten Keksen dekoriert.</p><p>Eine 20-cm-Springform und pasteurisierte Milchprodukte verwenden. Die 395 Minuten umfassen 35 Minuten Vorbereitung und mindestens 360 Minuten Kühlung.</p>"},{"id":"970fe140-6a4d-5e00-8d80-26be61db4cd2","recipe_group_id":"a3e8d4de-d972-49a4-89e0-84800ae95b28","slug":"no-bake-oreo-cheesecake","public_path":"/en/no-bake-oreo-cheesecake","source_url":null,"language":"en","title":"No-bake Oreo cheesecake","excerpt":"No-bake Oreo cheesecake with a crunchy cookie base and cream cheese filling. A 20 cm tin makes 12 slices after at least 6 hours in the fridge.","summary":"Chocolate cookies and butter make the base; cream cheese, whipping cream and gelatin form the filling. The cake sets in the fridge and is finished with reserved cookies.\n\nUse a 20 cm springform tin and pasteurised dairy. The 395-minute total includes 35 minutes of preparation and at least 360 minutes of chilling.","category":"Desserts","category_slug":"postres","difficulty":"Medium","course":"Dessert","cuisine":"International","prep_time_minutes":35,"cook_time_minutes":0,"total_time_minutes":395,"servings":12,"ingredients":[{"name":"Oreo cookies or similar","amount":"300","unit":"g","group":"Base and filling"},{"name":"unsalted butter","amount":"70","unit":"g","group":"Base"},{"name":"cream cheese","amount":"500","unit":"g","group":"Filling"},{"name":"whipping cream, at least 35 % fat","amount":"250","unit":"ml","group":"Filling"},{"name":"sugar","amount":"80","unit":"g","group":"Filling"},{"name":"unflavoured gelatin","amount":"8","unit":"g","group":"Filling"},{"name":"cold water","amount":"40","unit":"ml","group":"Filling"}],"steps":[{"title":"Prepare the tin and cookies","content":"Line the base of a 20 cm springform tin with baking paper. Set aside 200 g cookies for the base, 80 g for the filling and 20 g for decoration. Finely crush the 200 g with their cream centres.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-01.webp","image_alt":"No-bake Oreo cheesecake: Prepare the tin and cookies"},{"title":"Make the base","content":"Melt 70 g butter and mix into the crumbs. Spread in the tin and press evenly with a glass. Refrigerate while making the filling.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-02.webp","image_alt":"No-bake Oreo cheesecake: Make the base"},{"title":"Hydrate the gelatin","content":"Sprinkle 8 g gelatin over 40 ml cold water and leave for 10 minutes. Do not pour water onto a lump of gelatin, which may form clumps.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-03.webp","image_alt":"No-bake Oreo cheesecake: Hydrate the gelatin"},{"title":"Beat the cream cheese","content":"Beat 500 g pasteurised cream cheese with 80 g sugar for 2 minutes until smooth. Let the cheese lose its chill for about 15 minutes beforehand; do not warm it.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-04.webp","image_alt":"No-bake Oreo cheesecake: Beat the cream cheese"},{"title":"Whip the cream","content":"Whip 250 ml cold cream to soft peaks, usually 2–4 minutes. Keep bowl and beaters cold and stop before the cream becomes grainy.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-05.webp","image_alt":"No-bake Oreo cheesecake: Whip the cream"},{"title":"Fold in gelatin and cookies","content":"Dissolve the hydrated gelatin in short 5-second heating bursts without boiling. Mix first with 2 tablespoons of the cheese mixture, then return to the bowl. Fold in the cream and then 80 g broken cookies.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-06.webp","image_alt":"No-bake Oreo cheesecake: Fold in gelatin and cookies"},{"title":"Fill and refrigerate","content":"Pour the filling onto the cold base and smooth. Cover and refrigerate at 4 °C or below for at least 6 hours. Freezing is not a substitute for this setting time.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-07.webp","image_alt":"No-bake Oreo cheesecake: Fill and refrigerate"},{"title":"Unmould and slice","content":"Run a thin spatula around the edge, release the ring and decorate with the reserved 20 g cookies. Cut 12 slices using a clean knife, drying it between cuts. Refrigerate the remainder.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-08.webp","image_alt":"No-bake Oreo cheesecake: Unmould and slice"}],"notes":"Keep covered in the fridge for up to 3 days; do not leave at room temperature for more than 2 hours. Light cream does not whip the same way. Yogurt and soft quark are not direct substitutes for cream cheese here. Follow the manufacturer's method for a vegetarian setting agent rather than swapping equal weights.","nutrition":{"calories":403.0,"protein_g":5.1,"carbs_g":27.3,"fat_g":31.4,"saturated_fat_g":17.6,"fiber_g":0.7,"sugar_g":19.0,"sodium_mg":235.0,"serving_size":"1 of 12 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 12 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation. Cookies are approximated using generic SR Legacy chocolate sandwich cookie data; the actual brand may differ."},"keywords":["no-bake Oreo cheesecake","Oreo cookie cheesecake","cheesecake without oven"],"image_url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","gallery":[{"url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","alt":"No-bake Oreo cheesecake: finished dish"}],"seo":{"title":"No-bake Oreo cheesecake | Manual de Cocina","description":"No-bake Oreo cheesecake with a crunchy cookie base and cream cheese filling. A 20 cm tin makes 12 slices after at least 6 hours in the fridge.","image_alt":"No-bake Oreo cheesecake: finished dish","image_variants":["/recetas/cheesecake-de-oreo-sin-horno/portada-1x1.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-4x3.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-16x9.webp"],"faq":[{"q":"Can I leave out the gelatin?","a":"This formula uses gelatin for clean, stable slices. Omitting it requires reformulating the filling."},{"q":"Do I include the cookie cream centres?","a":"Yes, crush whole cookies for the base and break whole cookies for the filling."},{"q":"How long should it chill?","a":"At least 6 hours at 4 °C or below. Check that the centre is firm before releasing the tin."}]},"published":false,"editorial_status":"ready","content_html":"<p>Chocolate cookies and butter make the base; cream cheese, whipping cream and gelatin form the filling. The cake sets in the fridge and is finished with reserved cookies.</p><p>Use a 20 cm springform tin and pasteurised dairy. The 395-minute total includes 35 minutes of preparation and at least 360 minutes of chilling.</p>"},{"id":"ff5b93be-cb2f-5be6-8d47-e3f351bdba9f","recipe_group_id":"a3e8d4de-d972-49a4-89e0-84800ae95b28","slug":"cheesecake-oreo-sans-cuisson","public_path":"/fr/cheesecake-oreo-sans-cuisson","source_url":null,"language":"fr","title":"Cheesecake Oreo sans cuisson","excerpt":"Cheesecake Oreo sans cuisson, base croustillante et garniture au fromage frais. Moule de 20 cm, 12 parts et au moins 6 heures au réfrigérateur.","summary":"La base associe biscuits au chocolat et beurre; la garniture contient fromage frais, crème et gélatine. Le gâteau prend au réfrigérateur et se décore avec les biscuits réservés.\n\nUtilisez un moule à charnière de 20 cm et des produits laitiers pasteurisés. Les 395 minutes comprennent 35 minutes de préparation et au moins 360 minutes de réfrigération.","category":"Desserts","category_slug":"postres","difficulty":"Moyenne","course":"Dessert","cuisine":"Internationale","prep_time_minutes":35,"cook_time_minutes":0,"total_time_minutes":395,"servings":12,"ingredients":[{"name":"biscuits Oreo ou similaires","amount":"300","unit":"g","group":"Base et garniture"},{"name":"beurre doux","amount":"70","unit":"g","group":"Base"},{"name":"fromage frais à tartiner","amount":"500","unit":"g","group":"Garniture"},{"name":"crème à fouetter, au moins 35 % de matière grasse","amount":"250","unit":"ml","group":"Garniture"},{"name":"sucre","amount":"80","unit":"g","group":"Garniture"},{"name":"gélatine neutre","amount":"8","unit":"g","group":"Garniture"},{"name":"eau froide","amount":"40","unit":"ml","group":"Garniture"}],"steps":[{"title":"Préparer le moule et les biscuits","content":"Tapissez de papier cuisson le fond d’un moule à charnière de 20 cm. Réservez 200 g de biscuits pour la base, 80 g pour la garniture et 20 g pour décorer. Réduisez les 200 g entiers, crème comprise, en miettes fines.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-01.webp","image_alt":"Cheesecake Oreo sans cuisson: Préparer le moule et les biscuits"},{"title":"Former la base","content":"Faites fondre 70 g de beurre et mélangez aux miettes. Étalez dans le moule et tassez uniformément avec un verre. Réfrigérez pendant la préparation de la garniture.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-02.webp","image_alt":"Cheesecake Oreo sans cuisson: Former la base"},{"title":"Hydrater la gélatine","content":"Saupoudrez 8 g de gélatine sur 40 ml d’eau froide. Laissez gonfler 10 minutes; ne versez pas l’eau sur un bloc de gélatine pour éviter les grumeaux.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-03.webp","image_alt":"Cheesecake Oreo sans cuisson: Hydrater la gélatine"},{"title":"Lisser le fromage frais","content":"Fouettez 500 g de fromage frais pasteurisé avec 80 g de sucre pendant 2 minutes. Sortez le fromage environ 15 minutes avant, sans le chauffer, et arrêtez dès que la préparation est lisse.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-04.webp","image_alt":"Cheesecake Oreo sans cuisson: Lisser le fromage frais"},{"title":"Fouetter la crème","content":"Fouettez 250 ml de crème froide en pics souples, généralement 2–4 minutes. Gardez bol et fouets froids; arrêtez avant qu’elle ne devienne granuleuse.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-05.webp","image_alt":"Cheesecake Oreo sans cuisson: Fouetter la crème"},{"title":"Incorporer la gélatine et les biscuits","content":"Dissolvez la gélatine hydratée par impulsions de 5 secondes, sans bouillir. Mélangez d’abord avec 2 cuillères à soupe de fromage, puis remettez au bol. Incorporez délicatement la crème, puis 80 g de biscuits en morceaux.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-06.webp","image_alt":"Cheesecake Oreo sans cuisson: Incorporer la gélatine et les biscuits"},{"title":"Garnir et réfrigérer","content":"Versez sur la base froide et lissez. Couvrez et réfrigérez au moins 6 heures à 4 °C ou moins. Le congélateur ne remplace pas ce temps de prise.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-07.webp","image_alt":"Cheesecake Oreo sans cuisson: Garnir et réfrigérer"},{"title":"Démouler et couper","content":"Décollez le bord avec une spatule fine, ouvrez le cercle et décorez avec les 20 g de biscuits. Coupez 12 parts avec un couteau propre, séché entre les coupes. Gardez le reste au frais.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-08.webp","image_alt":"Cheesecake Oreo sans cuisson: Démouler et couper"}],"notes":"Conservez couvert au réfrigérateur jusqu’à 3 jours; pas plus de 2 heures à température ambiante. La crème légère ne monte pas de la même façon; yaourt et fromage blanc ne remplacent pas directement le fromage frais. Pour un gélifiant végétarien, suivez son mode d’emploi, sans substitution au même poids.","nutrition":{"calories":403.0,"protein_g":5.1,"carbs_g":27.3,"fat_g":31.4,"saturated_fat_g":17.6,"fiber_g":0.7,"sugar_g":19.0,"sodium_mg":235.0,"serving_size":"1 des 12 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 12 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire. Les biscuits sont approximés par les données SR Legacy de biscuits sandwich au chocolat; la marque peut modifier les valeurs."},"keywords":["cheesecake Oreo sans cuisson","gâteau Oreo","cheesecake au fromage frais"],"image_url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","gallery":[{"url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","alt":"Cheesecake Oreo sans cuisson: plat terminé"}],"seo":{"title":"Cheesecake Oreo sans cuisson | Manual de Cocina","description":"Cheesecake Oreo sans cuisson, base croustillante et garniture au fromage frais. Moule de 20 cm, 12 parts et au moins 6 heures au réfrigérateur.","image_alt":"Cheesecake Oreo sans cuisson: plat terminé","image_variants":["/recetas/cheesecake-de-oreo-sin-horno/portada-1x1.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-4x3.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-16x9.webp"],"faq":[{"q":"Peut-on omettre la gélatine?","a":"Elle stabilise les parts dans cette formule. L’omettre nécessite de reformuler la garniture."},{"q":"Utilise-t-on la crème des biscuits?","a":"Oui, les biscuits sont broyés ou cassés entiers, crème comprise."},{"q":"Quelle durée de réfrigération?","a":"Au moins 6 heures à 4 °C ou moins. Vérifiez que le centre est ferme avant de démouler."}]},"published":false,"editorial_status":"ready","content_html":"<p>La base associe biscuits au chocolat et beurre; la garniture contient fromage frais, crème et gélatine. Le gâteau prend au réfrigérateur et se décore avec les biscuits réservés.</p><p>Utilisez un moule à charnière de 20 cm et des produits laitiers pasteurisés. Les 395 minutes comprennent 35 minutes de préparation et au moins 360 minutes de réfrigération.</p>"},{"id":"54d7ee6d-c7d1-588d-8b60-189508457bc6","recipe_group_id":"a3e8d4de-d972-49a4-89e0-84800ae95b28","slug":"cheesecake-oreo-senza-cottura","public_path":"/it/cheesecake-oreo-senza-cottura","source_url":null,"language":"it","title":"Cheesecake Oreo senza cottura","excerpt":"Cheesecake Oreo senza cottura con base croccante e crema al formaggio. Stampo da 20 cm, 12 porzioni e almeno 6 ore in frigorifero.","summary":"Biscotti al cioccolato e burro formano la base; formaggio cremoso, panna e gelatina il ripieno. Si rassoda in frigorifero e si decora con i biscotti tenuti da parte.\n\nUsa uno stampo a cerniera da 20 cm e latticini pastorizzati. I 395 minuti comprendono 35 minuti di preparazione e almeno 360 di raffreddamento.","category":"Dolci","category_slug":"postres","difficulty":"Media","course":"Dolce","cuisine":"Internazionale","prep_time_minutes":35,"cook_time_minutes":0,"total_time_minutes":395,"servings":12,"ingredients":[{"name":"biscotti Oreo o simili","amount":"300","unit":"g","group":"Base e ripieno"},{"name":"burro non salato","amount":"70","unit":"g","group":"Base"},{"name":"formaggio fresco spalmabile","amount":"500","unit":"g","group":"Ripieno"},{"name":"panna da montare, almeno 35 % di grassi","amount":"250","unit":"ml","group":"Ripieno"},{"name":"zucchero","amount":"80","unit":"g","group":"Ripieno"},{"name":"gelatina neutra","amount":"8","unit":"g","group":"Ripieno"},{"name":"acqua fredda","amount":"40","unit":"ml","group":"Ripieno"}],"steps":[{"title":"Preparare stampo e biscotti","content":"Rivesti il fondo dello stampo da 20 cm con carta forno. Dividi i biscotti: 200 g per la base, 80 g per il ripieno, 20 g per decorare. Trita finemente i 200 g interi, crema compresa.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-01.webp","image_alt":"Cheesecake Oreo senza cottura: Preparare stampo e biscotti"},{"title":"Formare la base","content":"Sciogli 70 g di burro e mescola alle briciole. Distribuisci nello stampo e compatta con un bicchiere. Refrigeralo mentre prepari il ripieno.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-02.webp","image_alt":"Cheesecake Oreo senza cottura: Formare la base"},{"title":"Idratare la gelatina","content":"Cospargi 8 g di gelatina su 40 ml di acqua fredda e lascia 10 minuti. Non versare acqua su un blocco di gelatina, per evitare grumi.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-03.webp","image_alt":"Cheesecake Oreo senza cottura: Idratare la gelatina"},{"title":"Lavorare il formaggio","content":"Lavora 500 g di formaggio pastorizzato con 80 g di zucchero per 2 minuti. Lascia perdere il freddo al formaggio per circa 15 minuti, senza scaldarlo; fermati quando è liscio.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-04.webp","image_alt":"Cheesecake Oreo senza cottura: Lavorare il formaggio"},{"title":"Montare la panna","content":"Monta 250 ml di panna fredda a picchi morbidi, circa 2–4 minuti. Tieni freddi ciotola e fruste e fermati prima che diventi granulosa.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-05.webp","image_alt":"Cheesecake Oreo senza cottura: Montare la panna"},{"title":"Incorporare gelatina e biscotti","content":"Sciogli la gelatina idratata con impulsi di 5 secondi senza bollire. Mescolala prima con 2 cucchiai di crema di formaggio, poi rimettila nel composto. Incorpora delicatamente panna e 80 g di biscotti spezzati.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-06.webp","image_alt":"Cheesecake Oreo senza cottura: Incorporare gelatina e biscotti"},{"title":"Riempire e refrigerare","content":"Versa sulla base fredda e livella. Copri e refrigera almeno 6 ore a 4 °C o meno. Il congelatore non sostituisce questo riposo.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-07.webp","image_alt":"Cheesecake Oreo senza cottura: Riempire e refrigerare"},{"title":"Sformare e tagliare","content":"Passa una spatola sottile lungo il bordo, apri l’anello e decora con 20 g di biscotti. Taglia 12 fette con coltello pulito asciugato tra i tagli. Conserva il resto in frigorifero.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-08.webp","image_alt":"Cheesecake Oreo senza cottura: Sformare e tagliare"}],"notes":"Coperta in frigorifero dura fino a 3 giorni; non lasciarla a temperatura ambiente oltre 2 ore. La panna leggera non monta ugualmente. Yogurt e formaggio magro non sono sostituti diretti. Per un gelificante vegetariano segui le sue istruzioni, senza sostituire lo stesso peso.","nutrition":{"calories":403.0,"protein_g":5.1,"carbs_g":27.3,"fat_g":31.4,"saturated_fat_g":17.6,"fiber_g":0.7,"sugar_g":19.0,"sodium_mg":235.0,"serving_size":"1 delle 12 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 12 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario. I biscotti sono approssimati con dati SR Legacy di biscotti sandwich al cioccolato; la marca effettiva può variare."},"keywords":["cheesecake Oreo senza cottura","torta Oreo","cheesecake senza forno"],"image_url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","gallery":[{"url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","alt":"Cheesecake Oreo senza cottura: piatto pronto"}],"seo":{"title":"Cheesecake Oreo senza cottura | Manual de Cocina","description":"Cheesecake Oreo senza cottura con base croccante e crema al formaggio. Stampo da 20 cm, 12 porzioni e almeno 6 ore in frigorifero.","image_alt":"Cheesecake Oreo senza cottura: piatto pronto","image_variants":["/recetas/cheesecake-de-oreo-sin-horno/portada-1x1.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-4x3.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-16x9.webp"],"faq":[{"q":"Posso omettere la gelatina?","a":"In questa formula garantisce fette stabili. Ometterla richiede di riformulare il ripieno."},{"q":"Uso anche la crema dei biscotti?","a":"Sì, trita o spezza i biscotti interi, crema compresa."},{"q":"Quanto deve raffreddare?","a":"Almeno 6 ore a 4 °C o meno; verifica che il centro sia sodo prima di sformare."}]},"published":false,"editorial_status":"ready","content_html":"<p>Biscotti al cioccolato e burro formano la base; formaggio cremoso, panna e gelatina il ripieno. Si rassoda in frigorifero e si decora con i biscotti tenuti da parte.</p><p>Usa uno stampo a cerniera da 20 cm e latticini pastorizzati. I 395 minuti comprendono 35 minuti di preparazione e almeno 360 di raffreddamento.</p>"},{"id":"c93bc167-d3e6-53ec-82d7-bd9c6f4d28fe","recipe_group_id":"a3e8d4de-d972-49a4-89e0-84800ae95b28","slug":"焼かないオレオチーズケーキ","public_path":"/ja/焼かないオレオチーズケーキ","source_url":null,"language":"ja","title":"焼かないオレオチーズケーキ","excerpt":"サクッとしたオレオの土台となめらかなチーズクリーム。20 cm型で12切れ、冷蔵庫で最低6時間冷やす焼かないケーキです。","summary":"チョコレートクッキーとバターで土台を作り、クリームチーズ、生クリーム、ゼラチンを詰めます。冷蔵庫で固め、取り分けたクッキーで飾ります。\n\n底が外れる20 cm型と加熱殺菌済みの乳製品を使います。総時間395分には準備35分と冷却最低360分を含みます。","category":"デザート","category_slug":"postres","difficulty":"普通","course":"デザート","cuisine":"世界の料理","prep_time_minutes":35,"cook_time_minutes":0,"total_time_minutes":395,"servings":12,"ingredients":[{"name":"オレオまたは同様のクッキー","amount":"300","unit":"g","group":"土台・フィリング"},{"name":"無塩バター","amount":"70","unit":"g","group":"土台"},{"name":"クリームチーズ","amount":"500","unit":"g","group":"フィリング"},{"name":"乳脂肪35 %以上の生クリーム","amount":"250","unit":"ml","group":"フィリング"},{"name":"砂糖","amount":"80","unit":"g","group":"フィリング"},{"name":"無味のゼラチン","amount":"8","unit":"g","group":"フィリング"},{"name":"冷水","amount":"40","unit":"ml","group":"フィリング"}],"steps":[{"title":"型とクッキーを用意する","content":"20 cm型の底にオーブンシートを敷きます。クッキーを土台200 g、フィリング80 g、飾り20 gに分けます。200 gを中のクリームごと細かく砕きます。","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-01.webp","image_alt":"焼かないオレオチーズケーキ: 型とクッキーを用意する"},{"title":"土台を作る","content":"バター70 gを溶かしてクッキーの粉と混ぜます。型に広げ、グラスで均一に押し固め、フィリングを作る間冷蔵します。","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-02.webp","image_alt":"焼かないオレオチーズケーキ: 土台を作る"},{"title":"ゼラチンをふやかす","content":"冷水40 mlにゼラチン8 gを振り入れ、10分ふやかします。ゼラチンの塊に水をかけるとダマになるため避けます。","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-03.webp","image_alt":"焼かないオレオチーズケーキ: ゼラチンをふやかす"},{"title":"クリームチーズを混ぜる","content":"加熱殺菌済みクリームチーズ500 gと砂糖80 gを2分混ぜます。チーズは約15分前に出して冷たさを和らげ、加熱せず、なめらかになったら止めます。","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-04.webp","image_alt":"焼かないオレオチーズケーキ: クリームチーズを混ぜる"},{"title":"生クリームを泡立てる","content":"冷たい生クリーム250 mlを2–4分、柔らかな角が立つまで泡立てます。ボウルと泡立て器も冷やし、ざらつく前に止めます。","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-05.webp","image_alt":"焼かないオレオチーズケーキ: 生クリームを泡立てる"},{"title":"ゼラチンとクッキーを加える","content":"ゼラチンを5秒ずつ短く加熱して溶かし、沸騰させません。チーズ生地大さじ2と先に混ぜてから全体へ戻します。生クリームを折り込み、クッキー80 gを加えます。","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-06.webp","image_alt":"焼かないオレオチーズケーキ: ゼラチンとクッキーを加える"},{"title":"型に入れて冷やす","content":"冷えた土台に生地を流し、表面をならします。覆って4 °C以下で最低6時間冷蔵します。冷凍庫で固める方法でこの休ませ時間を代用しないでください。","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-07.webp","image_alt":"焼かないオレオチーズケーキ: 型に入れて冷やす"},{"title":"型から外して切る","content":"薄いへらで縁を外し、型の輪を開き、クッキー20 gで飾ります。清潔な包丁を切るたびに拭いて12切れにします。残りは冷蔵します。","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-08.webp","image_alt":"焼かないオレオチーズケーキ: 型から外して切る"}],"notes":"覆って冷蔵で最長3日保存し、常温で2時間以上置きません。低脂肪クリームは同様に泡立たず、ヨーグルトは同量のチーズ代替になりません。植物性凝固剤は製品の使い方に合わせ、同じ重量で置換しないでください。","nutrition":{"calories":403.0,"protein_g":5.1,"carbs_g":27.3,"fat_g":31.4,"saturated_fat_g":17.6,"fiber_g":0.7,"sugar_g":19.0,"sodium_mg":235.0,"serving_size":"全12人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を12人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。 クッキーはSR Legacyの一般的なチョコレートサンドクッキーで近似しています。実際の製品で変わります。"},"keywords":["オレオチーズケーキ","焼かないケーキ","クッキーチーズケーキ"],"image_url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","gallery":[{"url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","alt":"焼かないオレオチーズケーキ: 完成した料理"}],"seo":{"title":"焼かないオレオチーズケーキ | Manual de Cocina","description":"サクッとしたオレオの土台となめらかなチーズクリーム。20 cm型で12切れ、冷蔵庫で最低6時間冷やす焼かないケーキです。","image_alt":"焼かないオレオチーズケーキ: 完成した料理","image_variants":["/recetas/cheesecake-de-oreo-sin-horno/portada-1x1.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-4x3.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-16x9.webp"],"faq":[{"q":"ゼラチンを抜けますか？","a":"この配合では切り分けを安定させるため使います。抜く場合はフィリングの配合変更が必要です。"},{"q":"クッキーの中のクリームも使いますか？","a":"はい。土台もフィリングもクッキーをクリームごと使います。"},{"q":"どのくらい冷やしますか？","a":"4 °C以下で最低6時間です。中央が固まってから型を外します。"}]},"published":false,"editorial_status":"ready","content_html":"<p>チョコレートクッキーとバターで土台を作り、クリームチーズ、生クリーム、ゼラチンを詰めます。冷蔵庫で固め、取り分けたクッキーで飾ります。</p><p>底が外れる20 cm型と加熱殺菌済みの乳製品を使います。総時間395分には準備35分と冷却最低360分を含みます。</p>"},{"id":"2bf00b51-1b08-5020-93ca-28baa2a4a7fc","recipe_group_id":"a3e8d4de-d972-49a4-89e0-84800ae95b28","slug":"cheesecake-de-oreo-sem-forno","public_path":"/pt/cheesecake-de-oreo-sem-forno","source_url":null,"language":"pt","title":"Cheesecake de Oreo sem forno","excerpt":"Cheesecake de Oreo sem forno, base crocante e recheio de cream cheese. Forma de 20 cm, 12 fatias e pelo menos 6 horas de geladeira.","summary":"Biscoitos de chocolate e manteiga formam a base; cream cheese, creme de leite fresco e gelatina compõem o recheio. Ele firma na geladeira e recebe os biscoitos reservados.\n\nUse forma de fundo removível de 20 cm e laticínios pasteurizados. Os 395 minutos incluem 35 de preparo e pelo menos 360 de refrigeração.","category":"Sobremesas","category_slug":"postres","difficulty":"Média","course":"Sobremesa","cuisine":"Internacional","prep_time_minutes":35,"cook_time_minutes":0,"total_time_minutes":395,"servings":12,"ingredients":[{"name":"biscoitos Oreo ou similares","amount":"300","unit":"g","group":"Base e recheio"},{"name":"manteiga sem sal","amount":"70","unit":"g","group":"Base"},{"name":"cream cheese","amount":"500","unit":"g","group":"Recheio"},{"name":"creme de leite fresco para bater, mínimo 35 % de gordura","amount":"250","unit":"ml","group":"Recheio"},{"name":"açúcar","amount":"80","unit":"g","group":"Recheio"},{"name":"gelatina sem sabor","amount":"8","unit":"g","group":"Recheio"},{"name":"água fria","amount":"40","unit":"ml","group":"Recheio"}],"steps":[{"title":"Prepare a forma e os biscoitos","content":"Forre o fundo da forma de 20 cm com papel-manteiga. Separe 200 g de biscoitos para a base, 80 g para o recheio e 20 g para decorar. Triture os 200 g inteiros, com o creme, em migalhas finas.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-01.webp","image_alt":"Cheesecake de Oreo sem forno: Prepare a forma e os biscoitos"},{"title":"Faça a base","content":"Derreta 70 g de manteiga e misture às migalhas. Distribua na forma e pressione uniformemente com um copo. Refrigere enquanto prepara o recheio.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-02.webp","image_alt":"Cheesecake de Oreo sem forno: Faça a base"},{"title":"Hidrate a gelatina","content":"Polvilhe 8 g de gelatina sobre 40 ml de água fria e espere 10 minutos. Não despeje água sobre um bloco de gelatina, evitando grumos.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-03.webp","image_alt":"Cheesecake de Oreo sem forno: Hidrate a gelatina"},{"title":"Bata o cream cheese","content":"Bata 500 g de cream cheese pasteurizado com 80 g de açúcar por 2 minutos. Tire o queijo do frio cerca de 15 minutos antes, sem aquecer; pare quando estiver liso.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-04.webp","image_alt":"Cheesecake de Oreo sem forno: Bata o cream cheese"},{"title":"Bata o creme de leite","content":"Bata 250 ml de creme de leite fresco frio até picos suaves, normalmente 2–4 minutos. Mantenha tigela e batedores frios e pare antes de ficar granulado.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-05.webp","image_alt":"Cheesecake de Oreo sem forno: Bata o creme de leite"},{"title":"Incorpore gelatina e biscoitos","content":"Dissolva a gelatina hidratada em pulsos de 5 segundos, sem ferver. Misture primeiro com 2 colheres de sopa do creme de queijo e devolva à tigela. Incorpore delicadamente o creme batido e 80 g de biscoitos quebrados.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-06.webp","image_alt":"Cheesecake de Oreo sem forno: Incorpore gelatina e biscoitos"},{"title":"Recheie e leve à geladeira","content":"Despeje sobre a base fria e alise. Cubra e refrigere por pelo menos 6 horas a 4 °C ou menos. Congelar não substitui esse repouso.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-07.webp","image_alt":"Cheesecake de Oreo sem forno: Recheie e leve à geladeira"},{"title":"Desenforme e corte","content":"Solte a borda com espátula fina, abra o aro e decore com 20 g de biscoitos. Corte 12 fatias com faca limpa, seca entre os cortes. Guarde o restante refrigerado.","image_url":"/recetas/cheesecake-de-oreo-sin-horno/paso-08.webp","image_alt":"Cheesecake de Oreo sem forno: Desenforme e corte"}],"notes":"Conserve coberto na geladeira por até 3 dias; não deixe mais de 2 horas em temperatura ambiente. Creme de leite leve não bate igual; iogurte não substitui diretamente o cream cheese. Para gelificante vegetariano, adapte ao fabricante, sem trocar pelo mesmo peso.","nutrition":{"calories":403.0,"protein_g":5.1,"carbs_g":27.3,"fat_g":31.4,"saturated_fat_g":17.6,"fiber_g":0.7,"sugar_g":19.0,"sodium_mg":235.0,"serving_size":"1 de 12 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 12 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário. Os biscoitos são aproximados por dados SR Legacy de biscoito recheado de chocolate; a marca pode variar."},"keywords":["cheesecake de Oreo sem forno","torta Oreo","cheesecake sem assar"],"image_url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","gallery":[{"url":"/recetas/cheesecake-de-oreo-sin-horno/portada.webp","alt":"Cheesecake de Oreo sem forno: prato pronto"}],"seo":{"title":"Cheesecake de Oreo sem forno | Manual de Cocina","description":"Cheesecake de Oreo sem forno, base crocante e recheio de cream cheese. Forma de 20 cm, 12 fatias e pelo menos 6 horas de geladeira.","image_alt":"Cheesecake de Oreo sem forno: prato pronto","image_variants":["/recetas/cheesecake-de-oreo-sin-horno/portada-1x1.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-4x3.webp","/recetas/cheesecake-de-oreo-sin-horno/portada-16x9.webp"],"faq":[{"q":"Posso fazer sem gelatina?","a":"Esta fórmula usa gelatina para fatias firmes. Omitir exige reformular o recheio."},{"q":"Uso o creme dos biscoitos?","a":"Sim, eles são triturados ou quebrados inteiros, com o creme."},{"q":"Quanto tempo precisa de geladeira?","a":"Pelo menos 6 horas a 4 °C ou menos. Confira se o centro está firme antes de desenformar."}]},"published":false,"editorial_status":"ready","content_html":"<p>Biscoitos de chocolate e manteiga formam a base; cream cheese, creme de leite fresco e gelatina compõem o recheio. Ele firma na geladeira e recebe os biscoitos reservados.</p><p>Use forma de fundo removível de 20 cm e laticínios pasteurizados. Os 395 minutos incluem 35 de preparo e pelo menos 360 de refrigeração.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/cheesecake-de-oreo-sin-horno') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

-- receta-de-salchichas-alemanas
do $pub$
declare
  g constant uuid := '04460456-460a-4002-9026-f422dd7a5388';
  es_id constant uuid := '4af5552f-a808-46e0-b838-c33cb6f10473';
  j constant jsonb := $j$[{"id":"4af5552f-a808-46e0-b838-c33cb6f10473","recipe_group_id":"04460456-460a-4002-9026-f422dd7a5388","slug":"receta-de-salchichas-alemanas","public_path":"/receta-de-salchichas-alemanas","source_url":"https://manualdecocina.com/receta-de-salchichas-alemanas/","language":"es","title":"Salchichas alemanas caseras tipo bratwurst","excerpt":"Salchichas caseras tipo bratwurst con cerdo, mejorana y nuez moscada. Aprende a mantener la mezcla fría, embutir y cocer hasta 71 °C.","summary":"Esta propuesta casera combina paleta de cerdo, grasa dorsal y especias, sin curado ni fermentación. Requiere picadora, embutidora y tripa natural de cerdo apta para alimentos.\n\nRinde 8 salchichas grandes. Mantener carne, grasa y utensilios fríos ayuda a ligar la mezcla; los 100 minutos incluyen 30 minutos de enfriado.","category":"Platos principales","category_slug":"platos-principales","difficulty":"Media","course":"Plato principal","cuisine":"Alemana","prep_time_minutes":45,"cook_time_minutes":25,"total_time_minutes":100,"servings":8,"ingredients":[{"name":"paleta de cerdo sin hueso","amount":"700","unit":"g","group":"Masa"},{"name":"grasa dorsal de cerdo","amount":"300","unit":"g","group":"Masa"},{"name":"agua con hielo","amount":"100","unit":"ml","group":"Masa"},{"name":"sal","amount":"16","unit":"g","group":"Especias"},{"name":"pimienta blanca molida","amount":"2","unit":"g","group":"Especias"},{"name":"mejorana seca","amount":"2","unit":"g","group":"Especias"},{"name":"nuez moscada molida","amount":"1","unit":"g","group":"Especias"},{"name":"tripa natural de cerdo de 28–32 mm","amount":"2","unit":"m","group":"Embutido"},{"name":"aceite vegetal","amount":"5","unit":"g","group":"Dorado"}],"steps":[{"title":"Prepara la tripa y los utensilios","content":"Aclara 2 m de tripa siguiendo las instrucciones del proveedor, incluida la limpieza interior, y mantenla en agua limpia. Enfría 15 minutos las piezas de la picadora y el bol. Mantén la carne refrigerada a 4 °C o menos.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-01.webp","image_alt":"Salchichas alemanas caseras tipo bratwurst: Prepara la tripa y los utensilios"},{"title":"Corta y enfría la carne","content":"Corta 700 g de paleta y 300 g de grasa dorsal en dados de 2 cm. Extiéndelos separados en una bandeja y enfría 30 minutos en la nevera; deben estar muy fríos sin llegar a un bloque congelado.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-02.webp","image_alt":"Salchichas alemanas caseras tipo bratwurst: Corta y enfría la carne"},{"title":"Pica la mezcla","content":"Pasa carne y grasa por el disco de 4–5 mm hacia el bol frío. Si se calientan o la grasa se embarra, detén el trabajo y vuelve a enfriar antes de continuar.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-03.webp","image_alt":"Salchichas alemanas caseras tipo bratwurst: Pica la mezcla"},{"title":"Liga y sazona","content":"Añade 16 g de sal, 2 g de pimienta blanca, 2 g de mejorana y 1 g de nuez moscada. Mezcla 3–4 minutos agregando poco a poco 100 ml de agua helada hasta que la masa esté pegajosa. Conserva en frío.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-04.webp","image_alt":"Salchichas alemanas caseras tipo bratwurst: Liga y sazona"},{"title":"Comprueba la sazón","content":"Cocina una cucharadita de masa en una sartén hasta que el centro alcance 71 °C, y pruébala solo después de cocinarla. Ajusta especias si hace falta; cualquier cambio de sal altera la estimación nutricional.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-05.webp","image_alt":"Salchichas alemanas caseras tipo bratwurst: Comprueba la sazón"},{"title":"Embute y forma las piezas","content":"Coloca la tripa en la boquilla y rellena sin apretar en exceso. Divide en 8 piezas de longitud similar girando los extremos en sentidos alternos. Pincha únicamente las bolsas de aire con una aguja limpia.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-06.webp","image_alt":"Salchichas alemanas caseras tipo bratwurst: Embute y forma las piezas"},{"title":"Cuece con control de temperatura","content":"Pon las salchichas en agua a 80 °C, sin hervor fuerte. Cocina unos 15–20 minutos hasta que una pieza medida por el centro alcance al menos 71 °C. El tiempo depende del grosor: manda el termómetro.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-07.webp","image_alt":"Salchichas alemanas caseras tipo bratwurst: Cuece con control de temperatura"},{"title":"Dora y sirve","content":"Escurre y seca con papel limpio. Dora con 5 g de aceite en sartén durante 4–5 minutos, girando las piezas. Sirve enseguida; el dorado final no sustituye la cocción hasta 71 °C.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-08.webp","image_alt":"Salchichas alemanas caseras tipo bratwurst: Dora y sirve"}],"notes":"No es un producto curado: no secar ni almacenar a temperatura ambiente. Refrigera las salchichas crudas y cocínalas en 24 horas, o congela hasta 2 meses. Las cocidas se conservan refrigeradas hasta 3 días; recalienta hasta 74 °C. La pimienta blanca se aproxima nutricionalmente con pimienta negra; tripa y agua se excluyen por su aporte mínimo. No sustituyas por carne de ave manteniendo el mismo objetivo de temperatura.","nutrition":{"calories":518.0,"protein_g":16.2,"carbs_g":0.4,"fat_g":49.7,"saturated_fat_g":17.6,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":836.0,"serving_size":"1 de 8 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 8 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma. Se contabilizan toda la grasa y el aceite; parte puede escurrir. La tripa se omite, y la pimienta blanca se aproxima con pimienta negra. Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"paleta de cerdo sin hueso","edible_grams":700,"fdc_id":167843,"fdc_description":"Pork, fresh, shoulder, whole, separable lean and fat, raw","per_100g":{"sugar_g":0.0,"fat_g":17.99,"carbs_g":0.0,"calories":236.0,"saturated_fat_g":6.24,"fiber_g":0.0,"sodium_mg":65.0,"protein_g":17.18},"source_url":"https://fdc.nal.usda.gov/food-details/167843/nutrients"},{"ingredient":"grasa dorsal de cerdo","edible_grams":300,"fdc_id":167811,"fdc_description":"Pork, fresh, backfat, raw","per_100g":{"sugar_g":0.0,"fiber_g":0.0,"sodium_mg":11.0,"protein_g":2.92,"saturated_fat_g":32.21,"fat_g":88.69,"carbs_g":0.0,"calories":812.0},"source_url":"https://fdc.nal.usda.gov/food-details/167811/nutrients"},{"ingredient":"sal","edible_grams":16,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0.0,"sodium_mg":38758.0,"saturated_fat_g":0.0,"protein_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"pimienta blanca molida","edible_grams":2,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":63.95,"calories":251.0,"protein_g":10.39,"fiber_g":25.3,"sodium_mg":20.0,"saturated_fat_g":1.392},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"mejorana seca","edible_grams":2,"fdc_id":170928,"fdc_description":"Spices, marjoram, dried","per_100g":{"fat_g":7.04,"carbs_g":60.56,"calories":271.0,"sodium_mg":77.0,"protein_g":12.66,"fiber_g":40.3,"saturated_fat_g":0.529,"sugar_g":4.09},"source_url":"https://fdc.nal.usda.gov/food-details/170928/nutrients"},{"ingredient":"nuez moscada molida","edible_grams":1,"fdc_id":171326,"fdc_description":"Spices, nutmeg, ground","per_100g":{"protein_g":5.84,"sodium_mg":16.0,"saturated_fat_g":25.94,"fat_g":36.31,"carbs_g":49.29,"calories":525.0,"sugar_g":2.99,"fiber_g":20.8},"source_url":"https://fdc.nal.usda.gov/food-details/171326/nutrients"},{"ingredient":"aceite vegetal","edible_grams":5,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"fat_g":100.0,"saturated_fat_g":7.365,"protein_g":0.0,"carbs_g":0.0,"calories":884.0,"fiber_g":0.0,"sodium_mg":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"}]},"keywords":["bratwurst casera","salchichas de cerdo caseras","embutir salchichas"],"image_url":"/recetas/receta-de-salchichas-alemanas/portada.webp","gallery":[{"url":"/recetas/receta-de-salchichas-alemanas/portada.webp","alt":"Salchichas alemanas caseras tipo bratwurst: plato terminado"}],"seo":{"title":"Salchichas alemanas caseras tipo bratwurst | Manual de Cocina","description":"Salchichas caseras tipo bratwurst con cerdo, mejorana y nuez moscada. Aprende a mantener la mezcla fría, embutir y cocer hasta 71 °C.","image_alt":"Salchichas alemanas caseras tipo bratwurst: plato terminado","image_variants":["/recetas/receta-de-salchichas-alemanas/portada-1x1.webp","/recetas/receta-de-salchichas-alemanas/portada-4x3.webp","/recetas/receta-de-salchichas-alemanas/portada-16x9.webp"],"faq":[{"q":"¿Puedo usar carne picada comprada?","a":"Sí, si conoces su proporción de grasa y se mantiene bien fría. Necesitas ajustar la grasa añadida; esta fórmula está calculada para paleta y grasa dorsal."},{"q":"¿Por qué la mezcla debe estar fría?","a":"El frío ayuda a mantener la grasa separada durante el picado y a obtener una masa ligada, sin que se embarren los utensilios."},{"q":"¿Son salchichas curadas?","a":"No. Se cocinan hasta 71 °C y se guardan refrigeradas o congeladas; no se dejan madurar a temperatura ambiente."}]},"published":false,"editorial_status":"ready","content_html":"<p>Esta propuesta casera combina paleta de cerdo, grasa dorsal y especias, sin curado ni fermentación. Requiere picadora, embutidora y tripa natural de cerdo apta para alimentos.</p><p>Rinde 8 salchichas grandes. Mantener carne, grasa y utensilios fríos ayuda a ligar la mezcla; los 100 minutos incluyen 30 minutos de enfriado.</p>"},{"id":"b239b910-8987-5cf0-b662-ad54d146ca56","recipe_group_id":"04460456-460a-4002-9026-f422dd7a5388","slug":"bratwurst-selber-machen","public_path":"/de/bratwurst-selber-machen","source_url":null,"language":"de","title":"Bratwurst selbst gemacht","excerpt":"Frische Bratwurst aus Schweineschulter, Rückenspeck und Gewürzen: kalt verarbeiten, in Naturdarm füllen und bis 71 °C Kerntemperatur garen.","summary":"Frische, weder gepökelte noch fermentierte Würste aus Schulter und Rückenspeck. Fleischwolf, Wurstfüller und lebensmittelechter Schweinedarm sind nötig.\n\nErgibt 8 große Würste. Fleisch, Fett und Werkzeuge kalt halten. 100 Minuten Gesamtzeit enthalten 30 Minuten Kühlung.","category":"Hauptgerichte","category_slug":"platos-principales","difficulty":"Mittel","course":"Hauptgericht","cuisine":"Deutsch","prep_time_minutes":45,"cook_time_minutes":25,"total_time_minutes":100,"servings":8,"ingredients":[{"name":"Schweineschulter ohne Knochen","amount":"700","unit":"g","group":"Wurstmasse"},{"name":"Schweinerückenspeck","amount":"300","unit":"g","group":"Wurstmasse"},{"name":"Eiswasser","amount":"100","unit":"ml","group":"Wurstmasse"},{"name":"Salz","amount":"16","unit":"g","group":"Gewürze"},{"name":"gemahlener weißer Pfeffer","amount":"2","unit":"g","group":"Gewürze"},{"name":"getrockneter Majoran","amount":"2","unit":"g","group":"Gewürze"},{"name":"gemahlene Muskatnuss","amount":"1","unit":"g","group":"Gewürze"},{"name":"Schweinenaturdarm, 28–32 mm","amount":"2","unit":"m","group":"Hülle"},{"name":"Pflanzenöl","amount":"5","unit":"g","group":"Braten"}],"steps":[{"title":"Darm und Geräte vorbereiten","content":"2 m Darm nach Herstellerangaben außen und innen spülen und in sauberem Wasser halten. Wolfteile und Schüssel 15 Minuten kühlen; Fleisch bei höchstens 4 °C lagern.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-01.webp","image_alt":"Bratwurst selbst gemacht: Darm und Geräte vorbereiten"},{"title":"Fleisch schneiden und kühlen","content":"700 g Schulter und 300 g Rückenspeck in 2-cm-Würfel schneiden. Getrennt auf einem Blech 30 Minuten kühlen: sehr kalt, aber nicht als gefrorener Block.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-02.webp","image_alt":"Bratwurst selbst gemacht: Fleisch schneiden und kühlen"},{"title":"Mischung wolfen","content":"Fleisch und Speck durch die 4–5-mm-Scheibe in die kalte Schüssel drehen. Bei Erwärmung oder schmierendem Fett stoppen und erneut kühlen.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-03.webp","image_alt":"Bratwurst selbst gemacht: Mischung wolfen"},{"title":"Binden und würzen","content":"16 g Salz, 2 g weißen Pfeffer, 2 g Majoran und 1 g Muskat zugeben. 3–4 Minuten mischen und nach und nach 100 ml Eiswasser einarbeiten, bis die Masse klebt. Kühl halten.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-04.webp","image_alt":"Bratwurst selbst gemacht: Binden und würzen"},{"title":"Würzung prüfen","content":"Einen Teelöffel Masse in der Pfanne bis 71 °C im Kern garen, erst dann probieren. Gewürze gegebenenfalls anpassen; zusätzliche Salzmenge verändert die Nährwerte.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-05.webp","image_alt":"Bratwurst selbst gemacht: Würzung prüfen"},{"title":"Füllen und abdrehen","content":"Darm aufziehen und locker füllen. Durch abwechselndes Drehen 8 gleich lange Würste bilden. Nur Luftblasen mit sauberer Nadel anstechen.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-06.webp","image_alt":"Bratwurst selbst gemacht: Füllen und abdrehen"},{"title":"Mit Temperaturkontrolle garen","content":"In 80 °C heißem Wasser ohne starkes Kochen etwa 15–20 Minuten garen, bis eine im Zentrum gemessene Wurst mindestens 71 °C erreicht. Die Dicke bestimmt die Zeit: Thermometer verwenden.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-07.webp","image_alt":"Bratwurst selbst gemacht: Mit Temperaturkontrolle garen"},{"title":"Bräunen und servieren","content":"Abtropfen und mit sauberem Papier trocknen. Mit 5 g Öl 4–5 Minuten unter Wenden bräunen und sofort servieren. Bräunen ersetzt das Garen bis 71 °C nicht.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-08.webp","image_alt":"Bratwurst selbst gemacht: Bräunen und servieren"}],"notes":"Nicht gepökelt: weder trocknen noch ungekühlt lagern. Roh gekühlt innerhalb 24 Stunden garen oder bis 2 Monate einfrieren. Gegart gekühlt bis 3 Tage lagern und auf 74 °C erwärmen. Weißer Pfeffer wird mit schwarzem angenähert; Darm und Wasser sind ausgenommen. Bei Geflügel gilt nicht dasselbe Temperaturziel.","nutrition":{"calories":518.0,"protein_g":16.2,"carbs_g":0.4,"fat_g":49.7,"saturated_fat_g":17.6,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":836.0,"serving_size":"1 von 8 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 8 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers. Alles Fett und Öl wird gezählt, obwohl es teilweise abtropft. Darm ist ausgenommen; weißer Pfeffer wird mit schwarzem angenähert."},"keywords":["Bratwurst selber machen","frische Schweinebratwurst","Bratwurst Naturdarm"],"image_url":"/recetas/receta-de-salchichas-alemanas/portada.webp","gallery":[{"url":"/recetas/receta-de-salchichas-alemanas/portada.webp","alt":"Bratwurst selbst gemacht: fertiges Gericht"}],"seo":{"title":"Bratwurst selbst gemacht | Manual de Cocina","description":"Frische Bratwurst aus Schweineschulter, Rückenspeck und Gewürzen: kalt verarbeiten, in Naturdarm füllen und bis 71 °C Kerntemperatur garen.","image_alt":"Bratwurst selbst gemacht: fertiges Gericht","image_variants":["/recetas/receta-de-salchichas-alemanas/portada-1x1.webp","/recetas/receta-de-salchichas-alemanas/portada-4x3.webp","/recetas/receta-de-salchichas-alemanas/portada-16x9.webp"],"faq":[{"q":"Geht gekauftes Hackfleisch?","a":"Bei bekannter Fettmenge und kalter Verarbeitung; zusätzliches Fett entsprechend anpassen."},{"q":"Warum so kalt arbeiten?","a":"Damit Fett beim Wolfen nicht schmiert und eine gebundene Masse entsteht."},{"q":"Sind diese Würste gepökelt?","a":"Nein. Bis 71 °C garen und gekühlt oder gefroren lagern; nicht ungekühlt reifen lassen."}]},"published":false,"editorial_status":"ready","content_html":"<p>Frische, weder gepökelte noch fermentierte Würste aus Schulter und Rückenspeck. Fleischwolf, Wurstfüller und lebensmittelechter Schweinedarm sind nötig.</p><p>Ergibt 8 große Würste. Fleisch, Fett und Werkzeuge kalt halten. 100 Minuten Gesamtzeit enthalten 30 Minuten Kühlung.</p>"},{"id":"c490fef3-a677-5df1-8138-2be766ed1e44","recipe_group_id":"04460456-460a-4002-9026-f422dd7a5388","slug":"homemade-german-sausages","public_path":"/en/homemade-german-sausages","source_url":null,"language":"en","title":"Homemade bratwurst-style sausages","excerpt":"Fresh German-style pork sausages with shoulder, back fat and spices. Grind cold, fill natural casings and cook to a 71 °C centre.","summary":"These fresh pork sausages are neither cured nor fermented. You need a meat grinder, sausage stuffer and food-grade natural pork casing.\n\nMakes 8 large sausages. Keep meat, fat and equipment cold; the 100-minute total includes 30 minutes of chilling.","category":"Main dishes","category_slug":"platos-principales","difficulty":"Medium","course":"Main course","cuisine":"German","prep_time_minutes":45,"cook_time_minutes":25,"total_time_minutes":100,"servings":8,"ingredients":[{"name":"boneless pork shoulder","amount":"700","unit":"g","group":"Sausage mixture"},{"name":"pork back fat","amount":"300","unit":"g","group":"Sausage mixture"},{"name":"ice water","amount":"100","unit":"ml","group":"Sausage mixture"},{"name":"salt","amount":"16","unit":"g","group":"Spices"},{"name":"ground white pepper","amount":"2","unit":"g","group":"Spices"},{"name":"dried marjoram","amount":"2","unit":"g","group":"Spices"},{"name":"ground nutmeg","amount":"1","unit":"g","group":"Spices"},{"name":"natural pork casing, 28–32 mm","amount":"2","unit":"m","group":"Casing"},{"name":"vegetable oil","amount":"5","unit":"g","group":"Browning"}],"steps":[{"title":"Prepare the casings and equipment","content":"Rinse 2 m casing inside and out as the supplier directs and keep in clean water. Chill grinder parts and bowl for 15 minutes. Keep meat at 4 °C or below.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-01.webp","image_alt":"Homemade bratwurst-style sausages: Prepare the casings and equipment"},{"title":"Cut and chill the meat","content":"Cut 700 g shoulder and 300 g back fat into 2 cm cubes. Spread separately on a tray and refrigerate 30 minutes: very cold, not a frozen block.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-02.webp","image_alt":"Homemade bratwurst-style sausages: Cut and chill the meat"},{"title":"Grind the mixture","content":"Grind meat and fat through a 4–5 mm plate into the cold bowl. If they warm or fat smears, stop and chill again.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-03.webp","image_alt":"Homemade bratwurst-style sausages: Grind the mixture"},{"title":"Mix and season","content":"Add 16 g salt, 2 g white pepper, 2 g marjoram and 1 g nutmeg. Mix 3–4 minutes, gradually adding 100 ml ice water until sticky. Keep cold.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-04.webp","image_alt":"Homemade bratwurst-style sausages: Mix and season"},{"title":"Check the seasoning","content":"Cook a teaspoonful in a pan to 71 °C at the centre, then taste. Adjust spices if needed; any extra salt changes the nutrition estimate.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-05.webp","image_alt":"Homemade bratwurst-style sausages: Check the seasoning"},{"title":"Fill and form the sausages","content":"Slide casing onto the nozzle and fill without packing tightly. Twist alternately to make 8 similar-length links. Prick only air pockets with a clean needle.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-06.webp","image_alt":"Homemade bratwurst-style sausages: Fill and form the sausages"},{"title":"Cook with temperature control","content":"Poach in water at 80 °C without vigorous boiling for about 15–20 minutes, until a link measures at least 71 °C in the centre. Thickness affects time: use a thermometer.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-07.webp","image_alt":"Homemade bratwurst-style sausages: Cook with temperature control"},{"title":"Brown and serve","content":"Drain and dry with clean paper. Brown in 5 g oil for 4–5 minutes, turning, then serve immediately. Browning does not replace reaching 71 °C.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-08.webp","image_alt":"Homemade bratwurst-style sausages: Brown and serve"}],"notes":"Not cured: do not dry or store at room temperature. Cook refrigerated raw links within 24 hours or freeze for up to 2 months. Cooked links keep refrigerated 3 days; reheat to 74 °C. White pepper is approximated with black; casing and water are excluded. Do not substitute poultry while retaining the same temperature target.","nutrition":{"calories":518.0,"protein_g":16.2,"carbs_g":0.4,"fat_g":49.7,"saturated_fat_g":17.6,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":836.0,"serving_size":"1 of 8 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 8 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation. All fat and oil are counted although some may drain away. Casing is omitted and white pepper is approximated with black pepper."},"keywords":["homemade German sausages","fresh bratwurst","pork sausage natural casing"],"image_url":"/recetas/receta-de-salchichas-alemanas/portada.webp","gallery":[{"url":"/recetas/receta-de-salchichas-alemanas/portada.webp","alt":"Homemade bratwurst-style sausages: finished dish"}],"seo":{"title":"Homemade bratwurst-style sausages | Manual de Cocina","description":"Fresh German-style pork sausages with shoulder, back fat and spices. Grind cold, fill natural casings and cook to a 71 °C centre.","image_alt":"Homemade bratwurst-style sausages: finished dish","image_variants":["/recetas/receta-de-salchichas-alemanas/portada-1x1.webp","/recetas/receta-de-salchichas-alemanas/portada-4x3.webp","/recetas/receta-de-salchichas-alemanas/portada-16x9.webp"],"faq":[{"q":"Can I use bought minced pork?","a":"Yes, if its fat ratio is known and it stays cold. Adjust the added fat; this formula uses shoulder and back fat."},{"q":"Why must the mixture stay cold?","a":"It keeps fat from smearing during grinding and helps the mixture bind."},{"q":"Are these cured sausages?","a":"No. Cook to 71 °C and refrigerate or freeze; do not mature them at room temperature."}]},"published":false,"editorial_status":"ready","content_html":"<p>These fresh pork sausages are neither cured nor fermented. You need a meat grinder, sausage stuffer and food-grade natural pork casing.</p><p>Makes 8 large sausages. Keep meat, fat and equipment cold; the 100-minute total includes 30 minutes of chilling.</p>"},{"id":"02577eb1-5d0f-5603-81ab-ce718e9ea7e7","recipe_group_id":"04460456-460a-4002-9026-f422dd7a5388","slug":"saucisses-allemandes-maison","public_path":"/fr/saucisses-allemandes-maison","source_url":null,"language":"fr","title":"Saucisses maison façon bratwurst","excerpt":"Saucisses allemandes fraîches à l’épaule de porc, gras dorsal et épices. Travaillez à froid, embossez en boyau et cuisez à 71 °C à cœur.","summary":"Saucisses fraîches, sans salaison ni fermentation, à l’épaule de porc et au gras dorsal. Il faut un hachoir, un poussoir et du boyau de porc alimentaire.\n\nPour 8 grandes saucisses. Gardez ingrédients et matériel froids; les 100 minutes comprennent 30 minutes de refroidissement.","category":"Plats principaux","category_slug":"platos-principales","difficulty":"Moyenne","course":"Plat principal","cuisine":"Allemande","prep_time_minutes":45,"cook_time_minutes":25,"total_time_minutes":100,"servings":8,"ingredients":[{"name":"épaule de porc désossée","amount":"700","unit":"g","group":"Farce"},{"name":"gras dorsal de porc","amount":"300","unit":"g","group":"Farce"},{"name":"eau glacée","amount":"100","unit":"ml","group":"Farce"},{"name":"sel","amount":"16","unit":"g","group":"Épices"},{"name":"poivre blanc moulu","amount":"2","unit":"g","group":"Épices"},{"name":"marjolaine séchée","amount":"2","unit":"g","group":"Épices"},{"name":"muscade moulue","amount":"1","unit":"g","group":"Épices"},{"name":"boyau naturel de porc, 28–32 mm","amount":"2","unit":"m","group":"Boyau"},{"name":"huile végétale","amount":"5","unit":"g","group":"Dorage"}],"steps":[{"title":"Préparer le boyau et le matériel","content":"Rincez 2 m de boyau, intérieur compris, selon le fournisseur et gardez dans l’eau propre. Refroidissez hachoir et bol 15 minutes; gardez la viande à 4 °C ou moins.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-01.webp","image_alt":"Saucisses maison façon bratwurst: Préparer le boyau et le matériel"},{"title":"Couper et refroidir la viande","content":"Coupez 700 g d’épaule et 300 g de gras en dés de 2 cm. Étalez séparément et réfrigérez 30 minutes, très froids sans former un bloc gelé.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-02.webp","image_alt":"Saucisses maison façon bratwurst: Couper et refroidir la viande"},{"title":"Hacher le mélange","content":"Hachez avec une grille de 4–5 mm dans le bol froid. Si la viande chauffe ou le gras s’étale, arrêtez et refroidissez à nouveau.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-03.webp","image_alt":"Saucisses maison façon bratwurst: Hacher le mélange"},{"title":"Lier et assaisonner","content":"Ajoutez 16 g de sel, 2 g de poivre blanc, 2 g de marjolaine et 1 g de muscade. Mélangez 3–4 minutes avec 100 ml d’eau glacée versée progressivement, jusqu’à une farce collante. Gardez au froid.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-04.webp","image_alt":"Saucisses maison façon bratwurst: Lier et assaisonner"},{"title":"Vérifier l’assaisonnement","content":"Cuisez une cuillère à café de farce à 71 °C à cœur avant de goûter. Ajustez les épices si nécessaire; tout ajout de sel modifie la nutrition.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-05.webp","image_alt":"Saucisses maison façon bratwurst: Vérifier l’assaisonnement"},{"title":"Embosser et former","content":"Enfilez le boyau sur l’embout et remplissez sans trop serrer. Formez 8 pièces similaires en torsadant alternativement. Percez seulement les poches d’air avec une aiguille propre.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-06.webp","image_alt":"Saucisses maison façon bratwurst: Embosser et former"},{"title":"Cuire avec contrôle de température","content":"Pochez dans une eau à 80 °C, sans forte ébullition, 15–20 minutes environ jusqu’à au moins 71 °C au centre d’une saucisse. L’épaisseur change la durée: le thermomètre fait foi.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-07.webp","image_alt":"Saucisses maison façon bratwurst: Cuire avec contrôle de température"},{"title":"Dorer et servir","content":"Égouttez et séchez avec du papier propre. Dorez dans 5 g d’huile 4–5 minutes en tournant et servez immédiatement. Le dorage ne remplace pas la cuisson à 71 °C.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-08.webp","image_alt":"Saucisses maison façon bratwurst: Dorer et servir"}],"notes":"Ce n’est pas une salaison: ne pas sécher ni conserver à température ambiante. Cuisez les saucisses crues réfrigérées sous 24 heures ou congelez jusqu’à 2 mois. Cuites, gardez 3 jours au froid et réchauffez à 74 °C. Poivre blanc approximé par le noir; boyau et eau exclus. La volaille nécessite un autre seuil de cuisson.","nutrition":{"calories":518.0,"protein_g":16.2,"carbs_g":0.4,"fat_g":49.7,"saturated_fat_g":17.6,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":836.0,"serving_size":"1 des 8 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 8 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire. Tout le gras et l’huile sont comptés malgré un éventuel égouttage; boyau exclu et poivre blanc approximé par le noir."},"keywords":["saucisses allemandes maison","bratwurst fraîche","saucisse de porc en boyau"],"image_url":"/recetas/receta-de-salchichas-alemanas/portada.webp","gallery":[{"url":"/recetas/receta-de-salchichas-alemanas/portada.webp","alt":"Saucisses maison façon bratwurst: plat terminé"}],"seo":{"title":"Saucisses maison façon bratwurst | Manual de Cocina","description":"Saucisses allemandes fraîches à l’épaule de porc, gras dorsal et épices. Travaillez à froid, embossez en boyau et cuisez à 71 °C à cœur.","image_alt":"Saucisses maison façon bratwurst: plat terminé","image_variants":["/recetas/receta-de-salchichas-alemanas/portada-1x1.webp","/recetas/receta-de-salchichas-alemanas/portada-4x3.webp","/recetas/receta-de-salchichas-alemanas/portada-16x9.webp"],"faq":[{"q":"Peut-on acheter la viande déjà hachée?","a":"Oui, si son taux de gras est connu et si elle reste froide; ajustez le gras ajouté."},{"q":"Pourquoi garder la farce froide?","a":"Le gras reste séparé au hachage et la farce se lie sans s’étaler sur le matériel."},{"q":"Sont-elles des saucisses de salaison?","a":"Non: cuisson à 71 °C, puis réfrigération ou congélation. Pas de maturation à température ambiante."}]},"published":false,"editorial_status":"ready","content_html":"<p>Saucisses fraîches, sans salaison ni fermentation, à l’épaule de porc et au gras dorsal. Il faut un hachoir, un poussoir et du boyau de porc alimentaire.</p><p>Pour 8 grandes saucisses. Gardez ingrédients et matériel froids; les 100 minutes comprennent 30 minutes de refroidissement.</p>"},{"id":"68d17ba7-a382-554f-a48d-e5d30f0a1ed2","recipe_group_id":"04460456-460a-4002-9026-f422dd7a5388","slug":"salsicce-tedesche-fatte-in-casa","public_path":"/it/salsicce-tedesche-fatte-in-casa","source_url":null,"language":"it","title":"Salsicce fatte in casa tipo bratwurst","excerpt":"Salsicce tedesche fresche con spalla di maiale, grasso dorsale e spezie. Lavora a freddo, insacca e cuoci fino a 71 °C al centro.","summary":"Salsicce fresche senza stagionatura né fermentazione. Servono tritacarne, insaccatrice e budello naturale di maiale per uso alimentare.\n\nSi ottengono 8 salsicce grandi. Mantieni carne, grasso e attrezzi freddi; i 100 minuti includono 30 di raffreddamento.","category":"Secondi piatti","category_slug":"platos-principales","difficulty":"Media","course":"Piatto principale","cuisine":"Tedesca","prep_time_minutes":45,"cook_time_minutes":25,"total_time_minutes":100,"servings":8,"ingredients":[{"name":"spalla di maiale disossata","amount":"700","unit":"g","group":"Impasto"},{"name":"grasso dorsale di maiale","amount":"300","unit":"g","group":"Impasto"},{"name":"acqua ghiacciata","amount":"100","unit":"ml","group":"Impasto"},{"name":"sale","amount":"16","unit":"g","group":"Spezie"},{"name":"pepe bianco macinato","amount":"2","unit":"g","group":"Spezie"},{"name":"maggiorana secca","amount":"2","unit":"g","group":"Spezie"},{"name":"noce moscata macinata","amount":"1","unit":"g","group":"Spezie"},{"name":"budello naturale di maiale, 28–32 mm","amount":"2","unit":"m","group":"Budello"},{"name":"olio vegetale","amount":"5","unit":"g","group":"Doratura"}],"steps":[{"title":"Preparare budello e utensili","content":"Sciacqua 2 m di budello anche internamente secondo il fornitore e tienilo in acqua pulita. Raffredda tritacarne e ciotola 15 minuti; carne a 4 °C o meno.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-01.webp","image_alt":"Salsicce fatte in casa tipo bratwurst: Preparare budello e utensili"},{"title":"Tagliare e raffreddare la carne","content":"Taglia 700 g di spalla e 300 g di grasso in dadi da 2 cm. Distribuisci separati in teglia e refrigera 30 minuti: molto freddi, non un blocco congelato.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-02.webp","image_alt":"Salsicce fatte in casa tipo bratwurst: Tagliare e raffreddare la carne"},{"title":"Tritare il composto","content":"Trita con disco da 4–5 mm nella ciotola fredda. Se scaldano o il grasso si spalma, interrompi e raffredda di nuovo.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-03.webp","image_alt":"Salsicce fatte in casa tipo bratwurst: Tritare il composto"},{"title":"Legare e insaporire","content":"Aggiungi 16 g di sale, 2 g di pepe bianco, 2 g di maggiorana e 1 g di noce moscata. Mescola 3–4 minuti aggiungendo gradualmente 100 ml di acqua ghiacciata, fino a un impasto appiccicoso. Tieni freddo.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-04.webp","image_alt":"Salsicce fatte in casa tipo bratwurst: Legare e insaporire"},{"title":"Controllare il condimento","content":"Cuoci un cucchiaino d’impasto a 71 °C al centro prima di assaggiare. Correggi le spezie se necessario; più sale modifica la nutrizione.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-05.webp","image_alt":"Salsicce fatte in casa tipo bratwurst: Controllare il condimento"},{"title":"Insaccare e formare","content":"Infila il budello e riempi senza stringere troppo. Forma 8 pezzi simili ruotando in direzioni alternate. Fora soltanto le sacche d’aria con ago pulito.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-06.webp","image_alt":"Salsicce fatte in casa tipo bratwurst: Insaccare e formare"},{"title":"Cuocere controllando la temperatura","content":"Immergi in acqua a 80 °C senza forte bollore per circa 15–20 minuti, fino ad almeno 71 °C nel centro. Lo spessore cambia il tempo: usa il termometro.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-07.webp","image_alt":"Salsicce fatte in casa tipo bratwurst: Cuocere controllando la temperatura"},{"title":"Rosolare e servire","content":"Scola e asciuga con carta pulita. Dora con 5 g di olio per 4–5 minuti girando e servi subito. La doratura non sostituisce la cottura a 71 °C.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-08.webp","image_alt":"Salsicce fatte in casa tipo bratwurst: Rosolare e servire"}],"notes":"Non stagionata: non essiccare né conservare a temperatura ambiente. Cuoci le salsicce crude refrigerate entro 24 ore o congela fino a 2 mesi. Cotte durano 3 giorni in frigorifero; riscalda a 74 °C. Pepe bianco approssimato con nero; budello e acqua esclusi. Non sostituire con pollame mantenendo la stessa temperatura.","nutrition":{"calories":518.0,"protein_g":16.2,"carbs_g":0.4,"fat_g":49.7,"saturated_fat_g":17.6,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":836.0,"serving_size":"1 delle 8 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 8 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario. Si contano tutti i grassi e l’olio anche se parte scola; budello escluso e pepe bianco approssimato con nero."},"keywords":["salsicce tedesche fatte in casa","bratwurst fresca","salsiccia di maiale"],"image_url":"/recetas/receta-de-salchichas-alemanas/portada.webp","gallery":[{"url":"/recetas/receta-de-salchichas-alemanas/portada.webp","alt":"Salsicce fatte in casa tipo bratwurst: piatto pronto"}],"seo":{"title":"Salsicce fatte in casa tipo bratwurst | Manual de Cocina","description":"Salsicce tedesche fresche con spalla di maiale, grasso dorsale e spezie. Lavora a freddo, insacca e cuoci fino a 71 °C al centro.","image_alt":"Salsicce fatte in casa tipo bratwurst: piatto pronto","image_variants":["/recetas/receta-de-salchichas-alemanas/portada-1x1.webp","/recetas/receta-de-salchichas-alemanas/portada-4x3.webp","/recetas/receta-de-salchichas-alemanas/portada-16x9.webp"],"faq":[{"q":"Posso usare macinato acquistato?","a":"Sì, conoscendo la percentuale di grasso e mantenendolo freddo; adegua il grasso aggiunto."},{"q":"Perché lavorare a freddo?","a":"Evita che il grasso si spalmi durante la macinatura e favorisce un impasto legato."},{"q":"Sono salsicce stagionate?","a":"No: cuoci a 71 °C e conserva refrigerato o congelato; non lasciare maturare fuori dal frigorifero."}]},"published":false,"editorial_status":"ready","content_html":"<p>Salsicce fresche senza stagionatura né fermentazione. Servono tritacarne, insaccatrice e budello naturale di maiale per uso alimentare.</p><p>Si ottengono 8 salsicce grandi. Mantieni carne, grasso e attrezzi freddi; i 100 minuti includono 30 di raffreddamento.</p>"},{"id":"e3f215d2-bb40-5af0-be5a-0229de788856","recipe_group_id":"04460456-460a-4002-9026-f422dd7a5388","slug":"手作りドイツソーセージ","public_path":"/ja/手作りドイツソーセージ","source_url":null,"language":"ja","title":"自家製ブラートヴルスト風ソーセージ","excerpt":"豚肩肉と背脂、スパイスで作る生ソーセージ。冷たく挽いて天然腸に詰め、中心71 °Cまで加熱します。","summary":"塩漬け熟成や発酵を行わない生ソーセージです。肉挽き機、ソーセージ詰め器、食品用の豚天然腸が必要です。\n\n大きめ8本分。肉、脂、器具を冷たく保ちます。総時間100分には冷却30分を含みます。","category":"主菜","category_slug":"platos-principales","difficulty":"普通","course":"主菜","cuisine":"ドイツ料理","prep_time_minutes":45,"cook_time_minutes":25,"total_time_minutes":100,"servings":8,"ingredients":[{"name":"骨なし豚肩肉","amount":"700","unit":"g","group":"肉だね"},{"name":"豚背脂","amount":"300","unit":"g","group":"肉だね"},{"name":"氷水","amount":"100","unit":"ml","group":"肉だね"},{"name":"塩","amount":"16","unit":"g","group":"スパイス"},{"name":"白こしょう粉","amount":"2","unit":"g","group":"スパイス"},{"name":"乾燥マジョラム","amount":"2","unit":"g","group":"スパイス"},{"name":"ナツメグ粉","amount":"1","unit":"g","group":"スパイス"},{"name":"豚天然腸、径28–32 mm","amount":"2","unit":"m","group":"腸詰め"},{"name":"植物油","amount":"5","unit":"g","group":"焼き色付け"}],"steps":[{"title":"ケーシングと器具を用意する","content":"天然腸2 mを製品の指示に従い内側も洗い、清潔な水に浸します。挽き機の部品とボウルを15分冷やし、肉は4 °C以下に保ちます。","image_url":"/recetas/receta-de-salchichas-alemanas/paso-01.webp","image_alt":"自家製ブラートヴルスト風ソーセージ: ケーシングと器具を用意する"},{"title":"肉を切って冷やす","content":"肩肉700 gと背脂300 gを2 cm角に切ります。別々に広げて冷蔵で30分冷やします。十分冷たくし、凍った一塊にはしません。","image_url":"/recetas/receta-de-salchichas-alemanas/paso-02.webp","image_alt":"自家製ブラートヴルスト風ソーセージ: 肉を切って冷やす"},{"title":"肉と脂を挽く","content":"4–5 mmのプレートで肉と脂を挽き、冷たいボウルに受けます。温まったり脂が練り付いたら止めて再度冷やします。","image_url":"/recetas/receta-de-salchichas-alemanas/paso-03.webp","image_alt":"自家製ブラートヴルスト風ソーセージ: 肉と脂を挽く"},{"title":"混ぜて味付けする","content":"塩16 g、白こしょう2 g、マジョラム2 g、ナツメグ1 gを加えます。氷水100 mlを少しずつ入れて3–4分混ぜ、粘りを出し、冷たく保ちます。","image_url":"/recetas/receta-de-salchichas-alemanas/paso-04.webp","image_alt":"自家製ブラートヴルスト風ソーセージ: 混ぜて味付けする"},{"title":"味付けを確認する","content":"小さじ1杯の肉だねを中心71 °Cまで焼いてから味見します。必要なら香辛料を調整します。塩の追加は栄養推定値を変えます。","image_url":"/recetas/receta-de-salchichas-alemanas/paso-05.webp","image_alt":"自家製ブラートヴルスト風ソーセージ: 味付けを確認する"},{"title":"詰めて成形する","content":"腸をノズルに付け、詰めすぎないように充填します。交互の向きにひねり、同程度の長さの8本にします。空気だまりだけ清潔な針で抜きます。","image_url":"/recetas/receta-de-salchichas-alemanas/paso-06.webp","image_alt":"自家製ブラートヴルスト風ソーセージ: 詰めて成形する"},{"title":"温度を確認しながら加熱する","content":"80 °Cの湯で強く沸かさず約15–20分加熱し、1本の中心が最低71 °Cに達するまで煮ます。太さで時間が変わるので温度計で確認します。","image_url":"/recetas/receta-de-salchichas-alemanas/paso-07.webp","image_alt":"自家製ブラートヴルスト風ソーセージ: 温度を確認しながら加熱する"},{"title":"焼き色を付けて盛り付ける","content":"水を切り、清潔な紙で拭きます。油5 gで4–5分、返しながら焼き色を付け、すぐ提供します。焼き色だけでは中心71 °Cの加熱を代用できません。","image_url":"/recetas/receta-de-salchichas-alemanas/paso-08.webp","image_alt":"自家製ブラートヴルスト風ソーセージ: 焼き色を付けて盛り付ける"}],"notes":"熟成品ではないため乾燥・常温保存はしません。生は冷蔵して24時間以内に調理するか最長2か月冷凍します。加熱後は冷蔵で最長3日、再加熱は74 °Cまで。白こしょうは黒こしょうで栄養を近似し、腸と水は除外。鶏肉への置換に同じ温度基準を使わないでください。","nutrition":{"calories":518.0,"protein_g":16.2,"carbs_g":0.4,"fat_g":49.7,"saturated_fat_g":17.6,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":836.0,"serving_size":"全8人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を8人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。 流れ出る分も含め脂と油を全量計算します。腸は除外し、白こしょうを黒こしょうで近似しています。"},"keywords":["手作りソーセージ","ブラートヴルスト","豚天然腸ソーセージ"],"image_url":"/recetas/receta-de-salchichas-alemanas/portada.webp","gallery":[{"url":"/recetas/receta-de-salchichas-alemanas/portada.webp","alt":"自家製ブラートヴルスト風ソーセージ: 完成した料理"}],"seo":{"title":"自家製ブラートヴルスト風ソーセージ | Manual de Cocina","description":"豚肩肉と背脂、スパイスで作る生ソーセージ。冷たく挽いて天然腸に詰め、中心71 °Cまで加熱します。","image_alt":"自家製ブラートヴルスト風ソーセージ: 完成した料理","image_variants":["/recetas/receta-de-salchichas-alemanas/portada-1x1.webp","/recetas/receta-de-salchichas-alemanas/portada-4x3.webp","/recetas/receta-de-salchichas-alemanas/portada-16x9.webp"],"faq":[{"q":"市販のひき肉を使えますか？","a":"脂肪割合が分かり、冷たく扱える場合は使えます。加える脂を調整します。"},{"q":"なぜ冷たく扱うのですか？","a":"挽くときに脂が練り付くのを防ぎ、まとまりのある肉だねを作るためです。"},{"q":"熟成ソーセージですか？","a":"いいえ。71 °Cまで加熱し、冷蔵か冷凍で保存します。常温熟成しません。"}]},"published":false,"editorial_status":"ready","content_html":"<p>塩漬け熟成や発酵を行わない生ソーセージです。肉挽き機、ソーセージ詰め器、食品用の豚天然腸が必要です。</p><p>大きめ8本分。肉、脂、器具を冷たく保ちます。総時間100分には冷却30分を含みます。</p>"},{"id":"8d187aab-ed72-5e32-bb92-844ce644f78c","recipe_group_id":"04460456-460a-4002-9026-f422dd7a5388","slug":"linguicas-alemas-caseiras","public_path":"/pt/linguicas-alemas-caseiras","source_url":null,"language":"pt","title":"Linguiças caseiras tipo bratwurst","excerpt":"Linguiças alemãs frescas com paleta suína, gordura dorsal e especiarias. Moa a frio, embuta em tripa natural e cozinhe até 71 °C no centro.","summary":"Linguiças frescas sem cura nem fermentação. Precisam de moedor, embutidor e tripa natural suína própria para alimentos.\n\nRende 8 linguiças grandes. Mantenha carne, gordura e utensílios frios; os 100 minutos incluem 30 de refrigeração.","category":"Pratos principais","category_slug":"platos-principales","difficulty":"Média","course":"Prato principal","cuisine":"Alemã","prep_time_minutes":45,"cook_time_minutes":25,"total_time_minutes":100,"servings":8,"ingredients":[{"name":"paleta suína sem osso","amount":"700","unit":"g","group":"Massa"},{"name":"gordura dorsal suína","amount":"300","unit":"g","group":"Massa"},{"name":"água com gelo","amount":"100","unit":"ml","group":"Massa"},{"name":"sal","amount":"16","unit":"g","group":"Especiarias"},{"name":"pimenta branca moída","amount":"2","unit":"g","group":"Especiarias"},{"name":"manjerona seca","amount":"2","unit":"g","group":"Especiarias"},{"name":"noz-moscada moída","amount":"1","unit":"g","group":"Especiarias"},{"name":"tripa natural suína de 28–32 mm","amount":"2","unit":"m","group":"Embutimento"},{"name":"óleo vegetal","amount":"5","unit":"g","group":"Dourar"}],"steps":[{"title":"Prepare a tripa e os utensílios","content":"Lave 2 m de tripa, inclusive por dentro, conforme o fornecedor e mantenha em água limpa. Resfrie peças do moedor e tigela por 15 minutos. Carne a 4 °C ou menos.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-01.webp","image_alt":"Linguiças caseiras tipo bratwurst: Prepare a tripa e os utensílios"},{"title":"Corte e resfrie a carne","content":"Corte 700 g de paleta e 300 g de gordura em cubos de 2 cm. Espalhe separados e refrigere 30 minutos: bem frios, sem formar bloco congelado.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-02.webp","image_alt":"Linguiças caseiras tipo bratwurst: Corte e resfrie a carne"},{"title":"Moa a mistura","content":"Moa carne e gordura com disco de 4–5 mm para a tigela fria. Se aquecerem ou a gordura virar pasta, pare e resfrie novamente.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-03.webp","image_alt":"Linguiças caseiras tipo bratwurst: Moa a mistura"},{"title":"Misture e tempere","content":"Junte 16 g de sal, 2 g de pimenta branca, 2 g de manjerona e 1 g de noz-moscada. Misture 3–4 minutos com 100 ml de água gelada aos poucos até ficar pegajoso. Mantenha frio.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-04.webp","image_alt":"Linguiças caseiras tipo bratwurst: Misture e tempere"},{"title":"Confira o tempero","content":"Cozinhe uma colher de chá da massa até 71 °C no centro antes de provar. Ajuste especiarias se necessário; sal adicional altera a nutrição.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-05.webp","image_alt":"Linguiças caseiras tipo bratwurst: Confira o tempero"},{"title":"Encha e modele","content":"Encaixe a tripa e encha sem apertar demais. Divida em 8 peças semelhantes, torcendo em sentidos alternados. Fure só bolsas de ar com agulha limpa.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-06.webp","image_alt":"Linguiças caseiras tipo bratwurst: Encha e modele"},{"title":"Cozinhe controlando a temperatura","content":"Cozinhe em água a 80 °C sem fervura forte por cerca de 15–20 minutos, até uma peça alcançar pelo menos 71 °C no centro. A espessura muda o tempo: use termômetro.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-07.webp","image_alt":"Linguiças caseiras tipo bratwurst: Cozinhe controlando a temperatura"},{"title":"Doure e sirva","content":"Escorra e seque com papel limpo. Doure com 5 g de óleo por 4–5 minutos, virando, e sirva logo. Dourar não substitui cozinhar até 71 °C.","image_url":"/recetas/receta-de-salchichas-alemanas/paso-08.webp","image_alt":"Linguiças caseiras tipo bratwurst: Doure e sirva"}],"notes":"Não é curada: não secar nem guardar em temperatura ambiente. Cozinhe as cruas refrigeradas em 24 horas ou congele até 2 meses. Cozidas duram 3 dias refrigeradas; reaqueça até 74 °C. Pimenta branca aproximada pela preta; tripa e água excluídas. Não troque por aves mantendo a mesma temperatura-alvo.","nutrition":{"calories":518.0,"protein_g":16.2,"carbs_g":0.4,"fat_g":49.7,"saturated_fat_g":17.6,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":836.0,"serving_size":"1 de 8 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 8 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário. Toda gordura e óleo são contados mesmo que parte escorra. Tripa excluída; pimenta branca aproximada pela preta."},"keywords":["linguiça alemã caseira","bratwurst fresca","linguiça suína natural"],"image_url":"/recetas/receta-de-salchichas-alemanas/portada.webp","gallery":[{"url":"/recetas/receta-de-salchichas-alemanas/portada.webp","alt":"Linguiças caseiras tipo bratwurst: prato pronto"}],"seo":{"title":"Linguiças caseiras tipo bratwurst | Manual de Cocina","description":"Linguiças alemãs frescas com paleta suína, gordura dorsal e especiarias. Moa a frio, embuta em tripa natural e cozinhe até 71 °C no centro.","image_alt":"Linguiças caseiras tipo bratwurst: prato pronto","image_variants":["/recetas/receta-de-salchichas-alemanas/portada-1x1.webp","/recetas/receta-de-salchichas-alemanas/portada-4x3.webp","/recetas/receta-de-salchichas-alemanas/portada-16x9.webp"],"faq":[{"q":"Posso usar carne já moída?","a":"Sim, sabendo a proporção de gordura e mantendo fria. Ajuste a gordura acrescentada."},{"q":"Por que a massa precisa estar fria?","a":"Evita que a gordura se espalhe no moedor e ajuda a ligar a massa."},{"q":"São linguiças curadas?","a":"Não: cozinhe até 71 °C e refrigere ou congele. Não deixe maturar em temperatura ambiente."}]},"published":false,"editorial_status":"ready","content_html":"<p>Linguiças frescas sem cura nem fermentação. Precisam de moedor, embutidor e tripa natural suína própria para alimentos.</p><p>Rende 8 linguiças grandes. Mantenha carne, gordura e utensílios frios; os 100 minutos incluem 30 de refrigeração.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-de-salchichas-alemanas') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

-- ensalada-primavera-pollo
do $pub$
declare
  g constant uuid := 'a25bba5a-9659-40ee-bba9-92221a8d7c19';
  es_id constant uuid := '7351cc9b-b440-49bd-b65f-9714bc405c9e';
  j constant jsonb := $j$[{"id":"7351cc9b-b440-49bd-b65f-9714bc405c9e","recipe_group_id":"a25bba5a-9659-40ee-bba9-92221a8d7c19","slug":"ensalada-primavera-pollo","public_path":"/ensalada-primavera-pollo","source_url":"https://manualdecocina.com/ensalada-primavera-pollo/","language":"es","title":"Ensalada primavera con pollo","excerpt":"Ensalada primavera con pollo, lechuga, pepino, tomate y maíz, aliñada con limón y mostaza. Cuatro porciones y cocción del pollo paso a paso.","summary":"Una ensalada de pollo en tiras con verduras crujientes y un aliño de limón, aceite y mostaza. El pollo se cocina por separado y se deja templar antes de añadirlo a la lechuga.\n\nRinde 4 porciones. Los 45 minutos incluyen 10 minutos de reposo y templado del pollo; la cocción se verifica con termómetro.","category":"Ensaladas","category_slug":"ensaladas","difficulty":"Fácil","course":"Plato principal","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":45,"servings":4,"ingredients":[{"name":"pechuga de pollo sin piel","amount":"500","unit":"g","group":"Pollo"},{"name":"aceite vegetal","amount":"10","unit":"g","group":"Pollo"},{"name":"sal","amount":"3","unit":"g","group":"Pollo"},{"name":"pimienta negra","amount":"0.5","unit":"g","group":"Pollo"},{"name":"lechuga romana","amount":"200","unit":"g","group":"Ensalada"},{"name":"pepino con piel","amount":"200","unit":"g","group":"Ensalada"},{"name":"tomate","amount":"250","unit":"g","group":"Ensalada"},{"name":"zanahoria","amount":"100","unit":"g","group":"Ensalada"},{"name":"maíz cocido en conserva, escurrido","amount":"120","unit":"g","group":"Ensalada"},{"name":"zumo de limón","amount":"30","unit":"g","group":"Aliño"},{"name":"aceite vegetal","amount":"25","unit":"g","group":"Aliño"},{"name":"mostaza preparada","amount":"10","unit":"g","group":"Aliño"}],"steps":[{"title":"Lava y seca las verduras","content":"Lava 200 g de lechuga, 200 g de pepino, 250 g de tomate y 100 g de zanahoria bajo agua potable. Escurre y seca bien la lechuga. Mantén estas verduras separadas de la tabla y los utensilios del pollo crudo.","image_url":"/recetas/ensalada-primavera-pollo/paso-01.webp","image_alt":"Ensalada primavera con pollo: Lava y seca las verduras"},{"title":"Corta las verduras","content":"Trocea la lechuga, corta el pepino y el tomate en dados de 1,5 cm y ralla la zanahoria. Escurre 120 g de maíz. Guarda todo en un bol en la nevera mientras cocinas el pollo.","image_url":"/recetas/ensalada-primavera-pollo/paso-02.webp","image_alt":"Ensalada primavera con pollo: Corta las verduras"},{"title":"Prepara el pollo","content":"Divide 500 g de pechuga en filetes de grosor uniforme de unos 2 cm. Sazona con 3 g de sal y 0,5 g de pimienta. No laves el pollo crudo; limpia manos y superficie después de manipularlo.","image_url":"/recetas/ensalada-primavera-pollo/paso-03.webp","image_alt":"Ensalada primavera con pollo: Prepara el pollo"},{"title":"Cocina el pollo","content":"Calienta 10 g de aceite en sartén a fuego medio. Cocina los filetes unos 6–7 minutos por lado, hasta que el centro alcance 74 °C. Si se doran antes de llegar a esa temperatura, baja el fuego y tapa brevemente.","image_url":"/recetas/ensalada-primavera-pollo/paso-04.webp","image_alt":"Ensalada primavera con pollo: Cocina el pollo"},{"title":"Deja templar y corta","content":"Pasa el pollo cocido a una tabla limpia. Reposa 5 minutos y corta en tiras de 1 cm. Deja perder el calor intenso otros 5 minutos para no marchitar la lechuga.","image_url":"/recetas/ensalada-primavera-pollo/paso-05.webp","image_alt":"Ensalada primavera con pollo: Deja templar y corta"},{"title":"Emulsiona el aliño","content":"Bate 30 g de zumo de limón con 10 g de mostaza. Añade lentamente 25 g de aceite y mezcla 1 minuto hasta que se integre. No añadas sal sin probar antes, porque la mostaza ya la aporta.","image_url":"/recetas/ensalada-primavera-pollo/paso-06.webp","image_alt":"Ensalada primavera con pollo: Emulsiona el aliño"},{"title":"Mezcla la ensalada","content":"Añade las tiras de pollo templadas al bol con lechuga, pepino, tomate, zanahoria y maíz. Vierte el aliño y mezcla con dos cucharas justo antes de servir.","image_url":"/recetas/ensalada-primavera-pollo/paso-07.webp","image_alt":"Ensalada primavera con pollo: Mezcla la ensalada"},{"title":"Reparte y sirve","content":"Reparte en 4 platos procurando distribuir pollo y maíz por igual. Sirve inmediatamente. Si preparas para otro día, guarda pollo, verduras y aliño por separado y refrigera sin demora.","image_url":"/recetas/ensalada-primavera-pollo/paso-08.webp","image_alt":"Ensalada primavera con pollo: Reparte y sirve"}],"notes":"Conserva el pollo cocido refrigerado hasta 3 días y las verduras lavadas, bien secas, hasta 2 días. Una ensalada ya aliñada pierde textura; consúmela el mismo día. Puedes cambiar el maíz por guisantes cocidos manteniendo la cantidad, pero la nutrición cambiará. No se incluye pan ni otros acompañamientos.","nutrition":{"calories":288.0,"protein_g":30.7,"carbs_g":13.3,"fat_g":12.9,"saturated_fat_g":1.5,"fiber_g":3.5,"sugar_g":5.8,"sodium_mg":462.0,"serving_size":"1 de 4 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 4 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma.  Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"pechuga de pollo sin piel","edible_grams":500,"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120.0,"saturated_fat_g":0.563,"sodium_mg":45.0,"protein_g":22.5,"sugar_g":0.0,"carbs_g":0.0,"fiber_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients"},{"ingredient":"aceite vegetal","edible_grams":10,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"fat_g":100.0,"saturated_fat_g":7.365,"protein_g":0.0,"carbs_g":0.0,"calories":884.0,"fiber_g":0.0,"sodium_mg":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"sal","edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0.0,"sodium_mg":38758.0,"saturated_fat_g":0.0,"protein_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"pimienta negra","edible_grams":0.5,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":63.95,"calories":251.0,"protein_g":10.39,"fiber_g":25.3,"sodium_mg":20.0,"saturated_fat_g":1.392},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"lechuga romana","edible_grams":200,"fdc_id":169247,"fdc_description":"Lettuce, cos or romaine, raw","per_100g":{"carbs_g":3.29,"calories":17.0,"saturated_fat_g":0.039,"sodium_mg":8.0,"fat_g":0.3,"sugar_g":1.19,"fiber_g":2.1,"protein_g":1.23},"source_url":"https://fdc.nal.usda.gov/food-details/169247/nutrients"},{"ingredient":"pepino con piel","edible_grams":200,"fdc_id":168409,"fdc_description":"Cucumber, with peel, raw","per_100g":{"carbs_g":3.63,"calories":15.0,"sugar_g":1.67,"saturated_fat_g":0.037,"sodium_mg":2.0,"fat_g":0.11,"fiber_g":0.5,"protein_g":0.65},"source_url":"https://fdc.nal.usda.gov/food-details/168409/nutrients"},{"ingredient":"tomate","edible_grams":250,"fdc_id":170457,"fdc_description":"Tomatoes, red, ripe, raw, year round average","per_100g":{"sugar_g":2.63,"carbs_g":3.89,"calories":18.0,"saturated_fat_g":0.028,"fat_g":0.2,"fiber_g":1.2,"sodium_mg":5.0,"protein_g":0.88},"source_url":"https://fdc.nal.usda.gov/food-details/170457/nutrients"},{"ingredient":"zanahoria","edible_grams":100,"fdc_id":170393,"fdc_description":"Carrots, raw","per_100g":{"saturated_fat_g":0.032,"sodium_mg":69.0,"protein_g":0.93,"fat_g":0.24,"sugar_g":4.74,"carbs_g":9.58,"calories":41.0,"fiber_g":2.8},"source_url":"https://fdc.nal.usda.gov/food-details/170393/nutrients"},{"ingredient":"maíz cocido en conserva, escurrido","edible_grams":120,"fdc_id":169214,"fdc_description":"Corn, sweet, yellow, canned, whole kernel, drained solids","per_100g":{"fat_g":1.22,"carbs_g":14.34,"calories":67.0,"sugar_g":4.44,"saturated_fat_g":0.245,"fiber_g":2.0,"sodium_mg":205.0,"protein_g":2.29},"source_url":"https://fdc.nal.usda.gov/food-details/169214/nutrients"},{"ingredient":"zumo de limón","edible_grams":30,"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1.0,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22.0},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients"},{"ingredient":"aceite vegetal","edible_grams":25,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"fat_g":100.0,"saturated_fat_g":7.365,"protein_g":0.0,"carbs_g":0.0,"calories":884.0,"fiber_g":0.0,"sodium_mg":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"mostaza preparada","edible_grams":10,"fdc_id":172234,"fdc_description":"Mustard, prepared, yellow","per_100g":{"protein_g":3.74,"fiber_g":4.0,"sodium_mg":1104.0,"saturated_fat_g":0.214,"fat_g":3.34,"carbs_g":5.83,"calories":60.0,"sugar_g":0.92},"source_url":"https://fdc.nal.usda.gov/food-details/172234/nutrients"}]},"keywords":["ensalada primavera con pollo","ensalada pollo y verduras","aliño limón mostaza"],"image_url":"/recetas/ensalada-primavera-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-primavera-pollo/portada.webp","alt":"Ensalada primavera con pollo: plato terminado"}],"seo":{"title":"Ensalada primavera con pollo | Manual de Cocina","description":"Ensalada primavera con pollo, lechuga, pepino, tomate y maíz, aliñada con limón y mostaza. Cuatro porciones y cocción del pollo paso a paso.","image_alt":"Ensalada primavera con pollo: plato terminado","image_variants":["/recetas/ensalada-primavera-pollo/portada-1x1.webp","/recetas/ensalada-primavera-pollo/portada-4x3.webp","/recetas/ensalada-primavera-pollo/portada-16x9.webp"],"faq":[{"q":"¿Puedo usar pollo ya cocinado?","a":"Sí, utiliza 350–375 g de pollo cocido conservado correctamente. La nutrición de esta receta se calcula con 500 g de pechuga cruda."},{"q":"¿Puedo prepararla el día anterior?","a":"Guarda por separado el pollo, las verduras secas y el aliño. Mezcla al servir para mantener la textura."},{"q":"¿Cómo evito que la lechuga se marchite?","a":"Sécala bien, deja templar el pollo y añade el aliño justo antes de comer."}]},"published":false,"editorial_status":"ready","content_html":"<p>Una ensalada de pollo en tiras con verduras crujientes y un aliño de limón, aceite y mostaza. El pollo se cocina por separado y se deja templar antes de añadirlo a la lechuga.</p><p>Rinde 4 porciones. Los 45 minutos incluyen 10 minutos de reposo y templado del pollo; la cocción se verifica con termómetro.</p>"},{"id":"15f7121e-f1f9-51b6-b9ed-0c2717c0f284","recipe_group_id":"a25bba5a-9659-40ee-bba9-92221a8d7c19","slug":"fruehlingssalat-mit-haehnchen","public_path":"/de/fruehlingssalat-mit-haehnchen","source_url":null,"language":"de","title":"Frühlingssalat mit Hähnchen","excerpt":"Frühlingssalat mit gebratenem Hähnchen, knackigem Gemüse und Zitronen-Senf-Dressing. Für 4 Portionen in 45 Minuten, mit getrennten Vorbereitungsschritten.","summary":"Hähnchenstreifen mit knackigem Gemüse und Zitronen-Öl-Senf-Dressing. Das Fleisch wird getrennt gegart und vor dem Salat etwas abgekühlt.\n\n4 Portionen; die 45 Minuten enthalten 10 Minuten Ruhe und Abkühlung. Die Garung mit Thermometer prüfen.","category":"Salate","category_slug":"ensaladas","difficulty":"Einfach","course":"Hauptgericht","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":45,"servings":4,"ingredients":[{"name":"Hähnchenbrust ohne Haut","amount":"500","unit":"g","group":"Hähnchen"},{"name":"Pflanzenöl","amount":"10","unit":"g","group":"Hähnchen"},{"name":"Salz","amount":"3","unit":"g","group":"Hähnchen"},{"name":"schwarzer Pfeffer","amount":"0.5","unit":"g","group":"Hähnchen"},{"name":"Römersalat","amount":"200","unit":"g","group":"Salat"},{"name":"Gurke mit Schale","amount":"200","unit":"g","group":"Salat"},{"name":"Tomate","amount":"250","unit":"g","group":"Salat"},{"name":"Karotte","amount":"100","unit":"g","group":"Salat"},{"name":"Dosenmais, gegart und abgetropft","amount":"120","unit":"g","group":"Salat"},{"name":"Zitronensaft","amount":"30","unit":"g","group":"Dressing"},{"name":"Pflanzenöl","amount":"25","unit":"g","group":"Dressing"},{"name":"zubereiteter Senf","amount":"10","unit":"g","group":"Dressing"}],"steps":[{"title":"Gemüse waschen und trocknen","content":"200 g Salat, 200 g Gurke, 250 g Tomate und 100 g Karotte mit Trinkwasser waschen. Salat gut trocknen. Gemüse von Brett und Werkzeugen für rohes Hähnchen fernhalten.","image_url":"/recetas/ensalada-primavera-pollo/paso-01.webp","image_alt":"Frühlingssalat mit Hähnchen: Gemüse waschen und trocknen"},{"title":"Gemüse schneiden","content":"Salat zerteilen, Gurke und Tomate in 1,5-cm-Würfel schneiden, Karotte raspeln. 120 g Mais abtropfen. Alles im Kühlschrank aufbewahren.","image_url":"/recetas/ensalada-primavera-pollo/paso-02.webp","image_alt":"Frühlingssalat mit Hähnchen: Gemüse schneiden"},{"title":"Hähnchen vorbereiten","content":"500 g Brust in gleichmäßig etwa 2 cm dicke Filets teilen. Mit 3 g Salz und 0,5 g Pfeffer würzen. Rohes Hähnchen nicht waschen; danach Hände und Arbeitsfläche reinigen.","image_url":"/recetas/ensalada-primavera-pollo/paso-03.webp","image_alt":"Frühlingssalat mit Hähnchen: Hähnchen vorbereiten"},{"title":"Hähnchen garen","content":"10 g Öl bei mittlerer Hitze erhitzen. Filets etwa 6–7 Minuten je Seite bis 74 °C im Kern garen. Bräunen sie zu früh, Hitze reduzieren und kurz abdecken.","image_url":"/recetas/ensalada-primavera-pollo/paso-04.webp","image_alt":"Frühlingssalat mit Hähnchen: Hähnchen garen"},{"title":"Abkühlen lassen und schneiden","content":"Gegartes Hähnchen auf ein sauberes Brett legen. 5 Minuten ruhen, in 1 cm breite Streifen schneiden und weitere 5 Minuten abkühlen lassen, damit der Salat nicht welkt.","image_url":"/recetas/ensalada-primavera-pollo/paso-05.webp","image_alt":"Frühlingssalat mit Hähnchen: Abkühlen lassen und schneiden"},{"title":"Dressing emulgieren","content":"30 g Zitronensaft mit 10 g Senf verquirlen. Langsam 25 g Öl einrühren und 1 Minute vermischen. Wegen des Salzes im Senf erst probieren, bevor zusätzlich gesalzen wird.","image_url":"/recetas/ensalada-primavera-pollo/paso-06.webp","image_alt":"Frühlingssalat mit Hähnchen: Dressing emulgieren"},{"title":"Salat mischen","content":"Lauwarmes Hähnchen zu Salat, Gurke, Tomate, Karotte und Mais geben. Erst unmittelbar vor dem Servieren das Dressing mit zwei Löffeln unterheben.","image_url":"/recetas/ensalada-primavera-pollo/paso-07.webp","image_alt":"Frühlingssalat mit Hähnchen: Salat mischen"},{"title":"Portionieren und servieren","content":"Auf 4 Teller verteilen, Hähnchen und Mais gleichmäßig aufteilen. Sofort servieren. Für später Fleisch, Gemüse und Dressing getrennt unverzüglich kühlen.","image_url":"/recetas/ensalada-primavera-pollo/paso-08.webp","image_alt":"Frühlingssalat mit Hähnchen: Portionieren und servieren"}],"notes":"Gegartes Hähnchen gekühlt bis 3 Tage, gewaschenes trockenes Gemüse bis 2 Tage lagern. Angemachten Salat am selben Tag essen. Mais kann durch gleich viel gegarte Erbsen ersetzt werden, mit veränderten Nährwerten. Brot und Beilagen sind nicht eingerechnet.","nutrition":{"calories":288.0,"protein_g":30.7,"carbs_g":13.3,"fat_g":12.9,"saturated_fat_g":1.5,"fiber_g":3.5,"sugar_g":5.8,"sodium_mg":462.0,"serving_size":"1 von 4 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 4 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers."},"keywords":["Frühlingssalat mit Hähnchen","Hähnchensalat","Zitronen-Senf-Dressing"],"image_url":"/recetas/ensalada-primavera-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-primavera-pollo/portada.webp","alt":"Frühlingssalat mit Hähnchen: fertiges Gericht"}],"seo":{"title":"Frühlingssalat mit Hähnchen | Manual de Cocina","description":"Frühlingssalat mit gebratenem Hähnchen, knackigem Gemüse und Zitronen-Senf-Dressing. Für 4 Portionen in 45 Minuten, mit getrennten Vorbereitungsschritten.","image_alt":"Frühlingssalat mit Hähnchen: fertiges Gericht","image_variants":["/recetas/ensalada-primavera-pollo/portada-1x1.webp","/recetas/ensalada-primavera-pollo/portada-4x3.webp","/recetas/ensalada-primavera-pollo/portada-16x9.webp"],"faq":[{"q":"Geht bereits gegartes Hähnchen?","a":"350–375 g sicher gelagertes gegartes Hähnchen verwenden; berechnet wurde mit 500 g roher Brust."},{"q":"Kann ich am Vortag vorbereiten?","a":"Fleisch, trockenes Gemüse und Dressing getrennt lagern und erst zum Essen mischen."},{"q":"Wie bleibt der Salat knackig?","a":"Gut trocknen, Hähnchen abkühlen lassen und Dressing erst vor dem Essen hinzufügen."}]},"published":false,"editorial_status":"ready","content_html":"<p>Hähnchenstreifen mit knackigem Gemüse und Zitronen-Öl-Senf-Dressing. Das Fleisch wird getrennt gegart und vor dem Salat etwas abgekühlt.</p><p>4 Portionen; die 45 Minuten enthalten 10 Minuten Ruhe und Abkühlung. Die Garung mit Thermometer prüfen.</p>"},{"id":"7a3b88dd-b6c9-57f7-b3a2-798895104b05","recipe_group_id":"a25bba5a-9659-40ee-bba9-92221a8d7c19","slug":"spring-salad-with-chicken","public_path":"/en/spring-salad-with-chicken","source_url":null,"language":"en","title":"Spring chicken salad","excerpt":"Spring chicken salad with crisp vegetables and lemon-mustard dressing. Four servings in 45 minutes, with the chicken cooked and cooled separately.","summary":"Chicken strips with crisp vegetables and lemon, oil and mustard dressing. Cook the chicken separately and let it cool slightly before adding to the lettuce.\n\nMakes 4 servings. The 45 minutes include 10 minutes of resting and cooling; check doneness with a thermometer.","category":"Salads","category_slug":"ensaladas","difficulty":"Easy","course":"Main course","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":45,"servings":4,"ingredients":[{"name":"skinless chicken breast","amount":"500","unit":"g","group":"Chicken"},{"name":"vegetable oil","amount":"10","unit":"g","group":"Chicken"},{"name":"salt","amount":"3","unit":"g","group":"Chicken"},{"name":"black pepper","amount":"0.5","unit":"g","group":"Chicken"},{"name":"romaine lettuce","amount":"200","unit":"g","group":"Salad"},{"name":"unpeeled cucumber","amount":"200","unit":"g","group":"Salad"},{"name":"tomato","amount":"250","unit":"g","group":"Salad"},{"name":"carrot","amount":"100","unit":"g","group":"Salad"},{"name":"canned cooked sweetcorn, drained","amount":"120","unit":"g","group":"Salad"},{"name":"lemon juice","amount":"30","unit":"g","group":"Dressing"},{"name":"vegetable oil","amount":"25","unit":"g","group":"Dressing"},{"name":"prepared mustard","amount":"10","unit":"g","group":"Dressing"}],"steps":[{"title":"Wash and dry the vegetables","content":"Wash 200 g lettuce, 200 g cucumber, 250 g tomato and 100 g carrot under potable water. Dry the lettuce well. Keep vegetables away from the raw-chicken board and utensils.","image_url":"/recetas/ensalada-primavera-pollo/paso-01.webp","image_alt":"Spring chicken salad: Wash and dry the vegetables"},{"title":"Cut the vegetables","content":"Chop lettuce, dice cucumber and tomato into 1.5 cm pieces and grate carrot. Drain 120 g sweetcorn. Refrigerate everything in a bowl while cooking the chicken.","image_url":"/recetas/ensalada-primavera-pollo/paso-02.webp","image_alt":"Spring chicken salad: Cut the vegetables"},{"title":"Prepare the chicken","content":"Cut 500 g chicken breast into evenly thick fillets, about 2 cm. Season with 3 g salt and 0.5 g pepper. Do not wash raw chicken; clean hands and surfaces afterwards.","image_url":"/recetas/ensalada-primavera-pollo/paso-03.webp","image_alt":"Spring chicken salad: Prepare the chicken"},{"title":"Cook the chicken","content":"Heat 10 g oil over medium heat. Cook fillets about 6–7 minutes per side until the centre reaches 74 °C. If they brown too soon, lower the heat and briefly cover.","image_url":"/recetas/ensalada-primavera-pollo/paso-04.webp","image_alt":"Spring chicken salad: Cook the chicken"},{"title":"Let cool slightly and slice","content":"Transfer cooked chicken to a clean board. Rest 5 minutes, cut into 1 cm strips and cool another 5 minutes so it does not wilt the lettuce.","image_url":"/recetas/ensalada-primavera-pollo/paso-05.webp","image_alt":"Spring chicken salad: Let cool slightly and slice"},{"title":"Emulsify the dressing","content":"Whisk 30 g lemon juice with 10 g mustard. Slowly add 25 g oil and whisk for 1 minute. Taste before adding salt, as mustard already contains it.","image_url":"/recetas/ensalada-primavera-pollo/paso-06.webp","image_alt":"Spring chicken salad: Emulsify the dressing"},{"title":"Toss the salad","content":"Add the warm chicken strips to the lettuce, cucumber, tomato, carrot and corn. Pour in dressing and toss with two spoons just before serving.","image_url":"/recetas/ensalada-primavera-pollo/paso-07.webp","image_alt":"Spring chicken salad: Toss the salad"},{"title":"Divide and serve","content":"Divide between 4 plates, distributing chicken and corn evenly. Serve immediately. For later use, refrigerate chicken, vegetables and dressing separately without delay.","image_url":"/recetas/ensalada-primavera-pollo/paso-08.webp","image_alt":"Spring chicken salad: Divide and serve"}],"notes":"Cooked chicken keeps refrigerated up to 3 days; washed, dry vegetables up to 2 days. Eat dressed salad the same day. Equal-weight cooked peas can replace corn, but nutrition changes. Bread and other sides are not included.","nutrition":{"calories":288.0,"protein_g":30.7,"carbs_g":13.3,"fat_g":12.9,"saturated_fat_g":1.5,"fiber_g":3.5,"sugar_g":5.8,"sodium_mg":462.0,"serving_size":"1 of 4 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 4 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation."},"keywords":["spring chicken salad","chicken vegetable salad","lemon mustard dressing"],"image_url":"/recetas/ensalada-primavera-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-primavera-pollo/portada.webp","alt":"Spring chicken salad: finished dish"}],"seo":{"title":"Spring chicken salad | Manual de Cocina","description":"Spring chicken salad with crisp vegetables and lemon-mustard dressing. Four servings in 45 minutes, with the chicken cooked and cooled separately.","image_alt":"Spring chicken salad: finished dish","image_variants":["/recetas/ensalada-primavera-pollo/portada-1x1.webp","/recetas/ensalada-primavera-pollo/portada-4x3.webp","/recetas/ensalada-primavera-pollo/portada-16x9.webp"],"faq":[{"q":"Can I use cooked chicken?","a":"Use 350–375 g safely stored cooked chicken. Nutrition here is calculated from 500 g raw breast."},{"q":"Can I prepare it a day ahead?","a":"Store chicken, dry vegetables and dressing separately, then combine when serving."},{"q":"How do I stop the lettuce wilting?","a":"Dry it thoroughly, cool the chicken slightly and add dressing immediately before eating."}]},"published":false,"editorial_status":"ready","content_html":"<p>Chicken strips with crisp vegetables and lemon, oil and mustard dressing. Cook the chicken separately and let it cool slightly before adding to the lettuce.</p><p>Makes 4 servings. The 45 minutes include 10 minutes of resting and cooling; check doneness with a thermometer.</p>"},{"id":"c33721eb-b679-5c81-a007-15864bc33a17","recipe_group_id":"a25bba5a-9659-40ee-bba9-92221a8d7c19","slug":"salade-printaniere-au-poulet","public_path":"/fr/salade-printaniere-au-poulet","source_url":null,"language":"fr","title":"Salade printanière au poulet","excerpt":"Salade printanière au poulet, légumes croquants et vinaigrette citron-moutarde. Quatre portions en 45 minutes, poulet cuit séparément.","summary":"Des lanières de poulet, des légumes croquants et une vinaigrette au citron, huile et moutarde. Le poulet cuit séparément puis tiédit avant de rejoindre la laitue.\n\n4 portions en 45 minutes, dont 10 de repos et refroidissement. Vérifiez la cuisson au thermomètre.","category":"Salades","category_slug":"ensaladas","difficulty":"Facile","course":"Plat principal","cuisine":"Internationale","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":45,"servings":4,"ingredients":[{"name":"blanc de poulet sans peau","amount":"500","unit":"g","group":"Poulet"},{"name":"huile végétale","amount":"10","unit":"g","group":"Poulet"},{"name":"sel","amount":"3","unit":"g","group":"Poulet"},{"name":"poivre noir","amount":"0.5","unit":"g","group":"Poulet"},{"name":"laitue romaine","amount":"200","unit":"g","group":"Salade"},{"name":"concombre avec peau","amount":"200","unit":"g","group":"Salade"},{"name":"tomate","amount":"250","unit":"g","group":"Salade"},{"name":"carotte","amount":"100","unit":"g","group":"Salade"},{"name":"maïs en conserve cuit et égoutté","amount":"120","unit":"g","group":"Salade"},{"name":"jus de citron","amount":"30","unit":"g","group":"Vinaigrette"},{"name":"huile végétale","amount":"25","unit":"g","group":"Vinaigrette"},{"name":"moutarde préparée","amount":"10","unit":"g","group":"Vinaigrette"}],"steps":[{"title":"Laver et sécher les légumes","content":"Lavez 200 g de laitue, 200 g de concombre, 250 g de tomate et 100 g de carotte à l’eau potable. Séchez bien la laitue; éloignez les ustensiles du poulet cru.","image_url":"/recetas/ensalada-primavera-pollo/paso-01.webp","image_alt":"Salade printanière au poulet: Laver et sécher les légumes"},{"title":"Couper les légumes","content":"Coupez la laitue, taillez concombre et tomate en dés de 1,5 cm, râpez la carotte. Égouttez 120 g de maïs et réfrigérez le tout.","image_url":"/recetas/ensalada-primavera-pollo/paso-02.webp","image_alt":"Salade printanière au poulet: Couper les légumes"},{"title":"Préparer le poulet","content":"Divisez 500 g de poulet en filets d’environ 2 cm d’épaisseur régulière. Assaisonnez avec 3 g de sel et 0,5 g de poivre. Ne lavez pas le poulet cru; nettoyez ensuite mains et surface.","image_url":"/recetas/ensalada-primavera-pollo/paso-03.webp","image_alt":"Salade printanière au poulet: Préparer le poulet"},{"title":"Cuire le poulet","content":"Chauffez 10 g d’huile à feu moyen. Cuisez environ 6–7 minutes par face jusqu’à 74 °C à cœur. Si le poulet dore trop vite, baissez le feu et couvrez brièvement.","image_url":"/recetas/ensalada-primavera-pollo/paso-04.webp","image_alt":"Salade printanière au poulet: Cuire le poulet"},{"title":"Laisser tiédir et couper","content":"Sur une planche propre, laissez reposer le poulet cuit 5 minutes, coupez en lanières de 1 cm puis laissez tiédir encore 5 minutes pour préserver la laitue.","image_url":"/recetas/ensalada-primavera-pollo/paso-05.webp","image_alt":"Salade printanière au poulet: Laisser tiédir et couper"},{"title":"Émulsionner la vinaigrette","content":"Fouettez 30 g de jus de citron avec 10 g de moutarde. Incorporez lentement 25 g d’huile pendant 1 minute. Goûtez avant de saler, car la moutarde apporte déjà du sel.","image_url":"/recetas/ensalada-primavera-pollo/paso-06.webp","image_alt":"Salade printanière au poulet: Émulsionner la vinaigrette"},{"title":"Mélanger la salade","content":"Ajoutez le poulet tiède à la laitue, concombre, tomate, carotte et maïs. Mélangez la vinaigrette avec deux cuillères juste avant de servir.","image_url":"/recetas/ensalada-primavera-pollo/paso-07.webp","image_alt":"Salade printanière au poulet: Mélanger la salade"},{"title":"Répartir et servir","content":"Répartissez sur 4 assiettes, en distribuant poulet et maïs équitablement. Servez immédiatement; pour plus tard, réfrigérez sans attendre les trois composants séparément.","image_url":"/recetas/ensalada-primavera-pollo/paso-08.webp","image_alt":"Salade printanière au poulet: Répartir et servir"}],"notes":"Poulet cuit: jusqu’à 3 jours au réfrigérateur; légumes lavés bien secs: 2 jours. Consommez la salade assaisonnée le jour même. Des petits pois cuits de même poids peuvent remplacer le maïs, mais changent la nutrition. Pain et accompagnements exclus.","nutrition":{"calories":288.0,"protein_g":30.7,"carbs_g":13.3,"fat_g":12.9,"saturated_fat_g":1.5,"fiber_g":3.5,"sugar_g":5.8,"sodium_mg":462.0,"serving_size":"1 des 4 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 4 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire."},"keywords":["salade printanière poulet","salade poulet légumes","vinaigrette citron moutarde"],"image_url":"/recetas/ensalada-primavera-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-primavera-pollo/portada.webp","alt":"Salade printanière au poulet: plat terminé"}],"seo":{"title":"Salade printanière au poulet | Manual de Cocina","description":"Salade printanière au poulet, légumes croquants et vinaigrette citron-moutarde. Quatre portions en 45 minutes, poulet cuit séparément.","image_alt":"Salade printanière au poulet: plat terminé","image_variants":["/recetas/ensalada-primavera-pollo/portada-1x1.webp","/recetas/ensalada-primavera-pollo/portada-4x3.webp","/recetas/ensalada-primavera-pollo/portada-16x9.webp"],"faq":[{"q":"Peut-on utiliser du poulet déjà cuit?","a":"Oui, 350–375 g correctement conservés. Le calcul utilise 500 g de blanc cru."},{"q":"Peut-on préparer la veille?","a":"Gardez poulet, légumes secs et vinaigrette séparés; mélangez au service."},{"q":"Comment garder la laitue croquante?","a":"Séchez-la, laissez tiédir le poulet et ajoutez la vinaigrette au dernier moment."}]},"published":false,"editorial_status":"ready","content_html":"<p>Des lanières de poulet, des légumes croquants et une vinaigrette au citron, huile et moutarde. Le poulet cuit séparément puis tiédit avant de rejoindre la laitue.</p><p>4 portions en 45 minutes, dont 10 de repos et refroidissement. Vérifiez la cuisson au thermomètre.</p>"},{"id":"a409ee34-2139-5715-a9f3-bf0c40bd8c7f","recipe_group_id":"a25bba5a-9659-40ee-bba9-92221a8d7c19","slug":"insalata-primavera-con-pollo","public_path":"/it/insalata-primavera-con-pollo","source_url":null,"language":"it","title":"Insalata primaverile con pollo","excerpt":"Insalata primavera con pollo, verdure croccanti e condimento al limone e senape. Quattro porzioni in 45 minuti, pollo cotto separatamente.","summary":"Strisce di pollo, verdure croccanti e condimento con limone, olio e senape. Il pollo cuoce separatamente e intiepidisce prima della lattuga.\n\n4 porzioni in 45 minuti, inclusi 10 di riposo e raffreddamento. Controlla la cottura con termometro.","category":"Insalate","category_slug":"ensaladas","difficulty":"Facile","course":"Piatto principale","cuisine":"Internazionale","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":45,"servings":4,"ingredients":[{"name":"petto di pollo senza pelle","amount":"500","unit":"g","group":"Pollo"},{"name":"olio vegetale","amount":"10","unit":"g","group":"Pollo"},{"name":"sale","amount":"3","unit":"g","group":"Pollo"},{"name":"pepe nero","amount":"0.5","unit":"g","group":"Pollo"},{"name":"lattuga romana","amount":"200","unit":"g","group":"Insalata"},{"name":"cetriolo con buccia","amount":"200","unit":"g","group":"Insalata"},{"name":"pomodoro","amount":"250","unit":"g","group":"Insalata"},{"name":"carota","amount":"100","unit":"g","group":"Insalata"},{"name":"mais cotto in scatola, scolato","amount":"120","unit":"g","group":"Insalata"},{"name":"succo di limone","amount":"30","unit":"g","group":"Condimento"},{"name":"olio vegetale","amount":"25","unit":"g","group":"Condimento"},{"name":"senape pronta","amount":"10","unit":"g","group":"Condimento"}],"steps":[{"title":"Lavare e asciugare le verdure","content":"Lava 200 g di lattuga, 200 g di cetriolo, 250 g di pomodoro e 100 g di carota con acqua potabile. Asciuga bene la lattuga e separa gli utensili del pollo crudo.","image_url":"/recetas/ensalada-primavera-pollo/paso-01.webp","image_alt":"Insalata primaverile con pollo: Lavare e asciugare le verdure"},{"title":"Tagliare le verdure","content":"Spezzetta lattuga, taglia cetriolo e pomodoro a dadi di 1,5 cm e grattugia carota. Scola 120 g di mais; conserva tutto in frigorifero.","image_url":"/recetas/ensalada-primavera-pollo/paso-02.webp","image_alt":"Insalata primaverile con pollo: Tagliare le verdure"},{"title":"Preparare il pollo","content":"Dividi 500 g di pollo in filetti uniformi di circa 2 cm. Condisci con 3 g di sale e 0,5 g di pepe. Non lavare il pollo crudo; pulisci mani e superficie dopo averlo toccato.","image_url":"/recetas/ensalada-primavera-pollo/paso-03.webp","image_alt":"Insalata primaverile con pollo: Preparare il pollo"},{"title":"Cuocere il pollo","content":"Scalda 10 g di olio a fuoco medio. Cuoci i filetti circa 6–7 minuti per lato fino a 74 °C al centro. Se dorano prima, abbassa e copri brevemente.","image_url":"/recetas/ensalada-primavera-pollo/paso-04.webp","image_alt":"Insalata primaverile con pollo: Cuocere il pollo"},{"title":"Lasciare intiepidire e tagliare","content":"Metti il pollo cotto su un tagliere pulito. Riposa 5 minuti, taglia strisce da 1 cm e lascia intiepidire altri 5 minuti per non appassire la lattuga.","image_url":"/recetas/ensalada-primavera-pollo/paso-05.webp","image_alt":"Insalata primaverile con pollo: Lasciare intiepidire e tagliare"},{"title":"Emulsionare il condimento","content":"Sbatti 30 g di succo di limone con 10 g di senape. Versa lentamente 25 g di olio e mescola 1 minuto. Assaggia prima di salare, perché la senape contiene sale.","image_url":"/recetas/ensalada-primavera-pollo/paso-06.webp","image_alt":"Insalata primaverile con pollo: Emulsionare il condimento"},{"title":"Mescolare l’insalata","content":"Unisci pollo tiepido, lattuga, cetriolo, pomodoro, carota e mais. Aggiungi il condimento e mescola con due cucchiai appena prima di servire.","image_url":"/recetas/ensalada-primavera-pollo/paso-07.webp","image_alt":"Insalata primaverile con pollo: Mescolare l’insalata"},{"title":"Dividere e servire","content":"Dividi in 4 piatti, distribuendo pollo e mais equamente. Servi subito; per un altro giorno refrigera senza ritardo pollo, verdure e condimento separati.","image_url":"/recetas/ensalada-primavera-pollo/paso-08.webp","image_alt":"Insalata primaverile con pollo: Dividere e servire"}],"notes":"Pollo cotto refrigerato fino a 3 giorni; verdure lavate e asciutte fino a 2 giorni. Consuma l’insalata condita in giornata. Puoi sostituire mais con uguale peso di piselli cotti, cambiando la nutrizione. Pane e contorni esclusi.","nutrition":{"calories":288.0,"protein_g":30.7,"carbs_g":13.3,"fat_g":12.9,"saturated_fat_g":1.5,"fiber_g":3.5,"sugar_g":5.8,"sodium_mg":462.0,"serving_size":"1 delle 4 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 4 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario."},"keywords":["insalata primavera pollo","insalata pollo verdure","condimento limone senape"],"image_url":"/recetas/ensalada-primavera-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-primavera-pollo/portada.webp","alt":"Insalata primaverile con pollo: piatto pronto"}],"seo":{"title":"Insalata primaverile con pollo | Manual de Cocina","description":"Insalata primavera con pollo, verdure croccanti e condimento al limone e senape. Quattro porzioni in 45 minuti, pollo cotto separatamente.","image_alt":"Insalata primaverile con pollo: piatto pronto","image_variants":["/recetas/ensalada-primavera-pollo/portada-1x1.webp","/recetas/ensalada-primavera-pollo/portada-4x3.webp","/recetas/ensalada-primavera-pollo/portada-16x9.webp"],"faq":[{"q":"Posso usare pollo già cotto?","a":"350–375 g conservati correttamente; la nutrizione è calcolata con 500 g di petto crudo."},{"q":"Posso preparare il giorno prima?","a":"Conserva pollo, verdure asciutte e condimento separati e mescola al servizio."},{"q":"Come evito che la lattuga appassisca?","a":"Asciugala, fai intiepidire il pollo e condisci subito prima di mangiare."}]},"published":false,"editorial_status":"ready","content_html":"<p>Strisce di pollo, verdure croccanti e condimento con limone, olio e senape. Il pollo cuoce separatamente e intiepidisce prima della lattuga.</p><p>4 porzioni in 45 minuti, inclusi 10 di riposo e raffreddamento. Controlla la cottura con termometro.</p>"},{"id":"47ba0ac6-0bf1-58c8-a038-507f369cffc2","recipe_group_id":"a25bba5a-9659-40ee-bba9-92221a8d7c19","slug":"春野菜とチキンのサラダ","public_path":"/ja/春野菜とチキンのサラダ","source_url":null,"language":"ja","title":"鶏肉入り春のサラダ","excerpt":"鶏肉とシャキシャキ野菜のサラダ、レモンとマスタードのドレッシング。4人分を45分で、鶏肉は別に焼いて冷まします。","summary":"鶏肉の細切りと生野菜を、レモン、油、マスタードで和えます。鶏肉は別に加熱し、少し冷ましてからレタスに加えます。\n\n4人分、45分には鶏肉の休ませ・冷却10分を含みます。火通りは温度計で確認します。","category":"サラダ","category_slug":"ensaladas","difficulty":"簡単","course":"主菜","cuisine":"世界の料理","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":45,"servings":4,"ingredients":[{"name":"皮なし鶏胸肉","amount":"500","unit":"g","group":"鶏肉"},{"name":"植物油","amount":"10","unit":"g","group":"鶏肉"},{"name":"塩","amount":"3","unit":"g","group":"鶏肉"},{"name":"黒こしょう","amount":"0.5","unit":"g","group":"鶏肉"},{"name":"ロメインレタス","amount":"200","unit":"g","group":"サラダ"},{"name":"皮付ききゅうり","amount":"200","unit":"g","group":"サラダ"},{"name":"トマト","amount":"250","unit":"g","group":"サラダ"},{"name":"にんじん","amount":"100","unit":"g","group":"サラダ"},{"name":"加熱済み缶詰コーン、水切り","amount":"120","unit":"g","group":"サラダ"},{"name":"レモン汁","amount":"30","unit":"g","group":"ドレッシング"},{"name":"植物油","amount":"25","unit":"g","group":"ドレッシング"},{"name":"練りマスタード","amount":"10","unit":"g","group":"ドレッシング"}],"steps":[{"title":"野菜を洗って水気を切る","content":"レタス200 g、きゅうり200 g、トマト250 g、にんじん100 gを飲用水で洗います。レタスの水気を十分取り、生の鶏肉のまな板や器具から離します。","image_url":"/recetas/ensalada-primavera-pollo/paso-01.webp","image_alt":"鶏肉入り春のサラダ: 野菜を洗って水気を切る"},{"title":"野菜を切る","content":"レタスを切り、きゅうりとトマトを1.5 cm角に、にんじんをすりおろします。コーン120 gの水を切り、全部を冷蔵します。","image_url":"/recetas/ensalada-primavera-pollo/paso-02.webp","image_alt":"鶏肉入り春のサラダ: 野菜を切る"},{"title":"鶏肉を下ごしらえする","content":"鶏胸肉500 gを約2 cmの均一な厚さに切り、塩3 gとこしょう0.5 gで味付けします。生の鶏肉は洗わず、扱った後は手と台を洗います。","image_url":"/recetas/ensalada-primavera-pollo/paso-03.webp","image_alt":"鶏肉入り春のサラダ: 鶏肉を下ごしらえする"},{"title":"鶏肉を加熱する","content":"油10 gを中火で熱し、片面約6–7分ずつ、中心74 °Cまで焼きます。先に焦げそうなら弱火にして短くふたをします。","image_url":"/recetas/ensalada-primavera-pollo/paso-04.webp","image_alt":"鶏肉入り春のサラダ: 鶏肉を加熱する"},{"title":"粗熱を取り切る","content":"加熱済み肉を清潔なまな板へ移して5分休ませ、幅1 cmに切ります。レタスがしおれないようさらに5分冷まします。","image_url":"/recetas/ensalada-primavera-pollo/paso-05.webp","image_alt":"鶏肉入り春のサラダ: 粗熱を取り切る"},{"title":"ドレッシングを混ぜる","content":"レモン汁30 gとマスタード10 gを混ぜ、油25 gを少しずつ加えて1分混ぜます。マスタードの塩分があるため追加の塩は味見して判断します。","image_url":"/recetas/ensalada-primavera-pollo/paso-06.webp","image_alt":"鶏肉入り春のサラダ: ドレッシングを混ぜる"},{"title":"サラダを和える","content":"少し冷ました鶏肉をレタス、きゅうり、トマト、にんじん、コーンへ加えます。食べる直前にドレッシングをかけ、スプーン2本で混ぜます。","image_url":"/recetas/ensalada-primavera-pollo/paso-07.webp","image_alt":"鶏肉入り春のサラダ: サラダを和える"},{"title":"分けて盛り付ける","content":"鶏肉とコーンを均等に4皿へ分け、すぐ提供します。後日用なら鶏肉、野菜、ドレッシングを別々にすぐ冷蔵します。","image_url":"/recetas/ensalada-primavera-pollo/paso-08.webp","image_alt":"鶏肉入り春のサラダ: 分けて盛り付ける"}],"notes":"加熱済み鶏肉は冷蔵で最長3日、洗ってよく乾かした野菜は最長2日。和えたサラダは当日中に食べます。コーンを同量の加熱済みグリーンピースへ替えると栄養値が変わります。パンや付け合わせは計算外です。","nutrition":{"calories":288.0,"protein_g":30.7,"carbs_g":13.3,"fat_g":12.9,"saturated_fat_g":1.5,"fiber_g":3.5,"sugar_g":5.8,"sodium_mg":462.0,"serving_size":"全4人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を4人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。"},"keywords":["チキンサラダ","春野菜サラダ","レモンマスタードドレッシング"],"image_url":"/recetas/ensalada-primavera-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-primavera-pollo/portada.webp","alt":"鶏肉入り春のサラダ: 完成した料理"}],"seo":{"title":"鶏肉入り春のサラダ | Manual de Cocina","description":"鶏肉とシャキシャキ野菜のサラダ、レモンとマスタードのドレッシング。4人分を45分で、鶏肉は別に焼いて冷まします。","image_alt":"鶏肉入り春のサラダ: 完成した料理","image_variants":["/recetas/ensalada-primavera-pollo/portada-1x1.webp","/recetas/ensalada-primavera-pollo/portada-4x3.webp","/recetas/ensalada-primavera-pollo/portada-16x9.webp"],"faq":[{"q":"加熱済みの鶏肉を使えますか？","a":"正しく保存した350–375 gを使えます。栄養計算は生胸肉500 gを基準にしています。"},{"q":"前日に準備できますか？","a":"肉、乾いた野菜、ドレッシングを別々に保存し、提供時に混ぜます。"},{"q":"レタスがしおれない方法は？","a":"水気をよく取り、肉を少し冷まし、食べる直前に和えます。"}]},"published":false,"editorial_status":"ready","content_html":"<p>鶏肉の細切りと生野菜を、レモン、油、マスタードで和えます。鶏肉は別に加熱し、少し冷ましてからレタスに加えます。</p><p>4人分、45分には鶏肉の休ませ・冷却10分を含みます。火通りは温度計で確認します。</p>"},{"id":"c18fefb6-e3e5-5aa8-8100-dbabdab24dca","recipe_group_id":"a25bba5a-9659-40ee-bba9-92221a8d7c19","slug":"salada-primavera-com-frango","public_path":"/pt/salada-primavera-com-frango","source_url":null,"language":"pt","title":"Salada primavera com frango","excerpt":"Salada primavera com frango, legumes crocantes e molho de limão e mostarda. Quatro porções em 45 minutos, com o frango preparado separadamente.","summary":"Tiras de frango com vegetais crocantes e molho de limão, óleo e mostarda. O frango cozinha separado e amorna antes de entrar na alface.\n\nRende 4 porções. Os 45 minutos incluem 10 de descanso e resfriamento; confira a cocção com termômetro.","category":"Saladas","category_slug":"ensaladas","difficulty":"Fácil","course":"Prato principal","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":45,"servings":4,"ingredients":[{"name":"peito de frango sem pele","amount":"500","unit":"g","group":"Frango"},{"name":"óleo vegetal","amount":"10","unit":"g","group":"Frango"},{"name":"sal","amount":"3","unit":"g","group":"Frango"},{"name":"pimenta-do-reino","amount":"0.5","unit":"g","group":"Frango"},{"name":"alface-romana","amount":"200","unit":"g","group":"Salada"},{"name":"pepino com casca","amount":"200","unit":"g","group":"Salada"},{"name":"tomate","amount":"250","unit":"g","group":"Salada"},{"name":"cenoura","amount":"100","unit":"g","group":"Salada"},{"name":"milho cozido em conserva, escorrido","amount":"120","unit":"g","group":"Salada"},{"name":"suco de limão","amount":"30","unit":"g","group":"Molho"},{"name":"óleo vegetal","amount":"25","unit":"g","group":"Molho"},{"name":"mostarda preparada","amount":"10","unit":"g","group":"Molho"}],"steps":[{"title":"Lave e seque os vegetais","content":"Lave 200 g de alface, 200 g de pepino, 250 g de tomate e 100 g de cenoura com água potável. Seque bem a alface; separe da tábua e utensílios do frango cru.","image_url":"/recetas/ensalada-primavera-pollo/paso-01.webp","image_alt":"Salada primavera com frango: Lave e seque os vegetais"},{"title":"Corte os vegetais","content":"Pique alface, corte pepino e tomate em cubos de 1,5 cm e rale cenoura. Escorra 120 g de milho. Refrigere tudo enquanto cozinha o frango.","image_url":"/recetas/ensalada-primavera-pollo/paso-02.webp","image_alt":"Salada primavera com frango: Corte os vegetais"},{"title":"Prepare o frango","content":"Divida 500 g de peito em filés uniformes de cerca de 2 cm. Tempere com 3 g de sal e 0,5 g de pimenta. Não lave frango cru; limpe mãos e superfície depois.","image_url":"/recetas/ensalada-primavera-pollo/paso-03.webp","image_alt":"Salada primavera com frango: Prepare o frango"},{"title":"Cozinhe o frango","content":"Aqueça 10 g de óleo em fogo médio. Cozinhe cerca de 6–7 minutos por lado até 74 °C no centro. Se dourar antes, abaixe e tampe brevemente.","image_url":"/recetas/ensalada-primavera-pollo/paso-04.webp","image_alt":"Salada primavera com frango: Cozinhe o frango"},{"title":"Deixe amornar e corte","content":"Passe o frango cozido a uma tábua limpa. Descanse 5 minutos, corte tiras de 1 cm e deixe amornar mais 5 minutos para não murchar a alface.","image_url":"/recetas/ensalada-primavera-pollo/paso-05.webp","image_alt":"Salada primavera com frango: Deixe amornar e corte"},{"title":"Emulsione o molho","content":"Bata 30 g de suco de limão com 10 g de mostarda. Acrescente lentamente 25 g de óleo e misture 1 minuto. Prove antes de salgar, pois a mostarda já contém sal.","image_url":"/recetas/ensalada-primavera-pollo/paso-06.webp","image_alt":"Salada primavera com frango: Emulsione o molho"},{"title":"Misture a salada","content":"Junte frango morno, alface, pepino, tomate, cenoura e milho. Coloque o molho e misture com duas colheres só antes de servir.","image_url":"/recetas/ensalada-primavera-pollo/paso-07.webp","image_alt":"Salada primavera com frango: Misture a salada"},{"title":"Divida e sirva","content":"Divida em 4 pratos com frango e milho distribuídos igualmente. Sirva logo; para outro dia refrigere sem demora frango, verduras e molho separados.","image_url":"/recetas/ensalada-primavera-pollo/paso-08.webp","image_alt":"Salada primavera com frango: Divida e sirva"}],"notes":"Frango cozido refrigerado por até 3 dias; vegetais lavados e secos por até 2 dias. Salada temperada deve ser consumida no mesmo dia. Milho pode ser trocado por igual peso de ervilhas cozidas, alterando a nutrição. Pão e acompanhamentos não incluídos.","nutrition":{"calories":288.0,"protein_g":30.7,"carbs_g":13.3,"fat_g":12.9,"saturated_fat_g":1.5,"fiber_g":3.5,"sugar_g":5.8,"sodium_mg":462.0,"serving_size":"1 de 4 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 4 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário."},"keywords":["salada primavera frango","salada de frango","molho limão mostarda"],"image_url":"/recetas/ensalada-primavera-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-primavera-pollo/portada.webp","alt":"Salada primavera com frango: prato pronto"}],"seo":{"title":"Salada primavera com frango | Manual de Cocina","description":"Salada primavera com frango, legumes crocantes e molho de limão e mostarda. Quatro porções em 45 minutos, com o frango preparado separadamente.","image_alt":"Salada primavera com frango: prato pronto","image_variants":["/recetas/ensalada-primavera-pollo/portada-1x1.webp","/recetas/ensalada-primavera-pollo/portada-4x3.webp","/recetas/ensalada-primavera-pollo/portada-16x9.webp"],"faq":[{"q":"Posso usar frango já cozido?","a":"Use 350–375 g conservados corretamente; a nutrição considera 500 g de peito cru."},{"q":"Posso preparar na véspera?","a":"Guarde frango, vegetais secos e molho separados; misture ao servir."},{"q":"Como evitar alface murcha?","a":"Seque bem, deixe o frango amornar e tempere na hora de comer."}]},"published":false,"editorial_status":"ready","content_html":"<p>Tiras de frango com vegetais crocantes e molho de limão, óleo e mostarda. O frango cozinha separado e amorna antes de entrar na alface.</p><p>Rende 4 porções. Os 45 minutos incluem 10 de descanso e resfriamento; confira a cocção com termômetro.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/ensalada-primavera-pollo') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

-- receta-de-arroz-chino
do $pub$
declare
  g constant uuid := '441e8e63-7479-44fa-b0b1-8100065043ff';
  es_id constant uuid := '85a7216a-7875-41de-ba42-cbf488aa2277';
  j constant jsonb := $j$[{"id":"85a7216a-7875-41de-ba42-cbf488aa2277","recipe_group_id":"441e8e63-7479-44fa-b0b1-8100065043ff","slug":"receta-de-arroz-chino","public_path":"/receta-de-arroz-chino","source_url":"https://manualdecocina.com/receta-de-arroz-chino/","language":"es","title":"Arroz chino casero con pollo y huevo","excerpt":"Arroz chino casero con pollo, huevo y verduras, salteado por tandas con arroz frío. Cuatro porciones y consejos para que quede suelto.","summary":"Esta versión de arroz salteado combina pechuga, huevo, zanahoria, guisantes y cebolleta. Se trabaja en una sartén grande o wok y por tandas para que el arroz no se cueza en su propio vapor.\n\nSe parte de 700 g de arroz ya cocido y enfriado de forma segura. Los 40 minutos no incluyen la cocción y enfriado previos del arroz.","category":"Platos principales","category_slug":"platos-principales","difficulty":"Media","course":"Plato principal","cuisine":"Fusión","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"arroz blanco cocido y refrigerado","amount":"700","unit":"g","group":"Salteado"},{"name":"pechuga de pollo sin piel","amount":"300","unit":"g","group":"Salteado"},{"name":"huevos medianos","amount":"2","unit":"unidades","group":"Salteado"},{"name":"zanahoria","amount":"150","unit":"g","group":"Verduras"},{"name":"guisantes congelados","amount":"100","unit":"g","group":"Verduras"},{"name":"cebolleta","amount":"60","unit":"g","group":"Verduras"},{"name":"ajo","amount":"6","unit":"g","group":"Aromáticos"},{"name":"jengibre fresco","amount":"10","unit":"g","group":"Aromáticos"},{"name":"aceite vegetal","amount":"30","unit":"g","group":"Salteado"},{"name":"salsa de soja","amount":"30","unit":"g","group":"Sazón"}],"steps":[{"title":"Separa el arroz","content":"Saca 700 g de arroz cocido de la nevera y separa los grumos con un tenedor limpio. Usa arroz que se haya enfriado rápidamente y mantenido refrigerado; no emplees arroz que pasó la noche fuera.","image_url":"/recetas/receta-de-arroz-chino/paso-01.webp","image_alt":"Arroz chino casero con pollo y huevo: Separa el arroz"},{"title":"Corta y organiza","content":"Corta 300 g de pechuga en dados de 1,5 cm y 150 g de zanahoria en dados de 5 mm. Pica 60 g de cebolleta, 6 g de ajo y 10 g de jengibre. Bate 2 huevos y mide 100 g de guisantes y 30 g de soja.","image_url":"/recetas/receta-de-arroz-chino/paso-02.webp","image_alt":"Arroz chino casero con pollo y huevo: Corta y organiza"},{"title":"Cuaja los huevos","content":"Calienta 5 g de aceite en el wok. Añade los 2 huevos batidos y remueve durante 1–2 minutos hasta que estén completamente cuajados. Retíralos a un plato limpio.","image_url":"/recetas/receta-de-arroz-chino/paso-03.webp","image_alt":"Arroz chino casero con pollo y huevo: Cuaja los huevos"},{"title":"Cocina el pollo","content":"Añade 10 g de aceite y saltea el pollo unos 5–6 minutos, removiendo, hasta que los dados alcancen 74 °C en el centro. Retira a otro plato limpio; limpia cualquier utensilio que tocó pollo crudo.","image_url":"/recetas/receta-de-arroz-chino/paso-04.webp","image_alt":"Arroz chino casero con pollo y huevo: Cocina el pollo"},{"title":"Saltea las verduras","content":"Calienta 5 g de aceite y cocina la zanahoria 3 minutos. Añade los guisantes y la parte blanca de la cebolleta; cocina 2 minutos más. Agrega ajo y jengibre durante los últimos 30 segundos.","image_url":"/recetas/receta-de-arroz-chino/paso-05.webp","image_alt":"Arroz chino casero con pollo y huevo: Saltea las verduras"},{"title":"Fríe el arroz por tandas","content":"Retira las verduras y añade los 10 g de aceite restantes. Saltea el arroz en dos tandas durante 2 minutos cada una, extendiéndolo y removiendo para calentarlo bien. Junta las tandas y agrega 30 g de soja por el borde de la sartén.","image_url":"/recetas/receta-de-arroz-chino/paso-06.webp","image_alt":"Arroz chino casero con pollo y huevo: Fríe el arroz por tandas"},{"title":"Reúne los ingredientes","content":"Devuelve pollo, huevo y verduras al wok. Mezcla 1–2 minutos hasta que todo esté humeante y el conjunto alcance 74 °C. Añade la parte verde de la cebolleta y remueve.","image_url":"/recetas/receta-de-arroz-chino/paso-07.webp","image_alt":"Arroz chino casero con pollo y huevo: Reúne los ingredientes"},{"title":"Sirve inmediatamente","content":"Reparte el salteado en 4 cuencos. Si sobran porciones, pásalas enseguida a recipientes bajos y refrigera antes de 2 horas; no mantengas el wok templado a temperatura ambiente.","image_url":"/recetas/receta-de-arroz-chino/paso-08.webp","image_alt":"Arroz chino casero con pollo y huevo: Sirve inmediatamente"}],"notes":"Para cocinar arroz de antemano, enfríalo rápidamente en una bandeja poco profunda y refrigera cuanto antes; úsalo al día siguiente. No enfriar una olla grande durante horas. La soja aporta sal: prueba antes de añadir más. El arroz recién cocido y húmedo se apelmaza más. Recalienta las sobras hasta 74 °C y evita ciclos repetidos de enfriado y calentado.","nutrition":{"calories":467.0,"protein_g":27.4,"carbs_g":58.9,"fat_g":12.6,"saturated_fat_g":1.9,"fiber_g":3.4,"sugar_g":3.6,"sodium_mg":539.0,"serving_size":"1 de 4 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 4 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma.  Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"arroz blanco cocido y refrigerado","edible_grams":700,"fdc_id":168878,"fdc_description":"Rice, white, long-grain, regular, enriched, cooked","per_100g":{"sugar_g":0.05,"fiber_g":0.4,"sodium_mg":1.0,"saturated_fat_g":0.077,"protein_g":2.69,"fat_g":0.28,"carbs_g":28.17,"calories":130.0},"source_url":"https://fdc.nal.usda.gov/food-details/168878/nutrients"},{"ingredient":"pechuga de pollo sin piel","edible_grams":300,"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120.0,"saturated_fat_g":0.563,"sodium_mg":45.0,"protein_g":22.5,"sugar_g":0.0,"carbs_g":0.0,"fiber_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients"},{"ingredient":"huevos medianos","edible_grams":100,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143.0,"saturated_fat_g":3.126,"protein_g":12.56,"sodium_mg":142.0,"sugar_g":0.37,"fat_g":9.51,"carbs_g":0.72,"fiber_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"zanahoria","edible_grams":150,"fdc_id":170393,"fdc_description":"Carrots, raw","per_100g":{"saturated_fat_g":0.032,"sodium_mg":69.0,"protein_g":0.93,"fat_g":0.24,"sugar_g":4.74,"carbs_g":9.58,"calories":41.0,"fiber_g":2.8},"source_url":"https://fdc.nal.usda.gov/food-details/170393/nutrients"},{"ingredient":"guisantes congelados","edible_grams":100,"fdc_id":170016,"fdc_description":"Peas, green, frozen, unprepared (Includes foods for USDA's Food Distribution Program)","per_100g":{"sugar_g":5.0,"fat_g":0.4,"carbs_g":13.62,"calories":77.0,"protein_g":5.22,"fiber_g":4.5,"sodium_mg":108.0,"saturated_fat_g":0.066},"source_url":"https://fdc.nal.usda.gov/food-details/170016/nutrients"},{"ingredient":"cebolleta","edible_grams":60,"fdc_id":170005,"fdc_description":"Onions, spring or scallions (includes tops and bulb), raw","per_100g":{"sugar_g":2.33,"calories":32.0,"fat_g":0.19,"protein_g":1.83,"fiber_g":2.6,"sodium_mg":16.0,"saturated_fat_g":0.032,"carbs_g":7.34},"source_url":"https://fdc.nal.usda.gov/food-details/170005/nutrients"},{"ingredient":"ajo","edible_grams":6,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.06,"calories":149.0,"sugar_g":1.0,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17.0,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"jengibre fresco","edible_grams":10,"fdc_id":169231,"fdc_description":"Ginger root, raw","per_100g":{"sugar_g":1.7,"fat_g":0.75,"sodium_mg":13.0,"protein_g":1.82,"carbs_g":17.77,"calories":80.0,"fiber_g":2.0,"saturated_fat_g":0.203},"source_url":"https://fdc.nal.usda.gov/food-details/169231/nutrients"},{"ingredient":"aceite vegetal","edible_grams":30,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"fat_g":100.0,"saturated_fat_g":7.365,"protein_g":0.0,"carbs_g":0.0,"calories":884.0,"fiber_g":0.0,"sodium_mg":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"salsa de soja","edible_grams":30,"fdc_id":174277,"fdc_description":"Soy sauce made from soy and wheat (shoyu)","per_100g":{"fat_g":0.57,"carbs_g":4.93,"sugar_g":0.4,"protein_g":8.14,"sodium_mg":5493.0,"saturated_fat_g":0.073,"calories":53.0,"fiber_g":0.8},"source_url":"https://fdc.nal.usda.gov/food-details/174277/nutrients"}]},"keywords":["arroz chino casero","arroz salteado con pollo","arroz frito con huevo"],"image_url":"/recetas/receta-de-arroz-chino/portada.webp","gallery":[{"url":"/recetas/receta-de-arroz-chino/portada.webp","alt":"Arroz chino casero con pollo y huevo: plato terminado"}],"seo":{"title":"Arroz chino casero con pollo y huevo | Manual de Cocina","description":"Arroz chino casero con pollo, huevo y verduras, salteado por tandas con arroz frío. Cuatro porciones y consejos para que quede suelto.","image_alt":"Arroz chino casero con pollo y huevo: plato terminado","image_variants":["/recetas/receta-de-arroz-chino/portada-1x1.webp","/recetas/receta-de-arroz-chino/portada-4x3.webp","/recetas/receta-de-arroz-chino/portada-16x9.webp"],"faq":[{"q":"¿Por qué se usa arroz frío?","a":"La superficie está más seca y los granos se separan mejor al saltear. Debe haberse enfriado y refrigerado de forma segura."},{"q":"¿Puedo omitir el pollo?","a":"Sí, pero ya no tendrá los mismos valores nutricionales; añade el huevo y las verduras como indica el método."},{"q":"¿Es necesario tener wok?","a":"No. Una sartén amplia sirve si trabajas en tandas pequeñas y no acumulas humedad."}]},"published":false,"editorial_status":"ready","content_html":"<p>Esta versión de arroz salteado combina pechuga, huevo, zanahoria, guisantes y cebolleta. Se trabaja en una sartén grande o wok y por tandas para que el arroz no se cueza en su propio vapor.</p><p>Se parte de 700 g de arroz ya cocido y enfriado de forma segura. Los 40 minutos no incluyen la cocción y enfriado previos del arroz.</p>"},{"id":"3fb3fd22-0cd9-58e1-89af-ee4593360c5c","recipe_group_id":"441e8e63-7479-44fa-b0b1-8100065043ff","slug":"gebratener-reis-mit-haehnchen-und-ei","public_path":"/de/gebratener-reis-mit-haehnchen-und-ei","source_url":null,"language":"de","title":"Gebratener Reis mit Hähnchen und Ei","excerpt":"Gebratener Reis mit Hähnchen, Ei, Karotte und Erbsen. In kleinen Portionen im Wok oder einer großen Pfanne braten, damit die Körner locker bleiben.","summary":"Hähnchenbrust, Ei, Karotte, Erbsen und Frühlingszwiebeln werden mit Reis portionsweise gebraten, damit er nicht im eigenen Dampf gart.\n\n700 g bereits gegarter, sicher abgekühlter Reis sind nötig. Die 40 Minuten enthalten nicht dessen vorheriges Kochen und Kühlen.","category":"Hauptgerichte","category_slug":"platos-principales","difficulty":"Mittel","course":"Hauptgericht","cuisine":"Fusion","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"gekochter, gekühlter weißer Reis","amount":"700","unit":"g","group":"Pfannengericht"},{"name":"Hähnchenbrust ohne Haut","amount":"300","unit":"g","group":"Pfannengericht"},{"name":"mittelgroße Eier","amount":"2","unit":"Stück","group":"Pfannengericht"},{"name":"Karotte","amount":"150","unit":"g","group":"Gemüse"},{"name":"Tiefkühlerbsen","amount":"100","unit":"g","group":"Gemüse"},{"name":"Frühlingszwiebel","amount":"60","unit":"g","group":"Gemüse"},{"name":"Knoblauch","amount":"6","unit":"g","group":"Aromaten"},{"name":"frischer Ingwer","amount":"10","unit":"g","group":"Aromaten"},{"name":"Pflanzenöl","amount":"30","unit":"g","group":"Pfannengericht"},{"name":"Sojasauce","amount":"30","unit":"g","group":"Würzung"}],"steps":[{"title":"Reis auflockern","content":"700 g gekochten Reis aus dem Kühlschrank nehmen und Klumpen mit sauberer Gabel lösen. Nur schnell abgekühlten und gekühlt gelagerten Reis verwenden, keinen über Nacht ungekühlt gebliebenen.","image_url":"/recetas/receta-de-arroz-chino/paso-01.webp","image_alt":"Gebratener Reis mit Hähnchen und Ei: Reis auflockern"},{"title":"Schneiden und vorbereiten","content":"300 g Hähnchen in 1,5-cm-Würfel und 150 g Karotte in 5-mm-Würfel schneiden. 60 g Frühlingszwiebeln, 6 g Knoblauch und 10 g Ingwer hacken. 2 Eier verquirlen; 100 g Erbsen und 30 g Sojasauce abmessen.","image_url":"/recetas/receta-de-arroz-chino/paso-02.webp","image_alt":"Gebratener Reis mit Hähnchen und Ei: Schneiden und vorbereiten"},{"title":"Eier stocken lassen","content":"5 g Öl im Wok erhitzen. Die 2 Eier unter Rühren 1–2 Minuten vollständig stocken lassen und auf einen sauberen Teller geben.","image_url":"/recetas/receta-de-arroz-chino/paso-03.webp","image_alt":"Gebratener Reis mit Hähnchen und Ei: Eier stocken lassen"},{"title":"Hähnchen garen","content":"10 g Öl zugeben und Hähnchen unter Rühren etwa 5–6 Minuten bis 74 °C im Kern braten. Auf einen anderen sauberen Teller geben; Werkzeuge mit Rohfleischkontakt reinigen.","image_url":"/recetas/receta-de-arroz-chino/paso-04.webp","image_alt":"Gebratener Reis mit Hähnchen und Ei: Hähnchen garen"},{"title":"Gemüse anbraten","content":"5 g Öl erhitzen und Karotte 3 Minuten braten. Erbsen und weiße Zwiebelteile weitere 2 Minuten garen; Knoblauch und Ingwer für die letzten 30 Sekunden zugeben.","image_url":"/recetas/receta-de-arroz-chino/paso-05.webp","image_alt":"Gebratener Reis mit Hähnchen und Ei: Gemüse anbraten"},{"title":"Reis portionsweise braten","content":"Gemüse herausnehmen und restliche 10 g Öl zugeben. Reis in zwei Portionen je 2 Minuten ausbreiten und durchrühren. Zusammengeben und 30 g Sojasauce am Pfannenrand eingießen.","image_url":"/recetas/receta-de-arroz-chino/paso-06.webp","image_alt":"Gebratener Reis mit Hähnchen und Ei: Reis portionsweise braten"},{"title":"Zutaten zusammenführen","content":"Fleisch, Ei und Gemüse zurückgeben und 1–2 Minuten mischen, bis alles dampft und 74 °C erreicht. Grüne Zwiebelteile unterrühren.","image_url":"/recetas/receta-de-arroz-chino/paso-07.webp","image_alt":"Gebratener Reis mit Hähnchen und Ei: Zutaten zusammenführen"},{"title":"Sofort servieren","content":"Auf 4 Schüsseln verteilen. Reste sofort in flache Behälter füllen und innerhalb von 2 Stunden kühlen; den lauwarmen Wok nicht ungekühlt stehen lassen.","image_url":"/recetas/receta-de-arroz-chino/paso-08.webp","image_alt":"Gebratener Reis mit Hähnchen und Ei: Sofort servieren"}],"notes":"Reis für später schnell auf einem flachen Blech abkühlen und zügig kühlen; am Folgetag verwenden. Keinen großen Topf stundenlang abkühlen lassen. Wegen der Sojasauce vor zusätzlichem Salz probieren. Frischer feuchter Reis verklumpt leichter. Reste bis 74 °C erhitzen und wiederholtes Abkühlen/Aufwärmen vermeiden.","nutrition":{"calories":467.0,"protein_g":27.4,"carbs_g":58.9,"fat_g":12.6,"saturated_fat_g":1.9,"fiber_g":3.4,"sugar_g":3.6,"sodium_mg":539.0,"serving_size":"1 von 4 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 4 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers."},"keywords":["gebratener Reis Hähnchen Ei","Reis im Wok","chinesischer Bratreis"],"image_url":"/recetas/receta-de-arroz-chino/portada.webp","gallery":[{"url":"/recetas/receta-de-arroz-chino/portada.webp","alt":"Gebratener Reis mit Hähnchen und Ei: fertiges Gericht"}],"seo":{"title":"Gebratener Reis mit Hähnchen und Ei | Manual de Cocina","description":"Gebratener Reis mit Hähnchen, Ei, Karotte und Erbsen. In kleinen Portionen im Wok oder einer großen Pfanne braten, damit die Körner locker bleiben.","image_alt":"Gebratener Reis mit Hähnchen und Ei: fertiges Gericht","image_variants":["/recetas/receta-de-arroz-chino/portada-1x1.webp","/recetas/receta-de-arroz-chino/portada-4x3.webp","/recetas/receta-de-arroz-chino/portada-16x9.webp"],"faq":[{"q":"Warum kalter Reis?","a":"Trockene Oberfläche und getrennte Körner erleichtern das Braten. Er muss sicher abgekühlt und gekühlt gelagert sein."},{"q":"Kann ich Hähnchen weglassen?","a":"Ja, Ei und Gemüse wie beschrieben verwenden; die Nährwerte ändern sich."},{"q":"Brauche ich einen Wok?","a":"Eine breite Pfanne genügt, wenn kleine Portionen gebraten werden und keine Feuchtigkeit gesammelt wird."}]},"published":false,"editorial_status":"ready","content_html":"<p>Hähnchenbrust, Ei, Karotte, Erbsen und Frühlingszwiebeln werden mit Reis portionsweise gebraten, damit er nicht im eigenen Dampf gart.</p><p>700 g bereits gegarter, sicher abgekühlter Reis sind nötig. Die 40 Minuten enthalten nicht dessen vorheriges Kochen und Kühlen.</p>"},{"id":"2040f9a7-af6e-59f9-9c36-25389a75a29d","recipe_group_id":"441e8e63-7479-44fa-b0b1-8100065043ff","slug":"chicken-and-egg-fried-rice","public_path":"/en/chicken-and-egg-fried-rice","source_url":null,"language":"en","title":"Chicken and egg fried rice","excerpt":"Chicken and egg fried rice with carrots, peas and spring onions. Cook in batches in a wok or wide pan to keep the grains separate.","summary":"This fried rice combines chicken breast, eggs, carrots, peas and spring onions. Use a large wok or pan and work in batches to avoid steaming the rice.\n\nStart with 700 g safely cooled cooked rice. The 40 minutes exclude cooking and chilling the rice beforehand.","category":"Main dishes","category_slug":"platos-principales","difficulty":"Medium","course":"Main course","cuisine":"Fusion","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"cooked, refrigerated white rice","amount":"700","unit":"g","group":"Stir-fry"},{"name":"skinless chicken breast","amount":"300","unit":"g","group":"Stir-fry"},{"name":"medium eggs","amount":"2","unit":"pieces","group":"Stir-fry"},{"name":"carrot","amount":"150","unit":"g","group":"Vegetables"},{"name":"frozen peas","amount":"100","unit":"g","group":"Vegetables"},{"name":"spring onion","amount":"60","unit":"g","group":"Vegetables"},{"name":"garlic","amount":"6","unit":"g","group":"Aromatics"},{"name":"fresh ginger","amount":"10","unit":"g","group":"Aromatics"},{"name":"vegetable oil","amount":"30","unit":"g","group":"Stir-fry"},{"name":"soy sauce","amount":"30","unit":"g","group":"Seasoning"}],"steps":[{"title":"Separate the rice grains","content":"Take 700 g cooked rice from the fridge and loosen clumps with a clean fork. Use rice cooled quickly and kept refrigerated; never use rice left out overnight.","image_url":"/recetas/receta-de-arroz-chino/paso-01.webp","image_alt":"Chicken and egg fried rice: Separate the rice grains"},{"title":"Cut and organize","content":"Dice 300 g chicken into 1.5 cm pieces and 150 g carrot into 5 mm pieces. Chop 60 g spring onion, 6 g garlic and 10 g ginger. Beat 2 eggs; measure 100 g peas and 30 g soy sauce.","image_url":"/recetas/receta-de-arroz-chino/paso-02.webp","image_alt":"Chicken and egg fried rice: Cut and organize"},{"title":"Cook the eggs","content":"Heat 5 g oil in the wok. Scramble the 2 beaten eggs for 1–2 minutes until fully set; transfer to a clean plate.","image_url":"/recetas/receta-de-arroz-chino/paso-03.webp","image_alt":"Chicken and egg fried rice: Cook the eggs"},{"title":"Cook the chicken","content":"Add 10 g oil and stir-fry chicken about 5–6 minutes until the pieces reach 74 °C inside. Move to another clean plate; wash utensils that touched raw chicken.","image_url":"/recetas/receta-de-arroz-chino/paso-04.webp","image_alt":"Chicken and egg fried rice: Cook the chicken"},{"title":"Stir-fry the vegetables","content":"Heat 5 g oil and cook carrot for 3 minutes. Add peas and white spring-onion parts for another 2 minutes; add garlic and ginger during the last 30 seconds.","image_url":"/recetas/receta-de-arroz-chino/paso-05.webp","image_alt":"Chicken and egg fried rice: Stir-fry the vegetables"},{"title":"Fry the rice in batches","content":"Remove vegetables and add the remaining 10 g oil. Stir-fry rice in two batches for 2 minutes each, spreading and tossing thoroughly. Combine and pour 30 g soy sauce around the pan edge.","image_url":"/recetas/receta-de-arroz-chino/paso-06.webp","image_alt":"Chicken and egg fried rice: Fry the rice in batches"},{"title":"Combine the ingredients","content":"Return chicken, eggs and vegetables. Toss 1–2 minutes until steaming and the mixture reaches 74 °C. Add green spring-onion parts and stir.","image_url":"/recetas/receta-de-arroz-chino/paso-07.webp","image_alt":"Chicken and egg fried rice: Combine the ingredients"},{"title":"Serve immediately","content":"Divide into 4 bowls. Transfer leftovers promptly into shallow containers and refrigerate within 2 hours; do not leave a lukewarm wok at room temperature.","image_url":"/recetas/receta-de-arroz-chino/paso-08.webp","image_alt":"Chicken and egg fried rice: Serve immediately"}],"notes":"For advance rice, cool quickly on a shallow tray and refrigerate promptly; use the next day. Do not cool a large pot for hours. Taste before adding salt because soy sauce contains it. Fresh wet rice clumps more. Reheat leftovers to 74 °C and avoid repeated cooling/reheating cycles.","nutrition":{"calories":467.0,"protein_g":27.4,"carbs_g":58.9,"fat_g":12.6,"saturated_fat_g":1.9,"fiber_g":3.4,"sugar_g":3.6,"sodium_mg":539.0,"serving_size":"1 of 4 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 4 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation."},"keywords":["chicken egg fried rice","Chinese-style fried rice","wok rice"],"image_url":"/recetas/receta-de-arroz-chino/portada.webp","gallery":[{"url":"/recetas/receta-de-arroz-chino/portada.webp","alt":"Chicken and egg fried rice: finished dish"}],"seo":{"title":"Chicken and egg fried rice | Manual de Cocina","description":"Chicken and egg fried rice with carrots, peas and spring onions. Cook in batches in a wok or wide pan to keep the grains separate.","image_alt":"Chicken and egg fried rice: finished dish","image_variants":["/recetas/receta-de-arroz-chino/portada-1x1.webp","/recetas/receta-de-arroz-chino/portada-4x3.webp","/recetas/receta-de-arroz-chino/portada-16x9.webp"],"faq":[{"q":"Why use cold rice?","a":"Its drier surface helps grains separate during frying. It must have been cooled and refrigerated safely."},{"q":"Can I omit the chicken?","a":"Yes, follow the egg and vegetable method; nutrition will differ."},{"q":"Is a wok essential?","a":"A wide pan works if you cook small batches and avoid excess moisture."}]},"published":false,"editorial_status":"ready","content_html":"<p>This fried rice combines chicken breast, eggs, carrots, peas and spring onions. Use a large wok or pan and work in batches to avoid steaming the rice.</p><p>Start with 700 g safely cooled cooked rice. The 40 minutes exclude cooking and chilling the rice beforehand.</p>"},{"id":"d934b552-ae49-5049-8ba4-2bffa32dd8a0","recipe_group_id":"441e8e63-7479-44fa-b0b1-8100065043ff","slug":"riz-saute-poulet-oeufs","public_path":"/fr/riz-saute-poulet-oeufs","source_url":null,"language":"fr","title":"Riz sauté au poulet et aux œufs","excerpt":"Riz sauté au poulet et aux œufs, carotte, petits pois et ciboule. Travaillez en petites quantités au wok ou dans une grande poêle.","summary":"Poulet, œufs, carotte, petits pois et ciboule accompagnent ce riz sauté. Cuisez par petites quantités pour éviter qu’il ne cuise dans sa vapeur.\n\nPrévoyez 700 g de riz cuit refroidi correctement. Les 40 minutes excluent sa cuisson et son refroidissement préalables.","category":"Plats principaux","category_slug":"platos-principales","difficulty":"Moyenne","course":"Plat principal","cuisine":"Fusion","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"riz blanc cuit et réfrigéré","amount":"700","unit":"g","group":"Riz sauté"},{"name":"blanc de poulet sans peau","amount":"300","unit":"g","group":"Riz sauté"},{"name":"œufs moyens","amount":"2","unit":"pièces","group":"Riz sauté"},{"name":"carotte","amount":"150","unit":"g","group":"Légumes"},{"name":"petits pois surgelés","amount":"100","unit":"g","group":"Légumes"},{"name":"ciboule","amount":"60","unit":"g","group":"Légumes"},{"name":"ail","amount":"6","unit":"g","group":"Aromates"},{"name":"gingembre frais","amount":"10","unit":"g","group":"Aromates"},{"name":"huile végétale","amount":"30","unit":"g","group":"Riz sauté"},{"name":"sauce soja","amount":"30","unit":"g","group":"Assaisonnement"}],"steps":[{"title":"Séparer les grains de riz","content":"Sortez 700 g de riz cuit du réfrigérateur et séparez les grains avec une fourchette propre. Utilisez du riz vite refroidi et réfrigéré, jamais resté dehors la nuit.","image_url":"/recetas/receta-de-arroz-chino/paso-01.webp","image_alt":"Riz sauté au poulet et aux œufs: Séparer les grains de riz"},{"title":"Couper et organiser","content":"Taillez 300 g de poulet en dés de 1,5 cm et 150 g de carotte en dés de 5 mm. Hachez 60 g de ciboule, 6 g d’ail et 10 g de gingembre. Battez 2 œufs; mesurez 100 g de petits pois et 30 g de soja.","image_url":"/recetas/receta-de-arroz-chino/paso-02.webp","image_alt":"Riz sauté au poulet et aux œufs: Couper et organiser"},{"title":"Cuire les œufs","content":"Chauffez 5 g d’huile au wok. Brouillez les 2 œufs 1–2 minutes jusqu’à cuisson complète; réservez sur une assiette propre.","image_url":"/recetas/receta-de-arroz-chino/paso-03.webp","image_alt":"Riz sauté au poulet et aux œufs: Cuire les œufs"},{"title":"Cuire le poulet","content":"Ajoutez 10 g d’huile et sautez le poulet 5–6 minutes environ jusqu’à 74 °C à cœur. Réservez ailleurs; nettoyez les ustensiles ayant touché le poulet cru.","image_url":"/recetas/receta-de-arroz-chino/paso-04.webp","image_alt":"Riz sauté au poulet et aux œufs: Cuire le poulet"},{"title":"Faire sauter les légumes","content":"Chauffez 5 g d’huile; cuisez la carotte 3 minutes, puis petits pois et blanc de ciboule 2 minutes. Ajoutez ail et gingembre les 30 dernières secondes.","image_url":"/recetas/receta-de-arroz-chino/paso-05.webp","image_alt":"Riz sauté au poulet et aux œufs: Faire sauter les légumes"},{"title":"Faire sauter le riz par portions","content":"Retirez les légumes et ajoutez les 10 g d’huile restants. Sautez le riz en deux lots de 2 minutes, en l’étalant et remuant. Réunissez et versez 30 g de soja sur le bord.","image_url":"/recetas/receta-de-arroz-chino/paso-06.webp","image_alt":"Riz sauté au poulet et aux œufs: Faire sauter le riz par portions"},{"title":"Réunir les ingrédients","content":"Remettez poulet, œufs et légumes. Mélangez 1–2 minutes jusqu’à un ensemble fumant à 74 °C; ajoutez le vert de ciboule.","image_url":"/recetas/receta-de-arroz-chino/paso-07.webp","image_alt":"Riz sauté au poulet et aux œufs: Réunir les ingrédients"},{"title":"Servir immédiatement","content":"Servez dans 4 bols. Mettez rapidement les restes en récipients peu profonds et réfrigérez avant 2 heures; ne laissez pas le wok tiède à température ambiante.","image_url":"/recetas/receta-de-arroz-chino/paso-08.webp","image_alt":"Riz sauté au poulet et aux œufs: Servir immédiatement"}],"notes":"Refroidissez rapidement le riz sur une plaque peu profonde, puis réfrigérez et utilisez le lendemain. Ne laissez pas une grande casserole refroidir des heures. Goûtez avant de saler. Le riz fraîchement cuit humide colle davantage. Réchauffez à 74 °C sans cycles répétés de refroidissement et réchauffage.","nutrition":{"calories":467.0,"protein_g":27.4,"carbs_g":58.9,"fat_g":12.6,"saturated_fat_g":1.9,"fiber_g":3.4,"sugar_g":3.6,"sodium_mg":539.0,"serving_size":"1 des 4 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 4 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire."},"keywords":["riz sauté poulet œufs","riz chinois maison","riz au wok"],"image_url":"/recetas/receta-de-arroz-chino/portada.webp","gallery":[{"url":"/recetas/receta-de-arroz-chino/portada.webp","alt":"Riz sauté au poulet et aux œufs: plat terminé"}],"seo":{"title":"Riz sauté au poulet et aux œufs | Manual de Cocina","description":"Riz sauté au poulet et aux œufs, carotte, petits pois et ciboule. Travaillez en petites quantités au wok ou dans une grande poêle.","image_alt":"Riz sauté au poulet et aux œufs: plat terminé","image_variants":["/recetas/receta-de-arroz-chino/portada-1x1.webp","/recetas/receta-de-arroz-chino/portada-4x3.webp","/recetas/receta-de-arroz-chino/portada-16x9.webp"],"faq":[{"q":"Pourquoi du riz froid?","a":"Sa surface sèche facilite la séparation; il doit avoir été refroidi et conservé correctement."},{"q":"Peut-on omettre le poulet?","a":"Oui, procédez avec œufs et légumes; la nutrition change."},{"q":"Faut-il un wok?","a":"Une grande poêle suffit si les lots restent petits et peu humides."}]},"published":false,"editorial_status":"ready","content_html":"<p>Poulet, œufs, carotte, petits pois et ciboule accompagnent ce riz sauté. Cuisez par petites quantités pour éviter qu’il ne cuise dans sa vapeur.</p><p>Prévoyez 700 g de riz cuit refroidi correctement. Les 40 minutes excluent sa cuisson et son refroidissement préalables.</p>"},{"id":"930aef6c-3f1a-5bd8-99b4-c85bbf548d4c","recipe_group_id":"441e8e63-7479-44fa-b0b1-8100065043ff","slug":"riso-saltato-pollo-uova","public_path":"/it/riso-saltato-pollo-uova","source_url":null,"language":"it","title":"Riso saltato con pollo e uova","excerpt":"Riso saltato con pollo, uova, carote, piselli e cipollotto. Cuoci in piccole quantità nel wok o in padella larga per separare i chicchi.","summary":"Pollo, uova, carota, piselli e cipollotto arricchiscono questo riso saltato. Lavora in più turni per evitare di cuocerlo nel suo vapore.\n\nServono 700 g di riso già cotto e raffreddato correttamente. I 40 minuti escludono la precedente cottura e refrigerazione del riso.","category":"Secondi piatti","category_slug":"platos-principales","difficulty":"Media","course":"Piatto principale","cuisine":"Fusion","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"riso bianco cotto e refrigerato","amount":"700","unit":"g","group":"Saltato"},{"name":"petto di pollo senza pelle","amount":"300","unit":"g","group":"Saltato"},{"name":"uova medie","amount":"2","unit":"pezzi","group":"Saltato"},{"name":"carota","amount":"150","unit":"g","group":"Verdure"},{"name":"piselli surgelati","amount":"100","unit":"g","group":"Verdure"},{"name":"cipollotto","amount":"60","unit":"g","group":"Verdure"},{"name":"aglio","amount":"6","unit":"g","group":"Aromi"},{"name":"zenzero fresco","amount":"10","unit":"g","group":"Aromi"},{"name":"olio vegetale","amount":"30","unit":"g","group":"Saltato"},{"name":"salsa di soia","amount":"30","unit":"g","group":"Condimento"}],"steps":[{"title":"Separare i chicchi di riso","content":"Togli 700 g di riso dal frigorifero e separa i grumi con forchetta pulita. Deve essere stato raffreddato rapidamente e refrigerato, mai lasciato fuori tutta la notte.","image_url":"/recetas/receta-de-arroz-chino/paso-01.webp","image_alt":"Riso saltato con pollo e uova: Separare i chicchi di riso"},{"title":"Tagliare e organizzare","content":"Taglia 300 g di pollo a dadi da 1,5 cm e 150 g di carota a dadi da 5 mm. Trita 60 g di cipollotto, 6 g di aglio e 10 g di zenzero. Sbatti 2 uova; misura 100 g di piselli e 30 g di soia.","image_url":"/recetas/receta-de-arroz-chino/paso-02.webp","image_alt":"Riso saltato con pollo e uova: Tagliare e organizzare"},{"title":"Cuocere le uova","content":"Scalda 5 g di olio nel wok. Mescola le 2 uova per 1–2 minuti finché completamente cotte; trasferisci su piatto pulito.","image_url":"/recetas/receta-de-arroz-chino/paso-03.webp","image_alt":"Riso saltato con pollo e uova: Cuocere le uova"},{"title":"Cuocere il pollo","content":"Aggiungi 10 g di olio e salta il pollo circa 5–6 minuti fino a 74 °C al centro. Metti su altro piatto pulito; lava gli utensili del pollo crudo.","image_url":"/recetas/receta-de-arroz-chino/paso-04.webp","image_alt":"Riso saltato con pollo e uova: Cuocere il pollo"},{"title":"Saltare le verdure","content":"Scalda 5 g di olio e cuoci carota 3 minuti. Aggiungi piselli e parte bianca del cipollotto per 2 minuti; aglio e zenzero negli ultimi 30 secondi.","image_url":"/recetas/receta-de-arroz-chino/paso-05.webp","image_alt":"Riso saltato con pollo e uova: Saltare le verdure"},{"title":"Saltare il riso in più riprese","content":"Togli verdure e aggiungi gli ultimi 10 g di olio. Salta il riso in due turni da 2 minuti, stendendolo e mescolando. Riunisci e versa 30 g di soia sul bordo.","image_url":"/recetas/receta-de-arroz-chino/paso-06.webp","image_alt":"Riso saltato con pollo e uova: Saltare il riso in più riprese"},{"title":"Unire gli ingredienti","content":"Rimetti pollo, uova e verdure. Mescola 1–2 minuti finché fumante e a 74 °C; incorpora il verde del cipollotto.","image_url":"/recetas/receta-de-arroz-chino/paso-07.webp","image_alt":"Riso saltato con pollo e uova: Unire gli ingredienti"},{"title":"Servire subito","content":"Dividi in 4 ciotole. Metti subito gli avanzi in contenitori bassi e refrigera entro 2 ore; non lasciare il wok tiepido a temperatura ambiente.","image_url":"/recetas/receta-de-arroz-chino/paso-08.webp","image_alt":"Riso saltato con pollo e uova: Servire subito"}],"notes":"Raffredda il riso rapidamente su teglia bassa, refrigera subito e usa il giorno dopo. Non raffreddare una grande pentola per ore. Assaggia prima di salare: la soia contiene sale. Il riso fresco umido si ammassa. Riscalda gli avanzi a 74 °C ed evita cicli ripetuti di raffreddamento e riscaldamento.","nutrition":{"calories":467.0,"protein_g":27.4,"carbs_g":58.9,"fat_g":12.6,"saturated_fat_g":1.9,"fiber_g":3.4,"sugar_g":3.6,"sodium_mg":539.0,"serving_size":"1 delle 4 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 4 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario."},"keywords":["riso saltato pollo uova","riso cinese casalingo","riso al wok"],"image_url":"/recetas/receta-de-arroz-chino/portada.webp","gallery":[{"url":"/recetas/receta-de-arroz-chino/portada.webp","alt":"Riso saltato con pollo e uova: piatto pronto"}],"seo":{"title":"Riso saltato con pollo e uova | Manual de Cocina","description":"Riso saltato con pollo, uova, carote, piselli e cipollotto. Cuoci in piccole quantità nel wok o in padella larga per separare i chicchi.","image_alt":"Riso saltato con pollo e uova: piatto pronto","image_variants":["/recetas/receta-de-arroz-chino/portada-1x1.webp","/recetas/receta-de-arroz-chino/portada-4x3.webp","/recetas/receta-de-arroz-chino/portada-16x9.webp"],"faq":[{"q":"Perché riso freddo?","a":"La superficie asciutta separa meglio i chicchi. Deve essere raffreddato e refrigerato correttamente."},{"q":"Posso omettere il pollo?","a":"Sì, procedi con uova e verdure; cambia la nutrizione."},{"q":"È indispensabile il wok?","a":"Una padella larga va bene con piccole quantità e senza umidità eccessiva."}]},"published":false,"editorial_status":"ready","content_html":"<p>Pollo, uova, carota, piselli e cipollotto arricchiscono questo riso saltato. Lavora in più turni per evitare di cuocerlo nel suo vapore.</p><p>Servono 700 g di riso già cotto e raffreddato correttamente. I 40 minuti escludono la precedente cottura e refrigerazione del riso.</p>"},{"id":"e56c2f38-ba6e-5d49-907d-d39a69917d57","recipe_group_id":"441e8e63-7479-44fa-b0b1-8100065043ff","slug":"鶏肉と卵のチャーハン","public_path":"/ja/鶏肉と卵のチャーハン","source_url":null,"language":"ja","title":"鶏肉と卵のチャーハン","excerpt":"鶏肉と卵、にんじん、グリーンピースのチャーハン。広いフライパンか中華鍋で少量ずつ炒め、米をほぐします。","summary":"鶏胸肉、卵、にんじん、グリーンピース、青ねぎを使います。蒸れないよう大きな鍋で数回に分けて炒めます。\n\n安全に冷却した炊いた米700 gから作ります。40分には事前の炊飯・冷却時間は含みません。","category":"主菜","category_slug":"platos-principales","difficulty":"普通","course":"主菜","cuisine":"フュージョン料理","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"炊いて冷蔵した白米","amount":"700","unit":"g","group":"炒め物"},{"name":"皮なし鶏胸肉","amount":"300","unit":"g","group":"炒め物"},{"name":"中サイズの卵","amount":"2","unit":"個","group":"炒め物"},{"name":"にんじん","amount":"150","unit":"g","group":"野菜"},{"name":"冷凍グリーンピース","amount":"100","unit":"g","group":"野菜"},{"name":"青ねぎ","amount":"60","unit":"g","group":"野菜"},{"name":"にんにく","amount":"6","unit":"g","group":"香味"},{"name":"生しょうが","amount":"10","unit":"g","group":"香味"},{"name":"植物油","amount":"30","unit":"g","group":"炒め物"},{"name":"しょうゆ","amount":"30","unit":"g","group":"味付け"}],"steps":[{"title":"冷たいご飯をほぐす","content":"冷蔵庫から米700 gを出し、清潔なフォークでほぐします。素早く冷まして冷蔵した米を使い、一晩常温に置いた米は使いません。","image_url":"/recetas/receta-de-arroz-chino/paso-01.webp","image_alt":"鶏肉と卵のチャーハン: 冷たいご飯をほぐす"},{"title":"材料を切って準備する","content":"鶏肉300 gを1.5 cm角、にんじん150 gを5 mm角に切ります。ねぎ60 g、にんにく6 g、しょうが10 gを刻みます。卵2個を溶き、豆100 gとしょうゆ30 gを量ります。","image_url":"/recetas/receta-de-arroz-chino/paso-02.webp","image_alt":"鶏肉と卵のチャーハン: 材料を切って準備する"},{"title":"卵を加熱する","content":"油5 gを熱し、溶き卵2個を1–2分混ぜて完全に固まるまで炒め、清潔な皿へ取り出します。","image_url":"/recetas/receta-de-arroz-chino/paso-03.webp","image_alt":"鶏肉と卵のチャーハン: 卵を加熱する"},{"title":"鶏肉を加熱する","content":"油10 gで鶏肉を約5–6分炒め、中心74 °Cを確認して別の清潔な皿へ。生の肉に触れた器具を洗います。","image_url":"/recetas/receta-de-arroz-chino/paso-04.webp","image_alt":"鶏肉と卵のチャーハン: 鶏肉を加熱する"},{"title":"野菜を炒める","content":"油5 gでにんじんを3分炒め、豆とねぎの白い部分を加え2分。最後の30秒でにんにくとしょうがを加えます。","image_url":"/recetas/receta-de-arroz-chino/paso-05.webp","image_alt":"鶏肉と卵のチャーハン: 野菜を炒める"},{"title":"ご飯を分けて炒める","content":"野菜を取り出し、残りの油10 gを入れます。米を2回に分けて各2分、広げて混ぜながら炒めます。合わせて鍋肌からしょうゆ30 gを入れます。","image_url":"/recetas/receta-de-arroz-chino/paso-06.webp","image_alt":"鶏肉と卵のチャーハン: ご飯を分けて炒める"},{"title":"材料を合わせる","content":"鶏肉、卵、野菜を戻し1–2分混ぜ、全体が湯気を立て74 °Cになるまで加熱します。ねぎの青い部分を加えます。","image_url":"/recetas/receta-de-arroz-chino/paso-07.webp","image_alt":"鶏肉と卵のチャーハン: 材料を合わせる"},{"title":"すぐに盛り付ける","content":"4つの器へ分けます。残りはすぐ浅い容器へ入れ、2時間以内に冷蔵。ぬるい鍋を常温で放置しません。","image_url":"/recetas/receta-de-arroz-chino/paso-08.webp","image_alt":"鶏肉と卵のチャーハン: すぐに盛り付ける"}],"notes":"米は浅いトレーで素早く冷やしてすぐ冷蔵し、翌日に使います。大鍋を何時間も冷ます方法は避けます。しょうゆの塩分があるため味見してから塩を追加します。湿った炊きたて米は固まりやすくなります。残りは74 °Cまで再加熱し、冷却・加熱を何度も繰り返しません。","nutrition":{"calories":467.0,"protein_g":27.4,"carbs_g":58.9,"fat_g":12.6,"saturated_fat_g":1.9,"fiber_g":3.4,"sugar_g":3.6,"sodium_mg":539.0,"serving_size":"全4人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を4人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。"},"keywords":["鶏肉チャーハン","卵チャーハン","家庭の中華炒飯"],"image_url":"/recetas/receta-de-arroz-chino/portada.webp","gallery":[{"url":"/recetas/receta-de-arroz-chino/portada.webp","alt":"鶏肉と卵のチャーハン: 完成した料理"}],"seo":{"title":"鶏肉と卵のチャーハン | Manual de Cocina","description":"鶏肉と卵、にんじん、グリーンピースのチャーハン。広いフライパンか中華鍋で少量ずつ炒め、米をほぐします。","image_alt":"鶏肉と卵のチャーハン: 完成した料理","image_variants":["/recetas/receta-de-arroz-chino/portada-1x1.webp","/recetas/receta-de-arroz-chino/portada-4x3.webp","/recetas/receta-de-arroz-chino/portada-16x9.webp"],"faq":[{"q":"なぜ冷たい米を使いますか？","a":"表面が乾いてほぐれやすいためです。安全に冷却・冷蔵されている必要があります。"},{"q":"鶏肉を抜けますか？","a":"はい。卵と野菜の工程は同じですが栄養値が変わります。"},{"q":"中華鍋は必要ですか？","a":"広いフライパンでも、少量ずつ水分をためずに炒めれば作れます。"}]},"published":false,"editorial_status":"ready","content_html":"<p>鶏胸肉、卵、にんじん、グリーンピース、青ねぎを使います。蒸れないよう大きな鍋で数回に分けて炒めます。</p><p>安全に冷却した炊いた米700 gから作ります。40分には事前の炊飯・冷却時間は含みません。</p>"},{"id":"939a43a5-757a-5953-a2f9-ad687a1458e8","recipe_group_id":"441e8e63-7479-44fa-b0b1-8100065043ff","slug":"arroz-chines-com-frango-e-ovo","public_path":"/pt/arroz-chines-com-frango-e-ovo","source_url":null,"language":"pt","title":"Arroz chinês com frango e ovo","excerpt":"Arroz chinês com frango, ovo, cenoura, ervilha e cebolinha. Salteie em pequenas porções no wok ou frigideira larga para soltar os grãos.","summary":"Frango, ovo, cenoura, ervilha e cebolinha acompanham este arroz salteado. Trabalhe em pequenas porções para não cozinhar o arroz no próprio vapor.\n\nComece com 700 g de arroz cozido e resfriado com segurança. Os 40 minutos não incluem cozimento e refrigeração prévios do arroz.","category":"Pratos principais","category_slug":"platos-principales","difficulty":"Média","course":"Prato principal","cuisine":"Fusão","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"arroz branco cozido e refrigerado","amount":"700","unit":"g","group":"Salteado"},{"name":"peito de frango sem pele","amount":"300","unit":"g","group":"Salteado"},{"name":"ovos médios","amount":"2","unit":"unidades","group":"Salteado"},{"name":"cenoura","amount":"150","unit":"g","group":"Legumes"},{"name":"ervilhas congeladas","amount":"100","unit":"g","group":"Legumes"},{"name":"cebolinha","amount":"60","unit":"g","group":"Legumes"},{"name":"alho","amount":"6","unit":"g","group":"Aromáticos"},{"name":"gengibre fresco","amount":"10","unit":"g","group":"Aromáticos"},{"name":"óleo vegetal","amount":"30","unit":"g","group":"Salteado"},{"name":"molho de soja","amount":"30","unit":"g","group":"Tempero"}],"steps":[{"title":"Solte os grãos de arroz","content":"Tire 700 g de arroz da geladeira e solte os grumos com garfo limpo. Use arroz resfriado rapidamente e refrigerado; nunca arroz que passou a noite fora.","image_url":"/recetas/receta-de-arroz-chino/paso-01.webp","image_alt":"Arroz chinês com frango e ovo: Solte os grãos de arroz"},{"title":"Corte e organize","content":"Corte 300 g de frango em cubos de 1,5 cm e 150 g de cenoura em cubos de 5 mm. Pique 60 g de cebolinha, 6 g de alho e 10 g de gengibre. Bata 2 ovos; meça 100 g de ervilha e 30 g de soja.","image_url":"/recetas/receta-de-arroz-chino/paso-02.webp","image_alt":"Arroz chinês com frango e ovo: Corte e organize"},{"title":"Cozinhe os ovos","content":"Aqueça 5 g de óleo no wok. Mexa os 2 ovos por 1–2 minutos até firmarem completamente; retire a prato limpo.","image_url":"/recetas/receta-de-arroz-chino/paso-03.webp","image_alt":"Arroz chinês com frango e ovo: Cozinhe os ovos"},{"title":"Cozinhe o frango","content":"Junte 10 g de óleo e salteie frango cerca de 5–6 minutos até 74 °C no centro. Retire a outro prato limpo; lave utensílios do frango cru.","image_url":"/recetas/receta-de-arroz-chino/paso-04.webp","image_alt":"Arroz chinês com frango e ovo: Cozinhe o frango"},{"title":"Salteie os vegetais","content":"Aqueça 5 g de óleo e cozinhe cenoura 3 minutos. Junte ervilhas e parte branca da cebolinha por 2 minutos; alho e gengibre nos últimos 30 segundos.","image_url":"/recetas/receta-de-arroz-chino/paso-05.webp","image_alt":"Arroz chinês com frango e ovo: Salteie os vegetais"},{"title":"Frite o arroz em etapas","content":"Retire legumes e coloque os 10 g de óleo restantes. Salteie arroz em duas porções de 2 minutos, espalhando e mexendo. Reúna e despeje 30 g de soja pela borda.","image_url":"/recetas/receta-de-arroz-chino/paso-06.webp","image_alt":"Arroz chinês com frango e ovo: Frite o arroz em etapas"},{"title":"Junte os ingredientes","content":"Volte frango, ovo e legumes. Misture 1–2 minutos até fumegar e alcançar 74 °C. Junte a parte verde da cebolinha.","image_url":"/recetas/receta-de-arroz-chino/paso-07.webp","image_alt":"Arroz chinês com frango e ovo: Junte os ingredientes"},{"title":"Sirva imediatamente","content":"Divida em 4 tigelas. Passe sobras logo para recipientes rasos e refrigere antes de 2 horas; não deixe wok morno em temperatura ambiente.","image_url":"/recetas/receta-de-arroz-chino/paso-08.webp","image_alt":"Arroz chinês com frango e ovo: Sirva imediatamente"}],"notes":"Resfrie arroz rapidamente em bandeja rasa, refrigere logo e use no dia seguinte. Não deixe panela grande esfriando por horas. Prove antes de salgar devido ao molho de soja. Arroz recém-cozido úmido empelota. Reaqueça a 74 °C e evite ciclos repetidos de resfriar e aquecer.","nutrition":{"calories":467.0,"protein_g":27.4,"carbs_g":58.9,"fat_g":12.6,"saturated_fat_g":1.9,"fiber_g":3.4,"sugar_g":3.6,"sodium_mg":539.0,"serving_size":"1 de 4 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 4 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário."},"keywords":["arroz chinês frango ovo","arroz frito caseiro","arroz no wok"],"image_url":"/recetas/receta-de-arroz-chino/portada.webp","gallery":[{"url":"/recetas/receta-de-arroz-chino/portada.webp","alt":"Arroz chinês com frango e ovo: prato pronto"}],"seo":{"title":"Arroz chinês com frango e ovo | Manual de Cocina","description":"Arroz chinês com frango, ovo, cenoura, ervilha e cebolinha. Salteie em pequenas porções no wok ou frigideira larga para soltar os grãos.","image_alt":"Arroz chinês com frango e ovo: prato pronto","image_variants":["/recetas/receta-de-arroz-chino/portada-1x1.webp","/recetas/receta-de-arroz-chino/portada-4x3.webp","/recetas/receta-de-arroz-chino/portada-16x9.webp"],"faq":[{"q":"Por que usar arroz frio?","a":"A superfície seca separa melhor os grãos; precisa ter sido resfriado e refrigerado com segurança."},{"q":"Posso tirar o frango?","a":"Sim, siga ovo e legumes, mas a nutrição muda."},{"q":"Preciso de wok?","a":"Frigideira larga serve em pequenas porções e sem acumular umidade."}]},"published":false,"editorial_status":"ready","content_html":"<p>Frango, ovo, cenoura, ervilha e cebolinha acompanham este arroz salteado. Trabalhe em pequenas porções para não cozinhar o arroz no próprio vapor.</p><p>Comece com 700 g de arroz cozido e resfriado com segurança. Os 40 minutos não incluem cozimento e refrigeração prévios do arroz.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-de-arroz-chino') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

-- costillas-en-mole-rojo
do $pub$
declare
  g constant uuid := '2ede9cae-1481-427b-b13d-3f5fc9a4b261';
  es_id constant uuid := 'da4135aa-a4e9-47d2-aadd-9de4828d8d43';
  j constant jsonb := $j$[{"id":"da4135aa-a4e9-47d2-aadd-9de4828d8d43","recipe_group_id":"2ede9cae-1481-427b-b13d-3f5fc9a4b261","slug":"costillas-en-mole-rojo","public_path":"/costillas-en-mole-rojo","source_url":"https://manualdecocina.com/costillas-en-mole-rojo/","language":"es","title":"Costillas de cerdo en mole rojo casero","excerpt":"Costillas de cerdo en mole rojo casero con chile ancho, tomate, cacahuete y cacao. Cocción suave para obtener carne tierna y salsa espesa.","summary":"Un mole rojo casero simplificado con chile ancho, tomate, cacahuete y sésamo, terminado con chocolate negro. Se une a costillas cocidas lentamente hasta que la carne esté tierna.\n\nRinde 4 porciones sin arroz ni tortillas. Las costillas se pesan con hueso; para la nutrición se estima un 65 % de parte comestible. No se presenta como una fórmula regional única o tradicional.","category":"Platos principales","category_slug":"platos-principales","difficulty":"Media","course":"Plato principal","cuisine":"Mexicana","prep_time_minutes":35,"cook_time_minutes":105,"total_time_minutes":140,"servings":4,"ingredients":[{"name":"costillas de cerdo con hueso, cortadas","amount":"1000","unit":"g","group":"Carne"},{"name":"agua","amount":"1200","unit":"ml","group":"Cocción"},{"name":"sal","amount":"6","unit":"g","group":"Cocción"},{"name":"chiles anchos secos, sin tallo ni semillas","amount":"30","unit":"g","group":"Mole"},{"name":"tomate","amount":"300","unit":"g","group":"Mole"},{"name":"cebolla","amount":"150","unit":"g","group":"Mole"},{"name":"ajo","amount":"12","unit":"g","group":"Mole"},{"name":"cacahuetes tostados sin sal","amount":"30","unit":"g","group":"Mole"},{"name":"semillas de sésamo","amount":"20","unit":"g","group":"Mole"},{"name":"chocolate negro, 60–69 % cacao","amount":"25","unit":"g","group":"Mole"},{"name":"aceite vegetal","amount":"20","unit":"g","group":"Mole"},{"name":"canela molida","amount":"1","unit":"g","group":"Mole"},{"name":"clavo molido","amount":"0.2","unit":"g","group":"Mole"}],"steps":[{"title":"Prepara las costillas","content":"Pon 1 kg de costillas en una olla con 1,2 litros de agua y 6 g de sal. Lleva a un hervor suave y retira la espuma superficial con una cuchara. No laves la carne cruda.","image_url":"/recetas/costillas-en-mole-rojo/paso-01.webp","image_alt":"Costillas de cerdo en mole rojo casero: Prepara las costillas"},{"title":"Cuece hasta ablandar","content":"Tapa parcialmente y cocina a fuego bajo 75–90 minutos, hasta que la carne esté tierna. Añade agua caliente si se descubre demasiado. Reserva 500 ml del líquido y mantén las costillas calientes.","image_url":"/recetas/costillas-en-mole-rojo/paso-02.webp","image_alt":"Costillas de cerdo en mole rojo casero: Cuece hasta ablandar"},{"title":"Tuesta e hidrata los chiles","content":"Abre 30 g de chile ancho y elimina tallo y semillas. Tuesta en sartén seca unos 10 segundos por lado, sin ennegrecerlos. Cubre con agua caliente y deja hidratar 15 minutos; escurre y desecha esa agua.","image_url":"/recetas/costillas-en-mole-rojo/paso-03.webp","image_alt":"Costillas de cerdo en mole rojo casero: Tuesta e hidrata los chiles"},{"title":"Asa los vegetales","content":"Dora 300 g de tomate, 150 g de cebolla en gajos y 12 g de ajo en sartén seca, girándolos durante 10 minutos. Deben tener puntos tostados sin quedar carbonizados.","image_url":"/recetas/costillas-en-mole-rojo/paso-04.webp","image_alt":"Costillas de cerdo en mole rojo casero: Asa los vegetales"},{"title":"Tuesta y tritura el mole","content":"Tuesta 30 g de cacahuetes y 20 g de sésamo 1–2 minutos. Tritura con los chiles hidratados, vegetales asados, 1 g de canela, 0,2 g de clavo y 350 ml del líquido reservado hasta obtener una salsa lisa. Si el vaso no admite líquidos calientes, deja templar antes.","image_url":"/recetas/costillas-en-mole-rojo/paso-05.webp","image_alt":"Costillas de cerdo en mole rojo casero: Tuesta y tritura el mole"},{"title":"Cocina la salsa","content":"Calienta 20 g de aceite en una cazuela amplia. Añade el mole con cuidado de las salpicaduras y cocina 10 minutos a fuego bajo, removiendo el fondo. Incorpora hasta 150 ml más del líquido si queda demasiado espeso.","image_url":"/recetas/costillas-en-mole-rojo/paso-06.webp","image_alt":"Costillas de cerdo en mole rojo casero: Cocina la salsa"},{"title":"Añade chocolate y carne","content":"Disuelve 25 g de chocolate negro en el mole. Agrega las costillas cocidas y cocina 10 minutos a hervor suave para que se impregnen. La salsa debe cubrirlas sin formar un bloque; ajusta con agua caliente si hace falta.","image_url":"/recetas/costillas-en-mole-rojo/paso-07.webp","image_alt":"Costillas de cerdo en mole rojo casero: Añade chocolate y carne"},{"title":"Sirve en cuatro porciones","content":"Reparte las costillas y la salsa entre 4 platos. El arroz o las tortillas son opcionales y no están incluidos en ingredientes ni nutrición. Prueba la salsa antes de añadir sal adicional.","image_url":"/recetas/costillas-en-mole-rojo/paso-08.webp","image_alt":"Costillas de cerdo en mole rojo casero: Sirve en cuatro porciones"}],"notes":"Contiene cacahuete y sésamo. Para una persona con alergia, prepara una receta distinta que no use esos ingredientes ni utensilios contaminados. Conserva refrigerado hasta 3 días y recalienta hasta 74 °C. Puede congelarse hasta 2 meses. La proporción comestible de las costillas y la grasa descartada cambian mucho la estimación nutricional.","nutrition":{"calories":515.0,"protein_g":36.7,"carbs_g":17.5,"fat_g":33.6,"saturated_fat_g":6.6,"fiber_g":5.1,"sugar_g":6.3,"sodium_mg":695.0,"serving_size":"1 de 4 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 4 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma. La carne se aproxima con costilla de lomo SR Legacy: 650 g comestibles por 1 kg con hueso. Se cuenta toda la salsa; el rendimiento real puede variar. Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"costillas de cerdo con hueso, cortadas","edible_grams":650,"fdc_id":167895,"fdc_description":"Pork, fresh, loin, country-style ribs, separable lean and fat, raw","per_100g":{"fat_g":11.82,"carbs_g":0.0,"calories":189.0,"sugar_g":0.0,"protein_g":19.34,"fiber_g":0.0,"sodium_mg":63.0,"saturated_fat_g":2.37},"source_url":"https://fdc.nal.usda.gov/food-details/167895/nutrients"},{"ingredient":"sal","edible_grams":6,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0.0,"sodium_mg":38758.0,"saturated_fat_g":0.0,"protein_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"chiles anchos secos, sin tallo ni semillas","edible_grams":30,"fdc_id":169396,"fdc_description":"Peppers, ancho, dried","per_100g":{"sodium_mg":43.0,"calories":281.0,"carbs_g":51.42,"protein_g":11.86,"fiber_g":21.6,"saturated_fat_g":0.82,"fat_g":8.2},"source_url":"https://fdc.nal.usda.gov/food-details/169396/nutrients"},{"ingredient":"tomate","edible_grams":300,"fdc_id":170457,"fdc_description":"Tomatoes, red, ripe, raw, year round average","per_100g":{"sugar_g":2.63,"carbs_g":3.89,"calories":18.0,"saturated_fat_g":0.028,"fat_g":0.2,"fiber_g":1.2,"sodium_mg":5.0,"protein_g":0.88},"source_url":"https://fdc.nal.usda.gov/food-details/170457/nutrients"},{"ingredient":"cebolla","edible_grams":150,"fdc_id":170000,"fdc_description":"Onions, raw","per_100g":{"sugar_g":4.24,"fat_g":0.1,"carbs_g":9.34,"calories":40.0,"saturated_fat_g":0.042,"protein_g":1.1,"fiber_g":1.7,"sodium_mg":4.0},"source_url":"https://fdc.nal.usda.gov/food-details/170000/nutrients"},{"ingredient":"ajo","edible_grams":12,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.06,"calories":149.0,"sugar_g":1.0,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17.0,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"cacahuetes tostados sin sal","edible_grams":30,"fdc_id":173806,"fdc_description":"Peanuts, all types, dry-roasted, without salt","per_100g":{"fiber_g":8.4,"saturated_fat_g":7.723,"protein_g":24.35,"carbs_g":21.26,"calories":587.0,"sugar_g":4.9,"sodium_mg":6.0,"fat_g":49.66},"source_url":"https://fdc.nal.usda.gov/food-details/173806/nutrients"},{"ingredient":"semillas de sésamo","edible_grams":20,"fdc_id":170150,"fdc_description":"Seeds, sesame seeds, whole, dried","per_100g":{"sugar_g":0.3,"protein_g":17.73,"fiber_g":11.8,"sodium_mg":11.0,"saturated_fat_g":6.957,"fat_g":49.67,"carbs_g":23.45,"calories":573.0},"source_url":"https://fdc.nal.usda.gov/food-details/170150/nutrients"},{"ingredient":"chocolate negro, 60–69 % cacao","edible_grams":25,"fdc_id":170272,"fdc_description":"Chocolate, dark, 60-69% cacao solids","per_100g":{"fat_g":38.31,"carbs_g":52.42,"calories":579.0,"protein_g":6.12,"fiber_g":8.0,"sodium_mg":10.0,"saturated_fat_g":22.031,"sugar_g":36.71},"source_url":"https://fdc.nal.usda.gov/food-details/170272/nutrients"},{"ingredient":"aceite vegetal","edible_grams":20,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"fat_g":100.0,"saturated_fat_g":7.365,"protein_g":0.0,"carbs_g":0.0,"calories":884.0,"fiber_g":0.0,"sodium_mg":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"canela molida","edible_grams":1,"fdc_id":171320,"fdc_description":"Spices, cinnamon, ground","per_100g":{"sugar_g":2.17,"fiber_g":53.1,"protein_g":3.99,"sodium_mg":10.0,"saturated_fat_g":0.345,"fat_g":1.24,"carbs_g":80.59,"calories":247.0},"source_url":"https://fdc.nal.usda.gov/food-details/171320/nutrients"},{"ingredient":"clavo molido","edible_grams":0.2,"fdc_id":171321,"fdc_description":"Spices, cloves, ground","per_100g":{"sugar_g":2.38,"fat_g":13.0,"carbs_g":65.53,"calories":274.0,"fiber_g":33.9,"sodium_mg":277.0,"saturated_fat_g":3.952,"protein_g":5.97},"source_url":"https://fdc.nal.usda.gov/food-details/171321/nutrients"}]},"keywords":["costillas en mole rojo","mole rojo con chile ancho","costillas de cerdo guisadas"],"image_url":"/recetas/costillas-en-mole-rojo/portada.webp","gallery":[{"url":"/recetas/costillas-en-mole-rojo/portada.webp","alt":"Costillas de cerdo en mole rojo casero: plato terminado"}],"seo":{"title":"Costillas de cerdo en mole rojo casero | Manual de Cocina","description":"Costillas de cerdo en mole rojo casero con chile ancho, tomate, cacahuete y cacao. Cocción suave para obtener carne tierna y salsa espesa.","image_alt":"Costillas de cerdo en mole rojo casero: plato terminado","image_variants":["/recetas/costillas-en-mole-rojo/portada-1x1.webp","/recetas/costillas-en-mole-rojo/portada-4x3.webp","/recetas/costillas-en-mole-rojo/portada-16x9.webp"],"faq":[{"q":"¿Por qué amarga el mole?","a":"Los chiles, el sésamo o el ajo quemados pueden amargarlo. Tuesta brevemente y evita partes negras; el chocolate no corrige un quemado intenso."},{"q":"¿Puedo usar pasta de mole comercial?","a":"Sí, siguiendo su etiqueta, pero sería otra formulación y cambiarían cantidades, sal y nutrición."},{"q":"¿Se pueden preparar con anticipación?","a":"Sí. Refrigera rápidamente en recipientes bajos y recalienta hasta 74 °C, añadiendo agua si la salsa espesó."}]},"published":false,"editorial_status":"ready","content_html":"<p>Un mole rojo casero simplificado con chile ancho, tomate, cacahuete y sésamo, terminado con chocolate negro. Se une a costillas cocidas lentamente hasta que la carne esté tierna.</p><p>Rinde 4 porciones sin arroz ni tortillas. Las costillas se pesan con hueso; para la nutrición se estima un 65 % de parte comestible. No se presenta como una fórmula regional única o tradicional.</p>"},{"id":"61b6cb51-ba24-5c94-96d8-68a851085706","recipe_group_id":"2ede9cae-1481-427b-b13d-3f5fc9a4b261","slug":"schweinerippchen-in-rotem-mole","public_path":"/de/schweinerippchen-in-rotem-mole","source_url":null,"language":"de","title":"Schweinerippchen in roter Mole","excerpt":"Schweinerippchen in rotem Mole mit Ancho-Chili, Tomate, Erdnüssen, Sesam und dunkler Schokolade. Langsam garen und mit der Sauce verbinden.","summary":"Ein vereinfachter roter Mole mit Ancho-Chili, Tomate, Erdnuss, Sesam und dunkler Schokolade umhüllt weich gegarte Rippchen.\n\n4 Portionen ohne Reis oder Tortillas. Rippchen werden mit Knochen gewogen; 65 % essbarer Anteil werden geschätzt. Dies ist keine verbindliche regionale Traditionsformel.","category":"Hauptgerichte","category_slug":"platos-principales","difficulty":"Mittel","course":"Hauptgericht","cuisine":"Mexikanisch","prep_time_minutes":35,"cook_time_minutes":105,"total_time_minutes":140,"servings":4,"ingredients":[{"name":"Schweinerippchen mit Knochen, zerteilt","amount":"1000","unit":"g","group":"Fleisch"},{"name":"Wasser","amount":"1200","unit":"ml","group":"Garen"},{"name":"Salz","amount":"6","unit":"g","group":"Garen"},{"name":"getrocknete Ancho-Chilis ohne Stiel und Samen","amount":"30","unit":"g","group":"Mole"},{"name":"Tomate","amount":"300","unit":"g","group":"Mole"},{"name":"Zwiebel","amount":"150","unit":"g","group":"Mole"},{"name":"Knoblauch","amount":"12","unit":"g","group":"Mole"},{"name":"geröstete ungesalzene Erdnüsse","amount":"30","unit":"g","group":"Mole"},{"name":"Sesamsamen","amount":"20","unit":"g","group":"Mole"},{"name":"dunkle Schokolade, 60–69 % Kakao","amount":"25","unit":"g","group":"Mole"},{"name":"Pflanzenöl","amount":"20","unit":"g","group":"Mole"},{"name":"gemahlener Zimt","amount":"1","unit":"g","group":"Mole"},{"name":"gemahlene Nelken","amount":"0.2","unit":"g","group":"Mole"}],"steps":[{"title":"Rippchen vorbereiten","content":"1 kg Rippchen mit 1,2 Litern Wasser und 6 g Salz in einen Topf geben. Sanft aufkochen und Schaum abschöpfen. Rohes Fleisch nicht waschen.","image_url":"/recetas/costillas-en-mole-rojo/paso-01.webp","image_alt":"Schweinerippchen in roter Mole: Rippchen vorbereiten"},{"title":"Zart garen","content":"Teilweise abgedeckt bei kleiner Hitze 75–90 Minuten weich garen. Bei Bedarf heißes Wasser nachgießen. 500 ml Kochflüssigkeit zurückbehalten und Fleisch warm halten.","image_url":"/recetas/costillas-en-mole-rojo/paso-02.webp","image_alt":"Schweinerippchen in roter Mole: Zart garen"},{"title":"Chilis rösten und einweichen","content":"30 g Ancho-Chilis öffnen, Stiele und Samen entfernen. Trocken etwa 10 Sekunden je Seite rösten, ohne schwarze Stellen. Mit heißem Wasser bedeckt 15 Minuten einweichen, abgießen und dieses Wasser entsorgen.","image_url":"/recetas/costillas-en-mole-rojo/paso-03.webp","image_alt":"Schweinerippchen in roter Mole: Chilis rösten und einweichen"},{"title":"Gemüse rösten","content":"300 g Tomate, 150 g Zwiebelspalten und 12 g Knoblauch in trockener Pfanne 10 Minuten unter Wenden rösten, mit gebräunten, nicht verkohlten Stellen.","image_url":"/recetas/costillas-en-mole-rojo/paso-04.webp","image_alt":"Schweinerippchen in roter Mole: Gemüse rösten"},{"title":"Mole rösten und pürieren","content":"30 g Erdnüsse und 20 g Sesam 1–2 Minuten rösten. Mit Chilis, Röstgemüse, 1 g Zimt, 0,2 g Nelken und 350 ml Kochflüssigkeit glatt pürieren. Falls der Mixer keine heißen Flüssigkeiten verträgt, vorher abkühlen.","image_url":"/recetas/costillas-en-mole-rojo/paso-05.webp","image_alt":"Schweinerippchen in roter Mole: Mole rösten und pürieren"},{"title":"Sauce kochen","content":"20 g Öl im breiten Topf erhitzen. Mole vorsichtig zugeben und bei kleiner Hitze 10 Minuten unter Rühren garen. Bei zu dicker Sauce bis 150 ml weitere Kochflüssigkeit zugeben.","image_url":"/recetas/costillas-en-mole-rojo/paso-06.webp","image_alt":"Schweinerippchen in roter Mole: Sauce kochen"},{"title":"Schokolade und Fleisch hinzufügen","content":"25 g dunkle Schokolade in der Sauce auflösen. Rippchen zugeben und 10 Minuten sanft köcheln. Sauce soll sie umhüllen, nicht fest klumpen; gegebenenfalls heißes Wasser ergänzen.","image_url":"/recetas/costillas-en-mole-rojo/paso-07.webp","image_alt":"Schweinerippchen in roter Mole: Schokolade und Fleisch hinzufügen"},{"title":"In vier Portionen servieren","content":"Fleisch und Sauce auf 4 Teller verteilen. Reis oder Tortillas sind optional und nicht in Zutaten/Nährwerten enthalten. Vor zusätzlichem Salz probieren.","image_url":"/recetas/costillas-en-mole-rojo/paso-08.webp","image_alt":"Schweinerippchen in roter Mole: In vier Portionen servieren"}],"notes":"Enthält Erdnüsse und Sesam. Bei Allergie eine andere Rezeptur und unbelastete Geräte verwenden. Gekühlt bis 3 Tage, gefroren bis 2 Monate lagern; auf 74 °C erwärmen. Essbarer Anteil und entferntes Fett beeinflussen die Schätzung stark.","nutrition":{"calories":515.0,"protein_g":36.7,"carbs_g":17.5,"fat_g":33.6,"saturated_fat_g":6.6,"fiber_g":5.1,"sugar_g":6.3,"sodium_mg":695.0,"serving_size":"1 von 4 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 4 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers. Rippchen werden mit SR-Legacy-Schweinelendenrippen und 650 g essbarem Anteil je 1 kg mit Knochen angenähert. Die gesamte Sauce wird gezählt."},"keywords":["Rippchen roter Mole","Mole rojo Schweinefleisch","Ancho-Chili-Sauce"],"image_url":"/recetas/costillas-en-mole-rojo/portada.webp","gallery":[{"url":"/recetas/costillas-en-mole-rojo/portada.webp","alt":"Schweinerippchen in roter Mole: fertiges Gericht"}],"seo":{"title":"Schweinerippchen in roter Mole | Manual de Cocina","description":"Schweinerippchen in rotem Mole mit Ancho-Chili, Tomate, Erdnüssen, Sesam und dunkler Schokolade. Langsam garen und mit der Sauce verbinden.","image_alt":"Schweinerippchen in roter Mole: fertiges Gericht","image_variants":["/recetas/costillas-en-mole-rojo/portada-1x1.webp","/recetas/costillas-en-mole-rojo/portada-4x3.webp","/recetas/costillas-en-mole-rojo/portada-16x9.webp"],"faq":[{"q":"Warum schmeckt Mole bitter?","a":"Verbrannte Chilis, Sesam oder Knoblauch verursachen Bitterkeit; kurz rösten und schwarze Stellen vermeiden. Schokolade korrigiert stark Verbranntes nicht."},{"q":"Geht gekaufte Mole-Paste?","a":"Nach Packungsangaben, aber mit anderer Rezeptur, Salzmenge und Nährwerten."},{"q":"Kann ich vorab kochen?","a":"Ja, zügig in flachen Behältern kühlen und auf 74 °C erwärmen; eingedickte Sauce mit Wasser verdünnen."}]},"published":false,"editorial_status":"ready","content_html":"<p>Ein vereinfachter roter Mole mit Ancho-Chili, Tomate, Erdnuss, Sesam und dunkler Schokolade umhüllt weich gegarte Rippchen.</p><p>4 Portionen ohne Reis oder Tortillas. Rippchen werden mit Knochen gewogen; 65 % essbarer Anteil werden geschätzt. Dies ist keine verbindliche regionale Traditionsformel.</p>"},{"id":"53c78d6a-38ad-5621-b5dd-39ad300ac088","recipe_group_id":"2ede9cae-1481-427b-b13d-3f5fc9a4b261","slug":"pork-ribs-in-red-mole","public_path":"/en/pork-ribs-in-red-mole","source_url":null,"language":"en","title":"Pork ribs in homemade red mole","excerpt":"Pork ribs in red mole with ancho chillies, tomato, peanuts, sesame and dark chocolate. Slow-cook the ribs, then finish them in the sauce.","summary":"A simplified red mole with ancho chillies, tomato, peanuts, sesame and dark chocolate coats tender, slowly cooked ribs.\n\nMakes 4 servings without rice or tortillas. Ribs are weighed bone-in; nutrition assumes 65 % edible meat. This is not presented as a single traditional regional formula.","category":"Main dishes","category_slug":"platos-principales","difficulty":"Medium","course":"Main course","cuisine":"Mexican","prep_time_minutes":35,"cook_time_minutes":105,"total_time_minutes":140,"servings":4,"ingredients":[{"name":"bone-in pork ribs, cut into pieces","amount":"1000","unit":"g","group":"Meat"},{"name":"water","amount":"1200","unit":"ml","group":"Cooking"},{"name":"salt","amount":"6","unit":"g","group":"Cooking"},{"name":"dried ancho chillies, stems and seeds removed","amount":"30","unit":"g","group":"Mole"},{"name":"tomato","amount":"300","unit":"g","group":"Mole"},{"name":"onion","amount":"150","unit":"g","group":"Mole"},{"name":"garlic","amount":"12","unit":"g","group":"Mole"},{"name":"roasted unsalted peanuts","amount":"30","unit":"g","group":"Mole"},{"name":"sesame seeds","amount":"20","unit":"g","group":"Mole"},{"name":"dark chocolate, 60–69 % cocoa","amount":"25","unit":"g","group":"Mole"},{"name":"vegetable oil","amount":"20","unit":"g","group":"Mole"},{"name":"ground cinnamon","amount":"1","unit":"g","group":"Mole"},{"name":"ground cloves","amount":"0.2","unit":"g","group":"Mole"}],"steps":[{"title":"Prepare the ribs","content":"Put 1 kg ribs in a pot with 1.2 litres water and 6 g salt. Bring to a gentle simmer and skim surface foam. Do not wash raw meat.","image_url":"/recetas/costillas-en-mole-rojo/paso-01.webp","image_alt":"Pork ribs in homemade red mole: Prepare the ribs"},{"title":"Simmer until tender","content":"Partly cover and cook over low heat 75–90 minutes until tender. Top up with hot water if too exposed. Reserve 500 ml cooking liquid and keep ribs hot.","image_url":"/recetas/costillas-en-mole-rojo/paso-02.webp","image_alt":"Pork ribs in homemade red mole: Simmer until tender"},{"title":"Toast and soak the chillies","content":"Open 30 g ancho chillies and remove stems and seeds. Toast in a dry pan about 10 seconds each side without blackening. Cover with hot water for 15 minutes, then drain and discard soaking water.","image_url":"/recetas/costillas-en-mole-rojo/paso-03.webp","image_alt":"Pork ribs in homemade red mole: Toast and soak the chillies"},{"title":"Roast the vegetables","content":"Dry-roast 300 g tomato, 150 g onion wedges and 12 g garlic for 10 minutes, turning. Aim for toasted spots without charring.","image_url":"/recetas/costillas-en-mole-rojo/paso-04.webp","image_alt":"Pork ribs in homemade red mole: Roast the vegetables"},{"title":"Toast and blend the mole","content":"Toast 30 g peanuts and 20 g sesame for 1–2 minutes. Blend with chillies, roasted vegetables, 1 g cinnamon, 0.2 g cloves and 350 ml reserved liquid until smooth. Cool first if the blender cannot handle hot liquids.","image_url":"/recetas/costillas-en-mole-rojo/paso-05.webp","image_alt":"Pork ribs in homemade red mole: Toast and blend the mole"},{"title":"Cook the sauce","content":"Heat 20 g oil in a wide saucepan. Carefully add mole and cook over low heat 10 minutes, stirring the bottom. Add up to 150 ml more reserved liquid if too thick.","image_url":"/recetas/costillas-en-mole-rojo/paso-06.webp","image_alt":"Pork ribs in homemade red mole: Cook the sauce"},{"title":"Add chocolate and meat","content":"Dissolve 25 g dark chocolate in the mole. Add cooked ribs and simmer gently 10 minutes. Sauce should coat without becoming a solid mass; loosen with hot water if needed.","image_url":"/recetas/costillas-en-mole-rojo/paso-07.webp","image_alt":"Pork ribs in homemade red mole: Add chocolate and meat"},{"title":"Serve in four portions","content":"Divide ribs and sauce among 4 plates. Optional rice or tortillas are excluded from ingredients and nutrition. Taste before adding extra salt.","image_url":"/recetas/costillas-en-mole-rojo/paso-08.webp","image_alt":"Pork ribs in homemade red mole: Serve in four portions"}],"notes":"Contains peanuts and sesame. For an allergic person, use a different recipe and uncontaminated utensils. Refrigerate up to 3 days or freeze up to 2 months; reheat to 74 °C. Edible rib yield and discarded fat strongly affect nutrition.","nutrition":{"calories":515.0,"protein_g":36.7,"carbs_g":17.5,"fat_g":33.6,"saturated_fat_g":6.6,"fiber_g":5.1,"sugar_g":6.3,"sodium_mg":695.0,"serving_size":"1 of 4 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 4 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation. Meat is approximated using SR Legacy loin ribs: 650 g edible meat per 1 kg bone-in. All sauce is counted."},"keywords":["pork ribs red mole","mole rojo ribs","ancho mole sauce"],"image_url":"/recetas/costillas-en-mole-rojo/portada.webp","gallery":[{"url":"/recetas/costillas-en-mole-rojo/portada.webp","alt":"Pork ribs in homemade red mole: finished dish"}],"seo":{"title":"Pork ribs in homemade red mole | Manual de Cocina","description":"Pork ribs in red mole with ancho chillies, tomato, peanuts, sesame and dark chocolate. Slow-cook the ribs, then finish them in the sauce.","image_alt":"Pork ribs in homemade red mole: finished dish","image_variants":["/recetas/costillas-en-mole-rojo/portada-1x1.webp","/recetas/costillas-en-mole-rojo/portada-4x3.webp","/recetas/costillas-en-mole-rojo/portada-16x9.webp"],"faq":[{"q":"Why is the mole bitter?","a":"Burnt chillies, sesame or garlic can cause bitterness. Toast briefly; chocolate cannot fix badly burnt ingredients."},{"q":"Can I use commercial mole paste?","a":"Follow its label, but quantities, salt and nutrition will differ from this formulation."},{"q":"Can I make it ahead?","a":"Cool promptly in shallow containers and reheat to 74 °C, adding water if the sauce thickens."}]},"published":false,"editorial_status":"ready","content_html":"<p>A simplified red mole with ancho chillies, tomato, peanuts, sesame and dark chocolate coats tender, slowly cooked ribs.</p><p>Makes 4 servings without rice or tortillas. Ribs are weighed bone-in; nutrition assumes 65 % edible meat. This is not presented as a single traditional regional formula.</p>"},{"id":"f1a6195c-ff41-50ef-8821-cd3e2b9aa1bb","recipe_group_id":"2ede9cae-1481-427b-b13d-3f5fc9a4b261","slug":"travers-de-porc-mole-rouge","public_path":"/fr/travers-de-porc-mole-rouge","source_url":null,"language":"fr","title":"Travers de porc au mole rouge maison","excerpt":"Travers de porc au mole rouge: piment ancho, tomate, cacahuète, sésame et chocolat noir. Cuisez lentement la viande puis finissez dans la sauce.","summary":"Un mole rouge simplifié aux piments ancho, tomate, cacahuètes, sésame et chocolat noir accompagne des travers tendres.\n\n4 portions sans riz ni tortillas. Poids de viande avec os; part comestible estimée à 65 %. Il ne s’agit pas d’une formule régionale traditionnelle unique.","category":"Plats principaux","category_slug":"platos-principales","difficulty":"Moyenne","course":"Plat principal","cuisine":"Mexicaine","prep_time_minutes":35,"cook_time_minutes":105,"total_time_minutes":140,"servings":4,"ingredients":[{"name":"travers de porc avec os, coupés","amount":"1000","unit":"g","group":"Viande"},{"name":"eau","amount":"1200","unit":"ml","group":"Cuisson"},{"name":"sel","amount":"6","unit":"g","group":"Cuisson"},{"name":"piments ancho secs sans tiges ni graines","amount":"30","unit":"g","group":"Mole"},{"name":"tomate","amount":"300","unit":"g","group":"Mole"},{"name":"oignon","amount":"150","unit":"g","group":"Mole"},{"name":"ail","amount":"12","unit":"g","group":"Mole"},{"name":"cacahuètes grillées non salées","amount":"30","unit":"g","group":"Mole"},{"name":"graines de sésame","amount":"20","unit":"g","group":"Mole"},{"name":"chocolat noir, 60–69 % cacao","amount":"25","unit":"g","group":"Mole"},{"name":"huile végétale","amount":"20","unit":"g","group":"Mole"},{"name":"cannelle moulue","amount":"1","unit":"g","group":"Mole"},{"name":"clou de girofle moulu","amount":"0.2","unit":"g","group":"Mole"}],"steps":[{"title":"Préparer les travers","content":"Mettez 1 kg de travers avec 1,2 litre d’eau et 6 g de sel. Portez à frémissement et écumez. Ne lavez pas la viande crue.","image_url":"/recetas/costillas-en-mole-rojo/paso-01.webp","image_alt":"Travers de porc au mole rouge maison: Préparer les travers"},{"title":"Cuire jusqu’à tendreté","content":"Couvrez partiellement et cuisez à feu doux 75–90 minutes jusqu’à tendreté. Complétez d’eau chaude si nécessaire. Réservez 500 ml de liquide et gardez la viande chaude.","image_url":"/recetas/costillas-en-mole-rojo/paso-02.webp","image_alt":"Travers de porc au mole rouge maison: Cuire jusqu’à tendreté"},{"title":"Torréfier et réhydrater les piments","content":"Ouvrez 30 g de piments, ôtez tiges et graines. Toastez à sec environ 10 secondes par face sans noircir. Trempez dans l’eau chaude 15 minutes, égouttez et jetez cette eau.","image_url":"/recetas/costillas-en-mole-rojo/paso-03.webp","image_alt":"Travers de porc au mole rouge maison: Torréfier et réhydrater les piments"},{"title":"Griller les légumes","content":"Rôtissez à sec 300 g de tomate, 150 g d’oignon en quartiers et 12 g d’ail 10 minutes en tournant, sans carboniser.","image_url":"/recetas/costillas-en-mole-rojo/paso-04.webp","image_alt":"Travers de porc au mole rouge maison: Griller les légumes"},{"title":"Torréfier et mixer le mole","content":"Toastez 30 g de cacahuètes et 20 g de sésame 1–2 minutes. Mixez avec piments, légumes, 1 g de cannelle, 0,2 g de girofle et 350 ml de liquide réservé. Faites tiédir si le mixeur n’accepte pas le chaud.","image_url":"/recetas/costillas-en-mole-rojo/paso-05.webp","image_alt":"Travers de porc au mole rouge maison: Torréfier et mixer le mole"},{"title":"Cuire la sauce","content":"Chauffez 20 g d’huile, versez prudemment le mole et cuisez 10 minutes à feu doux en remuant le fond. Ajoutez jusqu’à 150 ml de liquide si nécessaire.","image_url":"/recetas/costillas-en-mole-rojo/paso-06.webp","image_alt":"Travers de porc au mole rouge maison: Cuire la sauce"},{"title":"Ajouter chocolat et viande","content":"Faites fondre 25 g de chocolat dans la sauce. Ajoutez la viande et laissez frémir 10 minutes. Elle doit être nappée, sans sauce compacte; ajustez avec de l’eau chaude.","image_url":"/recetas/costillas-en-mole-rojo/paso-07.webp","image_alt":"Travers de porc au mole rouge maison: Ajouter chocolat et viande"},{"title":"Servir en quatre portions","content":"Répartissez sur 4 assiettes. Riz et tortillas facultatifs ne sont pas inclus dans ingrédients et nutrition. Goûtez avant de saler davantage.","image_url":"/recetas/costillas-en-mole-rojo/paso-08.webp","image_alt":"Travers de porc au mole rouge maison: Servir en quatre portions"}],"notes":"Contient cacahuète et sésame. En cas d’allergie, choisissez une autre recette et des ustensiles non contaminés. Réfrigérez jusqu’à 3 jours ou congelez 2 mois; réchauffez à 74 °C. Rendement comestible et gras jeté font varier l’estimation.","nutrition":{"calories":515.0,"protein_g":36.7,"carbs_g":17.5,"fat_g":33.6,"saturated_fat_g":6.6,"fiber_g":5.1,"sugar_g":6.3,"sodium_mg":695.0,"serving_size":"1 des 4 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 4 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire. Viande approximée par des côtes de longe SR Legacy: 650 g comestibles pour 1 kg avec os. Toute la sauce est comptée."},"keywords":["travers porc mole rouge","mole rojo","sauce piment ancho"],"image_url":"/recetas/costillas-en-mole-rojo/portada.webp","gallery":[{"url":"/recetas/costillas-en-mole-rojo/portada.webp","alt":"Travers de porc au mole rouge maison: plat terminé"}],"seo":{"title":"Travers de porc au mole rouge maison | Manual de Cocina","description":"Travers de porc au mole rouge: piment ancho, tomate, cacahuète, sésame et chocolat noir. Cuisez lentement la viande puis finissez dans la sauce.","image_alt":"Travers de porc au mole rouge maison: plat terminé","image_variants":["/recetas/costillas-en-mole-rojo/portada-1x1.webp","/recetas/costillas-en-mole-rojo/portada-4x3.webp","/recetas/costillas-en-mole-rojo/portada-16x9.webp"],"faq":[{"q":"Pourquoi le mole est-il amer?","a":"Des piments, sésame ou ail brûlés l’expliquent. Toastez brièvement; le chocolat ne corrige pas un fort brûlé."},{"q":"Peut-on utiliser une pâte du commerce?","a":"Suivez son étiquette, mais formulation, sel et nutrition diffèrent."},{"q":"Peut-on préparer à l’avance?","a":"Refroidissez rapidement en récipients bas puis réchauffez à 74 °C, avec de l’eau si nécessaire."}]},"published":false,"editorial_status":"ready","content_html":"<p>Un mole rouge simplifié aux piments ancho, tomate, cacahuètes, sésame et chocolat noir accompagne des travers tendres.</p><p>4 portions sans riz ni tortillas. Poids de viande avec os; part comestible estimée à 65 %. Il ne s’agit pas d’une formule régionale traditionnelle unique.</p>"},{"id":"47b12b3c-2594-59de-b984-1f40c58f11a1","recipe_group_id":"2ede9cae-1481-427b-b13d-3f5fc9a4b261","slug":"costine-di-maiale-mole-rosso","public_path":"/it/costine-di-maiale-mole-rosso","source_url":null,"language":"it","title":"Costine di maiale al mole rosso","excerpt":"Costine in mole rosso con peperoncino ancho, pomodoro, arachidi, sesamo e cioccolato fondente. Carne cotta lentamente e finita nella salsa.","summary":"Mole rosso semplificato con ancho, pomodoro, arachidi, sesamo e fondente, unito a costine tenere.\n\n4 porzioni senza riso né tortillas. Carne pesata con osso; parte commestibile stimata al 65 %. Non è proposta come unica formula tradizionale regionale.","category":"Secondi piatti","category_slug":"platos-principales","difficulty":"Media","course":"Piatto principale","cuisine":"Messicana","prep_time_minutes":35,"cook_time_minutes":105,"total_time_minutes":140,"servings":4,"ingredients":[{"name":"costine di maiale con osso, tagliate","amount":"1000","unit":"g","group":"Carne"},{"name":"acqua","amount":"1200","unit":"ml","group":"Cottura"},{"name":"sale","amount":"6","unit":"g","group":"Cottura"},{"name":"peperoncini ancho secchi senza picciolo né semi","amount":"30","unit":"g","group":"Mole"},{"name":"pomodoro","amount":"300","unit":"g","group":"Mole"},{"name":"cipolla","amount":"150","unit":"g","group":"Mole"},{"name":"aglio","amount":"12","unit":"g","group":"Mole"},{"name":"arachidi tostate non salate","amount":"30","unit":"g","group":"Mole"},{"name":"semi di sesamo","amount":"20","unit":"g","group":"Mole"},{"name":"cioccolato fondente, 60–69 % cacao","amount":"25","unit":"g","group":"Mole"},{"name":"olio vegetale","amount":"20","unit":"g","group":"Mole"},{"name":"cannella macinata","amount":"1","unit":"g","group":"Mole"},{"name":"chiodi di garofano macinati","amount":"0.2","unit":"g","group":"Mole"}],"steps":[{"title":"Preparare le costine","content":"Metti 1 kg di costine con 1,2 litri d’acqua e 6 g di sale. Porta a lieve bollore e schiuma. Non lavare carne cruda.","image_url":"/recetas/costillas-en-mole-rojo/paso-01.webp","image_alt":"Costine di maiale al mole rosso: Preparare le costine"},{"title":"Cuocere finché tenere","content":"Copri parzialmente e cuoci a fuoco basso 75–90 minuti finché tenera; aggiungi acqua calda se necessario. Riserva 500 ml di liquido e mantieni la carne calda.","image_url":"/recetas/costillas-en-mole-rojo/paso-02.webp","image_alt":"Costine di maiale al mole rosso: Cuocere finché tenere"},{"title":"Tostare e ammollare i peperoncini","content":"Apri 30 g di ancho ed elimina piccioli e semi. Tosta a secco circa 10 secondi per lato senza annerire; ammolla in acqua calda 15 minuti, scola e scarta l’acqua.","image_url":"/recetas/costillas-en-mole-rojo/paso-03.webp","image_alt":"Costine di maiale al mole rosso: Tostare e ammollare i peperoncini"},{"title":"Arrostire le verdure","content":"Arrostisci a secco 300 g di pomodoro, 150 g di cipolla a spicchi e 12 g di aglio per 10 minuti girando, senza carbonizzare.","image_url":"/recetas/costillas-en-mole-rojo/paso-04.webp","image_alt":"Costine di maiale al mole rosso: Arrostire le verdure"},{"title":"Tostare e frullare il mole","content":"Tosta 30 g di arachidi e 20 g di sesamo 1–2 minuti. Frulla con peperoncini, verdure, 1 g di cannella, 0,2 g di garofano e 350 ml di liquido. Fai intiepidire se il frullatore non accetta liquidi caldi.","image_url":"/recetas/costillas-en-mole-rojo/paso-05.webp","image_alt":"Costine di maiale al mole rosso: Tostare e frullare il mole"},{"title":"Cuocere la salsa","content":"Scalda 20 g di olio, aggiungi il mole con cautela e cuoci 10 minuti a fuoco basso mescolando il fondo. Diluisci con fino a 150 ml di liquido se necessario.","image_url":"/recetas/costillas-en-mole-rojo/paso-06.webp","image_alt":"Costine di maiale al mole rosso: Cuocere la salsa"},{"title":"Aggiungere cioccolato e carne","content":"Sciogli 25 g di fondente nel mole. Aggiungi costine e cuoci a lieve bollore 10 minuti. La salsa deve avvolgere senza diventare un blocco; diluisci con acqua calda.","image_url":"/recetas/costillas-en-mole-rojo/paso-07.webp","image_alt":"Costine di maiale al mole rosso: Aggiungere cioccolato e carne"},{"title":"Servire in quattro porzioni","content":"Dividi in 4 piatti. Riso e tortillas sono facoltativi ed esclusi da ingredienti e nutrizione. Assaggia prima di aggiungere sale.","image_url":"/recetas/costillas-en-mole-rojo/paso-08.webp","image_alt":"Costine di maiale al mole rosso: Servire in quattro porzioni"}],"notes":"Contiene arachidi e sesamo. In caso di allergia scegli altra ricetta e utensili non contaminati. Refrigerato fino a 3 giorni o congelato 2 mesi; riscalda a 74 °C. Parte commestibile e grasso scartato modificano molto la stima.","nutrition":{"calories":515.0,"protein_g":36.7,"carbs_g":17.5,"fat_g":33.6,"saturated_fat_g":6.6,"fiber_g":5.1,"sugar_g":6.3,"sodium_mg":695.0,"serving_size":"1 delle 4 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 4 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario. Carne approssimata con costine di lombo SR Legacy: 650 g commestibili per 1 kg con osso. Tutta la salsa è conteggiata."},"keywords":["costine mole rosso","mole rojo maiale","salsa ancho"],"image_url":"/recetas/costillas-en-mole-rojo/portada.webp","gallery":[{"url":"/recetas/costillas-en-mole-rojo/portada.webp","alt":"Costine di maiale al mole rosso: piatto pronto"}],"seo":{"title":"Costine di maiale al mole rosso | Manual de Cocina","description":"Costine in mole rosso con peperoncino ancho, pomodoro, arachidi, sesamo e cioccolato fondente. Carne cotta lentamente e finita nella salsa.","image_alt":"Costine di maiale al mole rosso: piatto pronto","image_variants":["/recetas/costillas-en-mole-rojo/portada-1x1.webp","/recetas/costillas-en-mole-rojo/portada-4x3.webp","/recetas/costillas-en-mole-rojo/portada-16x9.webp"],"faq":[{"q":"Perché il mole è amaro?","a":"Ancho, sesamo o aglio bruciati possono causarlo. Tosta brevemente; il cioccolato non corregge bruciature forti."},{"q":"Posso usare pasta di mole pronta?","a":"Segui l’etichetta; formulazione, sale e nutrizione saranno diversi."},{"q":"Si può preparare in anticipo?","a":"Raffredda rapidamente in recipienti bassi e riscalda a 74 °C, diluendo se necessario."}]},"published":false,"editorial_status":"ready","content_html":"<p>Mole rosso semplificato con ancho, pomodoro, arachidi, sesamo e fondente, unito a costine tenere.</p><p>4 porzioni senza riso né tortillas. Carne pesata con osso; parte commestibile stimata al 65 %. Non è proposta come unica formula tradizionale regionale.</p>"},{"id":"6c41e18e-9e15-5c93-a2fa-f974d100d477","recipe_group_id":"2ede9cae-1481-427b-b13d-3f5fc9a4b261","slug":"豚スペアリブの赤いモーレ","public_path":"/ja/豚スペアリブの赤いモーレ","source_url":null,"language":"ja","title":"豚スペアリブの赤いモーレ煮","excerpt":"アンチョ、トマト、ピーナッツ、ごま、ダークチョコの赤いモーレ。豚スペアリブを柔らかく煮てソースに合わせます。","summary":"アンチョ、トマト、ピーナッツ、ごまとチョコの簡略版赤いモーレを、ゆっくり煮た豚肉に絡めます。\n\n米やトルティーヤなしで4人分。骨付き重量を使い、可食部65 %で栄養を推定します。特定地域の唯一の伝統配合とはしていません。","category":"主菜","category_slug":"platos-principales","difficulty":"普通","course":"主菜","cuisine":"メキシコ料理","prep_time_minutes":35,"cook_time_minutes":105,"total_time_minutes":140,"servings":4,"ingredients":[{"name":"骨付き豚スペアリブ、切り分け","amount":"1000","unit":"g","group":"肉"},{"name":"水","amount":"1200","unit":"ml","group":"煮込み"},{"name":"塩","amount":"6","unit":"g","group":"煮込み"},{"name":"乾燥アンチョ、軸と種なし","amount":"30","unit":"g","group":"モーレ"},{"name":"トマト","amount":"300","unit":"g","group":"モーレ"},{"name":"玉ねぎ","amount":"150","unit":"g","group":"モーレ"},{"name":"にんにく","amount":"12","unit":"g","group":"モーレ"},{"name":"無塩ローストピーナッツ","amount":"30","unit":"g","group":"モーレ"},{"name":"ごま","amount":"20","unit":"g","group":"モーレ"},{"name":"ダークチョコレート、カカオ60–69 %","amount":"25","unit":"g","group":"モーレ"},{"name":"植物油","amount":"20","unit":"g","group":"モーレ"},{"name":"シナモン粉","amount":"1","unit":"g","group":"モーレ"},{"name":"クローブ粉","amount":"0.2","unit":"g","group":"モーレ"}],"steps":[{"title":"スペアリブを用意する","content":"骨付き肉1 kgを水1.2リットルと塩6 gで穏やかに沸かし、アクを取ります。生肉は洗いません。","image_url":"/recetas/costillas-en-mole-rojo/paso-01.webp","image_alt":"豚スペアリブの赤いモーレ煮: スペアリブを用意する"},{"title":"柔らかく煮る","content":"少しふたを開け弱火で75–90分、柔らかくなるまで煮ます。必要なら湯を足し、煮汁500 mlを取り分け、肉を温かく保ちます。","image_url":"/recetas/costillas-en-mole-rojo/paso-02.webp","image_alt":"豚スペアリブの赤いモーレ煮: 柔らかく煮る"},{"title":"唐辛子を焼いて戻す","content":"アンチョ30 gの軸と種を除き、乾いた鍋で片面約10秒ずつ焦がさず焼きます。熱湯で15分戻し、水を切って戻し汁は捨てます。","image_url":"/recetas/costillas-en-mole-rojo/paso-03.webp","image_alt":"豚スペアリブの赤いモーレ煮: 唐辛子を焼いて戻す"},{"title":"野菜を焼く","content":"トマト300 g、くし形玉ねぎ150 g、にんにく12 gを乾いた鍋で10分、返しながら焼きます。焼き色を付け、炭化させません。","image_url":"/recetas/costillas-en-mole-rojo/paso-04.webp","image_alt":"豚スペアリブの赤いモーレ煮: 野菜を焼く"},{"title":"モーレの材料を炒って撹拌する","content":"ピーナッツ30 gとごま20 gを1–2分炒ります。チリ、野菜、シナモン1 g、クローブ0.2 g、煮汁350 mlと滑らかに攪拌。ミキサーが熱液不可なら冷ましてから行います。","image_url":"/recetas/costillas-en-mole-rojo/paso-05.webp","image_alt":"豚スペアリブの赤いモーレ煮: モーレの材料を炒って撹拌する"},{"title":"ソースを煮る","content":"油20 gを熱し、跳ねに注意してモーレを加え、弱火で10分、底を混ぜます。濃すぎれば残りの煮汁を最大150 ml加えます。","image_url":"/recetas/costillas-en-mole-rojo/paso-06.webp","image_alt":"豚スペアリブの赤いモーレ煮: ソースを煮る"},{"title":"チョコレートと肉を加える","content":"チョコ25 gを溶かし、煮た肉を加えて穏やかに10分煮ます。固い塊にならず肉に絡む濃度へ、必要なら湯で調整します。","image_url":"/recetas/costillas-en-mole-rojo/paso-07.webp","image_alt":"豚スペアリブの赤いモーレ煮: チョコレートと肉を加える"},{"title":"4人分に分ける","content":"肉とソースを4皿へ分けます。米やトルティーヤは任意で材料・栄養に含みません。塩の追加は味見して判断します。","image_url":"/recetas/costillas-en-mole-rojo/paso-08.webp","image_alt":"豚スペアリブの赤いモーレ煮: 4人分に分ける"}],"notes":"ピーナッツとごまを含みます。アレルギーの場合は別のレシピと汚染のない器具を選びます。冷蔵最長3日、冷凍最長2か月。再加熱は74 °Cまで。骨や捨てる脂の量で推定値が大きく変わります。","nutrition":{"calories":515.0,"protein_g":36.7,"carbs_g":17.5,"fat_g":33.6,"saturated_fat_g":6.6,"fiber_g":5.1,"sugar_g":6.3,"sodium_mg":695.0,"serving_size":"全4人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を4人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。 肉はSR Legacyのロインリブで近似し、骨付き1 kg当たり可食650 gとします。ソース全量を計算します。"},"keywords":["赤いモーレ","豚スペアリブモーレ","アンチョソース"],"image_url":"/recetas/costillas-en-mole-rojo/portada.webp","gallery":[{"url":"/recetas/costillas-en-mole-rojo/portada.webp","alt":"豚スペアリブの赤いモーレ煮: 完成した料理"}],"seo":{"title":"豚スペアリブの赤いモーレ煮 | Manual de Cocina","description":"アンチョ、トマト、ピーナッツ、ごま、ダークチョコの赤いモーレ。豚スペアリブを柔らかく煮てソースに合わせます。","image_alt":"豚スペアリブの赤いモーレ煮: 完成した料理","image_variants":["/recetas/costillas-en-mole-rojo/portada-1x1.webp","/recetas/costillas-en-mole-rojo/portada-4x3.webp","/recetas/costillas-en-mole-rojo/portada-16x9.webp"],"faq":[{"q":"モーレが苦いのはなぜ？","a":"チリ、ごま、にんにくの焦げが原因になり得ます。短く炒り、強い焦げをチョコで補正しようとしません。"},{"q":"市販のモーレペーストを使えますか？","a":"表示に従って使えますが、配合、塩分、栄養が異なります。"},{"q":"作り置きできますか？","a":"浅い容器で素早く冷蔵し、74 °Cまで再加熱します。固まったソースは水で調整します。"}]},"published":false,"editorial_status":"ready","content_html":"<p>アンチョ、トマト、ピーナッツ、ごまとチョコの簡略版赤いモーレを、ゆっくり煮た豚肉に絡めます。</p><p>米やトルティーヤなしで4人分。骨付き重量を使い、可食部65 %で栄養を推定します。特定地域の唯一の伝統配合とはしていません。</p>"},{"id":"37b032aa-d3b3-528f-961c-606958a764f6","recipe_group_id":"2ede9cae-1481-427b-b13d-3f5fc9a4b261","slug":"costelas-de-porco-mole-vermelho","public_path":"/pt/costelas-de-porco-mole-vermelho","source_url":null,"language":"pt","title":"Costelinhas de porco com mole vermelho","excerpt":"Costelas em mole vermelho com chile ancho, tomate, amendoim, gergelim e chocolate amargo. Cozinhe a carne lentamente e finalize no molho.","summary":"Mole vermelho simplificado de ancho, tomate, amendoim, gergelim e chocolate amargo, com costelas macias.\n\n4 porções sem arroz nem tortillas. Peso com osso; parte comestível estimada em 65 %. Não se apresenta como fórmula regional tradicional única.","category":"Pratos principais","category_slug":"platos-principales","difficulty":"Média","course":"Prato principal","cuisine":"Mexicana","prep_time_minutes":35,"cook_time_minutes":105,"total_time_minutes":140,"servings":4,"ingredients":[{"name":"costelas suínas com osso, cortadas","amount":"1000","unit":"g","group":"Carne"},{"name":"água","amount":"1200","unit":"ml","group":"Cozimento"},{"name":"sal","amount":"6","unit":"g","group":"Cozimento"},{"name":"chiles ancho secos sem talos nem sementes","amount":"30","unit":"g","group":"Mole"},{"name":"tomate","amount":"300","unit":"g","group":"Mole"},{"name":"cebola","amount":"150","unit":"g","group":"Mole"},{"name":"alho","amount":"12","unit":"g","group":"Mole"},{"name":"amendoins torrados sem sal","amount":"30","unit":"g","group":"Mole"},{"name":"sementes de gergelim","amount":"20","unit":"g","group":"Mole"},{"name":"chocolate amargo, 60–69 % cacau","amount":"25","unit":"g","group":"Mole"},{"name":"óleo vegetal","amount":"20","unit":"g","group":"Mole"},{"name":"canela moída","amount":"1","unit":"g","group":"Mole"},{"name":"cravo moído","amount":"0.2","unit":"g","group":"Mole"}],"steps":[{"title":"Prepare as costelinhas","content":"Ponha 1 kg de costelas com 1,2 litro de água e 6 g de sal. Ferva suavemente e retire espuma. Não lave carne crua.","image_url":"/recetas/costillas-en-mole-rojo/paso-01.webp","image_alt":"Costelinhas de porco com mole vermelho: Prepare as costelinhas"},{"title":"Cozinhe até amaciar","content":"Tampe parcialmente e cozinhe em fogo baixo 75–90 minutos até amaciar. Complete com água quente se necessário. Reserve 500 ml do líquido e mantenha a carne quente.","image_url":"/recetas/costillas-en-mole-rojo/paso-02.webp","image_alt":"Costelinhas de porco com mole vermelho: Cozinhe até amaciar"},{"title":"Toste e hidrate as pimentas","content":"Abra 30 g de ancho, tire talos e sementes. Torre a seco cerca de 10 segundos por lado sem escurecer. Hidrate em água quente 15 minutos, escorra e descarte essa água.","image_url":"/recetas/costillas-en-mole-rojo/paso-03.webp","image_alt":"Costelinhas de porco com mole vermelho: Toste e hidrate as pimentas"},{"title":"Asse os vegetais","content":"Toste a seco 300 g de tomate, 150 g de cebola em gomos e 12 g de alho por 10 minutos, virando sem carbonizar.","image_url":"/recetas/costillas-en-mole-rojo/paso-04.webp","image_alt":"Costelinhas de porco com mole vermelho: Asse os vegetais"},{"title":"Toste e bata o mole","content":"Torre 30 g de amendoim e 20 g de gergelim 1–2 minutos. Bata com chiles, vegetais, 1 g de canela, 0,2 g de cravo e 350 ml de líquido. Deixe amornar se o aparelho não aceita líquidos quentes.","image_url":"/recetas/costillas-en-mole-rojo/paso-05.webp","image_alt":"Costelinhas de porco com mole vermelho: Toste e bata o mole"},{"title":"Cozinhe o molho","content":"Aqueça 20 g de óleo e adicione mole com cuidado. Cozinhe em fogo baixo 10 minutos mexendo o fundo. Acrescente até 150 ml de líquido se engrossar demais.","image_url":"/recetas/costillas-en-mole-rojo/paso-06.webp","image_alt":"Costelinhas de porco com mole vermelho: Cozinhe o molho"},{"title":"Acrescente chocolate e carne","content":"Dissolva 25 g de chocolate no mole. Junte costelas e cozinhe suavemente 10 minutos. O molho deve cobrir sem virar bloco; ajuste com água quente.","image_url":"/recetas/costillas-en-mole-rojo/paso-07.webp","image_alt":"Costelinhas de porco com mole vermelho: Acrescente chocolate e carne"},{"title":"Sirva em quatro porções","content":"Divida carne e molho em 4 pratos. Arroz e tortillas são opcionais e não entram nos ingredientes nem na nutrição. Prove antes de adicionar sal.","image_url":"/recetas/costillas-en-mole-rojo/paso-08.webp","image_alt":"Costelinhas de porco com mole vermelho: Sirva em quatro porções"}],"notes":"Contém amendoim e gergelim. Em caso de alergia, escolha outra receita e utensílios sem contaminação. Refrigere até 3 dias ou congele 2 meses; reaqueça a 74 °C. Parte comestível e gordura descartada alteram bastante a estimativa.","nutrition":{"calories":515.0,"protein_g":36.7,"carbs_g":17.5,"fat_g":33.6,"saturated_fat_g":6.6,"fiber_g":5.1,"sugar_g":6.3,"sodium_mg":695.0,"serving_size":"1 de 4 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 4 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário. Carne aproximada por costela de lombo SR Legacy: 650 g comestíveis por 1 kg com osso. Todo molho é contado."},"keywords":["costelas mole vermelho","mole rojo porco","molho ancho"],"image_url":"/recetas/costillas-en-mole-rojo/portada.webp","gallery":[{"url":"/recetas/costillas-en-mole-rojo/portada.webp","alt":"Costelinhas de porco com mole vermelho: prato pronto"}],"seo":{"title":"Costelinhas de porco com mole vermelho | Manual de Cocina","description":"Costelas em mole vermelho com chile ancho, tomate, amendoim, gergelim e chocolate amargo. Cozinhe a carne lentamente e finalize no molho.","image_alt":"Costelinhas de porco com mole vermelho: prato pronto","image_variants":["/recetas/costillas-en-mole-rojo/portada-1x1.webp","/recetas/costillas-en-mole-rojo/portada-4x3.webp","/recetas/costillas-en-mole-rojo/portada-16x9.webp"],"faq":[{"q":"Por que o mole amarga?","a":"Chiles, gergelim ou alho queimados podem amargar. Torre brevemente; chocolate não corrige queimado intenso."},{"q":"Posso usar pasta pronta de mole?","a":"Siga o rótulo, mas quantidades, sal e nutrição serão diferentes."},{"q":"Posso preparar antes?","a":"Resfrie rapidamente em potes rasos e reaqueça a 74 °C; acrescente água se engrossar."}]},"published":false,"editorial_status":"ready","content_html":"<p>Mole vermelho simplificado de ancho, tomate, amendoim, gergelim e chocolate amargo, com costelas macias.</p><p>4 porções sem arroz nem tortillas. Peso com osso; parte comestível estimada em 65 %. Não se apresenta como fórmula regional tradicional única.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/costillas-en-mole-rojo') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

-- receta-de-hamburguesa-angus
do $pub$
declare
  g constant uuid := 'f38a2251-5235-4002-9ad6-7cea58219af6';
  es_id constant uuid := 'd1788f88-0b0e-400e-ad6b-2da6c0dd5c4f';
  j constant jsonb := $j$[{"id":"d1788f88-0b0e-400e-ad6b-2da6c0dd5c4f","recipe_group_id":"f38a2251-5235-4002-9ad6-7cea58219af6","slug":"receta-de-hamburguesa-angus","public_path":"/receta-de-hamburguesa-angus","source_url":"https://manualdecocina.com/receta-de-hamburguesa-angus/","language":"es","title":"Hamburguesa Angus casera","excerpt":"Hamburguesa Angus casera con carne de res, pan tostado, lechuga y tomate. Cuatro unidades y cocción de la carne picada hasta 71 °C.","summary":"Cuatro hamburguesas de 150 g de carne, formadas sin amasar en exceso y cocinadas en sartén o plancha. Llevan lechuga, tomate, cebolla, kétchup y mostaza; no llevan queso ni bacon.\n\nLa raza Angus identifica el origen de la carne, no sustituye el control de su frescura o de la temperatura de cocción.","category":"Platos principales","category_slug":"platos-principales","difficulty":"Media","course":"Plato principal","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":35,"servings":4,"ingredients":[{"name":"carne de res Angus picada, aproximadamente 20 % de grasa","amount":"600","unit":"g","group":"Hamburguesas"},{"name":"sal","amount":"4","unit":"g","group":"Hamburguesas"},{"name":"pimienta negra","amount":"1","unit":"g","group":"Hamburguesas"},{"name":"panes de hamburguesa","amount":"4","unit":"unidades","group":"Montaje"},{"name":"lechuga romana","amount":"60","unit":"g","group":"Montaje"},{"name":"tomate","amount":"160","unit":"g","group":"Montaje"},{"name":"cebolla","amount":"60","unit":"g","group":"Montaje"},{"name":"kétchup","amount":"40","unit":"g","group":"Salsas"},{"name":"mostaza preparada","amount":"20","unit":"g","group":"Salsas"}],"steps":[{"title":"Prepara los vegetales","content":"Lava y seca 60 g de lechuga. Corta 160 g de tomate en rodajas y 60 g de cebolla en aros finos. Reserva en frío sobre una tabla diferente de la utilizada para carne cruda.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-01.webp","image_alt":"Hamburguesa Angus casera: Prepara los vegetales"},{"title":"Divide la carne","content":"Divide 600 g de carne Angus picada en 4 porciones de 150 g. Mantén la carne fría y manipúlala solo lo necesario; no añadas huevo ni pan rallado.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-02.webp","image_alt":"Hamburguesa Angus casera: Divide la carne"},{"title":"Forma las hamburguesas","content":"Forma discos de aproximadamente 11 cm de diámetro y 1,5 cm de grosor. Haz una pequeña depresión en el centro para reducir el abombado. Refrigera mientras calientas la plancha.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-03.webp","image_alt":"Hamburguesa Angus casera: Forma las hamburguesas"},{"title":"Calienta y sazona","content":"Calienta una plancha o sartén de fondo grueso a fuego medio-alto durante 3 minutos. Reparte 4 g de sal y 1 g de pimienta sobre ambas caras de las hamburguesas justo antes de cocinarlas.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-04.webp","image_alt":"Hamburguesa Angus casera: Calienta y sazona"},{"title":"Cocina hasta 71 °C","content":"Cocina unos 4–5 minutos por lado sin aplastar. Introduce el termómetro lateralmente hasta el centro y alcanza al menos 71 °C; prolonga la cocción si hace falta. No uses el color interno como único criterio.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-05.webp","image_alt":"Hamburguesa Angus casera: Cocina hasta 71 °C"},{"title":"Tuesta los panes","content":"Retira las hamburguesas a un plato limpio. Abre los 4 panes y tuesta sus caras cortadas en la plancha durante 1–2 minutos, sin quemarlas. Usa utensilios que no hayan tocado carne cruda.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-06.webp","image_alt":"Hamburguesa Angus casera: Tuesta los panes"},{"title":"Monta las hamburguesas","content":"Reparte 40 g de kétchup y 20 g de mostaza entre las bases. Añade lechuga, una hamburguesa cocida, tomate y cebolla; cierra con la parte superior del pan.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-07.webp","image_alt":"Hamburguesa Angus casera: Monta las hamburguesas"},{"title":"Sirve recién hechas","content":"Sirve una hamburguesa por persona inmediatamente. Las patatas y otras guarniciones no se incluyen en la receta ni en su estimación nutricional.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-08.webp","image_alt":"Hamburguesa Angus casera: Sirve recién hechas"}],"notes":"La nutrición usa res picada genérica 80 % magra / 20 % grasa, porque no hay una ficha SR Legacy específica de Angus. Se contabiliza la grasa inicial completa aunque parte quede en la plancha. Conserva carne cruda refrigerada y cocina en 24 horas. Las hamburguesas cocidas, sin montar, se conservan hasta 3 días refrigeradas y se recalientan hasta 74 °C.","nutrition":{"calories":578.0,"protein_g":32.6,"carbs_g":36.7,"fat_g":32.7,"saturated_fat_g":11.9,"fiber_g":2.4,"sugar_g":8.4,"sodium_mg":933.0,"serving_size":"1 de 4 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 4 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma. La res Angus se aproxima con res picada genérica 80/20; los panes se calculan como 60 g por unidad. Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"carne de res Angus picada, aproximadamente 20 % de grasa","edible_grams":600,"fdc_id":174036,"fdc_description":"Beef, ground, 80% lean meat / 20% fat, raw","per_100g":{"fiber_g":0.0,"protein_g":17.17,"fat_g":20.0,"carbs_g":0.0,"sugar_g":0.0,"calories":254.0,"sodium_mg":66.0,"saturated_fat_g":7.581},"source_url":"https://fdc.nal.usda.gov/food-details/174036/nutrients"},{"ingredient":"sal","edible_grams":4,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0.0,"sodium_mg":38758.0,"saturated_fat_g":0.0,"protein_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"pimienta negra","edible_grams":1,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":63.95,"calories":251.0,"protein_g":10.39,"fiber_g":25.3,"sodium_mg":20.0,"saturated_fat_g":1.392},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"panes de hamburguesa","edible_grams":240,"fdc_id":172796,"fdc_description":"Rolls, hamburger or hotdog, plain","per_100g":{"saturated_fat_g":0.842,"fiber_g":1.8,"sodium_mg":494.0,"protein_g":9.77,"sugar_g":7.28,"fat_g":3.91,"carbs_g":50.12,"calories":279.0},"source_url":"https://fdc.nal.usda.gov/food-details/172796/nutrients"},{"ingredient":"lechuga romana","edible_grams":60,"fdc_id":169247,"fdc_description":"Lettuce, cos or romaine, raw","per_100g":{"carbs_g":3.29,"calories":17.0,"saturated_fat_g":0.039,"sodium_mg":8.0,"fat_g":0.3,"sugar_g":1.19,"fiber_g":2.1,"protein_g":1.23},"source_url":"https://fdc.nal.usda.gov/food-details/169247/nutrients"},{"ingredient":"tomate","edible_grams":160,"fdc_id":170457,"fdc_description":"Tomatoes, red, ripe, raw, year round average","per_100g":{"sugar_g":2.63,"carbs_g":3.89,"calories":18.0,"saturated_fat_g":0.028,"fat_g":0.2,"fiber_g":1.2,"sodium_mg":5.0,"protein_g":0.88},"source_url":"https://fdc.nal.usda.gov/food-details/170457/nutrients"},{"ingredient":"cebolla","edible_grams":60,"fdc_id":170000,"fdc_description":"Onions, raw","per_100g":{"sugar_g":4.24,"fat_g":0.1,"carbs_g":9.34,"calories":40.0,"saturated_fat_g":0.042,"protein_g":1.1,"fiber_g":1.7,"sodium_mg":4.0},"source_url":"https://fdc.nal.usda.gov/food-details/170000/nutrients"},{"ingredient":"kétchup","edible_grams":40,"fdc_id":168556,"fdc_description":"Catsup","per_100g":{"sodium_mg":907.0,"protein_g":1.04,"fiber_g":0.3,"saturated_fat_g":0.014,"sugar_g":21.27,"fat_g":0.1,"carbs_g":27.4,"calories":101.0},"source_url":"https://fdc.nal.usda.gov/food-details/168556/nutrients"},{"ingredient":"mostaza preparada","edible_grams":20,"fdc_id":172234,"fdc_description":"Mustard, prepared, yellow","per_100g":{"protein_g":3.74,"fiber_g":4.0,"sodium_mg":1104.0,"saturated_fat_g":0.214,"fat_g":3.34,"carbs_g":5.83,"calories":60.0,"sugar_g":0.92},"source_url":"https://fdc.nal.usda.gov/food-details/172234/nutrients"}]},"keywords":["hamburguesa Angus casera","hamburguesa 150 gramos","hamburguesa de res en sartén"],"image_url":"/recetas/receta-de-hamburguesa-angus/portada.webp","gallery":[{"url":"/recetas/receta-de-hamburguesa-angus/portada.webp","alt":"Hamburguesa Angus casera: plato terminado"}],"seo":{"title":"Hamburguesa Angus casera | Manual de Cocina","description":"Hamburguesa Angus casera con carne de res, pan tostado, lechuga y tomate. Cuatro unidades y cocción de la carne picada hasta 71 °C.","image_alt":"Hamburguesa Angus casera: plato terminado","image_variants":["/recetas/receta-de-hamburguesa-angus/portada-1x1.webp","/recetas/receta-de-hamburguesa-angus/portada-4x3.webp","/recetas/receta-de-hamburguesa-angus/portada-16x9.webp"],"faq":[{"q":"¿La carne Angus necesita otro tiempo?","a":"El tiempo depende del grosor y la plancha, no solo de la raza. La carne picada debe alcanzar 71 °C en el centro."},{"q":"¿Por qué no se aplasta mientras se cocina?","a":"Presionar expulsa jugos y puede dejar la hamburguesa más seca. Forma el disco antes y gíralo sin apretarlo."},{"q":"¿Puedo añadir queso?","a":"Sí, como variante opcional. No se incluye en los ingredientes ni en la nutrición de esta versión."}]},"published":false,"editorial_status":"ready","content_html":"<p>Cuatro hamburguesas de 150 g de carne, formadas sin amasar en exceso y cocinadas en sartén o plancha. Llevan lechuga, tomate, cebolla, kétchup y mostaza; no llevan queso ni bacon.</p><p>La raza Angus identifica el origen de la carne, no sustituye el control de su frescura o de la temperatura de cocción.</p>"},{"id":"0c3ddcb7-e696-57ce-bfd4-9728efbc41ce","recipe_group_id":"f38a2251-5235-4002-9ad6-7cea58219af6","slug":"angus-burger-selber-machen","public_path":"/de/angus-burger-selber-machen","source_url":null,"language":"de","title":"Angus-Burger selbst gemacht","excerpt":"Angus-Burger mit 150-g-Patties, Salat, Tomate, Zwiebel, Ketchup und Senf. In Pfanne oder auf der Platte bis 71 °C im Kern garen.","summary":"Vier Burger mit je 150 g Fleisch, ohne starkes Kneten geformt und in Pfanne oder auf Grillplatte gegart. Mit Salat, Tomate, Zwiebel, Ketchup und Senf, ohne Käse oder Speck.\n\nAngus bezeichnet die Rinderrasse und ersetzt keine Prüfung der Frische oder Kerntemperatur.","category":"Hauptgerichte","category_slug":"platos-principales","difficulty":"Mittel","course":"Hauptgericht","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":35,"servings":4,"ingredients":[{"name":"Angus-Rinderhack, etwa 20 % Fett","amount":"600","unit":"g","group":"Patties"},{"name":"Salz","amount":"4","unit":"g","group":"Patties"},{"name":"schwarzer Pfeffer","amount":"1","unit":"g","group":"Patties"},{"name":"Burgerbrötchen","amount":"4","unit":"Stück","group":"Zusammenstellen"},{"name":"Römersalat","amount":"60","unit":"g","group":"Zusammenstellen"},{"name":"Tomate","amount":"160","unit":"g","group":"Zusammenstellen"},{"name":"Zwiebel","amount":"60","unit":"g","group":"Zusammenstellen"},{"name":"Ketchup","amount":"40","unit":"g","group":"Saucen"},{"name":"zubereiteter Senf","amount":"20","unit":"g","group":"Saucen"}],"steps":[{"title":"Gemüse vorbereiten","content":"60 g Salat waschen und trocknen. 160 g Tomate in Scheiben und 60 g Zwiebel in dünne Ringe schneiden. Gekühlt auf einem anderen Brett als rohes Fleisch bereitstellen.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-01.webp","image_alt":"Angus-Burger selbst gemacht: Gemüse vorbereiten"},{"title":"Fleisch portionieren","content":"600 g Angus-Hack in 4 Portionen à 150 g teilen. Kalt halten und wenig bearbeiten; kein Ei oder Paniermehl zugeben.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-02.webp","image_alt":"Angus-Burger selbst gemacht: Fleisch portionieren"},{"title":"Patties formen","content":"Patties von etwa 11 cm Durchmesser und 1,5 cm Dicke formen. In der Mitte leicht eindrücken, um Wölben zu verringern. Beim Aufheizen der Pfanne kalt stellen.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-03.webp","image_alt":"Angus-Burger selbst gemacht: Patties formen"},{"title":"Erhitzen und würzen","content":"Schwere Pfanne oder Grillplatte 3 Minuten bei mittlerer bis hoher Hitze aufheizen. 4 g Salz und 1 g Pfeffer direkt vor dem Garen auf beide Seiten verteilen.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-04.webp","image_alt":"Angus-Burger selbst gemacht: Erhitzen und würzen"},{"title":"Bis 71 °C garen","content":"Etwa 4–5 Minuten je Seite ohne Drücken garen. Thermometer seitlich bis zur Mitte einführen; mindestens 71 °C erreichen, nötigenfalls länger garen. Nicht nur nach Fleischfarbe beurteilen.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-05.webp","image_alt":"Angus-Burger selbst gemacht: Bis 71 °C garen"},{"title":"Brötchen rösten","content":"Patties auf sauberen Teller nehmen. 4 Brötchen öffnen und Schnittflächen 1–2 Minuten rösten, ohne zu verbrennen. Saubere Werkzeuge ohne Rohfleischkontakt nutzen.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-06.webp","image_alt":"Angus-Burger selbst gemacht: Brötchen rösten"},{"title":"Burger zusammensetzen","content":"40 g Ketchup und 20 g Senf auf die Böden verteilen. Salat, gegartes Patty, Tomate und Zwiebel auflegen, mit Brötchendeckel schließen.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-07.webp","image_alt":"Angus-Burger selbst gemacht: Burger zusammensetzen"},{"title":"Frisch servieren","content":"Sofort je einen Burger pro Person servieren. Pommes und andere Beilagen sind nicht enthalten oder in die Nährwerte eingerechnet.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-08.webp","image_alt":"Angus-Burger selbst gemacht: Frisch servieren"}],"notes":"Nährwerte verwenden allgemeines Rinderhack 80/20, keine spezifische Angus-Fiche. Anfangsfett wird vollständig gezählt, auch wenn etwas austritt. Rohes Fleisch gekühlt innerhalb 24 Stunden garen. Gegarte Patties ohne Brötchen bis 3 Tage kühlen und auf 74 °C erwärmen.","nutrition":{"calories":578.0,"protein_g":32.6,"carbs_g":36.7,"fat_g":32.7,"saturated_fat_g":11.9,"fiber_g":2.4,"sugar_g":8.4,"sodium_mg":933.0,"serving_size":"1 von 4 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 4 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers. Angus wird mit allgemeinem Rinderhack 80/20 angenähert; jedes Brötchen wird mit 60 g berechnet."},"keywords":["Angus Burger selber machen","Burger 150 g","Rindfleischburger Pfanne"],"image_url":"/recetas/receta-de-hamburguesa-angus/portada.webp","gallery":[{"url":"/recetas/receta-de-hamburguesa-angus/portada.webp","alt":"Angus-Burger selbst gemacht: fertiges Gericht"}],"seo":{"title":"Angus-Burger selbst gemacht | Manual de Cocina","description":"Angus-Burger mit 150-g-Patties, Salat, Tomate, Zwiebel, Ketchup und Senf. In Pfanne oder auf der Platte bis 71 °C im Kern garen.","image_alt":"Angus-Burger selbst gemacht: fertiges Gericht","image_variants":["/recetas/receta-de-hamburguesa-angus/portada-1x1.webp","/recetas/receta-de-hamburguesa-angus/portada-4x3.webp","/recetas/receta-de-hamburguesa-angus/portada-16x9.webp"],"faq":[{"q":"Braucht Angus eine andere Garzeit?","a":"Dicke und Pfanne bestimmen die Zeit; Hackfleisch muss 71 °C im Kern erreichen."},{"q":"Warum nicht während des Bratens drücken?","a":"Das presst Saft heraus und kann das Patty trocknen. Vorher formen und ohne Drücken wenden."},{"q":"Kann ich Käse zugeben?","a":"Optional, aber nicht in Zutaten und Nährwerten dieser Version enthalten."}]},"published":false,"editorial_status":"ready","content_html":"<p>Vier Burger mit je 150 g Fleisch, ohne starkes Kneten geformt und in Pfanne oder auf Grillplatte gegart. Mit Salat, Tomate, Zwiebel, Ketchup und Senf, ohne Käse oder Speck.</p><p>Angus bezeichnet die Rinderrasse und ersetzt keine Prüfung der Frische oder Kerntemperatur.</p>"},{"id":"8656de83-e4f0-507b-8036-27924c5b8f78","recipe_group_id":"f38a2251-5235-4002-9ad6-7cea58219af6","slug":"homemade-angus-burger","public_path":"/en/homemade-angus-burger","source_url":null,"language":"en","title":"Homemade Angus burger","excerpt":"Angus burgers with 150 g patties, lettuce, tomato, onion, ketchup and mustard. Pan-cook to a 71 °C centre without pressing out the juices.","summary":"Four burgers with 150 g meat each, shaped with minimal handling and cooked in a pan or on a griddle. Topped with lettuce, tomato, onion, ketchup and mustard, without cheese or bacon.\n\nAngus identifies the cattle breed; it does not replace checking freshness or cooking temperature.","category":"Main dishes","category_slug":"platos-principales","difficulty":"Medium","course":"Main course","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":35,"servings":4,"ingredients":[{"name":"minced Angus beef, about 20 % fat","amount":"600","unit":"g","group":"Patties"},{"name":"salt","amount":"4","unit":"g","group":"Patties"},{"name":"black pepper","amount":"1","unit":"g","group":"Patties"},{"name":"burger buns","amount":"4","unit":"pieces","group":"Assembly"},{"name":"romaine lettuce","amount":"60","unit":"g","group":"Assembly"},{"name":"tomato","amount":"160","unit":"g","group":"Assembly"},{"name":"onion","amount":"60","unit":"g","group":"Assembly"},{"name":"ketchup","amount":"40","unit":"g","group":"Sauces"},{"name":"prepared mustard","amount":"20","unit":"g","group":"Sauces"}],"steps":[{"title":"Prepare the vegetables","content":"Wash and dry 60 g lettuce. Slice 160 g tomato and cut 60 g onion into thin rings. Refrigerate on a board separate from raw-meat preparation.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-01.webp","image_alt":"Homemade Angus burger: Prepare the vegetables"},{"title":"Divide the meat","content":"Divide 600 g Angus mince into 4 portions of 150 g. Keep cold and handle minimally; do not add egg or breadcrumbs.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-02.webp","image_alt":"Homemade Angus burger: Divide the meat"},{"title":"Shape the patties","content":"Shape patties about 11 cm across and 1.5 cm thick. Make a small central dent to reduce bulging. Refrigerate while heating the griddle.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-03.webp","image_alt":"Homemade Angus burger: Shape the patties"},{"title":"Heat and season","content":"Heat a heavy pan or griddle over medium-high heat for 3 minutes. Distribute 4 g salt and 1 g pepper over both sides just before cooking.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-04.webp","image_alt":"Homemade Angus burger: Heat and season"},{"title":"Cook to 71 °C","content":"Cook about 4–5 minutes per side without pressing. Insert a thermometer from the side to the centre and reach at least 71 °C; cook longer if needed. Internal colour alone is not a reliable test.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-05.webp","image_alt":"Homemade Angus burger: Cook to 71 °C"},{"title":"Toast the buns","content":"Move patties to a clean plate. Split 4 buns and toast cut sides for 1–2 minutes without burning. Use utensils that have not touched raw meat.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-06.webp","image_alt":"Homemade Angus burger: Toast the buns"},{"title":"Assemble the burgers","content":"Divide 40 g ketchup and 20 g mustard between bun bases. Add lettuce, one cooked patty, tomato and onion, then close with the bun top.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-07.webp","image_alt":"Homemade Angus burger: Assemble the burgers"},{"title":"Serve freshly cooked","content":"Serve one burger per person immediately. Fries and other sides are excluded from the recipe and nutrition estimate.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-08.webp","image_alt":"Homemade Angus burger: Serve freshly cooked"}],"notes":"Nutrition uses generic 80 % lean/20 % fat beef, as no Angus-specific SR Legacy entry was selected. All starting fat is counted although some remains in the pan. Cook refrigerated raw meat within 24 hours. Unassembled cooked patties keep refrigerated up to 3 days; reheat to 74 °C.","nutrition":{"calories":578.0,"protein_g":32.6,"carbs_g":36.7,"fat_g":32.7,"saturated_fat_g":11.9,"fiber_g":2.4,"sugar_g":8.4,"sodium_mg":933.0,"serving_size":"1 of 4 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 4 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation. Angus is approximated by generic 80/20 beef; buns are calculated at 60 g each."},"keywords":["homemade Angus burger","150 g beef burger","pan cooked burger"],"image_url":"/recetas/receta-de-hamburguesa-angus/portada.webp","gallery":[{"url":"/recetas/receta-de-hamburguesa-angus/portada.webp","alt":"Homemade Angus burger: finished dish"}],"seo":{"title":"Homemade Angus burger | Manual de Cocina","description":"Angus burgers with 150 g patties, lettuce, tomato, onion, ketchup and mustard. Pan-cook to a 71 °C centre without pressing out the juices.","image_alt":"Homemade Angus burger: finished dish","image_variants":["/recetas/receta-de-hamburguesa-angus/portada-1x1.webp","/recetas/receta-de-hamburguesa-angus/portada-4x3.webp","/recetas/receta-de-hamburguesa-angus/portada-16x9.webp"],"faq":[{"q":"Does Angus need a different cooking time?","a":"Thickness and pan heat determine time, not breed alone. Minced beef must reach 71 °C in the centre."},{"q":"Why not press the burger while cooking?","a":"Pressing expels juices and can dry it out. Shape first and turn without squeezing."},{"q":"Can I add cheese?","a":"As an optional variation; it is not included in this version's ingredients or nutrition."}]},"published":false,"editorial_status":"ready","content_html":"<p>Four burgers with 150 g meat each, shaped with minimal handling and cooked in a pan or on a griddle. Topped with lettuce, tomato, onion, ketchup and mustard, without cheese or bacon.</p><p>Angus identifies the cattle breed; it does not replace checking freshness or cooking temperature.</p>"},{"id":"6addf75b-893e-56f1-8129-daec697dc616","recipe_group_id":"f38a2251-5235-4002-9ad6-7cea58219af6","slug":"burger-angus-maison","public_path":"/fr/burger-angus-maison","source_url":null,"language":"fr","title":"Burger Angus maison","excerpt":"Burger Angus de 150 g, laitue, tomate, oignon, ketchup et moutarde. Cuisson à la poêle ou plancha jusqu’à 71 °C à cœur.","summary":"Quatre burgers de 150 g de viande chacun, façonnés sans trop pétrir, cuits à la poêle ou plancha. Laitue, tomate, oignon, ketchup et moutarde, sans fromage ni bacon.\n\nAngus désigne la race bovine, pas une garantie remplaçant la fraîcheur ou la température de cuisson.","category":"Plats principaux","category_slug":"platos-principales","difficulty":"Moyenne","course":"Plat principal","cuisine":"Internationale","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":35,"servings":4,"ingredients":[{"name":"bœuf Angus haché, environ 20 % de gras","amount":"600","unit":"g","group":"Steaks"},{"name":"sel","amount":"4","unit":"g","group":"Steaks"},{"name":"poivre noir","amount":"1","unit":"g","group":"Steaks"},{"name":"pains à burger","amount":"4","unit":"pièces","group":"Montage"},{"name":"laitue romaine","amount":"60","unit":"g","group":"Montage"},{"name":"tomate","amount":"160","unit":"g","group":"Montage"},{"name":"oignon","amount":"60","unit":"g","group":"Montage"},{"name":"ketchup","amount":"40","unit":"g","group":"Sauces"},{"name":"moutarde préparée","amount":"20","unit":"g","group":"Sauces"}],"steps":[{"title":"Préparer les légumes","content":"Lavez et séchez 60 g de laitue. Tranchez 160 g de tomate et 60 g d’oignon en anneaux fins. Réservez au frais sur une planche distincte de la viande crue.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-01.webp","image_alt":"Burger Angus maison: Préparer les légumes"},{"title":"Diviser la viande","content":"Divisez 600 g de bœuf en 4 portions de 150 g. Gardez froid et manipulez peu; sans œuf ni chapelure.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-02.webp","image_alt":"Burger Angus maison: Diviser la viande"},{"title":"Former les steaks","content":"Formez des disques de 11 cm environ et 1,5 cm d’épaisseur. Creusez légèrement le centre pour limiter le gonflement. Réfrigérez pendant le préchauffage.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-03.webp","image_alt":"Burger Angus maison: Former les steaks"},{"title":"Chauffer et assaisonner","content":"Chauffez poêle épaisse ou plancha 3 minutes à feu moyen-vif. Répartissez 4 g de sel et 1 g de poivre sur les deux faces juste avant cuisson.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-04.webp","image_alt":"Burger Angus maison: Chauffer et assaisonner"},{"title":"Cuire à 71 °C","content":"Cuisez environ 4–5 minutes par face sans presser. Insérez le thermomètre latéralement jusqu’au centre: au moins 71 °C, en prolongeant au besoin. La couleur seule ne suffit pas.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-05.webp","image_alt":"Burger Angus maison: Cuire à 71 °C"},{"title":"Griller les pains","content":"Posez les steaks sur une assiette propre. Ouvrez les 4 pains et toastez les faces coupées 1–2 minutes sans brûler, avec des ustensiles propres.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-06.webp","image_alt":"Burger Angus maison: Griller les pains"},{"title":"Monter les burgers","content":"Répartissez 40 g de ketchup et 20 g de moutarde sur les bases. Ajoutez laitue, steak cuit, tomate et oignon, puis fermez.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-07.webp","image_alt":"Burger Angus maison: Monter les burgers"},{"title":"Servir immédiatement","content":"Servez immédiatement un burger par personne. Frites et accompagnements ne sont pas inclus dans la recette ni dans la nutrition.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-08.webp","image_alt":"Burger Angus maison: Servir immédiatement"}],"notes":"Nutrition calculée avec bœuf haché générique 80/20, pas de fiche Angus spécifique. Tout le gras initial est compté même s’il reste dans la poêle. Cuisez la viande crue réfrigérée sous 24 heures. Steaks cuits non montés: 3 jours au frais, réchauffage à 74 °C.","nutrition":{"calories":578.0,"protein_g":32.6,"carbs_g":36.7,"fat_g":32.7,"saturated_fat_g":11.9,"fiber_g":2.4,"sugar_g":8.4,"sodium_mg":933.0,"serving_size":"1 des 4 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 4 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire. Angus approximé par bœuf 80/20; pains estimés à 60 g chacun."},"keywords":["burger Angus maison","burger bœuf 150 g","burger plancha"],"image_url":"/recetas/receta-de-hamburguesa-angus/portada.webp","gallery":[{"url":"/recetas/receta-de-hamburguesa-angus/portada.webp","alt":"Burger Angus maison: plat terminé"}],"seo":{"title":"Burger Angus maison | Manual de Cocina","description":"Burger Angus de 150 g, laitue, tomate, oignon, ketchup et moutarde. Cuisson à la poêle ou plancha jusqu’à 71 °C à cœur.","image_alt":"Burger Angus maison: plat terminé","image_variants":["/recetas/receta-de-hamburguesa-angus/portada-1x1.webp","/recetas/receta-de-hamburguesa-angus/portada-4x3.webp","/recetas/receta-de-hamburguesa-angus/portada-16x9.webp"],"faq":[{"q":"L’Angus nécessite-t-il une autre durée?","a":"Épaisseur et poêle déterminent la durée; le centre doit atteindre 71 °C."},{"q":"Pourquoi ne pas presser le steak?","a":"Cela chasse le jus et peut le dessécher. Façonnez avant et retournez sans pression."},{"q":"Peut-on ajouter du fromage?","a":"En variante facultative, non comptée dans les ingrédients ni la nutrition."}]},"published":false,"editorial_status":"ready","content_html":"<p>Quatre burgers de 150 g de viande chacun, façonnés sans trop pétrir, cuits à la poêle ou plancha. Laitue, tomate, oignon, ketchup et moutarde, sans fromage ni bacon.</p><p>Angus désigne la race bovine, pas une garantie remplaçant la fraîcheur ou la température de cuisson.</p>"},{"id":"6f5de595-4095-5736-8e69-0fd2d662c695","recipe_group_id":"f38a2251-5235-4002-9ad6-7cea58219af6","slug":"hamburger-angus-fatto-in-casa","public_path":"/it/hamburger-angus-fatto-in-casa","source_url":null,"language":"it","title":"Hamburger Angus fatto in casa","excerpt":"Hamburger Angus da 150 g con lattuga, pomodoro, cipolla, ketchup e senape. Cuoci in padella o piastra fino a 71 °C al centro.","summary":"Quattro hamburger con 150 g di carne ciascuno, formati senza impastare troppo e cotti in padella o piastra. Con lattuga, pomodoro, cipolla, ketchup e senape, senza formaggio né bacon.\n\nAngus indica la razza bovina e non sostituisce controlli di freschezza o temperatura.","category":"Secondi piatti","category_slug":"platos-principales","difficulty":"Media","course":"Piatto principale","cuisine":"Internazionale","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":35,"servings":4,"ingredients":[{"name":"macinato di manzo Angus, circa 20 % grassi","amount":"600","unit":"g","group":"Hamburger"},{"name":"sale","amount":"4","unit":"g","group":"Hamburger"},{"name":"pepe nero","amount":"1","unit":"g","group":"Hamburger"},{"name":"panini da hamburger","amount":"4","unit":"pezzi","group":"Montaggio"},{"name":"lattuga romana","amount":"60","unit":"g","group":"Montaggio"},{"name":"pomodoro","amount":"160","unit":"g","group":"Montaggio"},{"name":"cipolla","amount":"60","unit":"g","group":"Montaggio"},{"name":"ketchup","amount":"40","unit":"g","group":"Salse"},{"name":"senape pronta","amount":"20","unit":"g","group":"Salse"}],"steps":[{"title":"Preparare le verdure","content":"Lava e asciuga 60 g di lattuga. Taglia 160 g di pomodoro a fette e 60 g di cipolla ad anelli sottili. Tieni al fresco su tagliere diverso dalla carne cruda.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-01.webp","image_alt":"Hamburger Angus fatto in casa: Preparare le verdure"},{"title":"Dividere la carne","content":"Dividi 600 g di macinato in 4 porzioni da 150 g. Mantieni freddo e manipola poco, senza uova né pangrattato.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-02.webp","image_alt":"Hamburger Angus fatto in casa: Dividere la carne"},{"title":"Formare gli hamburger","content":"Forma dischi di circa 11 cm e 1,5 cm di spessore, con lieve incavo centrale. Refrigera mentre scaldi la piastra.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-03.webp","image_alt":"Hamburger Angus fatto in casa: Formare gli hamburger"},{"title":"Scaldare e insaporire","content":"Scalda padella pesante o piastra a fuoco medio-alto per 3 minuti. Distribuisci 4 g di sale e 1 g di pepe sui due lati appena prima di cuocere.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-04.webp","image_alt":"Hamburger Angus fatto in casa: Scaldare e insaporire"},{"title":"Cuocere a 71 °C","content":"Cuoci circa 4–5 minuti per lato senza schiacciare. Inserisci il termometro lateralmente fino al centro e raggiungi almeno 71 °C, prolungando se serve. Non giudicare solo dal colore.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-05.webp","image_alt":"Hamburger Angus fatto in casa: Cuocere a 71 °C"},{"title":"Tostare i panini","content":"Metti su piatto pulito. Apri i 4 panini e tosta i lati tagliati 1–2 minuti senza bruciare; usa utensili senza contatto con carne cruda.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-06.webp","image_alt":"Hamburger Angus fatto in casa: Tostare i panini"},{"title":"Comporre gli hamburger","content":"Distribuisci 40 g di ketchup e 20 g di senape sulle basi. Aggiungi lattuga, hamburger cotto, pomodoro e cipolla, poi chiudi.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-07.webp","image_alt":"Hamburger Angus fatto in casa: Comporre gli hamburger"},{"title":"Servire subito","content":"Servi subito un hamburger per persona. Patatine e contorni non entrano nella ricetta né nella nutrizione.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-08.webp","image_alt":"Hamburger Angus fatto in casa: Servire subito"}],"notes":"Nutrizione con manzo generico 80/20, non dati specifici Angus. Si conta tutto il grasso iniziale anche se parte resta sulla piastra. Cuoci carne cruda refrigerata entro 24 ore. Hamburger cotti non montati durano 3 giorni al freddo; riscalda a 74 °C.","nutrition":{"calories":578.0,"protein_g":32.6,"carbs_g":36.7,"fat_g":32.7,"saturated_fat_g":11.9,"fiber_g":2.4,"sugar_g":8.4,"sodium_mg":933.0,"serving_size":"1 delle 4 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 4 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario. Angus approssimato con manzo 80/20; panini stimati da 60 g ciascuno."},"keywords":["hamburger Angus casalingo","hamburger 150 g","hamburger in padella"],"image_url":"/recetas/receta-de-hamburguesa-angus/portada.webp","gallery":[{"url":"/recetas/receta-de-hamburguesa-angus/portada.webp","alt":"Hamburger Angus fatto in casa: piatto pronto"}],"seo":{"title":"Hamburger Angus fatto in casa | Manual de Cocina","description":"Hamburger Angus da 150 g con lattuga, pomodoro, cipolla, ketchup e senape. Cuoci in padella o piastra fino a 71 °C al centro.","image_alt":"Hamburger Angus fatto in casa: piatto pronto","image_variants":["/recetas/receta-de-hamburguesa-angus/portada-1x1.webp","/recetas/receta-de-hamburguesa-angus/portada-4x3.webp","/recetas/receta-de-hamburguesa-angus/portada-16x9.webp"],"faq":[{"q":"Angus richiede un tempo diverso?","a":"Dipende da spessore e piastra; il macinato deve arrivare a 71 °C al centro."},{"q":"Perché non schiacciarlo in cottura?","a":"Espelle succhi e può seccarlo. Forma prima e gira senza pressione."},{"q":"Posso aggiungere formaggio?","a":"Come variante facoltativa, esclusa dagli ingredienti e dalla nutrizione."}]},"published":false,"editorial_status":"ready","content_html":"<p>Quattro hamburger con 150 g di carne ciascuno, formati senza impastare troppo e cotti in padella o piastra. Con lattuga, pomodoro, cipolla, ketchup e senape, senza formaggio né bacon.</p><p>Angus indica la razza bovina e non sostituisce controlli di freschezza o temperatura.</p>"},{"id":"93642aec-2808-53ad-a2aa-97a4fb959e4b","recipe_group_id":"f38a2251-5235-4002-9ad6-7cea58219af6","slug":"自家製アンガスバーガー","public_path":"/ja/自家製アンガスバーガー","source_url":null,"language":"ja","title":"自家製アンガスビーフバーガー","excerpt":"150 gのアンガス牛パティにレタス、トマト、玉ねぎ、ケチャップ、マスタード。フライパンで中心71 °Cまで焼きます。","summary":"肉150 gずつのバーガー4個。練りすぎず形を作って焼き、レタス、トマト、玉ねぎ、ケチャップ、マスタードを挟みます。チーズやベーコンは使いません。\n\nアンガスは牛の品種を示すもので、鮮度や加熱温度の確認を代用しません。","category":"主菜","category_slug":"platos-principales","difficulty":"普通","course":"主菜","cuisine":"世界の料理","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":35,"servings":4,"ingredients":[{"name":"アンガス牛ひき肉、脂肪約20 %","amount":"600","unit":"g","group":"パティ"},{"name":"塩","amount":"4","unit":"g","group":"パティ"},{"name":"黒こしょう","amount":"1","unit":"g","group":"パティ"},{"name":"バーガーバンズ","amount":"4","unit":"個","group":"組み立て"},{"name":"ロメインレタス","amount":"60","unit":"g","group":"組み立て"},{"name":"トマト","amount":"160","unit":"g","group":"組み立て"},{"name":"玉ねぎ","amount":"60","unit":"g","group":"組み立て"},{"name":"ケチャップ","amount":"40","unit":"g","group":"ソース"},{"name":"練りマスタード","amount":"20","unit":"g","group":"ソース"}],"steps":[{"title":"野菜を用意する","content":"レタス60 gを洗い乾かし、トマト160 gを薄切り、玉ねぎ60 gを薄い輪切りにします。生肉とは別のまな板で扱い、冷やします。","image_url":"/recetas/receta-de-hamburguesa-angus/paso-01.webp","image_alt":"自家製アンガスビーフバーガー: 野菜を用意する"},{"title":"肉を分ける","content":"ひき肉600 gを150 gずつ4等分します。冷たく保ち、必要以上に触らず、卵やパン粉は入れません。","image_url":"/recetas/receta-de-hamburguesa-angus/paso-02.webp","image_alt":"自家製アンガスビーフバーガー: 肉を分ける"},{"title":"パティを成形する","content":"径約11 cm、厚さ1.5 cmの円盤にし、膨らみを減らすため中央を少しくぼませます。鍋を温める間冷蔵します。","image_url":"/recetas/receta-de-hamburguesa-angus/paso-03.webp","image_alt":"自家製アンガスビーフバーガー: パティを成形する"},{"title":"加熱の準備と味付けをする","content":"厚底フライパンか鉄板を中強火で3分温めます。焼く直前に塩4 gとこしょう1 gを両面へ分けます。","image_url":"/recetas/receta-de-hamburguesa-angus/paso-04.webp","image_alt":"自家製アンガスビーフバーガー: 加熱の準備と味付けをする"},{"title":"中心温度71 °Cまで加熱する","content":"押さえず片面約4–5分ずつ焼きます。温度計を横から中央まで刺し、最低71 °Cまで、必要なら長く焼きます。肉の色だけで判断しません。","image_url":"/recetas/receta-de-hamburguesa-angus/paso-05.webp","image_alt":"自家製アンガスビーフバーガー: 中心温度71 °Cまで加熱する"},{"title":"パンを焼く","content":"清潔な皿へ肉を移します。バンズ4個を開き、断面を1–2分焦がさず焼きます。生肉に触れていない器具を使います。","image_url":"/recetas/receta-de-hamburguesa-angus/paso-06.webp","image_alt":"自家製アンガスビーフバーガー: パンを焼く"},{"title":"バーガーを組み立てる","content":"下のパンへケチャップ40 gとマスタード20 gを分けます。レタス、焼いたパティ、トマト、玉ねぎを重ね、上のパンで閉じます。","image_url":"/recetas/receta-de-hamburguesa-angus/paso-07.webp","image_alt":"自家製アンガスビーフバーガー: バーガーを組み立てる"},{"title":"できたてを盛り付ける","content":"すぐ1人1個提供します。ポテトなどの付け合わせは材料・栄養に含みません。","image_url":"/recetas/receta-de-hamburguesa-angus/paso-08.webp","image_alt":"自家製アンガスビーフバーガー: できたてを盛り付ける"}],"notes":"栄養はアンガス専用データではなく、一般的な牛ひき肉80/20で計算。流れ出る分も脂を全量計上します。生肉は冷蔵して24時間以内に調理。組み立て前の加熱済みパティは冷蔵最長3日、再加熱74 °Cまで。","nutrition":{"calories":578.0,"protein_g":32.6,"carbs_g":36.7,"fat_g":32.7,"saturated_fat_g":11.9,"fiber_g":2.4,"sugar_g":8.4,"sodium_mg":933.0,"serving_size":"全4人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を4人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。 アンガス牛を一般的な80/20ひき肉で近似。バンズは1個60 gと計算しています。"},"keywords":["アンガスバーガー","自家製ハンバーガー","牛肉パティ"],"image_url":"/recetas/receta-de-hamburguesa-angus/portada.webp","gallery":[{"url":"/recetas/receta-de-hamburguesa-angus/portada.webp","alt":"自家製アンガスビーフバーガー: 完成した料理"}],"seo":{"title":"自家製アンガスビーフバーガー | Manual de Cocina","description":"150 gのアンガス牛パティにレタス、トマト、玉ねぎ、ケチャップ、マスタード。フライパンで中心71 °Cまで焼きます。","image_alt":"自家製アンガスビーフバーガー: 完成した料理","image_variants":["/recetas/receta-de-hamburguesa-angus/portada-1x1.webp","/recetas/receta-de-hamburguesa-angus/portada-4x3.webp","/recetas/receta-de-hamburguesa-angus/portada-16x9.webp"],"faq":[{"q":"アンガス牛は焼き時間が違いますか？","a":"厚さや鍋によります。ひき肉の中心は71 °Cまで加熱します。"},{"q":"なぜ焼きながら押さえないのですか？","a":"肉汁が出て乾きやすくなるためです。先に成形し、押さえず返します。"},{"q":"チーズを追加できますか？","a":"任意の変更として可能ですが、材料と栄養には含みません。"}]},"published":false,"editorial_status":"ready","content_html":"<p>肉150 gずつのバーガー4個。練りすぎず形を作って焼き、レタス、トマト、玉ねぎ、ケチャップ、マスタードを挟みます。チーズやベーコンは使いません。</p><p>アンガスは牛の品種を示すもので、鮮度や加熱温度の確認を代用しません。</p>"},{"id":"4dfdab9c-d67b-57ce-98ed-1b045459d084","recipe_group_id":"f38a2251-5235-4002-9ad6-7cea58219af6","slug":"hamburguer-angus-caseiro","public_path":"/pt/hamburguer-angus-caseiro","source_url":null,"language":"pt","title":"Hambúrguer Angus caseiro","excerpt":"Hambúrguer Angus de 150 g com alface, tomate, cebola, ketchup e mostarda. Faça na frigideira ou chapa até 71 °C no centro.","summary":"Quatro hambúrgueres com 150 g de carne cada, moldados sem amassar demais e feitos na chapa ou frigideira. Alface, tomate, cebola, ketchup e mostarda, sem queijo nem bacon.\n\nAngus indica a raça bovina e não substitui controle de frescor ou temperatura.","category":"Pratos principais","category_slug":"platos-principales","difficulty":"Média","course":"Prato principal","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":35,"servings":4,"ingredients":[{"name":"carne Angus moída, cerca de 20 % de gordura","amount":"600","unit":"g","group":"Hambúrgueres"},{"name":"sal","amount":"4","unit":"g","group":"Hambúrgueres"},{"name":"pimenta-do-reino","amount":"1","unit":"g","group":"Hambúrgueres"},{"name":"pães de hambúrguer","amount":"4","unit":"unidades","group":"Montagem"},{"name":"alface-romana","amount":"60","unit":"g","group":"Montagem"},{"name":"tomate","amount":"160","unit":"g","group":"Montagem"},{"name":"cebola","amount":"60","unit":"g","group":"Montagem"},{"name":"ketchup","amount":"40","unit":"g","group":"Molhos"},{"name":"mostarda preparada","amount":"20","unit":"g","group":"Molhos"}],"steps":[{"title":"Prepare os vegetais","content":"Lave e seque 60 g de alface. Corte 160 g de tomate em rodelas e 60 g de cebola em anéis finos. Refrigere em tábua distinta da carne crua.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-01.webp","image_alt":"Hambúrguer Angus caseiro: Prepare os vegetais"},{"title":"Divida a carne","content":"Divida 600 g de Angus em 4 porções de 150 g. Mantenha frio e manipule pouco; sem ovo nem farinha de rosca.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-02.webp","image_alt":"Hambúrguer Angus caseiro: Divida a carne"},{"title":"Modele os hambúrgueres","content":"Faça discos de cerca de 11 cm de diâmetro e 1,5 cm de espessura. Afunde levemente o centro para reduzir o abaulamento. Refrigere enquanto aquece a chapa.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-03.webp","image_alt":"Hambúrguer Angus caseiro: Modele os hambúrgueres"},{"title":"Aqueça e tempere","content":"Aqueça chapa ou frigideira pesada em fogo médio-alto por 3 minutos. Distribua 4 g de sal e 1 g de pimenta nos dois lados logo antes de cozinhar.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-04.webp","image_alt":"Hambúrguer Angus caseiro: Aqueça e tempere"},{"title":"Cozinhe até 71 °C","content":"Cozinhe cerca de 4–5 minutos por lado sem apertar. Introduza termômetro lateralmente até o centro e alcance pelo menos 71 °C; prolongue se necessário. Cor interna sozinha não basta.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-05.webp","image_alt":"Hambúrguer Angus caseiro: Cozinhe até 71 °C"},{"title":"Toste os pães","content":"Retire para prato limpo. Abra os 4 pães e toste lados cortados por 1–2 minutos sem queimar. Use utensílios sem contato com carne crua.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-06.webp","image_alt":"Hambúrguer Angus caseiro: Toste os pães"},{"title":"Monte os hambúrgueres","content":"Distribua 40 g de ketchup e 20 g de mostarda nas bases. Junte alface, hambúrguer cozido, tomate e cebola; feche com a parte superior.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-07.webp","image_alt":"Hambúrguer Angus caseiro: Monte os hambúrgueres"},{"title":"Sirva na hora","content":"Sirva um por pessoa imediatamente. Batatas e guarnições não entram nos ingredientes nem na nutrição.","image_url":"/recetas/receta-de-hamburguesa-angus/paso-08.webp","image_alt":"Hambúrguer Angus caseiro: Sirva na hora"}],"notes":"Nutrição com carne genérica 80/20, sem ficha específica Angus. Toda gordura inicial é contada, mesmo se parte ficar na chapa. Cozinhe carne crua refrigerada em 24 horas. Hambúrgueres cozidos sem montar duram 3 dias refrigerados; reaqueça a 74 °C.","nutrition":{"calories":578.0,"protein_g":32.6,"carbs_g":36.7,"fat_g":32.7,"saturated_fat_g":11.9,"fiber_g":2.4,"sugar_g":8.4,"sodium_mg":933.0,"serving_size":"1 de 4 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 4 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário. Angus aproximado por carne 80/20; pães calculados em 60 g por unidade."},"keywords":["hambúrguer Angus caseiro","hambúrguer 150 g","hambúrguer na chapa"],"image_url":"/recetas/receta-de-hamburguesa-angus/portada.webp","gallery":[{"url":"/recetas/receta-de-hamburguesa-angus/portada.webp","alt":"Hambúrguer Angus caseiro: prato pronto"}],"seo":{"title":"Hambúrguer Angus caseiro | Manual de Cocina","description":"Hambúrguer Angus de 150 g com alface, tomate, cebola, ketchup e mostarda. Faça na frigideira ou chapa até 71 °C no centro.","image_alt":"Hambúrguer Angus caseiro: prato pronto","image_variants":["/recetas/receta-de-hamburguesa-angus/portada-1x1.webp","/recetas/receta-de-hamburguesa-angus/portada-4x3.webp","/recetas/receta-de-hamburguesa-angus/portada-16x9.webp"],"faq":[{"q":"Angus exige outro tempo?","a":"Depende da espessura e chapa, não apenas da raça. Carne moída precisa de 71 °C no centro."},{"q":"Por que não apertar durante o cozimento?","a":"Expulsa sucos e pode ressecar. Molde antes e vire sem pressionar."},{"q":"Posso acrescentar queijo?","a":"Como variação opcional, não incluída nos ingredientes e nutrição."}]},"published":false,"editorial_status":"ready","content_html":"<p>Quatro hambúrgueres com 150 g de carne cada, moldados sem amassar demais e feitos na chapa ou frigideira. Alface, tomate, cebola, ketchup e mostarda, sem queijo nem bacon.</p><p>Angus indica a raça bovina e não substitui controle de frescor ou temperatura.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-de-hamburguesa-angus') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

-- receta-de-kare-raisu-japones
do $pub$
declare
  g constant uuid := '82aa2737-ada1-46ab-9ce9-8640b52d1f69';
  es_id constant uuid := '2b7d2480-476e-4f6a-8a1c-27cabfe08167';
  j constant jsonb := $j$[{"id":"2b7d2480-476e-4f6a-8a1c-27cabfe08167","recipe_group_id":"82aa2737-ada1-46ab-9ce9-8640b52d1f69","slug":"receta-de-kare-raisu-japones","public_path":"/receta-de-kare-raisu-japones","source_url":"https://manualdecocina.com/receta-de-kare-raisu-japones/","language":"es","title":"Kare raisu: curry japonés con arroz","excerpt":"Kare raisu casero con pollo, patata, zanahoria y arroz. Curry japonés suave con roux preparado en casa, sin pastillas comerciales.","summary":"Un curry espeso y suave servido con arroz blanco. En esta versión el roux se prepara con mantequilla, harina y curry en polvo; las verduras y el pollo se cuecen en agua antes de espesar la salsa.\n\nRinde 4 porciones. El arroz se cocina mientras hierve el guiso, por lo que los tiempos de ambas preparaciones se solapan.","category":"Platos principales","category_slug":"platos-principales","difficulty":"Media","course":"Plato principal","cuisine":"Japonesa","prep_time_minutes":25,"cook_time_minutes":45,"total_time_minutes":70,"servings":4,"ingredients":[{"name":"pechuga de pollo sin piel","amount":"500","unit":"g","group":"Guiso"},{"name":"cebolla","amount":"250","unit":"g","group":"Guiso"},{"name":"zanahoria","amount":"200","unit":"g","group":"Guiso"},{"name":"patata","amount":"350","unit":"g","group":"Guiso"},{"name":"ajo","amount":"6","unit":"g","group":"Guiso"},{"name":"jengibre fresco","amount":"10","unit":"g","group":"Guiso"},{"name":"aceite vegetal","amount":"15","unit":"g","group":"Guiso"},{"name":"agua","amount":"800","unit":"ml","group":"Guiso"},{"name":"salsa de soja","amount":"15","unit":"g","group":"Guiso"},{"name":"sal","amount":"3","unit":"g","group":"Guiso"},{"name":"mantequilla sin sal","amount":"30","unit":"g","group":"Roux"},{"name":"harina de trigo","amount":"30","unit":"g","group":"Roux"},{"name":"curry en polvo suave","amount":"12","unit":"g","group":"Roux"},{"name":"arroz blanco crudo","amount":"280","unit":"g","group":"Arroz"},{"name":"agua para el arroz","amount":"500","unit":"ml","group":"Arroz"}],"steps":[{"title":"Prepara los ingredientes","content":"Corta 500 g de pollo en dados de 3 cm. Corta 250 g de cebolla en tiras, 200 g de zanahoria en medias lunas y 350 g de patata en dados de 3 cm. Pica 6 g de ajo y 10 g de jengibre. Mantén separadas las tablas de carne y verduras.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-01.webp","image_alt":"Kare raisu: curry japonés con arroz: Prepara los ingredientes"},{"title":"Sofríe la cebolla","content":"Calienta 15 g de aceite en una cazuela y cocina la cebolla 8 minutos a fuego medio hasta ablandarla. Añade ajo y jengibre y remueve 1 minuto.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-02.webp","image_alt":"Kare raisu: curry japonés con arroz: Sofríe la cebolla"},{"title":"Añade pollo y verduras","content":"Agrega el pollo y cocina 3 minutos, girándolo. Incorpora zanahoria y patata, 800 ml de agua y 3 g de sal. Lleva a hervor suave, retira la espuma y tapa parcialmente.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-03.webp","image_alt":"Kare raisu: curry japonés con arroz: Añade pollo y verduras"},{"title":"Cuece el guiso","content":"Cocina 20–25 minutos a fuego bajo, hasta que patata y zanahoria estén tiernas. Comprueba que el centro de los dados de pollo alcanza 74 °C. Si falta líquido, añade agua caliente en pequeñas cantidades.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-04.webp","image_alt":"Kare raisu: curry japonés con arroz: Cuece el guiso"},{"title":"Cocina el arroz","content":"Mientras hierve el guiso, enjuaga 280 g de arroz y escúrrelo. Ponlo con 500 ml de agua en otra olla, lleva a ebullición y tapa. Cocina a fuego muy bajo 15 minutos, apaga y reposa 10 minutos sin destapar. Ajusta el agua si el envase del arroz lo requiere.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-05.webp","image_alt":"Kare raisu: curry japonés con arroz: Cocina el arroz"},{"title":"Prepara el roux","content":"Derrite 30 g de mantequilla en sartén a fuego bajo. Añade 30 g de harina y remueve 5 minutos hasta que esté beige. Añade 12 g de curry suave y cocina 30 segundos. Retira del fuego antes de que se queme.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-06.webp","image_alt":"Kare raisu: curry japonés con arroz: Prepara el roux"},{"title":"Espesa el curry","content":"Agrega al roux tres cucharones del líquido caliente del guiso, uno a uno, batiendo hasta alisar. Devuelve a la cazuela, añade 15 g de soja y cocina 5 minutos sin tapar, removiendo. Debe quedar espeso pero vertible.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-07.webp","image_alt":"Kare raisu: curry japonés con arroz: Espesa el curry"},{"title":"Sirve con arroz","content":"Separa los granos del arroz con una espátula. Reparte entre 4 platos y coloca el curry a un lado, con pollo y verduras distribuidos de manera similar.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-08.webp","image_alt":"Kare raisu: curry japonés con arroz: Sirve con arroz"}],"notes":"El curry en polvo varía entre marcas; elige uno suave y prueba antes de añadir más. La salsa espesa al enfriar: recalienta con agua hasta 74 °C. Refrigera curry y arroz por separado, en recipientes poco profundos, antes de 2 horas. Conserva el curry hasta 3 días y usa el arroz al día siguiente. No se incluye pasta de curry comercial ni caldo salado.","nutrition":{"calories":649.0,"protein_g":37.8,"carbs_g":90.4,"fat_g":14.4,"saturated_fat_g":5.0,"fiber_g":7.1,"sugar_g":6.0,"sodium_mg":602.0,"serving_size":"1 de 4 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 4 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma.  Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"pechuga de pollo sin piel","edible_grams":500,"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120.0,"saturated_fat_g":0.563,"sodium_mg":45.0,"protein_g":22.5,"sugar_g":0.0,"carbs_g":0.0,"fiber_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients"},{"ingredient":"cebolla","edible_grams":250,"fdc_id":170000,"fdc_description":"Onions, raw","per_100g":{"sugar_g":4.24,"fat_g":0.1,"carbs_g":9.34,"calories":40.0,"saturated_fat_g":0.042,"protein_g":1.1,"fiber_g":1.7,"sodium_mg":4.0},"source_url":"https://fdc.nal.usda.gov/food-details/170000/nutrients"},{"ingredient":"zanahoria","edible_grams":200,"fdc_id":170393,"fdc_description":"Carrots, raw","per_100g":{"saturated_fat_g":0.032,"sodium_mg":69.0,"protein_g":0.93,"fat_g":0.24,"sugar_g":4.74,"carbs_g":9.58,"calories":41.0,"fiber_g":2.8},"source_url":"https://fdc.nal.usda.gov/food-details/170393/nutrients"},{"ingredient":"patata","edible_grams":350,"fdc_id":170026,"fdc_description":"Potatoes, flesh and skin, raw","per_100g":{"fat_g":0.09,"calories":77.0,"sodium_mg":6.0,"saturated_fat_g":0.025,"protein_g":2.05,"fiber_g":2.1,"carbs_g":17.49,"sugar_g":0.82},"source_url":"https://fdc.nal.usda.gov/food-details/170026/nutrients"},{"ingredient":"ajo","edible_grams":6,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.06,"calories":149.0,"sugar_g":1.0,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17.0,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"jengibre fresco","edible_grams":10,"fdc_id":169231,"fdc_description":"Ginger root, raw","per_100g":{"sugar_g":1.7,"fat_g":0.75,"sodium_mg":13.0,"protein_g":1.82,"carbs_g":17.77,"calories":80.0,"fiber_g":2.0,"saturated_fat_g":0.203},"source_url":"https://fdc.nal.usda.gov/food-details/169231/nutrients"},{"ingredient":"aceite vegetal","edible_grams":15,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"fat_g":100.0,"saturated_fat_g":7.365,"protein_g":0.0,"carbs_g":0.0,"calories":884.0,"fiber_g":0.0,"sodium_mg":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"salsa de soja","edible_grams":15,"fdc_id":174277,"fdc_description":"Soy sauce made from soy and wheat (shoyu)","per_100g":{"fat_g":0.57,"carbs_g":4.93,"sugar_g":0.4,"protein_g":8.14,"sodium_mg":5493.0,"saturated_fat_g":0.073,"calories":53.0,"fiber_g":0.8},"source_url":"https://fdc.nal.usda.gov/food-details/174277/nutrients"},{"ingredient":"sal","edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0.0,"sodium_mg":38758.0,"saturated_fat_g":0.0,"protein_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"mantequilla sin sal","edible_grams":30,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717.0,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0.0,"sodium_mg":11.0},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"harina de trigo","edible_grams":30,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"fiber_g":2.7,"fat_g":0.98,"carbs_g":76.31,"calories":364.0,"protein_g":10.33,"sodium_mg":2.0,"saturated_fat_g":0.155,"sugar_g":0.27},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"curry en polvo suave","edible_grams":12,"fdc_id":170924,"fdc_description":"Spices, curry powder","per_100g":{"calories":325.0,"sodium_mg":52.0,"sugar_g":2.76,"saturated_fat_g":1.648,"fiber_g":53.2,"protein_g":14.29,"fat_g":14.01,"carbs_g":55.83},"source_url":"https://fdc.nal.usda.gov/food-details/170924/nutrients"},{"ingredient":"arroz blanco crudo","edible_grams":280,"fdc_id":168877,"fdc_description":"Rice, white, long-grain, regular, raw, enriched","per_100g":{"fat_g":0.66,"carbs_g":79.95,"calories":365.0,"protein_g":7.13,"fiber_g":1.3,"sodium_mg":5.0,"saturated_fat_g":0.18,"sugar_g":0.12},"source_url":"https://fdc.nal.usda.gov/food-details/168877/nutrients"}]},"keywords":["kare raisu casero","curry japonés con pollo","roux curry japonés"],"image_url":"/recetas/receta-de-kare-raisu-japones/portada.webp","gallery":[{"url":"/recetas/receta-de-kare-raisu-japones/portada.webp","alt":"Kare raisu: curry japonés con arroz: plato terminado"}],"seo":{"title":"Kare raisu: curry japonés con arroz | Manual de Cocina","description":"Kare raisu casero con pollo, patata, zanahoria y arroz. Curry japonés suave con roux preparado en casa, sin pastillas comerciales.","image_alt":"Kare raisu: curry japonés con arroz: plato terminado","image_variants":["/recetas/receta-de-kare-raisu-japones/portada-1x1.webp","/recetas/receta-de-kare-raisu-japones/portada-4x3.webp","/recetas/receta-de-kare-raisu-japones/portada-16x9.webp"],"faq":[{"q":"¿Puedo usar pastillas de curry japonés?","a":"Sí, pero sustituyen al roux y parte de la sazón. Sigue su envase; cantidades y nutrición de esta versión no serían equivalentes."},{"q":"¿Por qué se sirve arroz aparte?","a":"Permite combinar cada bocado con la cantidad de salsa deseada y evita que el arroz absorba toda la salsa."},{"q":"¿Qué hago si la salsa queda muy espesa?","a":"Añade agua caliente de 30 en 30 ml y remueve a fuego bajo hasta recuperar una textura vertible."}]},"published":false,"editorial_status":"ready","content_html":"<p>Un curry espeso y suave servido con arroz blanco. En esta versión el roux se prepara con mantequilla, harina y curry en polvo; las verduras y el pollo se cuecen en agua antes de espesar la salsa.</p><p>Rinde 4 porciones. El arroz se cocina mientras hierve el guiso, por lo que los tiempos de ambas preparaciones se solapan.</p>"},{"id":"6f86ce60-ad4e-5b5a-8acf-3fb2888cf7fd","recipe_group_id":"82aa2737-ada1-46ab-9ce9-8640b52d1f69","slug":"japanisches-curry-mit-reis","public_path":"/de/japanisches-curry-mit-reis","source_url":null,"language":"de","title":"Kare Raisu: japanisches Curry mit Reis","excerpt":"Japanisches Curry mit Hähnchen, Kartoffeln und Karotten, serviert mit Reis. Die milde Sauce wird mit einer selbst gemachten Curry-Mehlschwitze gebunden.","summary":"Mildes, dickes Curry mit weißem Reis. Butter, Mehl und Currypulver bilden die Mehlschwitze; Fleisch und Gemüse garen vorher in Wasser.\n\n4 Portionen. Der Reis kocht gleichzeitig mit dem Eintopf, deshalb überschneiden sich die Garzeiten.","category":"Hauptgerichte","category_slug":"platos-principales","difficulty":"Mittel","course":"Hauptgericht","cuisine":"Japanisch","prep_time_minutes":25,"cook_time_minutes":45,"total_time_minutes":70,"servings":4,"ingredients":[{"name":"Hähnchenbrust ohne Haut","amount":"500","unit":"g","group":"Eintopf"},{"name":"Zwiebel","amount":"250","unit":"g","group":"Eintopf"},{"name":"Karotte","amount":"200","unit":"g","group":"Eintopf"},{"name":"Kartoffel","amount":"350","unit":"g","group":"Eintopf"},{"name":"Knoblauch","amount":"6","unit":"g","group":"Eintopf"},{"name":"frischer Ingwer","amount":"10","unit":"g","group":"Eintopf"},{"name":"Pflanzenöl","amount":"15","unit":"g","group":"Eintopf"},{"name":"Wasser","amount":"800","unit":"ml","group":"Eintopf"},{"name":"Sojasauce","amount":"15","unit":"g","group":"Eintopf"},{"name":"Salz","amount":"3","unit":"g","group":"Eintopf"},{"name":"ungesalzene Butter","amount":"30","unit":"g","group":"Mehlschwitze"},{"name":"Weizenmehl","amount":"30","unit":"g","group":"Mehlschwitze"},{"name":"mildes Currypulver","amount":"12","unit":"g","group":"Mehlschwitze"},{"name":"ungekochter weißer Reis","amount":"280","unit":"g","group":"Reis"},{"name":"Wasser für den Reis","amount":"500","unit":"ml","group":"Reis"}],"steps":[{"title":"Zutaten vorbereiten","content":"500 g Hähnchen in 3-cm-Würfel schneiden, 250 g Zwiebel in Streifen, 200 g Karotte in Halbmonde und 350 g Kartoffel in 3-cm-Würfel. 6 g Knoblauch und 10 g Ingwer hacken. Getrennte Bretter nutzen.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-01.webp","image_alt":"Kare Raisu: japanisches Curry mit Reis: Zutaten vorbereiten"},{"title":"Zwiebel anschwitzen","content":"15 g Öl erhitzen und Zwiebel bei mittlerer Hitze 8 Minuten weich braten. Knoblauch und Ingwer 1 Minute mitrühren.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-02.webp","image_alt":"Kare Raisu: japanisches Curry mit Reis: Zwiebel anschwitzen"},{"title":"Hähnchen und Gemüse hinzufügen","content":"Hähnchen 3 Minuten unter Wenden anbraten. Karotte, Kartoffel, 800 ml Wasser und 3 g Salz zugeben. Sanft aufkochen, abschäumen und teilweise abdecken.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-03.webp","image_alt":"Kare Raisu: japanisches Curry mit Reis: Hähnchen und Gemüse hinzufügen"},{"title":"Eintopf garen","content":"20–25 Minuten bei kleiner Hitze garen, bis Gemüse weich ist und Hähnchen im Kern 74 °C erreicht. Bei Bedarf etwas heißes Wasser ergänzen.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-04.webp","image_alt":"Kare Raisu: japanisches Curry mit Reis: Eintopf garen"},{"title":"Reis kochen","content":"Währenddessen 280 g Reis spülen und abtropfen. Mit 500 ml Wasser aufkochen und abdecken. 15 Minuten bei sehr kleiner Hitze garen, dann ausgeschaltet 10 Minuten geschlossen ruhen. Wasser nach Packungsangaben anpassen.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-05.webp","image_alt":"Kare Raisu: japanisches Curry mit Reis: Reis kochen"},{"title":"Roux zubereiten","content":"30 g Butter bei kleiner Hitze schmelzen. 30 g Mehl 5 Minuten bis beige einrühren. 12 g mildes Curry 30 Sekunden mitgaren; vor dem Verbrennen vom Herd nehmen.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-06.webp","image_alt":"Kare Raisu: japanisches Curry mit Reis: Roux zubereiten"},{"title":"Curry andicken","content":"Drei Kellen heiße Eintopfflüssigkeit einzeln in die Mehlschwitze rühren, bis glatt. Zurückgeben, 15 g Sojasauce ergänzen und 5 Minuten offen unter Rühren garen: dick, aber gießbar.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-07.webp","image_alt":"Kare Raisu: japanisches Curry mit Reis: Curry andicken"},{"title":"Mit Reis servieren","content":"Reis auflockern und auf 4 Teller verteilen. Curry daneben geben und Fleisch sowie Gemüse gleichmäßig aufteilen.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-08.webp","image_alt":"Kare Raisu: japanisches Curry mit Reis: Mit Reis servieren"}],"notes":"Mildes Currypulver wählen und vor weiterer Zugabe probieren. Beim Abkühlen dickt die Sauce nach; mit Wasser auf 74 °C erwärmen. Curry und Reis getrennt in flachen Behältern innerhalb 2 Stunden kühlen. Curry bis 3 Tage lagern, Reis am Folgetag verwenden. Keine Fertig-Currypaste oder salzige Brühe enthalten.","nutrition":{"calories":649.0,"protein_g":37.8,"carbs_g":90.4,"fat_g":14.4,"saturated_fat_g":5.0,"fiber_g":7.1,"sugar_g":6.0,"sodium_mg":602.0,"serving_size":"1 von 4 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 4 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers."},"keywords":["japanisches Curry Reis","Kare raisu","Hähnchencurry Mehlschwitze"],"image_url":"/recetas/receta-de-kare-raisu-japones/portada.webp","gallery":[{"url":"/recetas/receta-de-kare-raisu-japones/portada.webp","alt":"Kare Raisu: japanisches Curry mit Reis: fertiges Gericht"}],"seo":{"title":"Kare Raisu: japanisches Curry mit Reis | Manual de Cocina","description":"Japanisches Curry mit Hähnchen, Kartoffeln und Karotten, serviert mit Reis. Die milde Sauce wird mit einer selbst gemachten Curry-Mehlschwitze gebunden.","image_alt":"Kare Raisu: japanisches Curry mit Reis: fertiges Gericht","image_variants":["/recetas/receta-de-kare-raisu-japones/portada-1x1.webp","/recetas/receta-de-kare-raisu-japones/portada-4x3.webp","/recetas/receta-de-kare-raisu-japones/portada-16x9.webp"],"faq":[{"q":"Gehen japanische Currywürfel?","a":"Sie ersetzen Mehlschwitze und einen Teil der Würzung. Packung beachten; Mengen und Nährwerte unterscheiden sich."},{"q":"Warum Reis separat?","a":"So lässt sich Sauce pro Bissen dosieren und der Reis saugt nicht alles auf."},{"q":"Was bei zu dicker Sauce?","a":"Heißes Wasser in 30-ml-Schritten bei kleiner Hitze einrühren, bis gießbar."}]},"published":false,"editorial_status":"ready","content_html":"<p>Mildes, dickes Curry mit weißem Reis. Butter, Mehl und Currypulver bilden die Mehlschwitze; Fleisch und Gemüse garen vorher in Wasser.</p><p>4 Portionen. Der Reis kocht gleichzeitig mit dem Eintopf, deshalb überschneiden sich die Garzeiten.</p>"},{"id":"7f6f869c-0135-5037-af91-f6d751991c62","recipe_group_id":"82aa2737-ada1-46ab-9ce9-8640b52d1f69","slug":"japanese-chicken-curry-rice","public_path":"/en/japanese-chicken-curry-rice","source_url":null,"language":"en","title":"Kare raisu: Japanese curry and rice","excerpt":"Japanese chicken curry with potatoes, carrots and rice. Make a mild curry roux from butter, flour and curry powder to thicken the sauce.","summary":"A thick, mild curry served with white rice. Make the roux with butter, flour and curry powder; simmer vegetables and chicken in water before thickening.\n\nMakes 4 servings. Rice cooks while the stew simmers, so their cooking times overlap.","category":"Main dishes","category_slug":"platos-principales","difficulty":"Medium","course":"Main course","cuisine":"Japanese","prep_time_minutes":25,"cook_time_minutes":45,"total_time_minutes":70,"servings":4,"ingredients":[{"name":"skinless chicken breast","amount":"500","unit":"g","group":"Stew"},{"name":"onion","amount":"250","unit":"g","group":"Stew"},{"name":"carrot","amount":"200","unit":"g","group":"Stew"},{"name":"potato","amount":"350","unit":"g","group":"Stew"},{"name":"garlic","amount":"6","unit":"g","group":"Stew"},{"name":"fresh ginger","amount":"10","unit":"g","group":"Stew"},{"name":"vegetable oil","amount":"15","unit":"g","group":"Stew"},{"name":"water","amount":"800","unit":"ml","group":"Stew"},{"name":"soy sauce","amount":"15","unit":"g","group":"Stew"},{"name":"salt","amount":"3","unit":"g","group":"Stew"},{"name":"unsalted butter","amount":"30","unit":"g","group":"Roux"},{"name":"wheat flour","amount":"30","unit":"g","group":"Roux"},{"name":"mild curry powder","amount":"12","unit":"g","group":"Roux"},{"name":"uncooked white rice","amount":"280","unit":"g","group":"Rice"},{"name":"water for rice","amount":"500","unit":"ml","group":"Rice"}],"steps":[{"title":"Prepare the ingredients","content":"Cut 500 g chicken into 3 cm cubes, 250 g onion into strips, 200 g carrot into half-moons and 350 g potato into 3 cm cubes. Chop 6 g garlic and 10 g ginger. Keep meat and vegetable boards separate.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-01.webp","image_alt":"Kare raisu: Japanese curry and rice: Prepare the ingredients"},{"title":"Sauté the onion","content":"Heat 15 g oil and soften onion over medium heat for 8 minutes. Stir in garlic and ginger for 1 minute.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-02.webp","image_alt":"Kare raisu: Japanese curry and rice: Sauté the onion"},{"title":"Add chicken and vegetables","content":"Add chicken and cook 3 minutes, turning. Add carrot, potato, 800 ml water and 3 g salt. Bring to a gentle simmer, skim foam and partly cover.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-03.webp","image_alt":"Kare raisu: Japanese curry and rice: Add chicken and vegetables"},{"title":"Simmer the stew","content":"Simmer over low heat 20–25 minutes until vegetables are tender and chicken reaches 74 °C inside. Add small amounts of hot water if needed.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-04.webp","image_alt":"Kare raisu: Japanese curry and rice: Simmer the stew"},{"title":"Cook the rice","content":"Meanwhile rinse and drain 280 g rice. Bring to the boil with 500 ml water and cover. Cook very gently 15 minutes, switch off and rest covered 10 minutes. Adjust water if the packet requires it.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-05.webp","image_alt":"Kare raisu: Japanese curry and rice: Cook the rice"},{"title":"Make the roux","content":"Melt 30 g butter over low heat. Stir in 30 g flour for 5 minutes until beige. Add 12 g mild curry powder for 30 seconds; remove before it burns.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-06.webp","image_alt":"Kare raisu: Japanese curry and rice: Make the roux"},{"title":"Thicken the curry","content":"Whisk three ladlefuls of hot stew liquid into the roux one at a time until smooth. Return to the stew, add 15 g soy sauce and cook uncovered 5 minutes, stirring. It should be thick but pourable.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-07.webp","image_alt":"Kare raisu: Japanese curry and rice: Thicken the curry"},{"title":"Serve with rice","content":"Fluff rice and divide among 4 plates. Place curry alongside, sharing chicken and vegetables evenly.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-08.webp","image_alt":"Kare raisu: Japanese curry and rice: Serve with rice"}],"notes":"Curry powders vary; choose mild and taste before adding more. Sauce thickens when cold; loosen with water and reheat to 74 °C. Refrigerate curry and rice separately in shallow containers within 2 hours. Keep curry up to 3 days and use rice the next day. Commercial curry paste and salted stock are not included.","nutrition":{"calories":649.0,"protein_g":37.8,"carbs_g":90.4,"fat_g":14.4,"saturated_fat_g":5.0,"fiber_g":7.1,"sugar_g":6.0,"sodium_mg":602.0,"serving_size":"1 of 4 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 4 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation."},"keywords":["Japanese chicken curry rice","kare raisu","homemade curry roux"],"image_url":"/recetas/receta-de-kare-raisu-japones/portada.webp","gallery":[{"url":"/recetas/receta-de-kare-raisu-japones/portada.webp","alt":"Kare raisu: Japanese curry and rice: finished dish"}],"seo":{"title":"Kare raisu: Japanese curry and rice | Manual de Cocina","description":"Japanese chicken curry with potatoes, carrots and rice. Make a mild curry roux from butter, flour and curry powder to thicken the sauce.","image_alt":"Kare raisu: Japanese curry and rice: finished dish","image_variants":["/recetas/receta-de-kare-raisu-japones/portada-1x1.webp","/recetas/receta-de-kare-raisu-japones/portada-4x3.webp","/recetas/receta-de-kare-raisu-japones/portada-16x9.webp"],"faq":[{"q":"Can I use Japanese curry blocks?","a":"They replace the roux and some seasoning. Follow the packet; quantities and nutrition will differ."},{"q":"Why serve rice separately?","a":"It lets you choose the sauce per bite and prevents rice absorbing it all."},{"q":"What if the sauce is too thick?","a":"Stir in hot water in 30 ml increments over low heat until pourable."}]},"published":false,"editorial_status":"ready","content_html":"<p>A thick, mild curry served with white rice. Make the roux with butter, flour and curry powder; simmer vegetables and chicken in water before thickening.</p><p>Makes 4 servings. Rice cooks while the stew simmers, so their cooking times overlap.</p>"},{"id":"c3a80907-0008-5b0a-bafb-fe9989865d35","recipe_group_id":"82aa2737-ada1-46ab-9ce9-8640b52d1f69","slug":"curry-japonais-poulet-riz","public_path":"/fr/curry-japonais-poulet-riz","source_url":null,"language":"fr","title":"Kare raisu : curry japonais et riz","excerpt":"Curry japonais au poulet, pommes de terre et carottes, avec riz. Un roux maison au beurre, farine et curry doux épaissit la sauce.","summary":"Curry doux et épais servi avec du riz blanc. Le roux est fait de beurre, farine et curry; poulet et légumes mijotent dans l’eau avant d’épaissir.\n\n4 portions. Le riz cuit pendant le mijotage: les durées se chevauchent.","category":"Plats principaux","category_slug":"platos-principales","difficulty":"Moyenne","course":"Plat principal","cuisine":"Japonaise","prep_time_minutes":25,"cook_time_minutes":45,"total_time_minutes":70,"servings":4,"ingredients":[{"name":"blanc de poulet sans peau","amount":"500","unit":"g","group":"Ragoût"},{"name":"oignon","amount":"250","unit":"g","group":"Ragoût"},{"name":"carotte","amount":"200","unit":"g","group":"Ragoût"},{"name":"pomme de terre","amount":"350","unit":"g","group":"Ragoût"},{"name":"ail","amount":"6","unit":"g","group":"Ragoût"},{"name":"gingembre frais","amount":"10","unit":"g","group":"Ragoût"},{"name":"huile végétale","amount":"15","unit":"g","group":"Ragoût"},{"name":"eau","amount":"800","unit":"ml","group":"Ragoût"},{"name":"sauce soja","amount":"15","unit":"g","group":"Ragoût"},{"name":"sel","amount":"3","unit":"g","group":"Ragoût"},{"name":"beurre doux","amount":"30","unit":"g","group":"Roux"},{"name":"farine de blé","amount":"30","unit":"g","group":"Roux"},{"name":"curry doux en poudre","amount":"12","unit":"g","group":"Roux"},{"name":"riz blanc cru","amount":"280","unit":"g","group":"Riz"},{"name":"eau pour le riz","amount":"500","unit":"ml","group":"Riz"}],"steps":[{"title":"Préparer les ingrédients","content":"Coupez 500 g de poulet en dés de 3 cm, 250 g d’oignon en lanières, 200 g de carotte en demi-rondelles et 350 g de pomme de terre en dés de 3 cm. Hachez 6 g d’ail et 10 g de gingembre. Séparez les planches.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-01.webp","image_alt":"Kare raisu : curry japonais et riz: Préparer les ingrédients"},{"title":"Faire revenir l’oignon","content":"Chauffez 15 g d’huile et faites fondre l’oignon 8 minutes à feu moyen. Ajoutez ail et gingembre 1 minute.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-02.webp","image_alt":"Kare raisu : curry japonais et riz: Faire revenir l’oignon"},{"title":"Ajouter poulet et légumes","content":"Cuisez le poulet 3 minutes en tournant. Ajoutez carotte, pomme de terre, 800 ml d’eau et 3 g de sel. Faites frémir, écumez et couvrez partiellement.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-03.webp","image_alt":"Kare raisu : curry japonais et riz: Ajouter poulet et légumes"},{"title":"Cuire le ragoût","content":"Mijotez 20–25 minutes à feu doux jusqu’aux légumes tendres et poulet à 74 °C au centre. Complétez d’un peu d’eau chaude si nécessaire.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-04.webp","image_alt":"Kare raisu : curry japonais et riz: Cuire le ragoût"},{"title":"Cuire le riz","content":"Pendant ce temps, rincez 280 g de riz, égouttez et portez à ébullition avec 500 ml d’eau. Couvrez, cuisez très doucement 15 minutes puis reposez hors feu 10 minutes sans ouvrir. Adaptez l’eau à l’emballage.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-05.webp","image_alt":"Kare raisu : curry japonais et riz: Cuire le riz"},{"title":"Préparer le roux","content":"Fondez 30 g de beurre à feu doux. Remuez 30 g de farine 5 minutes jusqu’à beige, puis 12 g de curry 30 secondes. Retirez avant de brûler.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-06.webp","image_alt":"Kare raisu : curry japonais et riz: Préparer le roux"},{"title":"Épaissir le curry","content":"Incorporez au roux trois louches de liquide chaud, une à une, en fouettant. Remettez au ragoût avec 15 g de soja; cuisez à découvert 5 minutes en remuant, épais mais versable.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-07.webp","image_alt":"Kare raisu : curry japonais et riz: Épaissir le curry"},{"title":"Servir avec le riz","content":"Aérez le riz, répartissez sur 4 assiettes et placez le curry à côté en partageant poulet et légumes.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-08.webp","image_alt":"Kare raisu : curry japonais et riz: Servir avec le riz"}],"notes":"Choisissez un curry doux, goûtez avant d’en ajouter. La sauce épaissit à froid: réchauffez à 74 °C avec de l’eau. Réfrigérez riz et curry séparément en récipients bas avant 2 heures. Curry jusqu’à 3 jours, riz le lendemain. Pas de pâte prête ni de bouillon salé inclus.","nutrition":{"calories":649.0,"protein_g":37.8,"carbs_g":90.4,"fat_g":14.4,"saturated_fat_g":5.0,"fiber_g":7.1,"sugar_g":6.0,"sodium_mg":602.0,"serving_size":"1 des 4 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 4 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire."},"keywords":["curry japonais poulet","kare raisu","roux curry maison"],"image_url":"/recetas/receta-de-kare-raisu-japones/portada.webp","gallery":[{"url":"/recetas/receta-de-kare-raisu-japones/portada.webp","alt":"Kare raisu : curry japonais et riz: plat terminé"}],"seo":{"title":"Kare raisu : curry japonais et riz | Manual de Cocina","description":"Curry japonais au poulet, pommes de terre et carottes, avec riz. Un roux maison au beurre, farine et curry doux épaissit la sauce.","image_alt":"Kare raisu : curry japonais et riz: plat terminé","image_variants":["/recetas/receta-de-kare-raisu-japones/portada-1x1.webp","/recetas/receta-de-kare-raisu-japones/portada-4x3.webp","/recetas/receta-de-kare-raisu-japones/portada-16x9.webp"],"faq":[{"q":"Peut-on utiliser des blocs de curry japonais?","a":"Ils remplacent le roux et une partie de l’assaisonnement. Suivez l’emballage; quantités et nutrition diffèrent."},{"q":"Pourquoi le riz à part?","a":"Cela permet de doser la sauce et évite qu’il l’absorbe entièrement."},{"q":"Sauce trop épaisse?","a":"Ajoutez de l’eau chaude par 30 ml en remuant à feu doux."}]},"published":false,"editorial_status":"ready","content_html":"<p>Curry doux et épais servi avec du riz blanc. Le roux est fait de beurre, farine et curry; poulet et légumes mijotent dans l’eau avant d’épaissir.</p><p>4 portions. Le riz cuit pendant le mijotage: les durées se chevauchent.</p>"},{"id":"315b31d0-6ee4-5b57-a211-3fc095d04d6c","recipe_group_id":"82aa2737-ada1-46ab-9ce9-8640b52d1f69","slug":"curry-giapponese-pollo-riso","public_path":"/it/curry-giapponese-pollo-riso","source_url":null,"language":"it","title":"Kare raisu: curry giapponese con riso","excerpt":"Curry giapponese di pollo con patate, carote e riso. Addensa la salsa con un roux casalingo di burro, farina e curry delicato.","summary":"Curry denso e delicato servito con riso bianco. Il roux usa burro, farina e curry; pollo e verdure cuociono in acqua prima di addensare.\n\n4 porzioni. Il riso cuoce mentre il curry sobbolle: i tempi si sovrappongono.","category":"Secondi piatti","category_slug":"platos-principales","difficulty":"Media","course":"Piatto principale","cuisine":"Giapponese","prep_time_minutes":25,"cook_time_minutes":45,"total_time_minutes":70,"servings":4,"ingredients":[{"name":"petto di pollo senza pelle","amount":"500","unit":"g","group":"Stufato"},{"name":"cipolla","amount":"250","unit":"g","group":"Stufato"},{"name":"carota","amount":"200","unit":"g","group":"Stufato"},{"name":"patata","amount":"350","unit":"g","group":"Stufato"},{"name":"aglio","amount":"6","unit":"g","group":"Stufato"},{"name":"zenzero fresco","amount":"10","unit":"g","group":"Stufato"},{"name":"olio vegetale","amount":"15","unit":"g","group":"Stufato"},{"name":"acqua","amount":"800","unit":"ml","group":"Stufato"},{"name":"salsa di soia","amount":"15","unit":"g","group":"Stufato"},{"name":"sale","amount":"3","unit":"g","group":"Stufato"},{"name":"burro non salato","amount":"30","unit":"g","group":"Roux"},{"name":"farina di frumento","amount":"30","unit":"g","group":"Roux"},{"name":"curry delicato in polvere","amount":"12","unit":"g","group":"Roux"},{"name":"riso bianco crudo","amount":"280","unit":"g","group":"Riso"},{"name":"acqua per il riso","amount":"500","unit":"ml","group":"Riso"}],"steps":[{"title":"Preparare gli ingredienti","content":"Taglia 500 g di pollo a dadi da 3 cm, 250 g di cipolla a strisce, 200 g di carota a mezze lune e 350 g di patata a dadi da 3 cm. Trita 6 g di aglio e 10 g di zenzero. Separa i taglieri.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-01.webp","image_alt":"Kare raisu: curry giapponese con riso: Preparare gli ingredienti"},{"title":"Rosolare la cipolla","content":"Scalda 15 g di olio e ammorbidisci cipolla a fuoco medio 8 minuti. Aggiungi aglio e zenzero per 1 minuto.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-02.webp","image_alt":"Kare raisu: curry giapponese con riso: Rosolare la cipolla"},{"title":"Aggiungere pollo e verdure","content":"Cuoci pollo 3 minuti girando. Unisci carota, patata, 800 ml d’acqua e 3 g di sale. Porta a lieve bollore, schiuma e copri parzialmente.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-03.webp","image_alt":"Kare raisu: curry giapponese con riso: Aggiungere pollo e verdure"},{"title":"Cuocere lo stufato","content":"Cuoci a fuoco basso 20–25 minuti finché verdure tenere e pollo a 74 °C al centro. Se serve, aggiungi poca acqua calda.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-04.webp","image_alt":"Kare raisu: curry giapponese con riso: Cuocere lo stufato"},{"title":"Cuocere il riso","content":"Intanto sciacqua e scola 280 g di riso. Porta a bollore con 500 ml d’acqua, copri, cuoci molto piano 15 minuti e riposa spento 10 minuti senza aprire. Adegua l’acqua alla confezione.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-05.webp","image_alt":"Kare raisu: curry giapponese con riso: Cuocere il riso"},{"title":"Preparare il roux","content":"Sciogli 30 g di burro a fuoco basso. Mescola 30 g di farina 5 minuti fino a beige, poi 12 g di curry per 30 secondi. Togli prima che bruci.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-06.webp","image_alt":"Kare raisu: curry giapponese con riso: Preparare il roux"},{"title":"Addensare il curry","content":"Mescola nel roux tre mestoli di liquido caldo, uno per volta, fino a liscio. Rimetti nel curry, aggiungi 15 g di soia e cuoci scoperto 5 minuti mescolando: denso ma versabile.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-07.webp","image_alt":"Kare raisu: curry giapponese con riso: Addensare il curry"},{"title":"Servire con il riso","content":"Sgrana il riso e dividi in 4 piatti, con curry a lato e pollo e verdure distribuiti equamente.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-08.webp","image_alt":"Kare raisu: curry giapponese con riso: Servire con il riso"}],"notes":"Scegli curry delicato e assaggia prima di aggiungere altro. Da freddo addensa: riscalda con acqua a 74 °C. Refrigera separatamente in contenitori bassi entro 2 ore. Curry fino a 3 giorni, riso il giorno dopo. Pasta pronta e brodo salato esclusi.","nutrition":{"calories":649.0,"protein_g":37.8,"carbs_g":90.4,"fat_g":14.4,"saturated_fat_g":5.0,"fiber_g":7.1,"sugar_g":6.0,"sodium_mg":602.0,"serving_size":"1 delle 4 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 4 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario."},"keywords":["curry giapponese pollo","kare raisu","roux al curry"],"image_url":"/recetas/receta-de-kare-raisu-japones/portada.webp","gallery":[{"url":"/recetas/receta-de-kare-raisu-japones/portada.webp","alt":"Kare raisu: curry giapponese con riso: piatto pronto"}],"seo":{"title":"Kare raisu: curry giapponese con riso | Manual de Cocina","description":"Curry giapponese di pollo con patate, carote e riso. Addensa la salsa con un roux casalingo di burro, farina e curry delicato.","image_alt":"Kare raisu: curry giapponese con riso: piatto pronto","image_variants":["/recetas/receta-de-kare-raisu-japones/portada-1x1.webp","/recetas/receta-de-kare-raisu-japones/portada-4x3.webp","/recetas/receta-de-kare-raisu-japones/portada-16x9.webp"],"faq":[{"q":"Posso usare dadi di curry giapponese?","a":"Sostituiscono roux e parte del condimento. Segui la confezione; quantità e nutrizione diverse."},{"q":"Perché riso separato?","a":"Permette di dosare la salsa evitando che venga tutta assorbita."},{"q":"Se la salsa è troppo densa?","a":"Aggiungi acqua calda in porzioni da 30 ml a fuoco basso."}]},"published":false,"editorial_status":"ready","content_html":"<p>Curry denso e delicato servito con riso bianco. Il roux usa burro, farina e curry; pollo e verdure cuociono in acqua prima di addensare.</p><p>4 porzioni. Il riso cuoce mentre il curry sobbolle: i tempi si sovrappongono.</p>"},{"id":"d03d4c52-5fe6-5512-8fe8-2b2fd68d1964","recipe_group_id":"82aa2737-ada1-46ab-9ce9-8640b52d1f69","slug":"ルーから作るチキンカレーライス","public_path":"/ja/ルーから作るチキンカレーライス","source_url":null,"language":"ja","title":"チキンカレーライス","excerpt":"鶏肉、じゃがいも、にんじんのカレーライス。バター、小麦粉、カレー粉で穏やかな自家製ルーを作ります。","summary":"白米に添えるとろみのある穏やかなカレー。野菜と鶏肉を水で煮てから、バター、小麦粉、カレー粉のルーでとろみを付けます。\n\n4人分。煮込み中に米を炊くため、両方の加熱時間は重なります。","category":"主菜","category_slug":"platos-principales","difficulty":"普通","course":"主菜","cuisine":"日本料理","prep_time_minutes":25,"cook_time_minutes":45,"total_time_minutes":70,"servings":4,"ingredients":[{"name":"皮なし鶏胸肉","amount":"500","unit":"g","group":"煮込み"},{"name":"玉ねぎ","amount":"250","unit":"g","group":"煮込み"},{"name":"にんじん","amount":"200","unit":"g","group":"煮込み"},{"name":"じゃがいも","amount":"350","unit":"g","group":"煮込み"},{"name":"にんにく","amount":"6","unit":"g","group":"煮込み"},{"name":"生しょうが","amount":"10","unit":"g","group":"煮込み"},{"name":"植物油","amount":"15","unit":"g","group":"煮込み"},{"name":"水","amount":"800","unit":"ml","group":"煮込み"},{"name":"しょうゆ","amount":"15","unit":"g","group":"煮込み"},{"name":"塩","amount":"3","unit":"g","group":"煮込み"},{"name":"無塩バター","amount":"30","unit":"g","group":"ルー"},{"name":"小麦粉","amount":"30","unit":"g","group":"ルー"},{"name":"マイルドなカレー粉","amount":"12","unit":"g","group":"ルー"},{"name":"生の白米","amount":"280","unit":"g","group":"ご飯"},{"name":"炊飯用の水","amount":"500","unit":"ml","group":"ご飯"}],"steps":[{"title":"材料を用意する","content":"鶏肉500 gを3 cm角、玉ねぎ250 gを細切り、にんじん200 gを半月、じゃがいも350 gを3 cm角に。にんにく6 gとしょうが10 gを刻み、生肉用と野菜用のまな板を分けます。","image_url":"/recetas/receta-de-kare-raisu-japones/paso-01.webp","image_alt":"チキンカレーライス: 材料を用意する"},{"title":"玉ねぎを炒める","content":"油15 gを熱し、玉ねぎを中火で8分炒めて柔らかくします。にんにくとしょうがを加え1分混ぜます。","image_url":"/recetas/receta-de-kare-raisu-japones/paso-02.webp","image_alt":"チキンカレーライス: 玉ねぎを炒める"},{"title":"鶏肉と野菜を加える","content":"鶏肉を返しながら3分焼き、にんじん、じゃがいも、水800 ml、塩3 gを加えます。穏やかに沸かし、アクを取り、ふたを少し開けます。","image_url":"/recetas/receta-de-kare-raisu-japones/paso-03.webp","image_alt":"チキンカレーライス: 鶏肉と野菜を加える"},{"title":"煮込む","content":"弱火で20–25分、野菜が柔らかくなるまで煮ます。鶏肉の中心74 °Cを確認し、水不足なら少量の湯を足します。","image_url":"/recetas/receta-de-kare-raisu-japones/paso-04.webp","image_alt":"チキンカレーライス: 煮込む"},{"title":"ご飯を炊く","content":"その間に米280 gを洗い、水を切ります。水500 mlで沸かしてふたをし、ごく弱火15分、火を止めて開けず10分蒸らします。製品表示に合わせ水量は調整します。","image_url":"/recetas/receta-de-kare-raisu-japones/paso-05.webp","image_alt":"チキンカレーライス: ご飯を炊く"},{"title":"ルーを作る","content":"バター30 gを弱火で溶かし、小麦粉30 gを混ぜて5分、ベージュ色にします。カレー粉12 gを加え30秒混ぜ、焦げる前に火を止めます。","image_url":"/recetas/receta-de-kare-raisu-japones/paso-06.webp","image_alt":"チキンカレーライス: ルーを作る"},{"title":"カレーにとろみを付ける","content":"熱い煮汁をお玉3杯、1杯ずつルーへ混ぜて滑らかにします。鍋へ戻し、しょうゆ15 gを加え、ふたなしで5分混ぜて煮ます。濃いが流れる状態にします。","image_url":"/recetas/receta-de-kare-raisu-japones/paso-07.webp","image_alt":"チキンカレーライス: カレーにとろみを付ける"},{"title":"ご飯と盛り付ける","content":"米をほぐして4皿に分けます。横にカレーを盛り、肉と野菜を同程度ずつ配ります。","image_url":"/recetas/receta-de-kare-raisu-japones/paso-08.webp","image_alt":"チキンカレーライス: ご飯と盛り付ける"}],"notes":"マイルドなカレー粉を選び、追加は味見して判断します。冷えると濃くなるため水を足し74 °Cまで再加熱。カレーと米は別の浅い容器で2時間以内に冷蔵。カレーは最長3日、米は翌日に使います。市販カレーペーストや塩味スープは含みません。","nutrition":{"calories":649.0,"protein_g":37.8,"carbs_g":90.4,"fat_g":14.4,"saturated_fat_g":5.0,"fiber_g":7.1,"sugar_g":6.0,"sodium_mg":602.0,"serving_size":"全4人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を4人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。"},"keywords":["手作りカレールー","チキンカレーライス","カレー粉から作るカレー"],"image_url":"/recetas/receta-de-kare-raisu-japones/portada.webp","gallery":[{"url":"/recetas/receta-de-kare-raisu-japones/portada.webp","alt":"チキンカレーライス: 完成した料理"}],"seo":{"title":"チキンカレーライス | Manual de Cocina","description":"鶏肉、じゃがいも、にんじんのカレーライス。バター、小麦粉、カレー粉で穏やかな自家製ルーを作ります。","image_alt":"チキンカレーライス: 完成した料理","image_variants":["/recetas/receta-de-kare-raisu-japones/portada-1x1.webp","/recetas/receta-de-kare-raisu-japones/portada-4x3.webp","/recetas/receta-de-kare-raisu-japones/portada-16x9.webp"],"faq":[{"q":"市販のカレールーを使えますか？","a":"ルーと調味の一部を置き換えます。表示に従い、分量・栄養はこの配合と異なります。"},{"q":"米を別に盛る理由は？","a":"一口ごとのソース量を調整でき、米が全部吸うのを防ぎます。"},{"q":"濃すぎるときは？","a":"湯を30 mlずつ加え、弱火で混ぜて流れる濃度へ調整します。"}]},"published":false,"editorial_status":"ready","content_html":"<p>白米に添えるとろみのある穏やかなカレー。野菜と鶏肉を水で煮てから、バター、小麦粉、カレー粉のルーでとろみを付けます。</p><p>4人分。煮込み中に米を炊くため、両方の加熱時間は重なります。</p>"},{"id":"fc023dd4-6417-5c04-aca8-6fd9d778264e","recipe_group_id":"82aa2737-ada1-46ab-9ce9-8640b52d1f69","slug":"curry-japones-frango-arroz","public_path":"/pt/curry-japones-frango-arroz","source_url":null,"language":"pt","title":"Kare raisu: curry japonês com arroz","excerpt":"Curry japonês de frango com batata, cenoura e arroz. Prepare o roux caseiro de manteiga, farinha e curry suave para engrossar o molho.","summary":"Curry espesso e suave servido com arroz branco. O roux leva manteiga, farinha e curry; frango e legumes cozinham em água antes de engrossar.\n\n4 porções. O arroz cozinha enquanto o ensopado ferve, sobrepondo os tempos.","category":"Pratos principais","category_slug":"platos-principales","difficulty":"Média","course":"Prato principal","cuisine":"Japonesa","prep_time_minutes":25,"cook_time_minutes":45,"total_time_minutes":70,"servings":4,"ingredients":[{"name":"peito de frango sem pele","amount":"500","unit":"g","group":"Ensopado"},{"name":"cebola","amount":"250","unit":"g","group":"Ensopado"},{"name":"cenoura","amount":"200","unit":"g","group":"Ensopado"},{"name":"batata","amount":"350","unit":"g","group":"Ensopado"},{"name":"alho","amount":"6","unit":"g","group":"Ensopado"},{"name":"gengibre fresco","amount":"10","unit":"g","group":"Ensopado"},{"name":"óleo vegetal","amount":"15","unit":"g","group":"Ensopado"},{"name":"água","amount":"800","unit":"ml","group":"Ensopado"},{"name":"molho de soja","amount":"15","unit":"g","group":"Ensopado"},{"name":"sal","amount":"3","unit":"g","group":"Ensopado"},{"name":"manteiga sem sal","amount":"30","unit":"g","group":"Roux"},{"name":"farinha de trigo","amount":"30","unit":"g","group":"Roux"},{"name":"curry suave em pó","amount":"12","unit":"g","group":"Roux"},{"name":"arroz branco cru","amount":"280","unit":"g","group":"Arroz"},{"name":"água para o arroz","amount":"500","unit":"ml","group":"Arroz"}],"steps":[{"title":"Prepare os ingredientes","content":"Corte 500 g de frango em cubos de 3 cm, 250 g de cebola em tiras, 200 g de cenoura em meias-luas e 350 g de batata em cubos de 3 cm. Pique 6 g de alho e 10 g de gengibre. Separe tábuas.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-01.webp","image_alt":"Kare raisu: curry japonês com arroz: Prepare os ingredientes"},{"title":"Refogue a cebola","content":"Aqueça 15 g de óleo e amoleça cebola em fogo médio por 8 minutos. Junte alho e gengibre por 1 minuto.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-02.webp","image_alt":"Kare raisu: curry japonês com arroz: Refogue a cebola"},{"title":"Acrescente frango e vegetais","content":"Cozinhe frango por 3 minutos, virando. Acrescente cenoura, batata, 800 ml de água e 3 g de sal. Ferva suavemente, retire espuma e tampe parcialmente.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-03.webp","image_alt":"Kare raisu: curry japonês com arroz: Acrescente frango e vegetais"},{"title":"Cozinhe o ensopado","content":"Cozinhe em fogo baixo 20–25 minutos até legumes macios e frango a 74 °C no centro. Complete com pouca água quente se necessário.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-04.webp","image_alt":"Kare raisu: curry japonês com arroz: Cozinhe o ensopado"},{"title":"Cozinhe o arroz","content":"Enquanto isso, lave e escorra 280 g de arroz. Ferva com 500 ml de água, tampe, cozinhe em fogo muito baixo 15 minutos e descanse desligado 10 minutos sem abrir. Ajuste água ao pacote.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-05.webp","image_alt":"Kare raisu: curry japonês com arroz: Cozinhe o arroz"},{"title":"Prepare o roux","content":"Derreta 30 g de manteiga em fogo baixo. Misture 30 g de farinha por 5 minutos até bege; junte 12 g de curry por 30 segundos. Retire antes de queimar.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-06.webp","image_alt":"Kare raisu: curry japonês com arroz: Prepare o roux"},{"title":"Engrosse o curry","content":"Misture três conchas de líquido quente ao roux, uma por vez, até alisar. Volte à panela com 15 g de soja e cozinhe destampado 5 minutos mexendo: espesso, mas fluido.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-07.webp","image_alt":"Kare raisu: curry japonês com arroz: Engrosse o curry"},{"title":"Sirva com arroz","content":"Solte os grãos e distribua arroz em 4 pratos. Ponha curry ao lado, repartindo frango e legumes igualmente.","image_url":"/recetas/receta-de-kare-raisu-japones/paso-08.webp","image_alt":"Kare raisu: curry japonês com arroz: Sirva com arroz"}],"notes":"Escolha curry suave e prove antes de acrescentar. O molho engrossa frio: reaqueça com água até 74 °C. Refrigere curry e arroz separados em recipientes rasos antes de 2 horas. Curry até 3 dias; arroz no dia seguinte. Pasta pronta e caldo salgado não incluídos.","nutrition":{"calories":649.0,"protein_g":37.8,"carbs_g":90.4,"fat_g":14.4,"saturated_fat_g":5.0,"fiber_g":7.1,"sugar_g":6.0,"sodium_mg":602.0,"serving_size":"1 de 4 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 4 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário."},"keywords":["curry japonês frango","kare raisu","roux de curry caseiro"],"image_url":"/recetas/receta-de-kare-raisu-japones/portada.webp","gallery":[{"url":"/recetas/receta-de-kare-raisu-japones/portada.webp","alt":"Kare raisu: curry japonês com arroz: prato pronto"}],"seo":{"title":"Kare raisu: curry japonês com arroz | Manual de Cocina","description":"Curry japonês de frango com batata, cenoura e arroz. Prepare o roux caseiro de manteiga, farinha e curry suave para engrossar o molho.","image_alt":"Kare raisu: curry japonês com arroz: prato pronto","image_variants":["/recetas/receta-de-kare-raisu-japones/portada-1x1.webp","/recetas/receta-de-kare-raisu-japones/portada-4x3.webp","/recetas/receta-de-kare-raisu-japones/portada-16x9.webp"],"faq":[{"q":"Posso usar tabletes de curry japonês?","a":"Substituem roux e parte do tempero. Siga o pacote; quantidades e nutrição diferem."},{"q":"Por que arroz separado?","a":"Permite dosar o molho e evita que o arroz absorva tudo."},{"q":"Molho muito grosso?","a":"Junte água quente de 30 em 30 ml mexendo em fogo baixo."}]},"published":false,"editorial_status":"ready","content_html":"<p>Curry espesso e suave servido com arroz branco. O roux leva manteiga, farinha e curry; frango e legumes cozinham em água antes de engrossar.</p><p>4 porções. O arroz cozinha enquanto o ensopado ferve, sobrepondo os tempos.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-de-kare-raisu-japones') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

-- receta-de-risotto-de-mar
do $pub$
declare
  g constant uuid := '734c10d3-e697-4918-8a98-d848105cabcf';
  es_id constant uuid := '75b02c1a-ea60-4f2b-9c2c-dc31daf7a55e';
  j constant jsonb := $j$[{"id":"75b02c1a-ea60-4f2b-9c2c-dc31daf7a55e","recipe_group_id":"734c10d3-e697-4918-8a98-d848105cabcf","slug":"receta-de-risotto-de-mar","public_path":"/receta-de-risotto-de-mar","source_url":"https://manualdecocina.com/receta-de-risotto-de-mar/","language":"es","title":"Risotto de mar con gambas y calamar","excerpt":"Risotto de mar con gambas y calamar, arroz cremoso y caldo añadido poco a poco. Cuatro porciones, sin nata ni queso en esta versión.","summary":"Un risotto de marisco con arroz de grano medio, gambas y calamar. La cremosidad procede del almidón del arroz y de una pequeña cantidad de mantequilla al final, sin nata.\n\nRinde 4 porciones y se sirve enseguida. Usa marisco limpio, sin cáscaras ni vísceras, y caldo sin sal añadida para poder ajustar la sazón.","category":"Platos principales","category_slug":"platos-principales","difficulty":"Media","course":"Plato principal","cuisine":"Italiana","prep_time_minutes":20,"cook_time_minutes":35,"total_time_minutes":55,"servings":4,"ingredients":[{"name":"arroz para risotto, crudo","amount":"320","unit":"g","group":"Arroz"},{"name":"gambas crudas peladas","amount":"300","unit":"g","group":"Marisco"},{"name":"calamar limpio","amount":"250","unit":"g","group":"Marisco"},{"name":"cebolla","amount":"120","unit":"g","group":"Sofrito"},{"name":"ajo","amount":"6","unit":"g","group":"Sofrito"},{"name":"aceite vegetal","amount":"20","unit":"g","group":"Sofrito"},{"name":"caldo de pescado sin sal añadida","amount":"1100","unit":"ml","group":"Cocción"},{"name":"mantequilla sin sal","amount":"20","unit":"g","group":"Acabado"},{"name":"perejil fresco","amount":"10","unit":"g","group":"Acabado"},{"name":"zumo de limón","amount":"15","unit":"g","group":"Acabado"},{"name":"sal","amount":"4","unit":"g","group":"Sazón"}],"steps":[{"title":"Prepara el marisco","content":"Mantén 300 g de gambas peladas y 250 g de calamar limpio en la nevera. Corta el calamar en anillas de 1 cm y seca con papel. Pica 120 g de cebolla, 6 g de ajo y 10 g de perejil.","image_url":"/recetas/receta-de-risotto-de-mar/paso-01.webp","image_alt":"Risotto de mar con gambas y calamar: Prepara el marisco"},{"title":"Calienta el caldo","content":"Calienta 1,1 litros de caldo de pescado sin sal hasta un hervor suave y mantenlo caliente a fuego mínimo. Reserva un cucharón. No es necesario añadir todo el caldo si el arroz llega antes a su punto.","image_url":"/recetas/receta-de-risotto-de-mar/paso-02.webp","image_alt":"Risotto de mar con gambas y calamar: Calienta el caldo"},{"title":"Cocina y reserva el marisco","content":"Calienta 10 g de aceite en una sartén amplia. Cocina el calamar unos 2 minutos y las gambas 2–3 minutos, hasta que estén opacos y alcancen 63 °C. Retira a un recipiente limpio y conserva caliente mientras empiezas el arroz.","image_url":"/recetas/receta-de-risotto-de-mar/paso-03.webp","image_alt":"Risotto de mar con gambas y calamar: Cocina y reserva el marisco"},{"title":"Sofríe y nacara el arroz","content":"En la misma cazuela añade los otros 10 g de aceite. Cocina la cebolla 5 minutos; añade el ajo 30 segundos. Incorpora 320 g de arroz y remueve 2 minutos, hasta que los bordes de los granos se vean translúcidos.","image_url":"/recetas/receta-de-risotto-de-mar/paso-04.webp","image_alt":"Risotto de mar con gambas y calamar: Sofríe y nacara el arroz"},{"title":"Añade caldo gradualmente","content":"Vierte 200 ml de caldo caliente y remueve con frecuencia. Cuando quede poco líquido, añade otro cucharón. Mantén un hervor suave durante unos 16–20 minutos, repitiendo las adiciones; el arroz debe quedar tierno con ligera resistencia central.","image_url":"/recetas/receta-de-risotto-de-mar/paso-05.webp","image_alt":"Risotto de mar con gambas y calamar: Añade caldo gradualmente"},{"title":"Devuelve el marisco","content":"Cuando falten unos 2 minutos para el punto del arroz, añade gambas, calamar y sus jugos. Agrega un poco de caldo si hace falta y remueve para calentarlos sin prolongar innecesariamente la cocción.","image_url":"/recetas/receta-de-risotto-de-mar/paso-06.webp","image_alt":"Risotto de mar con gambas y calamar: Devuelve el marisco"},{"title":"Manteca fuera del fuego","content":"Retira del fuego, añade 20 g de mantequilla, 15 g de zumo de limón y el perejil. Mezcla 1 minuto. Prueba y ajusta con hasta 4 g de sal según el caldo; debe moverse en una onda suave al agitar la cazuela.","image_url":"/recetas/receta-de-risotto-de-mar/paso-07.webp","image_alt":"Risotto de mar con gambas y calamar: Manteca fuera del fuego"},{"title":"Sirve sin esperar","content":"Reparte inmediatamente en 4 platos llanos. Inclina o golpea suavemente cada plato para extender el risotto; no debe formar una bola seca. No añadas nata ni queso para imitar la cremosidad.","image_url":"/recetas/receta-de-risotto-de-mar/paso-08.webp","image_alt":"Risotto de mar con gambas y calamar: Sirve sin esperar"}],"notes":"Contiene crustáceos y moluscos. No sustituir a ciegas si existe alergia. Para esta estimación el arroz de risotto se aproxima con arroz blanco de grano medio y se excluye el caldo, cuyo aporte depende de su receta: es un límite explícito de la nutrición. Refrigera sobras rápidamente en recipientes bajos y consume al día siguiente; recalienta hasta 74 °C, aunque perderá la textura recién hecha.","nutrition":{"calories":505.0,"protein_g":30.7,"carbs_g":69.1,"fat_g":10.8,"saturated_fat_g":3.3,"fiber_g":1.8,"sugar_g":1.4,"sodium_mg":509.0,"serving_size":"1 de 4 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 4 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma. El caldo de pescado no tiene ficha seleccionada y se excluye del cálculo; su aporte y sodio pueden aumentar los valores. Se aproxima el arroz de risotto con arroz blanco de grano medio. Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"arroz para risotto, crudo","edible_grams":320,"fdc_id":168879,"fdc_description":"Rice, white, medium-grain, raw, enriched","per_100g":{"saturated_fat_g":0.158,"protein_g":6.61,"fiber_g":1.4,"sodium_mg":1.0,"fat_g":0.58,"carbs_g":79.34,"calories":360.0},"source_url":"https://fdc.nal.usda.gov/food-details/168879/nutrients"},{"ingredient":"gambas crudas peladas","edible_grams":300,"fdc_id":175179,"fdc_description":"Crustaceans, shrimp, raw","per_100g":{"fat_g":0.51,"carbs_g":0.0,"calories":85.0,"protein_g":20.1,"sodium_mg":119.0,"saturated_fat_g":0.101},"source_url":"https://fdc.nal.usda.gov/food-details/175179/nutrients"},{"ingredient":"calamar limpio","edible_grams":250,"fdc_id":174223,"fdc_description":"Mollusks, squid, mixed species, raw","per_100g":{"sugar_g":0.0,"saturated_fat_g":0.358,"protein_g":15.58,"fiber_g":0.0,"sodium_mg":44.0,"fat_g":1.38,"carbs_g":3.08,"calories":92.0},"source_url":"https://fdc.nal.usda.gov/food-details/174223/nutrients"},{"ingredient":"cebolla","edible_grams":120,"fdc_id":170000,"fdc_description":"Onions, raw","per_100g":{"sugar_g":4.24,"fat_g":0.1,"carbs_g":9.34,"calories":40.0,"saturated_fat_g":0.042,"protein_g":1.1,"fiber_g":1.7,"sodium_mg":4.0},"source_url":"https://fdc.nal.usda.gov/food-details/170000/nutrients"},{"ingredient":"ajo","edible_grams":6,"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.06,"calories":149.0,"sugar_g":1.0,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17.0,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients"},{"ingredient":"aceite vegetal","edible_grams":20,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"fat_g":100.0,"saturated_fat_g":7.365,"protein_g":0.0,"carbs_g":0.0,"calories":884.0,"fiber_g":0.0,"sodium_mg":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"mantequilla sin sal","edible_grams":20,"fdc_id":173430,"fdc_description":"Butter, without salt","per_100g":{"sugar_g":0.06,"calories":717.0,"saturated_fat_g":50.489,"fat_g":81.11,"carbs_g":0.06,"protein_g":0.85,"fiber_g":0.0,"sodium_mg":11.0},"source_url":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"ingredient":"perejil fresco","edible_grams":10,"fdc_id":170416,"fdc_description":"Parsley, fresh","per_100g":{"carbs_g":6.33,"calories":36.0,"fat_g":0.79,"protein_g":2.97,"fiber_g":3.3,"sodium_mg":56.0,"saturated_fat_g":0.132,"sugar_g":0.85},"source_url":"https://fdc.nal.usda.gov/food-details/170416/nutrients"},{"ingredient":"zumo de limón","edible_grams":15,"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1.0,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22.0},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients"},{"ingredient":"sal","edible_grams":4,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0.0,"sodium_mg":38758.0,"saturated_fat_g":0.0,"protein_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}]},"keywords":["risotto de mar","risotto gambas y calamar","arroz cremoso con marisco"],"image_url":"/recetas/receta-de-risotto-de-mar/portada.webp","gallery":[{"url":"/recetas/receta-de-risotto-de-mar/portada.webp","alt":"Risotto de mar con gambas y calamar: plato terminado"}],"seo":{"title":"Risotto de mar con gambas y calamar | Manual de Cocina","description":"Risotto de mar con gambas y calamar, arroz cremoso y caldo añadido poco a poco. Cuatro porciones, sin nata ni queso en esta versión.","image_alt":"Risotto de mar con gambas y calamar: plato terminado","image_variants":["/recetas/receta-de-risotto-de-mar/portada-1x1.webp","/recetas/receta-de-risotto-de-mar/portada-4x3.webp","/recetas/receta-de-risotto-de-mar/portada-16x9.webp"],"faq":[{"q":"¿Hace falta nata?","a":"No. El almidón del arroz, el caldo y la mantequilla final proporcionan la textura cremosa."},{"q":"¿Se lava el arroz?","a":"En esta preparación no se lava, para conservar el almidón superficial que ayuda a ligar el risotto."},{"q":"¿Debo usar todo el caldo?","a":"No necesariamente. Depende del arroz y la evaporación; añade poco a poco hasta obtener el punto y la fluidez deseados."}]},"published":false,"editorial_status":"ready","content_html":"<p>Un risotto de marisco con arroz de grano medio, gambas y calamar. La cremosidad procede del almidón del arroz y de una pequeña cantidad de mantequilla al final, sin nata.</p><p>Rinde 4 porciones y se sirve enseguida. Usa marisco limpio, sin cáscaras ni vísceras, y caldo sin sal añadida para poder ajustar la sazón.</p>"},{"id":"8a23119f-4dbb-5fee-80ed-9948e97480c2","recipe_group_id":"734c10d3-e697-4918-8a98-d848105cabcf","slug":"meeresfruechte-risotto","public_path":"/de/meeresfruechte-risotto","source_url":null,"language":"de","title":"Meeresfrüchterisotto mit Garnelen und Tintenfisch","excerpt":"Meeresfrüchte-Risotto mit Garnelen und Tintenfisch, Brühe und etwas Butter. Cremig durch Reisstärke, ohne Sahne, für 4 Portionen.","summary":"Risotto mit mittelkörnigem Reis, Garnelen und Tintenfisch. Reisstärke und etwas Butter sorgen für Cremigkeit, ohne Sahne.\n\n4 Portionen, sofort servieren. Gereinigte Meeresfrüchte ohne Schalen oder Innereien und ungesalzene Fischbrühe verwenden.","category":"Hauptgerichte","category_slug":"platos-principales","difficulty":"Mittel","course":"Hauptgericht","cuisine":"Italienisch","prep_time_minutes":20,"cook_time_minutes":35,"total_time_minutes":55,"servings":4,"ingredients":[{"name":"ungekochter Risottoreis","amount":"320","unit":"g","group":"Reis"},{"name":"rohe geschälte Garnelen","amount":"300","unit":"g","group":"Meeresfrüchte"},{"name":"gereinigter Tintenfisch","amount":"250","unit":"g","group":"Meeresfrüchte"},{"name":"Zwiebel","amount":"120","unit":"g","group":"Ansatz"},{"name":"Knoblauch","amount":"6","unit":"g","group":"Ansatz"},{"name":"Pflanzenöl","amount":"20","unit":"g","group":"Ansatz"},{"name":"Fischbrühe ohne zugesetztes Salz","amount":"1100","unit":"ml","group":"Garen"},{"name":"ungesalzene Butter","amount":"20","unit":"g","group":"Abschluss"},{"name":"frische Petersilie","amount":"10","unit":"g","group":"Abschluss"},{"name":"Zitronensaft","amount":"15","unit":"g","group":"Abschluss"},{"name":"Salz","amount":"4","unit":"g","group":"Würzung"}],"steps":[{"title":"Meeresfrüchte vorbereiten","content":"300 g Garnelen und 250 g Tintenfisch gekühlt halten. Tintenfisch in 1 cm breite Ringe schneiden und trocken tupfen. 120 g Zwiebel, 6 g Knoblauch und 10 g Petersilie hacken.","image_url":"/recetas/receta-de-risotto-de-mar/paso-01.webp","image_alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: Meeresfrüchte vorbereiten"},{"title":"Brühe erhitzen","content":"1,1 Liter ungesalzene Fischbrühe sanft erhitzen und bei kleinster Hitze warm halten. Eine Kelle bereitlegen; nicht die ganze Brühe verwenden, wenn der Reis früher gar ist.","image_url":"/recetas/receta-de-risotto-de-mar/paso-02.webp","image_alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: Brühe erhitzen"},{"title":"Meeresfrüchte garen und beiseitestellen","content":"10 g Öl erhitzen. Tintenfisch etwa 2 Minuten, Garnelen 2–3 Minuten bis undurchsichtig und 63 °C garen. In ein sauberes Gefäß geben und warm halten.","image_url":"/recetas/receta-de-risotto-de-mar/paso-03.webp","image_alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: Meeresfrüchte garen und beiseitestellen"},{"title":"Reis anschwitzen","content":"Restliche 10 g Öl im selben Topf erhitzen. Zwiebel 5 Minuten, Knoblauch 30 Sekunden garen. 320 g Reis 2 Minuten rühren, bis die Kornränder durchsichtig wirken.","image_url":"/recetas/receta-de-risotto-de-mar/paso-04.webp","image_alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: Reis anschwitzen"},{"title":"Brühe nach und nach hinzufügen","content":"200 ml heiße Brühe zugeben und häufig rühren. Sobald wenig Flüssigkeit bleibt, eine weitere Kelle zugeben. 16–20 Minuten sanft köcheln und wiederholen, bis der Reis weich mit leichtem Kernbiss ist.","image_url":"/recetas/receta-de-risotto-de-mar/paso-05.webp","image_alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: Brühe nach und nach hinzufügen"},{"title":"Meeresfrüchte zurückgeben","content":"Etwa 2 Minuten vor dem Garpunkt Garnelen, Tintenfisch und Saft zurückgeben. Bei Bedarf Brühe ergänzen und erwärmen, ohne unnötig lange weiterzugaren.","image_url":"/recetas/receta-de-risotto-de-mar/paso-06.webp","image_alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: Meeresfrüchte zurückgeben"},{"title":"Butter abseits der Hitze einrühren","content":"Vom Herd nehmen und 20 g Butter, 15 g Zitronensaft und Petersilie 1 Minute einrühren. Nach Brühe mit bis zu 4 g Salz abschmecken. Beim Schwenken soll eine sanfte Welle entstehen.","image_url":"/recetas/receta-de-risotto-de-mar/paso-07.webp","image_alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: Butter abseits der Hitze einrühren"},{"title":"Sofort servieren","content":"Sofort auf 4 flache Teller verteilen. Durch leichtes Neigen oder Klopfen ausbreiten; es soll keine trockene Kugel sein. Keine Sahne oder Käse zum Nachahmen der Cremigkeit zufügen.","image_url":"/recetas/receta-de-risotto-de-mar/paso-08.webp","image_alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: Sofort servieren"}],"notes":"Enthält Krebstiere und Weichtiere; bei Allergien nicht ungeprüft ersetzen. Risottoreis wird mit mittelkörnigem weißen Reis angenähert; Brühe ist mangels ausgewählter Fiche ausgeschlossen. Reste schnell flach kühlen, am nächsten Tag essen und auf 74 °C erwärmen; die frische Konsistenz geht verloren.","nutrition":{"calories":505.0,"protein_g":30.7,"carbs_g":69.1,"fat_g":10.8,"saturated_fat_g":3.3,"fiber_g":1.8,"sugar_g":1.4,"sodium_mg":509.0,"serving_size":"1 von 4 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 4 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers. Fischbrühe mangels ausgewählter Nährwertfiche ausgeschlossen; sie kann Energie und Natrium erhöhen. Risottoreis wird mit mittelkörnigem weißen Reis angenähert."},"keywords":["Meeresfrüchte-Risotto","Garnelen Tintenfisch Risotto","Risotto ohne Sahne"],"image_url":"/recetas/receta-de-risotto-de-mar/portada.webp","gallery":[{"url":"/recetas/receta-de-risotto-de-mar/portada.webp","alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: fertiges Gericht"}],"seo":{"title":"Meeresfrüchterisotto mit Garnelen und Tintenfisch | Manual de Cocina","description":"Meeresfrüchte-Risotto mit Garnelen und Tintenfisch, Brühe und etwas Butter. Cremig durch Reisstärke, ohne Sahne, für 4 Portionen.","image_alt":"Meeresfrüchterisotto mit Garnelen und Tintenfisch: fertiges Gericht","image_variants":["/recetas/receta-de-risotto-de-mar/portada-1x1.webp","/recetas/receta-de-risotto-de-mar/portada-4x3.webp","/recetas/receta-de-risotto-de-mar/portada-16x9.webp"],"faq":[{"q":"Braucht es Sahne?","a":"Nein, Reisstärke, Brühe und Butter erzeugen die Cremigkeit."},{"q":"Soll der Reis gewaschen werden?","a":"Hier nicht: Die Oberflächenstärke bindet das Risotto."},{"q":"Muss alle Brühe hinein?","a":"Nein, Reissorte und Verdunstung entscheiden. Nach und nach bis zum gewünschten Garpunkt und Fließen zugeben."}]},"published":false,"editorial_status":"ready","content_html":"<p>Risotto mit mittelkörnigem Reis, Garnelen und Tintenfisch. Reisstärke und etwas Butter sorgen für Cremigkeit, ohne Sahne.</p><p>4 Portionen, sofort servieren. Gereinigte Meeresfrüchte ohne Schalen oder Innereien und ungesalzene Fischbrühe verwenden.</p>"},{"id":"b0a29f9d-34e4-5223-a076-9043ec418f26","recipe_group_id":"734c10d3-e697-4918-8a98-d848105cabcf","slug":"seafood-risotto","public_path":"/en/seafood-risotto","source_url":null,"language":"en","title":"Shrimp and squid risotto","excerpt":"Seafood risotto with prawns and squid, fish stock and a little butter. Rice starch gives it creaminess without cream; makes 4 servings.","summary":"Medium-grain rice risotto with prawns and squid. Rice starch and a little finishing butter give it creaminess without cream.\n\nMakes 4 servings to eat immediately. Use cleaned seafood without shells or innards and fish stock without added salt.","category":"Main dishes","category_slug":"platos-principales","difficulty":"Medium","course":"Main course","cuisine":"Italian","prep_time_minutes":20,"cook_time_minutes":35,"total_time_minutes":55,"servings":4,"ingredients":[{"name":"uncooked risotto rice","amount":"320","unit":"g","group":"Rice"},{"name":"raw peeled prawns","amount":"300","unit":"g","group":"Seafood"},{"name":"cleaned squid","amount":"250","unit":"g","group":"Seafood"},{"name":"onion","amount":"120","unit":"g","group":"Base"},{"name":"garlic","amount":"6","unit":"g","group":"Base"},{"name":"vegetable oil","amount":"20","unit":"g","group":"Base"},{"name":"fish stock without added salt","amount":"1100","unit":"ml","group":"Cooking"},{"name":"unsalted butter","amount":"20","unit":"g","group":"Finishing"},{"name":"fresh parsley","amount":"10","unit":"g","group":"Finishing"},{"name":"lemon juice","amount":"15","unit":"g","group":"Finishing"},{"name":"salt","amount":"4","unit":"g","group":"Seasoning"}],"steps":[{"title":"Prepare the seafood","content":"Keep 300 g peeled prawns and 250 g cleaned squid refrigerated. Cut squid into 1 cm rings and pat dry. Chop 120 g onion, 6 g garlic and 10 g parsley.","image_url":"/recetas/receta-de-risotto-de-mar/paso-01.webp","image_alt":"Shrimp and squid risotto: Prepare the seafood"},{"title":"Heat the stock","content":"Bring 1.1 litres unsalted fish stock to a gentle simmer and keep hot on low heat. Have a ladle ready; not all stock is needed if the rice cooks sooner.","image_url":"/recetas/receta-de-risotto-de-mar/paso-02.webp","image_alt":"Shrimp and squid risotto: Heat the stock"},{"title":"Cook and reserve the seafood","content":"Heat 10 g oil. Cook squid about 2 minutes and prawns 2–3 minutes until opaque and at 63 °C. Transfer to a clean container and keep hot while starting the rice.","image_url":"/recetas/receta-de-risotto-de-mar/paso-03.webp","image_alt":"Shrimp and squid risotto: Cook and reserve the seafood"},{"title":"Sauté and toast the rice","content":"Add the other 10 g oil to the same pan. Cook onion 5 minutes and garlic 30 seconds. Stir in 320 g rice for 2 minutes until grain edges become translucent.","image_url":"/recetas/receta-de-risotto-de-mar/paso-04.webp","image_alt":"Shrimp and squid risotto: Sauté and toast the rice"},{"title":"Add stock gradually","content":"Add 200 ml hot stock and stir frequently. When little liquid remains, add another ladleful. Simmer gently about 16–20 minutes, repeating additions, until tender with slight resistance in the centre.","image_url":"/recetas/receta-de-risotto-de-mar/paso-05.webp","image_alt":"Shrimp and squid risotto: Add stock gradually"},{"title":"Return the seafood","content":"About 2 minutes before the rice is ready, return prawns, squid and juices. Add stock if needed and stir to heat through without unnecessarily prolonging cooking.","image_url":"/recetas/receta-de-risotto-de-mar/paso-06.webp","image_alt":"Shrimp and squid risotto: Return the seafood"},{"title":"Stir in butter off the heat","content":"Off the heat, stir in 20 g butter, 15 g lemon juice and parsley for 1 minute. Taste and adjust with up to 4 g salt depending on the stock. It should move in a gentle wave when shaken.","image_url":"/recetas/receta-de-risotto-de-mar/paso-07.webp","image_alt":"Shrimp and squid risotto: Stir in butter off the heat"},{"title":"Serve straight away","content":"Immediately divide between 4 flat plates. Tilt or gently tap each plate to spread it; it should not be a dry mound. Do not add cream or cheese to imitate creaminess.","image_url":"/recetas/receta-de-risotto-de-mar/paso-08.webp","image_alt":"Shrimp and squid risotto: Serve straight away"}],"notes":"Contains crustaceans and molluscs; do not substitute blindly for allergies. Rice is approximated with medium-grain white rice; stock is excluded because no matching nutrient entry was selected. Refrigerate leftovers promptly in shallow containers, eat next day and reheat to 74 °C; freshly made texture will be lost.","nutrition":{"calories":505.0,"protein_g":30.7,"carbs_g":69.1,"fat_g":10.8,"saturated_fat_g":3.3,"fiber_g":1.8,"sugar_g":1.4,"sodium_mg":509.0,"serving_size":"1 of 4 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 4 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation. Fish stock is excluded because no nutrient entry was selected; it can add nutrients and sodium. Risotto rice is approximated with medium-grain white rice."},"keywords":["seafood risotto","prawn squid risotto","risotto without cream"],"image_url":"/recetas/receta-de-risotto-de-mar/portada.webp","gallery":[{"url":"/recetas/receta-de-risotto-de-mar/portada.webp","alt":"Shrimp and squid risotto: finished dish"}],"seo":{"title":"Shrimp and squid risotto | Manual de Cocina","description":"Seafood risotto with prawns and squid, fish stock and a little butter. Rice starch gives it creaminess without cream; makes 4 servings.","image_alt":"Shrimp and squid risotto: finished dish","image_variants":["/recetas/receta-de-risotto-de-mar/portada-1x1.webp","/recetas/receta-de-risotto-de-mar/portada-4x3.webp","/recetas/receta-de-risotto-de-mar/portada-16x9.webp"],"faq":[{"q":"Does it need cream?","a":"No. Rice starch, stock and finishing butter provide creaminess."},{"q":"Should I wash the rice?","a":"Not here: keep its surface starch to help bind the risotto."},{"q":"Must I use all the stock?","a":"Not necessarily. Rice and evaporation differ; add gradually to the desired doneness and fluidity."}]},"published":false,"editorial_status":"ready","content_html":"<p>Medium-grain rice risotto with prawns and squid. Rice starch and a little finishing butter give it creaminess without cream.</p><p>Makes 4 servings to eat immediately. Use cleaned seafood without shells or innards and fish stock without added salt.</p>"},{"id":"4e68e4e4-cd3c-530a-92e7-f34e712c745f","recipe_group_id":"734c10d3-e697-4918-8a98-d848105cabcf","slug":"risotto-aux-fruits-de-mer","public_path":"/fr/risotto-aux-fruits-de-mer","source_url":null,"language":"fr","title":"Risotto aux crevettes et au calamar","excerpt":"Risotto aux crevettes et calamars, bouillon de poisson et beurre. L’amidon du riz donne l’onctuosité sans crème, pour 4 portions.","summary":"Risotto de riz à grain moyen avec crevettes et calamars. L’amidon et un peu de beurre final donnent une texture crémeuse sans crème.\n\n4 portions à servir aussitôt. Utilisez des fruits de mer nettoyés, sans carapaces ni viscères, et du bouillon sans sel ajouté.","category":"Plats principaux","category_slug":"platos-principales","difficulty":"Moyenne","course":"Plat principal","cuisine":"Italienne","prep_time_minutes":20,"cook_time_minutes":35,"total_time_minutes":55,"servings":4,"ingredients":[{"name":"riz à risotto cru","amount":"320","unit":"g","group":"Riz"},{"name":"crevettes crues décortiquées","amount":"300","unit":"g","group":"Fruits de mer"},{"name":"calamar nettoyé","amount":"250","unit":"g","group":"Fruits de mer"},{"name":"oignon","amount":"120","unit":"g","group":"Base"},{"name":"ail","amount":"6","unit":"g","group":"Base"},{"name":"huile végétale","amount":"20","unit":"g","group":"Base"},{"name":"bouillon de poisson sans sel ajouté","amount":"1100","unit":"ml","group":"Cuisson"},{"name":"beurre doux","amount":"20","unit":"g","group":"Finition"},{"name":"persil frais","amount":"10","unit":"g","group":"Finition"},{"name":"jus de citron","amount":"15","unit":"g","group":"Finition"},{"name":"sel","amount":"4","unit":"g","group":"Assaisonnement"}],"steps":[{"title":"Préparer les fruits de mer","content":"Gardez au frais 300 g de crevettes et 250 g de calamar. Coupez le calamar en anneaux de 1 cm et séchez. Hachez 120 g d’oignon, 6 g d’ail et 10 g de persil.","image_url":"/recetas/receta-de-risotto-de-mar/paso-01.webp","image_alt":"Risotto aux crevettes et au calamar: Préparer les fruits de mer"},{"title":"Chauffer le bouillon","content":"Faites frémir 1,1 litre de bouillon non salé et gardez chaud à feu minimum, louche prête. Il n’est pas obligatoire de tout utiliser.","image_url":"/recetas/receta-de-risotto-de-mar/paso-02.webp","image_alt":"Risotto aux crevettes et au calamar: Chauffer le bouillon"},{"title":"Cuire et réserver les fruits de mer","content":"Chauffez 10 g d’huile. Cuisez calamar environ 2 minutes et crevettes 2–3 minutes, opaques et à 63 °C. Réservez dans un récipient propre et gardez chaud.","image_url":"/recetas/receta-de-risotto-de-mar/paso-03.webp","image_alt":"Risotto aux crevettes et au calamar: Cuire et réserver les fruits de mer"},{"title":"Faire revenir et nacrer le riz","content":"Ajoutez les autres 10 g d’huile. Cuisez oignon 5 minutes, ail 30 secondes, puis remuez 320 g de riz 2 minutes jusqu’aux bords translucides.","image_url":"/recetas/receta-de-risotto-de-mar/paso-04.webp","image_alt":"Risotto aux crevettes et au calamar: Faire revenir et nacrer le riz"},{"title":"Ajouter le bouillon progressivement","content":"Versez 200 ml de bouillon chaud et remuez souvent. Quand il en reste peu, ajoutez une louche. Répétez à frémissement environ 16–20 minutes, jusqu’au riz tendre avec légère résistance centrale.","image_url":"/recetas/receta-de-risotto-de-mar/paso-05.webp","image_alt":"Risotto aux crevettes et au calamar: Ajouter le bouillon progressivement"},{"title":"Remettre les fruits de mer","content":"À environ 2 minutes de la fin, remettez crevettes, calamar et jus. Complétez d’un peu de bouillon et réchauffez sans prolonger inutilement.","image_url":"/recetas/receta-de-risotto-de-mar/paso-06.webp","image_alt":"Risotto aux crevettes et au calamar: Remettre les fruits de mer"},{"title":"Incorporer le beurre hors du feu","content":"Hors feu, mélangez 20 g de beurre, 15 g de citron et persil 1 minute. Ajustez avec jusqu’à 4 g de sel selon le bouillon. Le risotto doit onduler quand on secoue la casserole.","image_url":"/recetas/receta-de-risotto-de-mar/paso-07.webp","image_alt":"Risotto aux crevettes et au calamar: Incorporer le beurre hors du feu"},{"title":"Servir sans attendre","content":"Servez aussitôt dans 4 assiettes plates. Inclinez ou tapotez pour étaler, sans former une boule sèche. Ne rajoutez pas crème ou fromage pour imiter l’onctuosité.","image_url":"/recetas/receta-de-risotto-de-mar/paso-08.webp","image_alt":"Risotto aux crevettes et au calamar: Servir sans attendre"}],"notes":"Contient crustacés et mollusques; pas de substitution aveugle en cas d’allergie. Riz approximé par grain moyen; bouillon exclu faute de fiche choisie. Réfrigérez rapidement en récipients bas, consommez le lendemain et réchauffez à 74 °C; texture fraîche perdue.","nutrition":{"calories":505.0,"protein_g":30.7,"carbs_g":69.1,"fat_g":10.8,"saturated_fat_g":3.3,"fiber_g":1.8,"sugar_g":1.4,"sodium_mg":509.0,"serving_size":"1 des 4 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 4 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire. Bouillon exclu faute de fiche sélectionnée; il peut augmenter les apports et le sodium. Riz approximé par riz blanc à grain moyen."},"keywords":["risotto fruits de mer","risotto crevettes calamars","risotto sans crème"],"image_url":"/recetas/receta-de-risotto-de-mar/portada.webp","gallery":[{"url":"/recetas/receta-de-risotto-de-mar/portada.webp","alt":"Risotto aux crevettes et au calamar: plat terminé"}],"seo":{"title":"Risotto aux crevettes et au calamar | Manual de Cocina","description":"Risotto aux crevettes et calamars, bouillon de poisson et beurre. L’amidon du riz donne l’onctuosité sans crème, pour 4 portions.","image_alt":"Risotto aux crevettes et au calamar: plat terminé","image_variants":["/recetas/receta-de-risotto-de-mar/portada-1x1.webp","/recetas/receta-de-risotto-de-mar/portada-4x3.webp","/recetas/receta-de-risotto-de-mar/portada-16x9.webp"],"faq":[{"q":"Faut-il de la crème?","a":"Non: amidon, bouillon et beurre suffisent."},{"q":"Faut-il laver le riz?","a":"Pas ici, pour conserver l’amidon de surface qui lie le risotto."},{"q":"Tout le bouillon est-il nécessaire?","a":"Cela dépend du riz et de l’évaporation; ajoutez progressivement jusqu’au point souhaité."}]},"published":false,"editorial_status":"ready","content_html":"<p>Risotto de riz à grain moyen avec crevettes et calamars. L’amidon et un peu de beurre final donnent une texture crémeuse sans crème.</p><p>4 portions à servir aussitôt. Utilisez des fruits de mer nettoyés, sans carapaces ni viscères, et du bouillon sans sel ajouté.</p>"},{"id":"0c8d3358-4a92-5f8e-a991-61a468efe0d8","recipe_group_id":"734c10d3-e697-4918-8a98-d848105cabcf","slug":"risotto-di-mare-gamberi-calamari","public_path":"/it/risotto-di-mare-gamberi-calamari","source_url":null,"language":"it","title":"Risotto con gamberi e calamari","excerpt":"Risotto di mare con gamberi, calamari, brodo di pesce e poco burro. Cremoso grazie all’amido, senza panna, per 4 porzioni.","summary":"Risotto con gamberi e calamari. La cremosità deriva dall’amido del riso e da poco burro finale, senza panna.\n\n4 porzioni da servire subito. Usa pesce pulito senza gusci né viscere e brodo senza sale aggiunto.","category":"Secondi piatti","category_slug":"platos-principales","difficulty":"Media","course":"Piatto principale","cuisine":"Italiana","prep_time_minutes":20,"cook_time_minutes":35,"total_time_minutes":55,"servings":4,"ingredients":[{"name":"riso da risotto crudo","amount":"320","unit":"g","group":"Riso"},{"name":"gamberi crudi sgusciati","amount":"300","unit":"g","group":"Mare"},{"name":"calamaro pulito","amount":"250","unit":"g","group":"Mare"},{"name":"cipolla","amount":"120","unit":"g","group":"Soffritto"},{"name":"aglio","amount":"6","unit":"g","group":"Soffritto"},{"name":"olio vegetale","amount":"20","unit":"g","group":"Soffritto"},{"name":"brodo di pesce senza sale aggiunto","amount":"1100","unit":"ml","group":"Cottura"},{"name":"burro non salato","amount":"20","unit":"g","group":"Finitura"},{"name":"prezzemolo fresco","amount":"10","unit":"g","group":"Finitura"},{"name":"succo di limone","amount":"15","unit":"g","group":"Finitura"},{"name":"sale","amount":"4","unit":"g","group":"Condimento"}],"steps":[{"title":"Preparare i frutti di mare","content":"Tieni refrigerati 300 g di gamberi e 250 g di calamaro. Taglia calamaro ad anelli di 1 cm e asciuga. Trita 120 g di cipolla, 6 g di aglio e 10 g di prezzemolo.","image_url":"/recetas/receta-de-risotto-de-mar/paso-01.webp","image_alt":"Risotto con gamberi e calamari: Preparare i frutti di mare"},{"title":"Scaldare il brodo","content":"Porta 1,1 litri di brodo a lieve bollore e mantieni caldo al minimo, con mestolo pronto. Non occorre usarlo tutto se il riso arriva prima a cottura.","image_url":"/recetas/receta-de-risotto-de-mar/paso-02.webp","image_alt":"Risotto con gamberi e calamari: Scaldare il brodo"},{"title":"Cuocere e tenere da parte i frutti di mare","content":"Scalda 10 g di olio. Cuoci calamaro circa 2 minuti e gamberi 2–3 minuti fino a opachi e 63 °C. Trasferisci a recipiente pulito e mantieni caldo.","image_url":"/recetas/receta-de-risotto-de-mar/paso-03.webp","image_alt":"Risotto con gamberi e calamari: Cuocere e tenere da parte i frutti di mare"},{"title":"Soffriggere e tostare il riso","content":"Aggiungi altri 10 g di olio nella stessa casseruola. Cuoci cipolla 5 minuti, aglio 30 secondi; tosta 320 g di riso 2 minuti fino a bordi traslucidi.","image_url":"/recetas/receta-de-risotto-de-mar/paso-04.webp","image_alt":"Risotto con gamberi e calamari: Soffriggere e tostare il riso"},{"title":"Aggiungere il brodo gradualmente","content":"Versa 200 ml di brodo caldo e mescola spesso. Quando resta poco liquido, aggiungi un mestolo. Ripeti a lieve bollore 16–20 minuti circa, fino a tenero con leggera resistenza al centro.","image_url":"/recetas/receta-de-risotto-de-mar/paso-05.webp","image_alt":"Risotto con gamberi e calamari: Aggiungere il brodo gradualmente"},{"title":"Rimettere i frutti di mare","content":"Circa 2 minuti prima del punto finale rimetti gamberi, calamaro e succhi. Aggiungi poco brodo se serve e scalda senza prolungare inutilmente.","image_url":"/recetas/receta-de-risotto-de-mar/paso-06.webp","image_alt":"Risotto con gamberi e calamari: Rimettere i frutti di mare"},{"title":"Mantecare fuori dal fuoco","content":"Fuori dal fuoco manteca con 20 g di burro, 15 g di succo di limone e prezzemolo per 1 minuto. Assaggia e usa fino a 4 g di sale secondo il brodo. Deve muoversi a onda.","image_url":"/recetas/receta-de-risotto-de-mar/paso-07.webp","image_alt":"Risotto con gamberi e calamari: Mantecare fuori dal fuoco"},{"title":"Servire subito","content":"Dividi subito in 4 piatti piani. Inclina o picchietta per allargare: non deve essere una palla asciutta. Non aggiungere panna o formaggio per simulare cremosità.","image_url":"/recetas/receta-de-risotto-de-mar/paso-08.webp","image_alt":"Risotto con gamberi e calamari: Servire subito"}],"notes":"Contiene crostacei e molluschi; non sostituire alla cieca in caso di allergia. Riso approssimato con bianco a grano medio; brodo escluso per mancanza di scheda scelta. Refrigera avanzi rapidamente in recipienti bassi, consuma il giorno dopo e riscalda a 74 °C; perderà la consistenza fresca.","nutrition":{"calories":505.0,"protein_g":30.7,"carbs_g":69.1,"fat_g":10.8,"saturated_fat_g":3.3,"fiber_g":1.8,"sugar_g":1.4,"sodium_mg":509.0,"serving_size":"1 delle 4 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 4 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario. Brodo escluso perché non è stata scelta una scheda; può aumentare apporti e sodio. Riso approssimato con bianco a grano medio."},"keywords":["risotto di mare","risotto gamberi calamari","risotto senza panna"],"image_url":"/recetas/receta-de-risotto-de-mar/portada.webp","gallery":[{"url":"/recetas/receta-de-risotto-de-mar/portada.webp","alt":"Risotto con gamberi e calamari: piatto pronto"}],"seo":{"title":"Risotto con gamberi e calamari | Manual de Cocina","description":"Risotto di mare con gamberi, calamari, brodo di pesce e poco burro. Cremoso grazie all’amido, senza panna, per 4 porzioni.","image_alt":"Risotto con gamberi e calamari: piatto pronto","image_variants":["/recetas/receta-de-risotto-de-mar/portada-1x1.webp","/recetas/receta-de-risotto-de-mar/portada-4x3.webp","/recetas/receta-de-risotto-de-mar/portada-16x9.webp"],"faq":[{"q":"Serve panna?","a":"No, amido, brodo e burro finale danno cremosità."},{"q":"Si lava il riso?","a":"Qui no, per mantenere l’amido superficiale che lega il risotto."},{"q":"Devo usare tutto il brodo?","a":"Non necessariamente: riso ed evaporazione cambiano. Versa gradualmente fino alla consistenza desiderata."}]},"published":false,"editorial_status":"ready","content_html":"<p>Risotto con gamberi e calamari. La cremosità deriva dall’amido del riso e da poco burro finale, senza panna.</p><p>4 porzioni da servire subito. Usa pesce pulito senza gusci né viscere e brodo senza sale aggiunto.</p>"},{"id":"bde67002-4eff-5486-aef6-8aa2314d2004","recipe_group_id":"734c10d3-e697-4918-8a98-d848105cabcf","slug":"えびといかのリゾット","public_path":"/ja/えびといかのリゾット","source_url":null,"language":"ja","title":"エビとイカのリゾット","excerpt":"えびといかのリゾット。魚のスープと少量のバター、米のでんぷんでクリーミーに仕上げ、生クリームは使いません。4人分。","summary":"中粒米、えび、いかのリゾットです。米のでんぷんと仕上げの少量のバターでとろみを出し、生クリームは使いません。\n\n4人分、出来たてを提供します。殻や内臓を除いた魚介と食塩無添加の魚スープを使います。","category":"主菜","category_slug":"platos-principales","difficulty":"普通","course":"主菜","cuisine":"イタリア料理","prep_time_minutes":20,"cook_time_minutes":35,"total_time_minutes":55,"servings":4,"ingredients":[{"name":"生のリゾット用米","amount":"320","unit":"g","group":"米"},{"name":"生のむきえび","amount":"300","unit":"g","group":"魚介"},{"name":"下処理済みいか","amount":"250","unit":"g","group":"魚介"},{"name":"玉ねぎ","amount":"120","unit":"g","group":"炒め材料"},{"name":"にんにく","amount":"6","unit":"g","group":"炒め材料"},{"name":"植物油","amount":"20","unit":"g","group":"炒め材料"},{"name":"食塩無添加の魚スープ","amount":"1100","unit":"ml","group":"煮込み"},{"name":"無塩バター","amount":"20","unit":"g","group":"仕上げ"},{"name":"生パセリ","amount":"10","unit":"g","group":"仕上げ"},{"name":"レモン汁","amount":"15","unit":"g","group":"仕上げ"},{"name":"塩","amount":"4","unit":"g","group":"味付け"}],"steps":[{"title":"魚介を用意する","content":"えび300 gといか250 gを冷蔵します。いかを幅1 cmの輪切りにして水気を取り、玉ねぎ120 g、にんにく6 g、パセリ10 gを刻みます。","image_url":"/recetas/receta-de-risotto-de-mar/paso-01.webp","image_alt":"エビとイカのリゾット: 魚介を用意する"},{"title":"だしを温める","content":"魚スープ1.1リットルを穏やかに温め、最弱火で保温します。お玉を用意し、米が先に煮えたら全量使う必要はありません。","image_url":"/recetas/receta-de-risotto-de-mar/paso-02.webp","image_alt":"エビとイカのリゾット: だしを温める"},{"title":"魚介を加熱して取り出す","content":"油10 gでいか約2分、えび2–3分、透明感がなくなり63 °Cになるまで焼きます。清潔な容器へ取り、温かく保ちます。","image_url":"/recetas/receta-de-risotto-de-mar/paso-03.webp","image_alt":"エビとイカのリゾット: 魚介を加熱して取り出す"},{"title":"米を炒める","content":"同じ鍋に残りの油10 gを入れ、玉ねぎ5分、にんにく30秒。米320 gを2分混ぜ、粒の縁が半透明になるまで炒めます。","image_url":"/recetas/receta-de-risotto-de-mar/paso-04.webp","image_alt":"エビとイカのリゾット: 米を炒める"},{"title":"だしを少しずつ加える","content":"熱いスープ200 mlを注ぎ、よく混ぜます。液が少なくなったらお玉1杯追加。穏やかに約16–20分、追加を繰り返し、中央に少し抵抗のある柔らかさへ。","image_url":"/recetas/receta-de-risotto-de-mar/paso-05.webp","image_alt":"エビとイカのリゾット: だしを少しずつ加える"},{"title":"魚介を戻す","content":"完成約2分前にえび、いか、出た汁を戻します。必要ならスープを足し、過度に長く煮ず温めます。","image_url":"/recetas/receta-de-risotto-de-mar/paso-06.webp","image_alt":"エビとイカのリゾット: 魚介を戻す"},{"title":"火を止めてバターを混ぜる","content":"火から外し、バター20 g、レモン汁15 g、パセリを1分混ぜます。スープに応じ塩を最大4 g調整。鍋を揺らすと穏やかな波になる濃度にします。","image_url":"/recetas/receta-de-risotto-de-mar/paso-07.webp","image_alt":"エビとイカのリゾット: 火を止めてバターを混ぜる"},{"title":"すぐに盛り付ける","content":"すぐ平皿4枚へ盛り、傾けるか軽くたたいて広げます。乾いた団子状にせず、クリームやチーズでとろみを代用しません。","image_url":"/recetas/receta-de-risotto-de-mar/paso-08.webp","image_alt":"エビとイカのリゾット: すぐに盛り付ける"}],"notes":"甲殻類と軟体類を含み、アレルギー時に安易に置換しません。米は中粒白米で近似し、魚スープは栄養データ未選択のため計算外。残りは浅い容器ですぐ冷蔵し翌日食べ、74 °Cまで再加熱します。出来たての食感は失われます。","nutrition":{"calories":505.0,"protein_g":30.7,"carbs_g":69.1,"fat_g":10.8,"saturated_fat_g":3.3,"fiber_g":1.8,"sugar_g":1.4,"sodium_mg":509.0,"serving_size":"全4人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を4人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。 魚スープはデータ未選択で計算から除外し、栄養とナトリウムを増やす可能性があります。米は中粒白米で近似しています。"},"keywords":["えびいかリゾット","魚介リゾット","生クリームなしリゾット"],"image_url":"/recetas/receta-de-risotto-de-mar/portada.webp","gallery":[{"url":"/recetas/receta-de-risotto-de-mar/portada.webp","alt":"エビとイカのリゾット: 完成した料理"}],"seo":{"title":"エビとイカのリゾット | Manual de Cocina","description":"えびといかのリゾット。魚のスープと少量のバター、米のでんぷんでクリーミーに仕上げ、生クリームは使いません。4人分。","image_alt":"エビとイカのリゾット: 完成した料理","image_variants":["/recetas/receta-de-risotto-de-mar/portada-1x1.webp","/recetas/receta-de-risotto-de-mar/portada-4x3.webp","/recetas/receta-de-risotto-de-mar/portada-16x9.webp"],"faq":[{"q":"生クリームは必要ですか？","a":"いいえ。米のでんぷん、スープ、バターでとろみが付きます。"},{"q":"米を洗いますか？","a":"この調理では表面のでんぷんを保つため洗いません。"},{"q":"スープを全部使いますか？","a":"米や蒸発量によります。好みの火通りと流れる濃度まで少しずつ加えます。"}]},"published":false,"editorial_status":"ready","content_html":"<p>中粒米、えび、いかのリゾットです。米のでんぷんと仕上げの少量のバターでとろみを出し、生クリームは使いません。</p><p>4人分、出来たてを提供します。殻や内臓を除いた魚介と食塩無添加の魚スープを使います。</p>"},{"id":"83569b8d-c8dd-5061-b604-fb10f9e42afc","recipe_group_id":"734c10d3-e697-4918-8a98-d848105cabcf","slug":"risoto-de-mar-camarao-lula","public_path":"/pt/risoto-de-mar-camarao-lula","source_url":null,"language":"pt","title":"Risoto com camarão e lula","excerpt":"Risoto de mar com camarão, lula, caldo de peixe e pouca manteiga. Cremoso pelo amido do arroz, sem creme de leite, para 4 porções.","summary":"Risoto de arroz de grão médio com camarão e lula. A cremosidade vem do amido e de pouca manteiga no final, sem creme de leite.\n\n4 porções para servir logo. Use frutos do mar limpos, sem cascas nem vísceras, e caldo sem sal adicionado.","category":"Pratos principais","category_slug":"platos-principales","difficulty":"Média","course":"Prato principal","cuisine":"Italiana","prep_time_minutes":20,"cook_time_minutes":35,"total_time_minutes":55,"servings":4,"ingredients":[{"name":"arroz para risoto cru","amount":"320","unit":"g","group":"Arroz"},{"name":"camarões crus descascados","amount":"300","unit":"g","group":"Frutos do mar"},{"name":"lula limpa","amount":"250","unit":"g","group":"Frutos do mar"},{"name":"cebola","amount":"120","unit":"g","group":"Refogado"},{"name":"alho","amount":"6","unit":"g","group":"Refogado"},{"name":"óleo vegetal","amount":"20","unit":"g","group":"Refogado"},{"name":"caldo de peixe sem sal adicionado","amount":"1100","unit":"ml","group":"Cozimento"},{"name":"manteiga sem sal","amount":"20","unit":"g","group":"Finalização"},{"name":"salsa fresca","amount":"10","unit":"g","group":"Finalização"},{"name":"suco de limão","amount":"15","unit":"g","group":"Finalização"},{"name":"sal","amount":"4","unit":"g","group":"Tempero"}],"steps":[{"title":"Prepare os frutos do mar","content":"Mantenha refrigerados 300 g de camarão e 250 g de lula. Corte lula em anéis de 1 cm e seque. Pique 120 g de cebola, 6 g de alho e 10 g de salsa.","image_url":"/recetas/receta-de-risotto-de-mar/paso-01.webp","image_alt":"Risoto com camarão e lula: Prepare os frutos do mar"},{"title":"Aqueça o caldo","content":"Aqueça 1,1 litro de caldo até fervura suave e mantenha quente no mínimo, com concha pronta. Não precisa usar tudo se o arroz atingir o ponto antes.","image_url":"/recetas/receta-de-risotto-de-mar/paso-02.webp","image_alt":"Risoto com camarão e lula: Aqueça o caldo"},{"title":"Cozinhe e reserve os frutos do mar","content":"Aqueça 10 g de óleo. Cozinhe lula cerca de 2 minutos e camarão 2–3 minutos até opacos e a 63 °C. Retire a recipiente limpo e mantenha quente.","image_url":"/recetas/receta-de-risotto-de-mar/paso-03.webp","image_alt":"Risoto com camarão e lula: Cozinhe e reserve os frutos do mar"},{"title":"Refogue e toste o arroz","content":"Junte os outros 10 g de óleo. Cozinhe cebola 5 minutos e alho 30 segundos; mexa 320 g de arroz por 2 minutos até bordas translúcidas.","image_url":"/recetas/receta-de-risotto-de-mar/paso-04.webp","image_alt":"Risoto com camarão e lula: Refogue e toste o arroz"},{"title":"Acrescente o caldo aos poucos","content":"Coloque 200 ml de caldo quente e mexa frequentemente. Quando restar pouco líquido, adicione outra concha. Repita em fervura suave por cerca de 16–20 minutos, até macio com leve resistência central.","image_url":"/recetas/receta-de-risotto-de-mar/paso-05.webp","image_alt":"Risoto com camarão e lula: Acrescente o caldo aos poucos"},{"title":"Devolva os frutos do mar","content":"A cerca de 2 minutos do ponto, volte camarão, lula e sucos. Junte pouco caldo se necessário e aqueça sem prolongar demais.","image_url":"/recetas/receta-de-risotto-de-mar/paso-06.webp","image_alt":"Risoto com camarão e lula: Devolva os frutos do mar"},{"title":"Misture a manteiga fora do fogo","content":"Fora do fogo, misture 20 g de manteiga, 15 g de limão e salsa por 1 minuto. Ajuste até 4 g de sal conforme o caldo. Deve ondular suavemente ao agitar a panela.","image_url":"/recetas/receta-de-risotto-de-mar/paso-07.webp","image_alt":"Risoto com camarão e lula: Misture a manteiga fora do fogo"},{"title":"Sirva sem esperar","content":"Divida logo em 4 pratos rasos. Incline ou bata suavemente para espalhar; não forme bola seca. Não junte creme de leite ou queijo para imitar cremosidade.","image_url":"/recetas/receta-de-risotto-de-mar/paso-08.webp","image_alt":"Risoto com camarão e lula: Sirva sem esperar"}],"notes":"Contém crustáceos e moluscos; não substitua sem avaliar alergias. Arroz aproximado por branco de grão médio; caldo excluído por falta de ficha selecionada. Refrigere sobras rapidamente em recipientes rasos, consuma no dia seguinte e reaqueça a 74 °C; perde textura de recém-feito.","nutrition":{"calories":505.0,"protein_g":30.7,"carbs_g":69.1,"fat_g":10.8,"saturated_fat_g":3.3,"fiber_g":1.8,"sugar_g":1.4,"sodium_mg":509.0,"serving_size":"1 de 4 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 4 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário. Caldo de peixe excluído por não haver ficha selecionada; pode aumentar nutrientes e sódio. Arroz aproximado por branco de grão médio."},"keywords":["risoto de mar","risoto camarão lula","risoto sem creme de leite"],"image_url":"/recetas/receta-de-risotto-de-mar/portada.webp","gallery":[{"url":"/recetas/receta-de-risotto-de-mar/portada.webp","alt":"Risoto com camarão e lula: prato pronto"}],"seo":{"title":"Risoto com camarão e lula | Manual de Cocina","description":"Risoto de mar com camarão, lula, caldo de peixe e pouca manteiga. Cremoso pelo amido do arroz, sem creme de leite, para 4 porções.","image_alt":"Risoto com camarão e lula: prato pronto","image_variants":["/recetas/receta-de-risotto-de-mar/portada-1x1.webp","/recetas/receta-de-risotto-de-mar/portada-4x3.webp","/recetas/receta-de-risotto-de-mar/portada-16x9.webp"],"faq":[{"q":"Precisa de creme de leite?","a":"Não: amido, caldo e manteiga final dão cremosidade."},{"q":"Lava-se o arroz?","a":"Aqui não, para manter o amido superficial que liga o risoto."},{"q":"Preciso usar todo o caldo?","a":"Depende do arroz e evaporação; adicione aos poucos até ponto e fluidez desejados."}]},"published":false,"editorial_status":"ready","content_html":"<p>Risoto de arroz de grão médio com camarão e lula. A cremosidade vem do amido e de pouca manteiga no final, sem creme de leite.</p><p>4 porções para servir logo. Use frutos do mar limpos, sem cascas nem vísceras, e caldo sem sal adicionado.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-de-risotto-de-mar') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

-- receta-de-wrap-de-pollo-con-vegetales
do $pub$
declare
  g constant uuid := '489e5092-352f-4ec5-8633-c628e784d22a';
  es_id constant uuid := 'ffda4188-dfd2-4e8f-a2bb-06edc8fec0fe';
  j constant jsonb := $j$[{"id":"ffda4188-dfd2-4e8f-a2bb-06edc8fec0fe","recipe_group_id":"489e5092-352f-4ec5-8633-c628e784d22a","slug":"receta-de-wrap-de-pollo-con-vegetales","public_path":"/receta-de-wrap-de-pollo-con-vegetales","source_url":"https://manualdecocina.com/receta-de-wrap-de-pollo-con-vegetales/","language":"es","title":"Wrap de pollo con vegetales","excerpt":"Wrap de pollo con vegetales: tortillas de trigo rellenas de pollo, pimiento, lechuga y tomate, con aliño de limón y mostaza.","summary":"Cuatro wraps de tortilla de trigo con pollo en tiras, pimiento salteado y verduras frescas. Se rellenan después de cocinar el pollo y templarlo para que la lechuga no se marchite.\n\nLos 40 minutos incluyen 5 de reposo del pollo. La nutrición corresponde a un wrap completo; no incluye guarniciones.","category":"Platos principales","category_slug":"platos-principales","difficulty":"Media","course":"Plato principal","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"pechuga de pollo sin piel","amount":"500","unit":"g","group":"Relleno caliente"},{"name":"pimiento rojo","amount":"200","unit":"g","group":"Relleno caliente"},{"name":"aceite vegetal","amount":"15","unit":"g","group":"Relleno caliente"},{"name":"sal","amount":"3","unit":"g","group":"Relleno caliente"},{"name":"pimienta negra","amount":"0.5","unit":"g","group":"Relleno caliente"},{"name":"tortillas grandes de trigo","amount":"4","unit":"unidades","group":"Montaje"},{"name":"lechuga romana","amount":"100","unit":"g","group":"Relleno fresco"},{"name":"tomate","amount":"200","unit":"g","group":"Relleno fresco"},{"name":"zumo de limón","amount":"20","unit":"g","group":"Aliño"},{"name":"mostaza preparada","amount":"10","unit":"g","group":"Aliño"},{"name":"aceite vegetal","amount":"10","unit":"g","group":"Aliño"}],"steps":[{"title":"Lava y corta los vegetales","content":"Lava y seca 100 g de lechuga, 200 g de tomate y 200 g de pimiento rojo. Corta la lechuga en tiras, el tomate en dados sin exceso de líquido y el pimiento en tiras de 1 cm.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-01.webp","image_alt":"Wrap de pollo con vegetales: Lava y corta los vegetales"},{"title":"Prepara el pollo","content":"Corta 500 g de pechuga en tiras de unos 2 cm de grosor. Sazona con 3 g de sal y 0,5 g de pimienta. Usa una tabla distinta de la de las verduras y limpia manos y utensilios.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-02.webp","image_alt":"Wrap de pollo con vegetales: Prepara el pollo"},{"title":"Cocina el pimiento","content":"Calienta 5 g de aceite en sartén a fuego medio-alto y cocina las tiras de pimiento 5 minutos, removiendo, hasta que estén tiernas pero con algo de textura. Retira a un plato limpio.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-03.webp","image_alt":"Wrap de pollo con vegetales: Cocina el pimiento"},{"title":"Cocina el pollo","content":"Añade 10 g de aceite y cocina las tiras de pollo 7–9 minutos, girándolas hasta que el centro alcance 74 °C. Si la sartén es pequeña, trabaja en tandas. Reposa 5 minutos fuera del fuego.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-04.webp","image_alt":"Wrap de pollo con vegetales: Cocina el pollo"},{"title":"Mezcla el aliño","content":"Bate 20 g de zumo de limón con 10 g de mostaza y 10 g de aceite durante 1 minuto. Reserva; no añadas el aliño a las verduras hasta montar los wraps.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-05.webp","image_alt":"Wrap de pollo con vegetales: Mezcla el aliño"},{"title":"Calienta las tortillas","content":"Calienta las 4 tortillas en sartén seca durante 15–20 segundos por lado, solo hasta que sean flexibles. Mantén cubiertas con un paño limpio mientras montas.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-06.webp","image_alt":"Wrap de pollo con vegetales: Calienta las tortillas"},{"title":"Rellena y enrolla","content":"Reparte lechuga, tomate, pimiento y pollo entre las tortillas dejando 3 cm libres en los bordes. Añade una cuarta parte del aliño a cada una. Pliega ambos lados hacia dentro y enrolla desde el borde cercano.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-07.webp","image_alt":"Wrap de pollo con vegetales: Rellena y enrolla"},{"title":"Corta y sirve","content":"Corta cada wrap en diagonal y sirve uno por persona. Si lo llevas fuera, enfría primero el pollo, guarda refrigerado y transporta con acumuladores de frío; no lo mantengas templado durante horas.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-08.webp","image_alt":"Wrap de pollo con vegetales: Corta y sirve"}],"notes":"Para preparar con anticipación, guarda el pollo cocido refrigerado hasta 3 días y monta los wraps el día que se consuman. El tomate húmedo ablanda la tortilla: retira el exceso de líquido. La tortilla grande se estima en 60 g; si el envase indica otro peso, ajusta la nutrición. Puedes usar tortilla de maíz, pero puede necesitar otro modo de plegado y cambia la estimación.","nutrition":{"calories":413.0,"protein_g":34.3,"carbs_g":35.9,"fat_g":14.5,"saturated_fat_g":2.0,"fiber_g":3.8,"sugar_g":5.5,"sodium_mg":826.0,"serving_size":"1 de 4 porciones","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de valores por 100 g de las fichas FDC verificadas, multiplicados por los gramos comestibles de cada ingrediente, dividida entre 4 porciones. Se cuenta todo el aceite y toda la sal indicados; no se incluyen acompañamientos opcionales.","note":"Estimación informativa; varía con marcas, rendimiento y grasa o salsa que no se consuma. Cada tortilla se estima en 60 g usando una ficha genérica SR Legacy de tortilla de trigo. Cantidades, tiempos, raciones y nutrición propuestos por IA, pendientes de confirmación del propietario.","inputs":[{"ingredient":"pechuga de pollo sin piel","edible_grams":500,"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120.0,"saturated_fat_g":0.563,"sodium_mg":45.0,"protein_g":22.5,"sugar_g":0.0,"carbs_g":0.0,"fiber_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients"},{"ingredient":"pimiento rojo","edible_grams":200,"fdc_id":170108,"fdc_description":"Peppers, sweet, red, raw","per_100g":{"fiber_g":2.1,"calories":26.0,"saturated_fat_g":0.059,"sodium_mg":4.0,"sugar_g":4.2,"carbs_g":6.03,"protein_g":0.99,"fat_g":0.3},"source_url":"https://fdc.nal.usda.gov/food-details/170108/nutrients"},{"ingredient":"aceite vegetal","edible_grams":15,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"fat_g":100.0,"saturated_fat_g":7.365,"protein_g":0.0,"carbs_g":0.0,"calories":884.0,"fiber_g":0.0,"sodium_mg":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"sal","edible_grams":3,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0.0,"sodium_mg":38758.0,"saturated_fat_g":0.0,"protein_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"pimienta negra","edible_grams":0.5,"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":63.95,"calories":251.0,"protein_g":10.39,"fiber_g":25.3,"sodium_mg":20.0,"saturated_fat_g":1.392},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients"},{"ingredient":"tortillas grandes de trigo","edible_grams":240,"fdc_id":167535,"fdc_description":"Tortillas, ready-to-bake or -fry, flour, shelf stable","per_100g":{"fat_g":7.58,"carbs_g":49.27,"calories":297.0,"sugar_g":2.66,"protein_g":8.01,"fiber_g":2.4,"sodium_mg":742.0,"saturated_fat_g":1.225},"source_url":"https://fdc.nal.usda.gov/food-details/167535/nutrients"},{"ingredient":"lechuga romana","edible_grams":100,"fdc_id":169247,"fdc_description":"Lettuce, cos or romaine, raw","per_100g":{"carbs_g":3.29,"calories":17.0,"saturated_fat_g":0.039,"sodium_mg":8.0,"fat_g":0.3,"sugar_g":1.19,"fiber_g":2.1,"protein_g":1.23},"source_url":"https://fdc.nal.usda.gov/food-details/169247/nutrients"},{"ingredient":"tomate","edible_grams":200,"fdc_id":170457,"fdc_description":"Tomatoes, red, ripe, raw, year round average","per_100g":{"sugar_g":2.63,"carbs_g":3.89,"calories":18.0,"saturated_fat_g":0.028,"fat_g":0.2,"fiber_g":1.2,"sodium_mg":5.0,"protein_g":0.88},"source_url":"https://fdc.nal.usda.gov/food-details/170457/nutrients"},{"ingredient":"zumo de limón","edible_grams":20,"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1.0,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22.0},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients"},{"ingredient":"mostaza preparada","edible_grams":10,"fdc_id":172234,"fdc_description":"Mustard, prepared, yellow","per_100g":{"protein_g":3.74,"fiber_g":4.0,"sodium_mg":1104.0,"saturated_fat_g":0.214,"fat_g":3.34,"carbs_g":5.83,"calories":60.0,"sugar_g":0.92},"source_url":"https://fdc.nal.usda.gov/food-details/172234/nutrients"},{"ingredient":"aceite vegetal","edible_grams":10,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"fat_g":100.0,"saturated_fat_g":7.365,"protein_g":0.0,"carbs_g":0.0,"calories":884.0,"fiber_g":0.0,"sodium_mg":0.0,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"}]},"keywords":["wrap de pollo con vegetales","tortilla rellena de pollo","wrap de pollo casero"],"image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","gallery":[{"url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","alt":"Wrap de pollo con vegetales: plato terminado"}],"seo":{"title":"Wrap de pollo con vegetales | Manual de Cocina","description":"Wrap de pollo con vegetales: tortillas de trigo rellenas de pollo, pimiento, lechuga y tomate, con aliño de limón y mostaza.","image_alt":"Wrap de pollo con vegetales: plato terminado","image_variants":["/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-1x1.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-4x3.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-16x9.webp"],"faq":[{"q":"¿Cómo evito que se rompa la tortilla?","a":"Calienta brevemente para hacerla flexible y deja margen libre antes de plegar; no sobrecargues el relleno."},{"q":"¿Puedo usar pollo del día anterior?","a":"Sí, si se refrigeró correctamente. Para comerlo frío, mantenlo frío hasta montar y transportar."},{"q":"¿Se puede congelar el wrap completo?","a":"La lechuga y el tomate pierden textura. Congela solo el pollo cocinado y monta después con vegetales frescos."}]},"published":false,"editorial_status":"ready","content_html":"<p>Cuatro wraps de tortilla de trigo con pollo en tiras, pimiento salteado y verduras frescas. Se rellenan después de cocinar el pollo y templarlo para que la lechuga no se marchite.</p><p>Los 40 minutos incluyen 5 de reposo del pollo. La nutrición corresponde a un wrap completo; no incluye guarniciones.</p>"},{"id":"debf7ea4-7d40-51d9-b82a-40374503b645","recipe_group_id":"489e5092-352f-4ec5-8633-c628e784d22a","slug":"haehnchen-wraps-mit-gemuese","public_path":"/de/haehnchen-wraps-mit-gemuese","source_url":null,"language":"de","title":"Hähnchen-Wrap mit Gemüse","excerpt":"Hähnchen-Wraps mit gebratener Paprika, Salat, Tomate und Zitronen-Senf-Dressing. Vier Weizentortillas werden nach dem Garen gefüllt und gerollt.","summary":"Vier Weizentortilla-Wraps mit Hähnchenstreifen, gebratener Paprika und frischem Gemüse. Das gegarte Fleisch etwas abkühlen lassen, damit der Salat nicht welkt.\n\nDie 40 Minuten enthalten 5 Minuten Ruhe für das Hähnchen. Nährwerte gelten für einen ganzen Wrap ohne Beilage.","category":"Hauptgerichte","category_slug":"platos-principales","difficulty":"Mittel","course":"Hauptgericht","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"Hähnchenbrust ohne Haut","amount":"500","unit":"g","group":"Warme Füllung"},{"name":"rote Paprika","amount":"200","unit":"g","group":"Warme Füllung"},{"name":"Pflanzenöl","amount":"15","unit":"g","group":"Warme Füllung"},{"name":"Salz","amount":"3","unit":"g","group":"Warme Füllung"},{"name":"schwarzer Pfeffer","amount":"0.5","unit":"g","group":"Warme Füllung"},{"name":"große Weizentortillas","amount":"4","unit":"Stück","group":"Zusammenstellen"},{"name":"Römersalat","amount":"100","unit":"g","group":"Frische Füllung"},{"name":"Tomate","amount":"200","unit":"g","group":"Frische Füllung"},{"name":"Zitronensaft","amount":"20","unit":"g","group":"Dressing"},{"name":"zubereiteter Senf","amount":"10","unit":"g","group":"Dressing"},{"name":"Pflanzenöl","amount":"10","unit":"g","group":"Dressing"}],"steps":[{"title":"Gemüse waschen und schneiden","content":"100 g Salat, 200 g Tomate und 200 g rote Paprika waschen und trocknen. Salat in Streifen, Tomate in Würfel ohne überschüssigen Saft und Paprika in 1 cm breite Streifen schneiden.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-01.webp","image_alt":"Hähnchen-Wrap mit Gemüse: Gemüse waschen und schneiden"},{"title":"Hähnchen vorbereiten","content":"500 g Brust in etwa 2 cm dicke Streifen schneiden. Mit 3 g Salz und 0,5 g Pfeffer würzen. Separates Brett verwenden und anschließend Hände und Werkzeuge reinigen.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-02.webp","image_alt":"Hähnchen-Wrap mit Gemüse: Hähnchen vorbereiten"},{"title":"Paprika garen","content":"5 g Öl bei mittlerer bis hoher Hitze erhitzen. Paprika unter Rühren 5 Minuten weich, aber noch bissfest braten. Auf sauberen Teller geben.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-03.webp","image_alt":"Hähnchen-Wrap mit Gemüse: Paprika garen"},{"title":"Hähnchen garen","content":"10 g Öl zugeben und Hähnchen 7–9 Minuten unter Wenden bis 74 °C im Kern garen. In kleiner Pfanne portionsweise arbeiten. Vom Herd genommen 5 Minuten ruhen lassen.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-04.webp","image_alt":"Hähnchen-Wrap mit Gemüse: Hähnchen garen"},{"title":"Dressing mischen","content":"20 g Zitronensaft, 10 g Senf und 10 g Öl 1 Minute verquirlen. Zurückstellen; Gemüse erst beim Zusammenstellen damit mischen.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-05.webp","image_alt":"Hähnchen-Wrap mit Gemüse: Dressing mischen"},{"title":"Tortillas erwärmen","content":"4 Tortillas in trockener Pfanne je Seite 15–20 Sekunden erwärmen, nur bis biegsam. Unter einem sauberen Tuch warm halten.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-06.webp","image_alt":"Hähnchen-Wrap mit Gemüse: Tortillas erwärmen"},{"title":"Füllen und rollen","content":"Salat, Tomate, Paprika und Hähnchen aufteilen, jeweils 3 cm Rand frei lassen. Je ein Viertel Dressing zugeben. Seiten einklappen und vom nahen Rand aufrollen.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-07.webp","image_alt":"Hähnchen-Wrap mit Gemüse: Füllen und rollen"},{"title":"Schneiden und servieren","content":"Diagonal halbieren und je einen Wrap servieren. Zum Mitnehmen Fleisch zuerst abkühlen, kühlen und mit Kühlakkus transportieren; nicht stundenlang lauwarm halten.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-08.webp","image_alt":"Hähnchen-Wrap mit Gemüse: Schneiden und servieren"}],"notes":"Gegartes Hähnchen gekühlt bis 3 Tage lagern; Wraps am Verzehrtag rollen. Überschüssigen Tomatensaft entfernen, damit die Tortilla nicht weich wird. Große Tortilla mit 60 g geschätzt; bei anderem Gewicht Nährwerte anpassen. Maistortilla verändert Faltweise und Nährwerte.","nutrition":{"calories":413.0,"protein_g":34.3,"carbs_g":35.9,"fat_g":14.5,"saturated_fat_g":2.0,"fiber_g":3.8,"sugar_g":5.5,"sodium_mg":826.0,"serving_size":"1 von 4 Portionen","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Berechnet aus den geprüften USDA-SR-Legacy-Werten je 100 g, gewichtet nach essbarer Zutatenmenge und geteilt durch 4 Portionen. Angegebenes Öl und Salz sind vollständig eingerechnet; optionale Beilagen sind ausgeschlossen.","note":"Orientierungswerte; Marken, Ausbeute und nicht verzehrte Sauce oder Fett verändern das Ergebnis. Mengen, Zeiten, Portionen und Nährwerte sind KI-Vorschläge und warten auf Bestätigung des Eigentümers. Jede Tortilla wird mit 60 g und allgemeinen SR-Legacy-Daten für Weizentortillas geschätzt."},"keywords":["Hähnchen Wrap Gemüse","Weizentortilla Hähnchen","Wrap selber rollen"],"image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","gallery":[{"url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","alt":"Hähnchen-Wrap mit Gemüse: fertiges Gericht"}],"seo":{"title":"Hähnchen-Wrap mit Gemüse | Manual de Cocina","description":"Hähnchen-Wraps mit gebratener Paprika, Salat, Tomate und Zitronen-Senf-Dressing. Vier Weizentortillas werden nach dem Garen gefüllt und gerollt.","image_alt":"Hähnchen-Wrap mit Gemüse: fertiges Gericht","image_variants":["/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-1x1.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-4x3.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-16x9.webp"],"faq":[{"q":"Wie verhindere ich Risse?","a":"Kurz erwärmen, Rand frei lassen und nicht zu voll füllen."},{"q":"Geht Hähnchen vom Vortag?","a":"Bei korrekter Kühlung ja; für kalten Verzehr bis zum Rollen und Transport kalt halten."},{"q":"Kann der fertige Wrap eingefroren werden?","a":"Salat und Tomate verlieren Textur. Nur gegartes Fleisch einfrieren und später frisch rollen."}]},"published":false,"editorial_status":"ready","content_html":"<p>Vier Weizentortilla-Wraps mit Hähnchenstreifen, gebratener Paprika und frischem Gemüse. Das gegarte Fleisch etwas abkühlen lassen, damit der Salat nicht welkt.</p><p>Die 40 Minuten enthalten 5 Minuten Ruhe für das Hähnchen. Nährwerte gelten für einen ganzen Wrap ohne Beilage.</p>"},{"id":"d5ce466b-9186-55b8-bc9c-875496dfffd9","recipe_group_id":"489e5092-352f-4ec5-8633-c628e784d22a","slug":"chicken-and-vegetable-wraps","public_path":"/en/chicken-and-vegetable-wraps","source_url":null,"language":"en","title":"Chicken and vegetable wrap","excerpt":"Chicken wraps with sautéed red pepper, lettuce, tomato and lemon-mustard dressing. Four wheat tortillas filled after the chicken is cooked and rested.","summary":"Four wheat-tortilla wraps with chicken strips, sautéed pepper and fresh vegetables. Cool the cooked chicken slightly before filling so it does not wilt the lettuce.\n\nThe 40 minutes include a 5-minute chicken rest. Nutrition is for one complete wrap without sides.","category":"Main dishes","category_slug":"platos-principales","difficulty":"Medium","course":"Main course","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"skinless chicken breast","amount":"500","unit":"g","group":"Hot filling"},{"name":"red pepper","amount":"200","unit":"g","group":"Hot filling"},{"name":"vegetable oil","amount":"15","unit":"g","group":"Hot filling"},{"name":"salt","amount":"3","unit":"g","group":"Hot filling"},{"name":"black pepper","amount":"0.5","unit":"g","group":"Hot filling"},{"name":"large wheat tortillas","amount":"4","unit":"pieces","group":"Assembly"},{"name":"romaine lettuce","amount":"100","unit":"g","group":"Fresh filling"},{"name":"tomato","amount":"200","unit":"g","group":"Fresh filling"},{"name":"lemon juice","amount":"20","unit":"g","group":"Dressing"},{"name":"prepared mustard","amount":"10","unit":"g","group":"Dressing"},{"name":"vegetable oil","amount":"10","unit":"g","group":"Dressing"}],"steps":[{"title":"Wash and cut the vegetables","content":"Wash and dry 100 g lettuce, 200 g tomato and 200 g red pepper. Shred lettuce, dice tomato without excess juice and cut pepper into 1 cm strips.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-01.webp","image_alt":"Chicken and vegetable wrap: Wash and cut the vegetables"},{"title":"Prepare the chicken","content":"Cut 500 g chicken breast into strips about 2 cm thick. Season with 3 g salt and 0.5 g pepper. Use a separate board and clean hands and utensils afterwards.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-02.webp","image_alt":"Chicken and vegetable wrap: Prepare the chicken"},{"title":"Cook the pepper","content":"Heat 5 g oil over medium-high heat. Stir-fry pepper strips for 5 minutes until tender but still textured. Remove to a clean plate.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-03.webp","image_alt":"Chicken and vegetable wrap: Cook the pepper"},{"title":"Cook the chicken","content":"Add 10 g oil and cook chicken 7–9 minutes, turning, until the centre reaches 74 °C. Use batches in a small pan. Rest off the heat for 5 minutes.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-04.webp","image_alt":"Chicken and vegetable wrap: Cook the chicken"},{"title":"Mix the dressing","content":"Whisk 20 g lemon juice with 10 g mustard and 10 g oil for 1 minute. Set aside; do not dress vegetables until assembling.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-05.webp","image_alt":"Chicken and vegetable wrap: Mix the dressing"},{"title":"Warm the tortillas","content":"Warm 4 tortillas in a dry pan 15–20 seconds per side, just until flexible. Keep covered with a clean towel while assembling.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-06.webp","image_alt":"Chicken and vegetable wrap: Warm the tortillas"},{"title":"Fill and roll","content":"Share lettuce, tomato, pepper and chicken between tortillas, leaving 3 cm edges. Add a quarter of the dressing to each. Fold both sides in and roll from the near edge.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-07.webp","image_alt":"Chicken and vegetable wrap: Fill and roll"},{"title":"Slice and serve","content":"Cut each wrap diagonally and serve one per person. For packed meals, cool the chicken first, refrigerate and transport with ice packs; do not keep lukewarm for hours.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-08.webp","image_alt":"Chicken and vegetable wrap: Slice and serve"}],"notes":"Cooked chicken keeps refrigerated up to 3 days; assemble wraps on the day of eating. Remove excess tomato juice to avoid soggy tortillas. Each large tortilla is estimated at 60 g; adjust nutrition if the packet differs. Corn tortillas require different folding and change nutrition.","nutrition":{"calories":413.0,"protein_g":34.3,"carbs_g":35.9,"fat_g":14.5,"saturated_fat_g":2.0,"fiber_g":3.8,"sugar_g":5.5,"sodium_mg":826.0,"serving_size":"1 of 4 servings","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Verified USDA SR Legacy values per 100 g are multiplied by the edible ingredient weights and divided by 4 servings. All listed oil and salt are counted; optional sides are excluded.","note":"Informational estimate; brands, yield and uneaten fat or sauce affect the result. Quantities, times, servings and nutrition are AI proposals awaiting owner confirmation. Each tortilla is estimated at 60 g using generic SR Legacy wheat-tortilla data."},"keywords":["chicken vegetable wraps","wheat tortilla chicken","homemade chicken wrap"],"image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","gallery":[{"url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","alt":"Chicken and vegetable wrap: finished dish"}],"seo":{"title":"Chicken and vegetable wrap | Manual de Cocina","description":"Chicken wraps with sautéed red pepper, lettuce, tomato and lemon-mustard dressing. Four wheat tortillas filled after the chicken is cooked and rested.","image_alt":"Chicken and vegetable wrap: finished dish","image_variants":["/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-1x1.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-4x3.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-16x9.webp"],"faq":[{"q":"How do I prevent the tortilla tearing?","a":"Warm briefly, leave clear edges and avoid overfilling."},{"q":"Can I use yesterday's chicken?","a":"Yes if refrigerated correctly. For cold eating, keep it chilled through assembly and transport."},{"q":"Can I freeze a whole wrap?","a":"Lettuce and tomato lose texture. Freeze cooked chicken alone and assemble later with fresh vegetables."}]},"published":false,"editorial_status":"ready","content_html":"<p>Four wheat-tortilla wraps with chicken strips, sautéed pepper and fresh vegetables. Cool the cooked chicken slightly before filling so it does not wilt the lettuce.</p><p>The 40 minutes include a 5-minute chicken rest. Nutrition is for one complete wrap without sides.</p>"},{"id":"eebcea80-02a5-507c-ac3b-d4377a4b2363","recipe_group_id":"489e5092-352f-4ec5-8633-c628e784d22a","slug":"wraps-poulet-legumes","public_path":"/fr/wraps-poulet-legumes","source_url":null,"language":"fr","title":"Wrap au poulet et aux légumes","excerpt":"Wraps de poulet, poivron sauté, laitue et tomate, sauce citron-moutarde. Quatre tortillas de blé garnies après cuisson et repos du poulet.","summary":"Quatre wraps de blé avec poulet en lanières, poivron sauté et légumes frais. Le poulet cuit puis tiédit pour ne pas flétrir la laitue.\n\nLes 40 minutes incluent 5 minutes de repos. Nutrition pour un wrap entier sans accompagnement.","category":"Plats principaux","category_slug":"platos-principales","difficulty":"Moyenne","course":"Plat principal","cuisine":"Internationale","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"blanc de poulet sans peau","amount":"500","unit":"g","group":"Garniture chaude"},{"name":"poivron rouge","amount":"200","unit":"g","group":"Garniture chaude"},{"name":"huile végétale","amount":"15","unit":"g","group":"Garniture chaude"},{"name":"sel","amount":"3","unit":"g","group":"Garniture chaude"},{"name":"poivre noir","amount":"0.5","unit":"g","group":"Garniture chaude"},{"name":"grandes tortillas de blé","amount":"4","unit":"pièces","group":"Montage"},{"name":"laitue romaine","amount":"100","unit":"g","group":"Garniture fraîche"},{"name":"tomate","amount":"200","unit":"g","group":"Garniture fraîche"},{"name":"jus de citron","amount":"20","unit":"g","group":"Sauce"},{"name":"moutarde préparée","amount":"10","unit":"g","group":"Sauce"},{"name":"huile végétale","amount":"10","unit":"g","group":"Sauce"}],"steps":[{"title":"Laver et couper les légumes","content":"Lavez et séchez 100 g de laitue, 200 g de tomate et 200 g de poivron rouge. Émincez laitue, taillez tomate en dés sans excès de jus et poivron en lanières de 1 cm.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-01.webp","image_alt":"Wrap au poulet et aux légumes: Laver et couper les légumes"},{"title":"Préparer le poulet","content":"Coupez 500 g de poulet en lanières d’environ 2 cm d’épaisseur. Assaisonnez avec 3 g de sel et 0,5 g de poivre. Utilisez une planche distincte et nettoyez mains et ustensiles.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-02.webp","image_alt":"Wrap au poulet et aux légumes: Préparer le poulet"},{"title":"Cuire le poivron","content":"Chauffez 5 g d’huile à feu moyen-vif et sautez le poivron 5 minutes en remuant, tendre mais encore texturé. Réservez sur une assiette propre.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-03.webp","image_alt":"Wrap au poulet et aux légumes: Cuire le poivron"},{"title":"Cuire le poulet","content":"Ajoutez 10 g d’huile et cuisez poulet 7–9 minutes en tournant jusqu’à 74 °C au centre. Procédez par lots si la poêle est petite. Reposez hors feu 5 minutes.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-04.webp","image_alt":"Wrap au poulet et aux légumes: Cuire le poulet"},{"title":"Mélanger la sauce","content":"Fouettez 20 g de jus de citron, 10 g de moutarde et 10 g d’huile 1 minute. Réservez; assaisonnez les légumes au montage seulement.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-05.webp","image_alt":"Wrap au poulet et aux légumes: Mélanger la sauce"},{"title":"Réchauffer les tortillas","content":"Chauffez 4 tortillas à sec 15–20 secondes par face, juste pour les assouplir. Gardez couvertes d’un linge propre.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-06.webp","image_alt":"Wrap au poulet et aux légumes: Réchauffer les tortillas"},{"title":"Garnir et rouler","content":"Répartissez laitue, tomate, poivron et poulet en laissant 3 cm libres aux bords. Ajoutez un quart de sauce par tortilla. Rabattez les côtés et roulez depuis le bord proche.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-07.webp","image_alt":"Wrap au poulet et aux légumes: Garnir et rouler"},{"title":"Couper et servir","content":"Coupez en diagonale et servez un wrap par personne. Pour emporter, refroidissez d’abord le poulet, réfrigérez et transportez avec pains de glace; pas des heures tiède.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-08.webp","image_alt":"Wrap au poulet et aux légumes: Couper et servir"}],"notes":"Poulet cuit réfrigéré jusqu’à 3 jours; montez les wraps le jour de consommation. Ôtez le jus de tomate pour éviter de détremper. Tortilla estimée à 60 g: adaptez la nutrition au poids réel. Une tortilla de maïs change le pliage et l’estimation.","nutrition":{"calories":413.0,"protein_g":34.3,"carbs_g":35.9,"fat_g":14.5,"saturated_fat_g":2.0,"fiber_g":3.8,"sugar_g":5.5,"sodium_mg":826.0,"serving_size":"1 des 4 portions","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des valeurs USDA SR Legacy vérifiées pour 100 g, pondérées par le poids comestible des ingrédients et divisées par 4 portions. Toute l’huile et tout le sel indiqués sont comptés; les accompagnements facultatifs sont exclus.","note":"Estimation indicative; les marques, le rendement et la sauce ou la graisse non consommée modifient le résultat. Quantités, durées, portions et nutrition proposées par IA, à confirmer par le propriétaire. Chaque tortilla est estimée à 60 g à partir des données SR Legacy génériques de tortilla de blé."},"keywords":["wrap poulet légumes","tortilla blé poulet","wrap maison"],"image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","gallery":[{"url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","alt":"Wrap au poulet et aux légumes: plat terminé"}],"seo":{"title":"Wrap au poulet et aux légumes | Manual de Cocina","description":"Wraps de poulet, poivron sauté, laitue et tomate, sauce citron-moutarde. Quatre tortillas de blé garnies après cuisson et repos du poulet.","image_alt":"Wrap au poulet et aux légumes: plat terminé","image_variants":["/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-1x1.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-4x3.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-16x9.webp"],"faq":[{"q":"Comment éviter de déchirer la tortilla?","a":"Chauffez brièvement, gardez un bord libre et ne surchargez pas."},{"q":"Peut-on utiliser le poulet de la veille?","a":"S’il a été bien réfrigéré; gardez-le froid jusqu’au montage et transport pour consommation froide."},{"q":"Peut-on congeler le wrap entier?","a":"Laitue et tomate perdent leur texture. Congelez seulement le poulet cuit, puis montez avec légumes frais."}]},"published":false,"editorial_status":"ready","content_html":"<p>Quatre wraps de blé avec poulet en lanières, poivron sauté et légumes frais. Le poulet cuit puis tiédit pour ne pas flétrir la laitue.</p><p>Les 40 minutes incluent 5 minutes de repos. Nutrition pour un wrap entier sans accompagnement.</p>"},{"id":"d2e0646d-b61c-517d-95ad-65c9ee4d92fc","recipe_group_id":"489e5092-352f-4ec5-8633-c628e784d22a","slug":"wrap-pollo-verdure","public_path":"/it/wrap-pollo-verdure","source_url":null,"language":"it","title":"Wrap con pollo e verdure","excerpt":"Wrap di pollo con peperone saltato, lattuga, pomodoro e condimento limone-senape. Quattro tortillas di frumento farcite dopo la cottura del pollo.","summary":"Quattro wrap di frumento con pollo a strisce, peperone saltato e verdure fresche. Il pollo cuoce e intiepidisce prima, per non appassire la lattuga.\n\nI 40 minuti includono 5 di riposo. Nutrizione per un wrap completo senza contorno.","category":"Secondi piatti","category_slug":"platos-principales","difficulty":"Media","course":"Piatto principale","cuisine":"Internazionale","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"petto di pollo senza pelle","amount":"500","unit":"g","group":"Ripieno caldo"},{"name":"peperone rosso","amount":"200","unit":"g","group":"Ripieno caldo"},{"name":"olio vegetale","amount":"15","unit":"g","group":"Ripieno caldo"},{"name":"sale","amount":"3","unit":"g","group":"Ripieno caldo"},{"name":"pepe nero","amount":"0.5","unit":"g","group":"Ripieno caldo"},{"name":"tortillas grandi di frumento","amount":"4","unit":"pezzi","group":"Montaggio"},{"name":"lattuga romana","amount":"100","unit":"g","group":"Ripieno fresco"},{"name":"pomodoro","amount":"200","unit":"g","group":"Ripieno fresco"},{"name":"succo di limone","amount":"20","unit":"g","group":"Condimento"},{"name":"senape pronta","amount":"10","unit":"g","group":"Condimento"},{"name":"olio vegetale","amount":"10","unit":"g","group":"Condimento"}],"steps":[{"title":"Lavare e tagliare le verdure","content":"Lava e asciuga 100 g di lattuga, 200 g di pomodoro e 200 g di peperone rosso. Taglia lattuga a strisce, pomodoro a dadi senza troppo liquido e peperone a strisce da 1 cm.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-01.webp","image_alt":"Wrap con pollo e verdure: Lavare e tagliare le verdure"},{"title":"Preparare il pollo","content":"Taglia 500 g di pollo a strisce spesse circa 2 cm. Condisci con 3 g di sale e 0,5 g di pepe. Usa tagliere separato e pulisci mani e utensili.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-02.webp","image_alt":"Wrap con pollo e verdure: Preparare il pollo"},{"title":"Cuocere il peperone","content":"Scalda 5 g di olio a fuoco medio-alto. Salta peperone 5 minuti mescolando, fino a tenero ma consistente. Metti su piatto pulito.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-03.webp","image_alt":"Wrap con pollo e verdure: Cuocere il peperone"},{"title":"Cuocere il pollo","content":"Aggiungi 10 g di olio e cuoci pollo 7–9 minuti girando fino a 74 °C al centro. In padella piccola lavora in più turni. Riposa fuori fuoco 5 minuti.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-04.webp","image_alt":"Wrap con pollo e verdure: Cuocere il pollo"},{"title":"Mescolare il condimento","content":"Sbatti 20 g di limone, 10 g di senape e 10 g di olio per 1 minuto. Riserva; condisci le verdure solo al montaggio.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-05.webp","image_alt":"Wrap con pollo e verdure: Mescolare il condimento"},{"title":"Scaldare le tortillas","content":"Scalda 4 tortillas in padella asciutta 15–20 secondi per lato, fino a flessibili. Tieni coperte con panno pulito.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-06.webp","image_alt":"Wrap con pollo e verdure: Scaldare le tortillas"},{"title":"Farcire e arrotolare","content":"Distribuisci lattuga, pomodoro, peperone e pollo lasciando 3 cm liberi ai bordi. Metti un quarto di condimento ciascuna. Ripiega i lati e arrotola dal bordo vicino.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-07.webp","image_alt":"Wrap con pollo e verdure: Farcire e arrotolare"},{"title":"Tagliare e servire","content":"Taglia diagonalmente e servi un wrap a testa. Per trasportare, raffredda prima il pollo, refrigera e usa accumulatori di freddo; non lasciare tiepido per ore.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-08.webp","image_alt":"Wrap con pollo e verdure: Tagliare e servire"}],"notes":"Pollo cotto refrigerato fino a 3 giorni; monta i wrap il giorno di consumo. Togli il succo in eccesso del pomodoro. Tortilla stimata a 60 g; adegua i valori al peso reale. Con mais cambiano piegatura e nutrizione.","nutrition":{"calories":413.0,"protein_g":34.3,"carbs_g":35.9,"fat_g":14.5,"saturated_fat_g":2.0,"fiber_g":3.8,"sugar_g":5.5,"sodium_mg":826.0,"serving_size":"1 delle 4 porzioni","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valori USDA SR Legacy verificati per 100 g, moltiplicati per i pesi commestibili degli ingredienti e divisi per 4 porzioni. Tutto l’olio e il sale indicati sono conteggiati; i contorni facoltativi sono esclusi.","note":"Stima orientativa; marche, resa e grasso o salsa non consumati cambiano il risultato. Quantità, tempi, porzioni e nutrizione proposti dall’IA, da confermare dal proprietario. Ogni tortilla è stimata a 60 g con dati generici SR Legacy di tortilla di frumento."},"keywords":["wrap pollo verdure","tortilla frumento pollo","wrap fatto in casa"],"image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","gallery":[{"url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","alt":"Wrap con pollo e verdure: piatto pronto"}],"seo":{"title":"Wrap con pollo e verdure | Manual de Cocina","description":"Wrap di pollo con peperone saltato, lattuga, pomodoro e condimento limone-senape. Quattro tortillas di frumento farcite dopo la cottura del pollo.","image_alt":"Wrap con pollo e verdure: piatto pronto","image_variants":["/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-1x1.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-4x3.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-16x9.webp"],"faq":[{"q":"Come evitare rotture?","a":"Scalda brevemente, lascia bordo libero e non riempire troppo."},{"q":"Posso usare pollo del giorno prima?","a":"Se refrigerato correttamente; per mangiarlo freddo mantienilo freddo fino al montaggio e trasporto."},{"q":"Posso congelare il wrap completo?","a":"Lattuga e pomodoro perdono consistenza. Congela solo pollo cotto e monta dopo con verdure fresche."}]},"published":false,"editorial_status":"ready","content_html":"<p>Quattro wrap di frumento con pollo a strisce, peperone saltato e verdure fresche. Il pollo cuoce e intiepidisce prima, per non appassire la lattuga.</p><p>I 40 minuti includono 5 di riposo. Nutrizione per un wrap completo senza contorno.</p>"},{"id":"fa724fbd-5b20-580c-9bb1-0abc840a5e3f","recipe_group_id":"489e5092-352f-4ec5-8633-c628e784d22a","slug":"鶏肉と野菜のラップサンド","public_path":"/ja/鶏肉と野菜のラップサンド","source_url":null,"language":"ja","title":"鶏肉と野菜のラップサンド","excerpt":"鶏肉、炒めた赤パプリカ、レタスとトマトのラップサンド。レモンマスタード味で、小麦トルティーヤ4枚に巻きます。","summary":"鶏肉の細切り、炒めたパプリカ、生野菜を小麦トルティーヤで巻く4個分。鶏肉を加熱して少し冷まし、レタスがしおれないようにします。\n\n40分には鶏肉を休ませる5分を含みます。栄養は付け合わせなしの1個分です。","category":"主菜","category_slug":"platos-principales","difficulty":"普通","course":"主菜","cuisine":"世界の料理","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"皮なし鶏胸肉","amount":"500","unit":"g","group":"温かい具"},{"name":"赤パプリカ","amount":"200","unit":"g","group":"温かい具"},{"name":"植物油","amount":"15","unit":"g","group":"温かい具"},{"name":"塩","amount":"3","unit":"g","group":"温かい具"},{"name":"黒こしょう","amount":"0.5","unit":"g","group":"温かい具"},{"name":"大きい小麦トルティーヤ","amount":"4","unit":"個","group":"組み立て"},{"name":"ロメインレタス","amount":"100","unit":"g","group":"生野菜"},{"name":"トマト","amount":"200","unit":"g","group":"生野菜"},{"name":"レモン汁","amount":"20","unit":"g","group":"ドレッシング"},{"name":"練りマスタード","amount":"10","unit":"g","group":"ドレッシング"},{"name":"植物油","amount":"10","unit":"g","group":"ドレッシング"}],"steps":[{"title":"野菜を洗って切る","content":"レタス100 g、トマト200 g、赤パプリカ200 gを洗い乾かします。レタスを細切り、トマトを汁気を除いた角切り、パプリカを幅1 cmに切ります。","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-01.webp","image_alt":"鶏肉と野菜のラップサンド: 野菜を洗って切る"},{"title":"鶏肉を用意する","content":"鶏胸肉500 gを厚さ約2 cmの細切りにし、塩3 gとこしょう0.5 gで味付け。別のまな板を使い、手と器具を洗います。","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-02.webp","image_alt":"鶏肉と野菜のラップサンド: 鶏肉を用意する"},{"title":"パプリカを炒める","content":"油5 gを中強火で熱し、パプリカを5分混ぜて炒めます。柔らかく歯応えを残し、清潔な皿へ取ります。","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-03.webp","image_alt":"鶏肉と野菜のラップサンド: パプリカを炒める"},{"title":"鶏肉を加熱する","content":"油10 gを加え、鶏肉を7–9分返しながら中心74 °Cまで加熱。鍋が小さければ分けて焼き、火から外して5分休ませます。","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-04.webp","image_alt":"鶏肉と野菜のラップサンド: 鶏肉を加熱する"},{"title":"ドレッシングを混ぜる","content":"レモン汁20 g、マスタード10 g、油10 gを1分混ぜて取り置きます。組み立てるまで野菜にかけません。","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-05.webp","image_alt":"鶏肉と野菜のラップサンド: ドレッシングを混ぜる"},{"title":"トルティーヤを温める","content":"トルティーヤ4枚を乾いた鍋で片面15–20秒ずつ、曲げやすくなるまで温め、清潔な布で覆います。","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-06.webp","image_alt":"鶏肉と野菜のラップサンド: トルティーヤを温める"},{"title":"詰めて巻く","content":"レタス、トマト、パプリカ、鶏肉を分け、縁3 cmを空けます。ドレッシングを各4分の1ずつ加え、両端を内側へ折り、手前から巻きます。","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-07.webp","image_alt":"鶏肉と野菜のラップサンド: 詰めて巻く"},{"title":"切って盛り付ける","content":"斜めに切って1人1個提供します。持ち運ぶなら肉を先に冷まし、冷蔵して保冷剤を使います。ぬるいまま何時間も置きません。","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-08.webp","image_alt":"鶏肉と野菜のラップサンド: 切って盛り付ける"}],"notes":"鶏肉は冷蔵最長3日、食べる当日に巻きます。トマトの余分な汁を取って皮の湿りを防ぎます。トルティーヤは1枚60 gで推定し、製品重量が違えば栄養を調整。とうもろこし製は巻き方と栄養が変わります。","nutrition":{"calories":413.0,"protein_g":34.3,"carbs_g":35.9,"fat_g":14.5,"saturated_fat_g":2.0,"fiber_g":3.8,"sugar_g":5.5,"sodium_mg":826.0,"serving_size":"全4人分のうち1人分","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"確認済みのUSDA SR Legacyの100 g当たりの値に各材料の可食重量を掛け、合計を4人分で割っています。記載した油と塩は全量を計上し、任意の付け合わせは含みません。","note":"参考推定値です。製品、出来上がり量、食べ残した脂やソースで変わります。分量、時間、人数、栄養値はAIの提案で、所有者の確認待ちです。 トルティーヤ1枚60 gを、SR Legacyの一般的な小麦トルティーヤデータで推定しています。"},"keywords":["チキンラップサンド","鶏肉野菜トルティーヤ","手作りラップ"],"image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","gallery":[{"url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","alt":"鶏肉と野菜のラップサンド: 完成した料理"}],"seo":{"title":"鶏肉と野菜のラップサンド | Manual de Cocina","description":"鶏肉、炒めた赤パプリカ、レタスとトマトのラップサンド。レモンマスタード味で、小麦トルティーヤ4枚に巻きます。","image_alt":"鶏肉と野菜のラップサンド: 完成した料理","image_variants":["/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-1x1.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-4x3.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-16x9.webp"],"faq":[{"q":"トルティーヤが破れない方法は？","a":"短く温め、縁を空け、具を詰めすぎないことです。"},{"q":"前日の鶏肉を使えますか？","a":"適切に冷蔵した場合は使えます。冷たいまま食べるなら組み立てと運搬中も保冷します。"},{"q":"完成したラップを冷凍できますか？","a":"レタスとトマトの食感が損なわれます。肉だけ冷凍し、後で新鮮な野菜と巻きます。"}]},"published":false,"editorial_status":"ready","content_html":"<p>鶏肉の細切り、炒めたパプリカ、生野菜を小麦トルティーヤで巻く4個分。鶏肉を加熱して少し冷まし、レタスがしおれないようにします。</p><p>40分には鶏肉を休ませる5分を含みます。栄養は付け合わせなしの1個分です。</p>"},{"id":"bb6221be-2495-5483-b850-cd6d762e82ee","recipe_group_id":"489e5092-352f-4ec5-8633-c628e784d22a","slug":"wrap-de-frango-com-vegetais","public_path":"/pt/wrap-de-frango-com-vegetais","source_url":null,"language":"pt","title":"Wrap de frango com legumes","excerpt":"Wrap de frango com pimentão salteado, alface, tomate e molho de limão e mostarda. Quatro tortillas de trigo recheadas após cozinhar o frango.","summary":"Quatro wraps de trigo com tiras de frango, pimentão salteado e vegetais frescos. O frango cozinha e amorna antes de rechear para não murchar a alface.\n\nOs 40 minutos incluem 5 de descanso. Nutrição para um wrap inteiro, sem guarnições.","category":"Pratos principais","category_slug":"platos-principales","difficulty":"Média","course":"Prato principal","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":15,"total_time_minutes":40,"servings":4,"ingredients":[{"name":"peito de frango sem pele","amount":"500","unit":"g","group":"Recheio quente"},{"name":"pimentão vermelho","amount":"200","unit":"g","group":"Recheio quente"},{"name":"óleo vegetal","amount":"15","unit":"g","group":"Recheio quente"},{"name":"sal","amount":"3","unit":"g","group":"Recheio quente"},{"name":"pimenta-do-reino","amount":"0.5","unit":"g","group":"Recheio quente"},{"name":"tortillas grandes de trigo","amount":"4","unit":"unidades","group":"Montagem"},{"name":"alface-romana","amount":"100","unit":"g","group":"Recheio fresco"},{"name":"tomate","amount":"200","unit":"g","group":"Recheio fresco"},{"name":"suco de limão","amount":"20","unit":"g","group":"Molho"},{"name":"mostarda preparada","amount":"10","unit":"g","group":"Molho"},{"name":"óleo vegetal","amount":"10","unit":"g","group":"Molho"}],"steps":[{"title":"Lave e corte os vegetais","content":"Lave e seque 100 g de alface, 200 g de tomate e 200 g de pimentão. Corte alface em tiras, tomate em cubos sem excesso de suco e pimentão em tiras de 1 cm.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-01.webp","image_alt":"Wrap de frango com legumes: Lave e corte os vegetais"},{"title":"Prepare o frango","content":"Corte 500 g de frango em tiras de cerca de 2 cm de espessura. Tempere com 3 g de sal e 0,5 g de pimenta. Use tábua distinta e limpe mãos e utensílios.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-02.webp","image_alt":"Wrap de frango com legumes: Prepare o frango"},{"title":"Cozinhe o pimentão","content":"Aqueça 5 g de óleo em fogo médio-alto. Salteie pimentão 5 minutos mexendo até macio mas com textura; retire a prato limpo.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-03.webp","image_alt":"Wrap de frango com legumes: Cozinhe o pimentão"},{"title":"Cozinhe o frango","content":"Junte 10 g de óleo e cozinhe frango 7–9 minutos virando até 74 °C no centro. Faça em porções se a panela for pequena. Descanse fora do fogo 5 minutos.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-04.webp","image_alt":"Wrap de frango com legumes: Cozinhe o frango"},{"title":"Misture o molho","content":"Bata 20 g de limão com 10 g de mostarda e 10 g de óleo por 1 minuto. Reserve; tempere vegetais só na montagem.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-05.webp","image_alt":"Wrap de frango com legumes: Misture o molho"},{"title":"Aqueça as tortillas","content":"Aqueça 4 tortillas a seco 15–20 segundos por lado, apenas até flexíveis. Cubra com pano limpo.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-06.webp","image_alt":"Wrap de frango com legumes: Aqueça as tortillas"},{"title":"Recheie e enrole","content":"Divida alface, tomate, pimentão e frango deixando 3 cm nas bordas. Coloque um quarto do molho em cada. Dobre os lados para dentro e enrole a partir da borda próxima.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-07.webp","image_alt":"Wrap de frango com legumes: Recheie e enrole"},{"title":"Corte e sirva","content":"Corte diagonalmente e sirva um por pessoa. Para levar, esfrie primeiro o frango, refrigere e transporte com bolsas de gelo; não deixe morno por horas.","image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/paso-08.webp","image_alt":"Wrap de frango com legumes: Corte e sirva"}],"notes":"Frango cozido refrigerado até 3 dias; monte no dia de consumo. Tire líquido do tomate para não amolecer. Tortilla estimada em 60 g; ajuste nutrição ao peso do pacote. Tortilla de milho muda dobra e estimativa.","nutrition":{"calories":413.0,"protein_g":34.3,"carbs_g":35.9,"fat_g":14.5,"saturated_fat_g":2.0,"fiber_g":3.8,"sugar_g":5.5,"sodium_mg":826.0,"serving_size":"1 de 4 porções","estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Valores USDA SR Legacy verificados por 100 g, multiplicados pelos pesos comestíveis e divididos por 4 porções. Todo o óleo e sal indicados entram no cálculo; acompanhamentos opcionais ficam de fora.","note":"Estimativa orientativa; marcas, rendimento e gordura ou molho não consumidos alteram o resultado. Quantidades, tempos, porções e nutrição são propostas de IA aguardando confirmação do proprietário. Cada tortilla estimada em 60 g com dados genéricos SR Legacy de tortilla de trigo."},"keywords":["wrap frango vegetais","tortilla de trigo frango","wrap caseiro"],"image_url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","gallery":[{"url":"/recetas/receta-de-wrap-de-pollo-con-vegetales/portada.webp","alt":"Wrap de frango com legumes: prato pronto"}],"seo":{"title":"Wrap de frango com legumes | Manual de Cocina","description":"Wrap de frango com pimentão salteado, alface, tomate e molho de limão e mostarda. Quatro tortillas de trigo recheadas após cozinhar o frango.","image_alt":"Wrap de frango com legumes: prato pronto","image_variants":["/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-1x1.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-4x3.webp","/recetas/receta-de-wrap-de-pollo-con-vegetales/portada-16x9.webp"],"faq":[{"q":"Como evitar que a tortilla rasgue?","a":"Aqueça brevemente, deixe bordas livres e não exagere no recheio."},{"q":"Posso usar frango da véspera?","a":"Se refrigerado corretamente; para consumir frio mantenha frio na montagem e transporte."},{"q":"Posso congelar o wrap inteiro?","a":"Alface e tomate perdem textura. Congele apenas frango cozido e monte depois com vegetais frescos."}]},"published":false,"editorial_status":"ready","content_html":"<p>Quatro wraps de trigo com tiras de frango, pimentão salteado e vegetais frescos. O frango cozinha e amorna antes de rechear para não murchar a alface.</p><p>Os 40 minutos incluem 5 de descanso. Nutrição para um wrap inteiro, sem guarnições.</p>"}]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-de-wrap-de-pollo-con-vegetales') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    x.content_html, x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;

commit;